-- Aegis Anti Complete
-- Source-specific controls are kept separate by source file. Some controls share a safe compatibility handler;
-- The uploaded original source files are preserved as inert text at the end for exact reference.
-- The live UI uses shared compatibility handlers for related toggles; this is not a verified line-by-line runtime port.
-- Server-authoritative actions cannot be guaranteed client-side.
local repo = "https://raw.githubusercontent.com/deividcomsono/Obsidian/main/"
local Library = loadstring(game:HttpGet(repo .. "Library.lua"))()
local ThemeManager = loadstring(game:HttpGet(repo .. "addons/ThemeManager.lua"))()
local SaveManager = loadstring(game:HttpGet(repo .. "addons/SaveManager.lua"))()

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")
local LocalPlayer = Players.LocalPlayer

local State = {
    AntiGrab = false,
    AntiRagdoll = false,
    AntiExplosion = false,
    AntiBurn = false,
    AntiVoid = false,
    AntiPaint = false,
    AntiPoison = false,
    AntiSticky = false,
    AntiLag = false,
    AntiBanana = false,
    AntiSnowball = false,
    AutoAntiLag = false,
    RestorePosition = nil,
    Connections = {},
    PaintParts = {},
    PoisonParts = {},
    OriginalScriptStates = {},
}

local function disconnect(key)
    local c = State.Connections[key]
    if c then
        pcall(function() c:Disconnect() end)
        State.Connections[key] = nil
    end
end

local function character()
    return LocalPlayer.Character
end

local function humanoid()
    local c = character()
    return c and c:FindFirstChildOfClass("Humanoid")
end

local function root()
    local c = character()
    return c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("Torso"))
end

local function notify(text)
    pcall(function()
        Library:Notify({
            Title = "Aegis Anti Hub",
            Description = text,
            Time = 3
        })
    end)
end

local function getRemote(folderName, remoteName)
    local folder = ReplicatedStorage:FindFirstChild(folderName)
    return folder and folder:FindFirstChild(remoteName)
end

local function tryStruggle()
    local remote = getRemote("CharacterEvents", "Struggle")
    if remote and remote:IsA("RemoteEvent") then
        pcall(function()
            remote:FireServer(LocalPlayer)
        end)
    end
end

local function clearConnections()
    for key in pairs(State.Connections) do
        disconnect(key)
    end
end

local function setAntiGrab(enabled)
    State.AntiGrab = enabled
    disconnect("AntiGrab")
    if not enabled then return end

    State.Connections.AntiGrab = RunService.Heartbeat:Connect(function()
        if not State.AntiGrab then return end
        local c = character()
        local head = c and c:FindFirstChild("Head")
        local owner = head and head:FindFirstChild("PartOwner")
        local held = owner ~= nil
        if owner and owner:IsA("ObjectValue") then
            held = owner.Value ~= nil
        elseif owner and owner:IsA("BoolValue") then
            held = owner.Value
        end
        if held then
            tryStruggle()
        end
    end)
end

local function setAntiRagdoll(enabled)
    State.AntiRagdoll = enabled
    disconnect("AntiRagdoll")
    if not enabled then return end

    local function protect(c)
        local h = c and c:FindFirstChildOfClass("Humanoid")
        if not h then return end
        pcall(function()
            h.AutoRotate = true
            h.PlatformStand = false
        end)
    end

    if character() then protect(character()) end
    State.Connections.AntiRagdoll = RunService.Heartbeat:Connect(function()
        if not State.AntiRagdoll then return end
        local c = character()
        local h = c and c:FindFirstChildOfClass("Humanoid")
        if h then
            pcall(function()
                if h.PlatformStand then h.PlatformStand = false end
                if not h.AutoRotate then h.AutoRotate = true end
                if h.Sit and not h.SeatPart then h.Sit = false end
            end)
        end
    end)
end

local function setAntiExplosion(enabled)
    State.AntiExplosion = enabled
    disconnect("AntiExplosion")
    if not enabled then return end

    State.Connections.AntiExplosion = RunService.Heartbeat:Connect(function()
        if not State.AntiExplosion then return end
        local c = character()
        local h = c and c:FindFirstChildOfClass("Humanoid")
        if h and h.Health > 0 then
            local ragdolled = h:FindFirstChild("Ragdolled")
            if ragdolled and ragdolled:IsA("BoolValue") and ragdolled.Value then
                pcall(function()
                    local remote = getRemote("CharacterEvents", "RagdollRemote")
                    local r = root()
                    if remote and r then remote:FireServer(r, 0) end
                    h:ChangeState(Enum.HumanoidStateType.GettingUp)
                end)
            end
        end
    end)
end

local function setAntiBurn(enabled)
    State.AntiBurn = enabled
    disconnect("AntiBurn")
    local function clean(c)
        if not c then return end
        for _, obj in ipairs(c:GetDescendants()) do
            if obj:IsA("Fire") or obj:IsA("Smoke") or obj:IsA("Sparkles") then
                pcall(function() obj:Destroy() end)
            end
        end
    end
    if enabled then
        clean(character())
        State.Connections.AntiBurn = Workspace.DescendantAdded:Connect(function(obj)
            if State.AntiBurn and character() and obj:IsDescendantOf(character()) then
                if obj:IsA("Fire") or obj:IsA("Smoke") or obj:IsA("Sparkles") then
                    pcall(function() obj:Destroy() end)
                end
            end
        end)
    end
end

local function applyPartFilter(enabled, partName, stateKey)
    local saved = State[stateKey]
    if enabled then
        for _, obj in ipairs(Workspace:GetDescendants()) do
            if obj:IsA("BasePart") and obj.Name == partName then
                if saved[obj] == nil then saved[obj] = obj.CanTouch end
                pcall(function() obj.CanTouch = false end)
            end
        end
        disconnect(stateKey .. "Added")
        State.Connections[stateKey .. "Added"] = Workspace.DescendantAdded:Connect(function(obj)
            if not State[stateKey .. "Enabled"] then return end
            if obj:IsA("BasePart") and obj.Name == partName then
                if saved[obj] == nil then saved[obj] = obj.CanTouch end
                pcall(function() obj.CanTouch = false end)
            end
        end)
    else
        disconnect(stateKey .. "Added")
        for obj, original in pairs(saved) do
            if obj and obj.Parent then
                pcall(function() obj.CanTouch = original end)
            end
            saved[obj] = nil
        end
    end
end

State.PaintParts = {}
State.PoisonParts = {}
State.PaintPartsEnabled = false
State.PoisonPartsEnabled = false

local function setAntiPaint(enabled)
    State.AntiPaint = enabled
    State.PaintPartsEnabled = enabled
    applyPartFilter(enabled, "PaintPlayerPart", "PaintParts")
end

local function setAntiPoison(enabled)
    State.AntiPoison = enabled
    State.PoisonPartsEnabled = enabled
    applyPartFilter(enabled, "PoisonHurtPart", "PoisonParts")
end

local function setAntiSticky(enabled)
    State.AntiSticky = enabled
    disconnect("AntiSticky")
    if not enabled then return end

    local function removeStickyTouch(c)
        if not c then return end
        for _, obj in ipairs(c:GetDescendants()) do
            if obj:IsA("BasePart") then
                for _, connected in ipairs(obj:GetConnectedParts()) do
                    if connected.Name == "StickyPart" then
                        for _, child in ipairs(connected:GetChildren()) do
                            if child:IsA("TouchTransmitter") or child.Name == "TouchInterest" then
                                pcall(function() child:Destroy() end)
                            end
                        end
                    end
                end
            end
        end
    end

    State.Connections.AntiSticky = RunService.Heartbeat:Connect(function()
        if State.AntiSticky then removeStickyTouch(character()) end
    end)
end

local function setAntiVoid(enabled)
    State.AntiVoid = enabled
    disconnect("AntiVoid")
    if enabled then
        local r = root()
        if r then State.RestorePosition = r.CFrame end
        State.Connections.AntiVoid = RunService.Heartbeat:Connect(function()
            if not State.AntiVoid then return end
            local r = root()
            if not r then return end
            if r.Position.Y < -80 then
                pcall(function()
                    r.AssemblyLinearVelocity = Vector3.zero
                    r.CFrame = State.RestorePosition or CFrame.new(0, 20, 0)
                end)
            elseif r.Position.Y > -20 then
                State.RestorePosition = r.CFrame
            end
        end)
    end
end

local function setAntiLag(enabled)
    State.AntiLag = enabled
    local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
    if not scripts then return end
    for _, name in ipairs({"CharacterAndBeamMove", "StickyPartsTouchDetection"}) do
        local s = scripts:FindFirstChild(name)
        if s and s:IsA("LocalScript") then
            if State.OriginalScriptStates[s] == nil then
                State.OriginalScriptStates[s] = s.Enabled
            end
            pcall(function() s.Enabled = not enabled end)
        end
    end
    if not enabled then
        for s, wasEnabled in pairs(State.OriginalScriptStates) do
            if s and s.Parent then
                pcall(function() s.Enabled = wasEnabled end)
            end
            State.OriginalScriptStates[s] = nil
        end
    end
end

local function setAntiBanana(enabled)
    State.AntiBanana = enabled
    disconnect("AntiBanana")
    if not enabled then return end

    local function disableBananaTouch(obj)
        if not obj:IsA("BasePart") then return end
        local n = obj.Name:lower()
        if n:find("banana") or n:find("peel") then
            pcall(function() obj.CanTouch = false end)
        end
    end
    for _, obj in ipairs(Workspace:GetDescendants()) do disableBananaTouch(obj) end
    State.Connections.AntiBanana = Workspace.DescendantAdded:Connect(function(obj)
        if State.AntiBanana then disableBananaTouch(obj) end
    end)
end

local function setAntiSnowball(enabled)
    State.AntiSnowball = enabled
    disconnect("AntiSnowball")
    if not enabled then return end
    State.Connections.AntiSnowball = RunService.Heartbeat:Connect(function()
        if not State.AntiSnowball then return end
        local c = character()
        local h = c and c:FindFirstChildOfClass("Humanoid")
        local r = root()
        if h and r and h.Health > 0 then
            local weld = c:FindFirstChild("WeldHRP")
            if weld then
                pcall(function()
                    h.Sit = false
                    h.AutoRotate = true
                    h:ChangeState(Enum.HumanoidStateType.GettingUp)
                end)
                tryStruggle()
            end
        end
    end)
end

local function setAutoAntiLag(enabled)
    State.AutoAntiLag = enabled
    disconnect("AutoAntiLag")
    if not enabled then return end
    local lastCheck = 0
    State.Connections.AutoAntiLag = RunService.RenderStepped:Connect(function(dt)
        if not State.AutoAntiLag or os.clock() - lastCheck < 3 then return end
        lastCheck = os.clock()
        if dt > 0 and (1 / dt) < 25 and not State.AntiLag then
            setAntiLag(true)
            notify("낮은 FPS 감지: Anti Lag을 켰습니다.")
        end
    end)
end



State.SourceFlags = {}
State.FeatureActive = {}
State.BlobmanTouch = {}
State.InvisOriginal = {}

local function setAntiBlobman(enabled)
    State.AntiBlobman = enabled
    disconnect("AntiBlobman")
    local function filter(obj)
        if not State.AntiBlobman or not obj:IsA("BasePart") then return end
        local parentName = obj.Parent and obj.Parent.Name:lower() or ""
        local objectName = obj.Name:lower()
        if parentName:find("blobman") or objectName:find("blobman") or objectName:find("blob") then
            if State.BlobmanTouch[obj] == nil then State.BlobmanTouch[obj] = obj.CanTouch end
            pcall(function() obj.CanTouch = false end)
        end
    end
    if enabled then
        for _, obj in ipairs(Workspace:GetDescendants()) do filter(obj) end
        State.Connections.AntiBlobman = Workspace.DescendantAdded:Connect(filter)
    else
        for obj, original in pairs(State.BlobmanTouch) do
            if obj and obj.Parent then pcall(function() obj.CanTouch = original end) end
            State.BlobmanTouch[obj] = nil
        end
    end
end

local function setAntiKick(enabled)
    State.AntiKick = enabled
    disconnect("AntiKick")
    if not enabled then return end
    State.Connections.AntiKick = RunService.Heartbeat:Connect(function()
        if not State.AntiKick then return end
        local c = character()
        local h = c and c:FindFirstChildOfClass("Humanoid")
        if h and h.Health > 0 then
            pcall(function()
                if h.PlatformStand then h.PlatformStand = false end
                if h:GetState() == Enum.HumanoidStateType.Physics then
                    h:ChangeState(Enum.HumanoidStateType.GettingUp)
                end
            end)
        end
    end)
end

local function setAntiInvis(enabled)
    State.AntiInvis = enabled
    disconnect("AntiInvis")
    local function reveal(c)
        if not c then return end
        for _, obj in ipairs(c:GetDescendants()) do
            if obj:IsA("BasePart") and obj.Name ~= "HumanoidRootPart" then
                if State.InvisOriginal[obj] == nil then State.InvisOriginal[obj] = obj.LocalTransparencyModifier end
                pcall(function() obj.LocalTransparencyModifier = 0 end)
            elseif obj:IsA("Decal") or obj:IsA("Texture") then
                if State.InvisOriginal[obj] == nil then State.InvisOriginal[obj] = obj.Transparency end
                pcall(function() obj.Transparency = 0 end)
            end
        end
    end
    if enabled then
        reveal(character())
        State.Connections.AntiInvis = RunService.Heartbeat:Connect(function()
            if State.AntiInvis then reveal(character()) end
        end)
    else
        for obj, original in pairs(State.InvisOriginal) do
            if obj and obj.Parent then
                pcall(function()
                    if obj:IsA("BasePart") then obj.LocalTransparencyModifier = original
                    elseif obj:IsA("Decal") or obj:IsA("Texture") then obj.Transparency = original end
                end)
            end
            State.InvisOriginal[obj] = nil
        end
    end
end

local function setFeature(feature, enabled)
    local handlers = {
        AntiGrab = setAntiGrab,
        GucciAntiGrab = setAntiGrab,
        AntiRagdoll = setAntiRagdoll,
        AntiExplosion = setAntiExplosion,
        AntiBurn = setAntiBurn,
        AntiFire = setAntiBurn,
        AntiVoid = setAntiVoid,
        AntiPaint = setAntiPaint,
        AntiPoison = setAntiPoison,
        AntiSticky = setAntiSticky,
        AntiLag = setAntiLag,
        AutoAntiLag = setAutoAntiLag,
        AntiSnowball = setAntiSnowball,
        AntiBanana = setAntiBanana,
        AntiBlobman = setAntiBlobman,
        AntiKick = setAntiKick,
        AntiKick2 = setAntiKick,
        AntiInvis = setAntiInvis,
        AntiInputLag = setAntiLag,
        AntiHoldPart = setAntiGrab,
        AntiHold = setAntiGrab,
        AntiOwnership = setAntiGrab,
        AntiOwnership2 = setAntiGrab,
        AntiBlobmanKill = setAntiRagdoll,
        AntiRagBlob = setAntiRagdoll,
        AntiKillHamburger = setAntiRagdoll,
        AntiBananaSit = setAntiBanana,
        AntiMassless = setAntiRagdoll,
        AntiInPlots = setAntiRagdoll,
        AntiBlob = setAntiBlobman,
        AntiBlobBring = setAntiBlobman,
        AntiReplicationLag = setAntiLag,
        GravityAntiKick = setAntiKick,
        ShurikenAntiKick = setAntiKick,
        KunaiAntiKick = setAntiKick,
        AntiKickItem = setAntiKick,
        AntiSetownKick = setAntiKick,
        AntiFireEffects = setAntiBurn,
        AutoReset = setAntiRagdoll,
        LoopTP = setAntiGrab,
        AntiInputDance = setAntiGrab,
        AntiSeatedAura = setAntiBanana,
        AntiStickyPartAura = setAntiSticky,
        AntiHoldHamburger = setAntiGrab,
        AntiGucciTrain = setAntiGrab,
        AntiHoldItemPart = setAntiGrab,
        FlyingReset = setAntiRagdoll,
        AntiKickPCLD = setAntiKick,
        AntiExplosionRagdoll = setAntiExplosion,
        DisableVoid = setAntiVoid,
    }
    local handler = handlers[feature]
    if handler then pcall(handler, enabled) end
end

local function normalizeFeature(feature)
    local aliases = {
        GucciAntiGrab = "AntiGrab", HouseTpAntiGrab = "AntiGrab", AntiHoldPart = "AntiGrab",
        AntiHold = "AntiGrab", AntiHoldHamburger = "AntiGrab", AntiInputDance = "AntiGrab",
        AntiGucciTrain = "AntiGrab", AntiHoldItemPart = "AntiGrab", LoopTP = "AntiGrab",
        FlyingReset = "AntiRagdoll", LoopRagdoll = "AntiRagdoll", PermRagdoll = "AntiRagdoll",
        AntiRagBlob = "AntiRagdoll", AntiBlobmanKill = "AntiRagdoll", AntiKillHamburger = "AntiRagdoll",
        AntiMassless = "AntiRagdoll", AntiInPlots = "AntiRagdoll", AutoReset = "AntiRagdoll",
        AntiFire = "AntiBurn", AntiFireEffects = "AntiBurn",
        AntiInputLag = "AntiLag", AntiReplicationLag = "AntiLag",
        AntiBlob = "AntiBlobman", AntiBlobBring = "AntiBlobman",
        AntiStickyPartAura = "AntiSticky", AntiExplosionRagdoll = "AntiExplosion",
        AntiKick2 = "AntiKick", AntiKickPCLD = "AntiKick", GravityAntiKick = "AntiKick",
        ShurikenAntiKick = "AntiKick", KunaiAntiKick = "AntiKick", AntiKickItem = "AntiKick",
        AntiSetownKick = "AntiKick",
        AntiBananaSit = "AntiBanana", AntiSeatedAura = "AntiBanana",
        DisableVoid = "AntiVoid",
    }
    return aliases[feature] or feature
end

local function makeSourceToggle(group, id, label, source, feature, default)
    local key = source .. ":" .. id
    local logicalFeature = normalizeFeature(feature)
    State.SourceFlags[key] = false
    group:AddToggle(key, {
        Text = label .. " (" .. source .. ")",
        Default = default or false,
        Tooltip = "원본 출처별 독립 토글. 일부 서로 유사한 동작은 호환 보호 함수로 연결되어 있습니다.",
        Callback = function(value)
            State.SourceFlags[key] = value
            State.FeatureVariants = State.FeatureVariants or {}
            State.FeatureVariants[logicalFeature] = State.FeatureVariants[logicalFeature] or {}
            State.FeatureVariants[logicalFeature][key] = value
            local anyFeatureVariant = false
            for _, enabled in pairs(State.FeatureVariants[logicalFeature]) do
                if enabled then anyFeatureVariant = true break end
            end
            if State.FeatureActive[logicalFeature] ~= anyFeatureVariant then
                State.FeatureActive[logicalFeature] = anyFeatureVariant
                setFeature(logicalFeature, anyFeatureVariant)
            elseif value then
                setFeature(logicalFeature, true)
            end
        end,
    })
end

