local function isGucciActiveAndNeedsSpawn()
    if Settings and Settings.Anti then
        if Settings.Anti.GucciAntiGrab or Settings.Anti.AntiGucciBlobman or Settings.Anti.AntiGucciBlobmanFast then
            return true
        end
    end
    return false
end

local function isGucciToyName(toyName)
    return toyName == "CreatureBlobman" or toyName == "SantaSleigh" or toyName == "TractorGreen"
end

local SpawnToyRF = newproxy(true)
local meta = getmetatable(SpawnToyRF)
meta.__index = function(_, k)
    if k == "InvokeServer" then
        return function(self, toyName, cf, vel, ...)
            if isGucciActiveAndNeedsSpawn() and not isGucciToyName(toyName) then
                if State and State.isRespawning then
                    return nil
                end
            end
            return rawSpawnToyRF:InvokeServer(toyName, cf, vel, ...)
        end
    end
    return rawSpawnToyRF[k]
end
meta.__newindex = function(_, k, v)
    rawSpawnToyRF[k] = v
end
meta.__tostring = function(_)
    return tostring(rawSpawnToyRF)
end
