local function findExtinguishPart()
    local map = Workspace:FindFirstChild("Map")
    local hole = map and map:FindFirstChild("Hole")
    local bigHole = hole and hole:FindFirstChild("PoisonBigHole")
    local ep = bigHole and bigHole:FindFirstChild("ExtinguishPart")
    if not ep then
        pcall(function()
            ep = Workspace.Map.Hole.PoisonBigHole:WaitForChild("ExtinguishPart", 5)
        end)
    end
    if ep then
        pcall(function()
            ep.Size = Vector3.new(0.5, 0.5, 0.5)
            ep.Transparency = 1
            if ep:FindFirstChild("Tex") then ep.Tex.Transparency = 1 end
        end)
    end
    return ep
end
local function isPlayerBurning()
    local char = LocalPlayer.Character
    if not char then return false end
    local fp = char:FindFirstChild("FirePlayerPart")
    local canBurn = fp and fp:FindFirstChild("CanBurn")
    if canBurn and canBurn.Value then return true end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if hrp then
        if hrp:FindFirstChild("FireLight") or hrp:FindFirstChild("FireParticleEmitter") then return true end
    end
    for _, part in ipairs(char:GetChildren()) do
        if part:IsA("BasePart") then
            if part:FindFirstChild("Fire") or part:FindFirstChild("FireParticleEmitter") then return true end
        end
    end
    return false
end
