local Utility = {}

function Utility.isLocalAlive()
    if State.isRespawning then return false end
    local char = LocalPlayer.Character
    if not char or not char.Parent then return false end
    local inWs = false
    local ok = pcall(function() inWs = char:IsDescendantOf(Workspace) end)
    if not ok or not inWs then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return false end
    local dead = false
    pcall(function() dead = (hum:GetState() == Enum.HumanoidStateType.Dead) end)
    if dead then return false end
    local hrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso")
    if not hrp or not hrp.Parent then return false end
    return true
end

function Utility.isAlive(plr)
    if not plr or plr == LocalPlayer then return Utility.isLocalAlive() end
    if not plr.Parent then return false end
    local char = plr.Character
    if not char or not char.Parent then return false end
    local inWs = false
    local ok = pcall(function() inWs = char:IsDescendantOf(Workspace) end)
    if not ok or not inWs then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return false end
    local dead = false
    pcall(function() dead = (hum:GetState() == Enum.HumanoidStateType.Dead) end)
    if dead then return false end
    local hrp = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso")
    if not hrp or not hrp.Parent then return false end
    return true
end

function Utility.GetPlayerCharacter()
    if not Utility.isLocalAlive() then return nil end
    return LocalPlayer.Character
end

function Utility.GetPlayerRootPart()
    if not Utility.isLocalAlive() then return nil end
    local char = LocalPlayer.Character
    return char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
end

function Utility.GetPlayerCFrame()
    local root = Utility.GetPlayerRootPart()
    return root and root.CFrame
end

function Utility.getHum(char) return char and char:FindFirstChildOfClass("Humanoid") end
function Utility.getRoot(char) return char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso")) end

