function AntiFeature.setupAntiGrabV1()
    if State.connections.antiGrabChanged then
        State.connections.antiGrabChanged:Disconnect()
        State.connections.antiGrabChanged = nil
    end
    if State.connections.antiGrabCharAdded then
        State.connections.antiGrabCharAdded:Disconnect()
        State.connections.antiGrabCharAdded = nil
    end
    local lastHolder = nil
    local function updateHolder(char)
        if not char then return end
        local head = char:FindFirstChild("Head")
        if head then
            local po = head:FindFirstChild("PartOwner")
            if po then lastHolder = tostring(po.Value) end
        end
        char.DescendantAdded:Connect(function(desc)
            if desc.Name == "PartOwner" then
                lastHolder = tostring(desc.Value)
            end
        end)
    end
    local function tryStart(isBeingHeld)
        if not isBeingHeld then return end
        if not Settings.Anti.AntiGrab then return end
        if not Utility.isLocalAlive() then return end
        if lastHolder and isProtectedPlayer(lastHolder) then return end
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        if not isHeldValue.Value then return end
        local conn
        local trackedChar = char
        conn = RunService.Heartbeat:Connect(function()
            if not Utility.isLocalAlive() then
                pcall(function() if hrp and hrp.Parent then hrp.Anchored = false end end)
                if conn then conn:Disconnect() end
                return
            end
            if not hrp or not hrp.Parent or hrp:IsDescendantOf(Workspace) == false then
                pcall(function() if hrp and hrp.Parent then hrp.Anchored = false end end)
                if conn then conn:Disconnect() end
                return
            end
            if trackedChar ~= LocalPlayer.Character then
                pcall(function() if hrp and hrp.Parent then hrp.Anchored = false end end)
                if conn then conn:Disconnect() end
                return
            end
            if isHeldValue.Value then
                pcall(function()
                    hrp.Velocity = Vector3.new()
                    hrp.Anchored = true
                    RemoteDispatcher:Fire(struggleEvent, LocalPlayer)
                    RemoteDispatcher:Fire(ragdollRemoteEvent, hrp, 0)
                end)
            else
                pcall(function() if hrp and hrp.Parent then hrp.Anchored = false end end)
                if conn then conn:Disconnect() end
            end
        end)
    end
    State.connections.antiGrabChanged = isHeldValue.Changed:Connect(tryStart)
    local char = LocalPlayer.Character
    if char and Utility.isLocalAlive() then updateHolder(char) end
    State.connections.antiGrabCharAdded = LocalPlayer.CharacterAdded:Connect(function(newChar)
        task.wait(0.6)
        if Utility.isLocalAlive() then
            updateHolder(newChar)
        end
    end)
    if isHeldValue.Value then
        tryStart(true)
    end
end
