local antiKickSec = AntiTab:Section({Text = "Anti Kick"})
antiKickSec:Toggle({Text = "Anti Replication Lag", Flag = "AntiReplicationLag", Default = false, Callback = function(v)
    Settings.Anti.AntiReplicationLag = v
    if v then
        if State.antiRepLag then return end
        State.antiRepLag = {}
        local conns = State.antiRepLag
        local LP = LocalPlayer
        local getConnections = getconnections
        local hookFn = hookfunction
        if type(getConnections) == "function" and type(hookFn) == "function" then
            local MAX_SINGLE = 32 * 1024
            local RATE_WINDOW = 1.0
            local MAX_RATE_PER_REMOTE = 256 * 1024
            local MAX_RATE_TOTAL = 1024 * 1024
            local MAX_PACKETS_PER_REMOTE = 15
            local THROTTLE_TIME = 3
            local hooked = {}
            local remoteStats = {}
            local totalBytesWindow = {bytes = 0, ts = tick()}
            local function deepSize(v, seen, depth)
                seen = seen or {}
                depth = depth or 0
                if depth > 6 then return 0 end
                local t = type(v)
                if t == "number" then return 8
                elseif t == "boolean" then return 1
                elseif t == "string" then return #v
                elseif t == "table" then
                    if seen[v] then return 0 end
                    seen[v] = true
                    local s = 0
                    for k, val in next, v do
                        s = s + deepSize(k, seen, depth + 1) + deepSize(val, seen, depth + 1)
                        if s > 1024 * 1024 then return s end
                    end
                    return s
                elseif t == "userdata" then
                    local ok, result = pcall(function()
                        local inst = v
                        if typeof(inst) == "Instance" then
                            local count = 0
                            for _ in pairs(inst:GetDescendants()) do
                                count = count + 1
                                if count > 100 then break end
                            end
                            return 256 + count * 32
                        end
                        return 512
                    end)
                    return ok and result or 512
                end
                return 0
            end
            local function findSender(...)
                local a = table.pack(...)
                for i = 1, math.min(a.n, 8) do
                    local cur = a[i]
                    while typeof(cur) == "Instance" do
                        if cur:IsA("Player") then return cur end
                        cur = cur.Parent
                    end
                end
                return nil
            end
            local function getRemoteName(remote)
                local ok, name = pcall(function() return remote:GetFullName() end)
                return ok and name or "Unknown"
            end
            local function shouldBlock(remote, a)
                local now = tick()
                local rName = getRemoteName(remote)
                if not remoteStats[rName] then
                    remoteStats[rName] = {bytes = 0, packets = 0, ts = now, throttleUntil = 0}
                end
                local stat = remoteStats[rName]
                if now - stat.ts > RATE_WINDOW then
                    stat.bytes = 0
                    stat.packets = 0
                    stat.ts = now
                end
                if now - totalBytesWindow.ts > RATE_WINDOW then
                    totalBytesWindow.bytes = 0
                    totalBytesWindow.ts = now
                end
                if stat.throttleUntil > now then return true end
                local sz = 0
                for i = 1, a.n do sz = sz + deepSize(a[i]) end
                stat.bytes = stat.bytes + sz
                stat.packets = stat.packets + 1
                totalBytesWindow.bytes = totalBytesWindow.bytes + sz
                if sz > MAX_SINGLE then
                    stat.throttleUntil = now + THROTTLE_TIME
                    return true
                end
                if stat.bytes > MAX_RATE_PER_REMOTE or stat.packets > MAX_PACKETS_PER_REMOTE then
                    stat.throttleUntil = now + THROTTLE_TIME
                    return true
                end
                if totalBytesWindow.bytes > MAX_RATE_TOTAL then
                    return true
                end
                return false
            end
            local function filterRemote(remote)
                local ok, cs = pcall(getConnections, remote.OnClientEvent)
                if not ok or type(cs) ~= "table" then return end
                for _, c in ipairs(cs) do
                    local f = c.Function
                    if type(f) == "function" and not hooked[f] then
                        local old = f
                        hooked[f] = old
                        local r = remote
                        pcall(hookFn, f, function(...)
                            local packed = table.pack(...)
                            if findSender(...) == LP then return old(...) end
                            if shouldBlock(r, packed) then return end
                            return old(...)
                        end)
                    end
                end
            end
            local function scan(c)
                if not c then return end
                for _, v in ipairs(c:GetDescendants()) do
                    if v:IsA("RemoteEvent") then pcall(filterRemote, v) end
                end
            end
            scan(ReplicatedStorage)
            scan(Workspace)
            conns.packetConn1 = ReplicatedStorage.DescendantAdded:Connect(function(v)
                if v:IsA("RemoteEvent") then pcall(filterRemote, v) end
            end)
            conns.packetConn2 = Workspace.DescendantAdded:Connect(function(v)
                if v:IsA("RemoteEvent") then pcall(filterRemote, v) end
            end)
            conns.unhook = function()
                for f, old in pairs(hooked) do pcall(hookFn, f, old) end
            end
            conns.resetStats = function() remoteStats = {}; totalBytesWindow = {bytes = 0, ts = tick()} end
        end
        local SOFT = 20000
        local CAP = 25000
        local partCount = 0
        local function isOwn(d)
            return LP.Character and d:IsDescendantOf(LP.Character)
        end
        local parts = workspace:GetDescendants()
        for _, p in ipairs(parts) do
            if p:IsA("BasePart") then partCount = partCount + 1 end
        end
        conns.cleanAdd = workspace.DescendantAdded:Connect(function(d)
            if not d:IsA("BasePart") then return end
            if isOwn(d) then return end
            partCount = partCount + 1
            if partCount > CAP then
                pcall(function() d:Destroy() end)
            elseif partCount > SOFT then
                pcall(function() d.Anchored = true; d.CanCollide = false; d.CastShadow = false end)
            end
        end)
        conns.cleanRem = workspace.DescendantRemoving:Connect(function(d)
            if d:IsA("BasePart") then
                partCount = partCount - 1
                if partCount < 0 then partCount = 0 end
            end
        end)
    else
        local conns = State.antiRepLag
        if conns then
            if conns.packetConn1 then pcall(function() conns.packetConn1:Disconnect() end) end
            if conns.packetConn2 then pcall(function() conns.packetConn2:Disconnect() end) end
            if conns.cleanAdd then pcall(function() conns.cleanAdd:Disconnect() end) end
            if conns.cleanRem then pcall(function() conns.cleanRem:Disconnect() end) end
            if conns.unhook then pcall(conns.unhook) end
        end
        State.antiRepLag = nil
    end
end})
