antiKickSec:Toggle({Text = "Shuriken Anti Kick", Flag = "ShurikenAntiKick", Default = false, Callback = function(v)
    Settings.Anti.ShurikenAntiKick = v
    if Settings.Anti.ShurikenMode == "Plot" then
        Settings.Anti.NewPlotAntiKick = v
        if v then
            if startPlotShuriken then startPlotShuriken() end
        else
            runningPlotAntiKick = false
            State.currentPlotShuriken = nil
        end
        return
    end
    if v then
        task.spawn(function()
            local plr = LocalPlayer
            local RS = ReplicatedStorage
            local setOwner = RS:WaitForChild("GrabEvents"):WaitForChild("SetNetworkOwner")
            local createGL = RS:WaitForChild("GrabEvents"):WaitForChild("CreateGrabLine")
            local destroyGL = RS:WaitForChild("GrabEvents"):WaitForChild("DestroyGrabLine")
            local stickyEvent = RS:WaitForChild("PlayerEvents"):WaitForChild("StickyPartEvent")
            local spawnRemote = RS.MenuToys.SpawnToyRemoteFunction
            local destroyrem = RS:WaitForChild("MenuToys"):WaitForChild("DestroyToy")
            local canSpawn = plr:WaitForChild("CanSpawnToy")
            local function getHRP()
                if Utility.isLocalAlive() then
                    local char = LocalPlayer.Character
                    return char and char:FindFirstChild("HumanoidRootPart")
                end
                return nil
            end
            local function ClearKunai()
                local inv = Workspace:FindFirstChild(plr.Name.."SpawnedInToys")
                if inv and destroyrem then
                    for _, v in pairs(inv:GetChildren()) do
                        if v.Name == "AntiKick" or v.Name == "NinjaShuriken" then
                            pcall(function() RemoteDispatcher:Fire(destroyrem, v) end)
                        end
                    end
                end
            end
            local function CheckForHome()
                if not workspace.PlotItems.PlayersInPlots:FindFirstChild(plr.Name) then
                    return false
                end
                for _, v in pairs(workspace.Plots:GetChildren()) do
                    local sign = v:FindFirstChild("PlotSign")
                    local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
                    if owners then
                        for _, b in pairs(owners:GetChildren()) do
                            if b.Value == plr.Name then
                                local folder = workspace.PlotItems:FindFirstChild(v.Name)
                                if folder then return true, folder end
                            end
                        end
                    end
                end
                return false
            end
            local function findExistingKunai()
                local inv = Workspace:FindFirstChild(plr.Name.."SpawnedInToys")
                local boolik, house = CheckForHome()
                local locs = {}
                if inv then locs[#locs+1] = inv end
                if boolik and house then locs[#locs+1] = house end
                for _, loc in ipairs(locs) do
                    local k = loc:FindFirstChild("AntiKick") or loc:FindFirstChild("NinjaShuriken")
                    if k then return k end
                    for _, child in ipairs(loc:GetChildren()) do
                        if child:IsA("Model") and child:FindFirstChild("StickyPart") then
                            child.Name = "AntiKick"
                            return child
                        end
                    end
                end
                return nil
            end
            local function StickKunai(kunai)
                if not kunai or not kunai:FindFirstChild("StickyPart") then return false end
                if not Utility.isLocalAlive() then return false end
                local currentHRP = getHRP()
                if not currentHRP then return false end
                if kunai:FindFirstChild("SoundPart") then
                    if not kunai.SoundPart:FindFirstChild("PartOwner") or kunai.SoundPart.PartOwner.Value ~= plr.Name then
                        pcall(function() RemoteDispatcher:Fire(setOwner, kunai.SoundPart, kunai.SoundPart.CFrame) end)
                    end
                end
                local sp = kunai.StickyPart
                if sp:FindFirstChild("StickyWeld") and sp.StickyWeld.Part1 then
                    return true
                end
                pcall(function() RemoteDispatcher:Fire(setOwner, sp, sp.CFrame) end)
                pcall(function() RemoteDispatcher:Fire(createGL, sp, Vector3.zero, sp.Position, false) end)
                pcall(function() RemoteDispatcher:Fire(destroyGL, sp) end)
                pcall(function() RemoteDispatcher:Fire(setOwner, sp, sp.CFrame) end)
                local firePart = currentHRP:FindFirstChild("FirePlayerPart") or currentHRP:WaitForChild("FirePlayerPart", 5)
                if firePart then
                    if Settings.Anti.UnsafeShuriken then
                        pcall(function() RemoteDispatcher:Fire(stickyEvent, sp, firePart, CFrame.new(0,0,0)) end)
                    else
                        pcall(function() RemoteDispatcher:Fire(stickyEvent, sp, firePart, CFrame.new(0,0,0) * CFrame.Angles(0, math.rad(90), math.rad(90))) end)
                    end
                    return true
                end
                return false
            end
            local function SpawnToy(name)
                local t = tick()
                while not canSpawn.Value do
                    if not Settings.Anti.ShurikenAntiKick or State.isRespawning or tick() - t > 5 then return nil end
                    task.wait(0.1)
                end
                local currentHRP = getHRP()
                if not currentHRP then return nil end
                local cf = currentHRP.CFrame * CFrame.new(Settings.Anti.UnsafeShuriken and 0 or 0, Settings.Anti.UnsafeShuriken and -0.5 or -1, Settings.Anti.UnsafeShuriken and 20 or 15)
                pcall(function() RemoteDispatcher:Invoke(spawnRemote, name, cf, Vector3.new(0,0,0)) end)
                local boolik, house = CheckForHome()
                local t2 = tick()
                while tick() - t2 < 4 do
                    if not Settings.Anti.ShurikenAntiKick or State.isRespawning then return nil end
                    local inv = Workspace:FindFirstChild(plr.Name.."SpawnedInToys")
                    local locs = {}
                    if inv then locs[#locs+1] = inv end
                    if boolik and house then locs[#locs+1] = house end
                    for _, loc in ipairs(locs) do
                        local k = loc:FindFirstChild("AntiKick") or loc:FindFirstChild(name) or loc:FindFirstChild("NinjaShuriken")
                        if k then
                            k.Name = "AntiKick"
                            return k
                        end
                    end
                    task.wait(0.1)
                end
                return nil
            end
            local lastSpawnT = 0
            local wasRespawning = false
            while Settings.Anti.ShurikenAntiKick do
                task.wait(0.05)
                if not Utility.isLocalAlive() then
                    wasRespawning = true
                    task.wait(0.2)
                    continue
                end
                if wasRespawning then
                    wasRespawning = false
                    lastSpawnT = 0
                    ClearKunai()
                end
                if not plr.Character or not plr.Character:FindFirstChild("Humanoid") or plr.Character.Humanoid.Health <= 0 then continue end
                local myHRP = getHRP()
                if not myHRP then continue end
                local kunai = findExistingKunai()
                local boolik, house = CheckForHome()
                if boolik and house and workspace.Plots:FindFirstChild(house.Name) then
                    local sign = workspace.Plots[house.Name]:FindFirstChild("PlotSign")
                    if sign and sign.ThisPlotsOwners.Value.TimeRemainingNum.Value > 89 and not kunai and tick() - lastSpawnT > 1 then
                        lastSpawnT = tick()
                        kunai = SpawnToy("NinjaShuriken")
                        if kunai == nil then continue end
                        kunai.Name = "AntiKick"
                        StickKunai(kunai)
                    end
                end
                if not kunai or not kunai.Parent then
                    if workspace.PlotItems.PlayersInPlots:FindFirstChild(plr.Name) then continue end
                    if tick() - lastSpawnT <= 0.8 then continue end
                    lastSpawnT = tick()
                    kunai = SpawnToy("NinjaShuriken")
                    if kunai == nil or not kunai.Parent then kunai = nil continue end
                    kunai.Name = "AntiKick"
                    StickKunai(kunai)
                    if not kunai or not kunai.Parent then kunai = nil continue end
                end
                local firePart = myHRP:FindFirstChild("FirePlayerPart") or myHRP:WaitForChild("FirePlayerPart", 5)
                if not firePart then continue end
                local sp = kunai and kunai.Parent and kunai:FindFirstChild("StickyPart")
                if not sp then ClearKunai() kunai = nil continue end
                local distToKunai = (myHRP.Position - sp.Position).Magnitude
                if distToKunai > 22 then
                    ClearKunai()
                    kunai = nil
                    continue
                end
                if Settings.Anti.UnsafeShuriken then
                    pcall(function() RemoteDispatcher:Fire(setOwner, sp, sp.CFrame) end)
                    pcall(function() RemoteDispatcher:Fire(stickyEvent, sp, firePart, CFrame.new(0,0,0)) end)
                else
                    local isStuck = sp:FindFirstChild("StickyWeld") and sp.StickyWeld.Part1 and true or false
                    if not isStuck then
                        local attemptStart = tick()
                        while tick() - attemptStart < 2.5 do
                            if not Settings.Anti.ShurikenAntiKick or State.isRespawning then break end
                            if not kunai or not kunai.Parent then kunai = nil break end
                            sp = kunai:FindFirstChild("StickyPart")
                            if not sp then kunai = nil break end
                            if sp:FindFirstChild("StickyWeld") and sp.StickyWeld.Part1 then isStuck = true break end
                            StickKunai(kunai)
                            task.wait(0.15)
                        end
                    end
                    if isStuck then
                        for _, obj in pairs(kunai:GetChildren()) do
                            if obj:IsA("BasePart") then
                                obj.CanTouch = false; obj.CanCollide = false; obj.CanQuery = false
                            end
                        end
                    end
                end
                if not kunai:FindFirstChild("Highlight") then
                    local high = Instance.new("Highlight", kunai)
                    high.FillColor = Color3.fromRGB(50, 50, 50)
                    high.OutlineColor = Color3.fromRGB(100, 100, 100)
                    high.Adornee = kunai
                end
                kunai.Name = "AntiKick"
            end
            ClearKunai()
        end)
    else
        local function ClearKunai()
            local plr = LocalPlayer
            local inv = Workspace:FindFirstChild(plr.Name.."SpawnedInToys")
            local destroyrem = ReplicatedStorage:WaitForChild("MenuToys"):WaitForChild("DestroyToy")
            if inv and destroyrem then
                for _, v in pairs(inv:GetChildren()) do
                    if v.Name == "AntiKick" or v.Name == "NinjaShuriken" then
                        pcall(function() RemoteDispatcher:Fire(destroyrem, v) end)
                    end
                end
            end
        end
        ClearKunai()
    end
end})
antiKickSec:Toggle({Text = "Unsafe Shuriken", Flag = "UnsafeShuriken", Default = false, Callback = function(v)
    if v and Settings.Anti.ShurikenMode ~= "Default" then return end
    Settings.Anti.UnsafeShuriken = v
end})
startPlotShuriken = function()
    if runningPlotAntiKick then return end
    runningPlotAntiKick = true
    task.spawn(function()
        local plr = LocalPlayer
        local RS = ReplicatedStorage
        local setOwner = setNetworkOwnerEvent
        local stickyEvent = StickyPartEvent
        local spawnRemote = SpawnToyRF
        local GE = RS:WaitForChild("GrabEvents")
        local createGL = GE:WaitForChild("CreateGrabLine")
        local destroyGL = GE:WaitForChild("DestroyGrabLine")
        local canSpawn = plr:WaitForChild("CanSpawnToy")
        local function getHRP()
            if Utility.isLocalAlive() then
                local char = LocalPlayer.Character
                return char and char:FindFirstChild("HumanoidRootPart")
            end
            return nil
        end
        local function isPlotFree(plot)
            local sign = plot:FindFirstChild("PlotSign")
            if not sign then return false end
            local limit = sign:FindFirstChild("ToysLimitNum")
            if limit and limit:IsA("IntValue") and limit.Value == 0 then
                return true
            end
            local owners = sign:FindFirstChild("ThisPlotsOwners")
            if owners then
                for _, desc in ipairs(owners:GetDescendants()) do
                    if desc.Name == "TimeRemainingNum" then
                        local valObj = desc.Parent
                        if valObj and valObj:IsA("StringValue") and valObj.Value ~= "" and valObj.Value ~= plr.Name then
                            return false
                        end
                    end
                end
            end
            return true
        end
        local function checkMyPlot()
            for i = 1, 5 do
                local plot = Workspace.Plots:FindFirstChild("Plot"..i)
                if plot then
                    local sign = plot:FindFirstChild("PlotSign")
                    if sign then
                        for _, desc in ipairs(sign:GetDescendants()) do
                            if desc.Name == "TimeRemainingNum" then
                                local valObj = desc.Parent
                                if valObj and valObj:IsA("StringValue") and valObj.Value == plr.Name then
                                    return plot
                                end
                            end
                        end
                    end
                end
            end
            return nil
        end
        local function claimPlot(plot)
            local sign = plot:FindFirstChild("PlotSign")
            if not sign then return end
            local grabPart = nil
            for _, desc in ipairs(sign:GetDescendants()) do
                if desc:IsA("BasePart") and desc.Name == "PlusGrabPart" then
                    grabPart = desc
                    break
                end
            end
            if grabPart then
                local hrp = getHRP()
                local hum = plr.Character:FindFirstChild("Humanoid")
                if hum then hum.Sit = false end
                hrp.CFrame = grabPart.CFrame * CFrame.new(0, 3, 0)
                hrp.Velocity = Vector3.zero
                task.wait(0.2)
                local claimTimeout = tick()
                while Settings.Anti.NewPlotAntiKick and not checkMyPlot() do
                    pcall(function() RemoteDispatcher:Fire(setOwner, grabPart, grabPart.CFrame) end)
                    task.wait(0.1)
                    if tick() - claimTimeout > 5 then break end
                end
            end
        end
        local function StickKunai(kunai)
            if not kunai or not kunai:FindFirstChild("StickyPart") then return end
            local currentHRP = getHRP()
            if kunai:FindFirstChild("SoundPart") then
                if not kunai.SoundPart:FindFirstChild("PartOwner") or kunai.SoundPart.PartOwner.Value ~= plr.Name then
                    pcall(function() RemoteDispatcher:Fire(setOwner, kunai.SoundPart, kunai.SoundPart.CFrame) end)
                end
            end
            local sp = kunai.StickyPart
            local alreadyStuck = sp:FindFirstChild("StickyWeld") and sp.StickyWeld.Part1 and true or false
            if alreadyStuck then return end
            if not Settings.Anti.UnsafeShuriken then
                pcall(function() RemoteDispatcher:Fire(setOwner, sp, sp.CFrame) end)
            end
            pcall(function() RemoteDispatcher:Fire(createGL, sp, Vector3.zero, sp.Position, false) end)
            pcall(function() RemoteDispatcher:Fire(destroyGL, sp) end)
            if not Settings.Anti.UnsafeShuriken then
                pcall(function() RemoteDispatcher:Fire(setOwner, sp, sp.CFrame) end)
            end
            local firePart = currentHRP:FindFirstChild("FirePlayerPart") or currentHRP:WaitForChild("FirePlayerPart", 5)
            if firePart then
                pcall(function()
                    RemoteDispatcher:Fire(stickyEvent, sp, firePart, CFrame.new(0,0,0) * CFrame.Angles(0,math.rad(90),math.rad(90)))
                end)
            end
        end
        local function SpawnToy(name, currentPlotName)
            local t = tick()
            while not canSpawn.Value and Settings.Anti.NewPlotAntiKick do
                if tick() - t > 5 then return nil end
                task.wait(0.1)
            end
            local currentHRP = getHRP()
            local spawnCF = nil
            local forward = currentHRP.CFrame.LookVector
            local spawnPositions = {
                currentHRP.CFrame * CFrame.new(2, 0, 5),
                currentHRP.CFrame * CFrame.new(-2, 0, 5),
                currentHRP.CFrame * CFrame.new(0, 0, 5),
                currentHRP.CFrame * CFrame.new(2, 0, 3),
                currentHRP.CFrame * CFrame.new(-2, 0, 3),
                currentHRP.CFrame * CFrame.new(0, 0, 3),
            }
            for _, cf in ipairs(spawnPositions) do
                local ray = Workspace:Raycast(cf.Position, Vector3.new(0, -50, 0))
                if not ray then
                    spawnCF = cf
                    break
                end
            end
            if not spawnCF then
                spawnCF = currentHRP.CFrame * CFrame.new(0, 0, 5)
            end
            task.spawn(function()
                pcall(function()
                    RemoteDispatcher:Invoke(spawnRemote, name, spawnCF, Vector3.new(0,0,0))
                end)
            end)
            local folder = Workspace.PlotItems:FindFirstChild(currentPlotName)
            if folder then
                return folder:WaitForChild(name, 2)
            end
            return nil
        end
        local savedPosition = nil
        local activeKunai = nil
        local lastChar = nil
        local function findExistingValidKunai()
            local hrp = getHRP()
            if not hrp then return nil end
            local plotItemsFolder = Workspace:FindFirstChild("PlotItems")
            local inv = Workspace:FindFirstChild(plr.Name.."SpawnedInToys")
            local currentPlot = checkMyPlot()
            local myPlotFolder = plotItemsFolder and currentPlot and plotItemsFolder:FindFirstChild(currentPlot.Name)
            local locs = {}
            if inv then locs[#locs+1] = inv end
            if myPlotFolder then locs[#locs+1] = myPlotFolder end
            local validKunai = nil
            local allKunai = {}
            for _, loc in ipairs(locs) do
                for _, k in ipairs(loc:GetChildren()) do
                    if k.Name == "AntiKick" or k.Name == "NinjaShuriken" then
                        if k:FindFirstChild("StickyPart") then
                            allKunai[#allKunai+1] = k
                            local sp = k.StickyPart
                            local isStuck = sp:FindFirstChild("StickyWeld") and sp.StickyWeld.Part1
                            local dist = (hrp.Position - sp.Position).Magnitude
                            if isStuck and dist < 8 then
                                validKunai = k
                            end
                        end
                    end
                end
            end
            if validKunai then
                for _, k in ipairs(allKunai) do
                    if k ~= validKunai then
                        pcall(function() RemoteDispatcher:Fire(DeleteToyRE, k) end)
                    end
                end
                return validKunai
            end
            return nil
        end
        while Settings.Anti.NewPlotAntiKick and runningPlotAntiKick do
            task.wait(0.05)
            local char = plr.Character
            if not char or not char:FindFirstChild("Humanoid") or char.Humanoid.Health <= 0 then
                activeKunai = nil
                savedPosition = nil
                lastChar = char
                continue
            end
            if char ~= lastChar then
                lastChar = char
                activeKunai = nil
                savedPosition = nil
            end
            local hrp = getHRP()
            local currentPlot = checkMyPlot()
            if not currentPlot then
                if not savedPosition then savedPosition = hrp.CFrame end
                for i = 1, 5 do
                    local plot = Workspace.Plots:FindFirstChild("Plot"..i)
                    if plot and isPlotFree(plot) then
                        claimPlot(plot)
                        currentPlot = checkMyPlot()
                        if currentPlot then break end
                    end
                end
                if not currentPlot then
                    activeKunai = nil
                    continue
                end
            end
            local plotItemsFolder = Workspace:FindFirstChild("PlotItems")
            local myPlotFolder = plotItemsFolder and plotItemsFolder:FindFirstChild(currentPlot.Name)
            if not activeKunai then
                local existing = findExistingValidKunai()
                if existing then
                    activeKunai = existing
                    State.currentPlotShuriken = existing
                    for _, obj in pairs(existing:GetChildren()) do
                        if obj:IsA("BasePart") then
                            obj.CanTouch = false
                            obj.CanCollide = false
                            obj.CanQuery = false
                        end
                    end
                    if not existing:FindFirstChild("Highlight") then
                        local high = Instance.new("Highlight", existing)
                        high.FillColor = Color3.fromRGB(50, 50, 50)
                        high.OutlineColor = Color3.fromRGB(100, 100, 100)
                        high.Adornee = existing
                    end
                    existing.Name = "AntiKick"
                    continue
                end
            end
            if activeKunai then
                if not activeKunai.Parent or not activeKunai:FindFirstChild("StickyPart") then
                    activeKunai = nil
                    State.currentPlotShuriken = nil
                else
                    local sp = activeKunai:FindFirstChild("StickyPart")
                    if sp then
                        local dist = (hrp.Position - sp.Position).Magnitude
                        if dist > 30 then
                            pcall(function() RemoteDispatcher:Fire(DeleteToyRE, activeKunai) end)
                            activeKunai = nil
                            State.currentPlotShuriken = nil
                        elseif activeKunai.StickyPart.CanTouch == false then
                            State.currentPlotShuriken = activeKunai
                            task.wait(0.05)
                            continue
                        end
                    else
                        activeKunai = nil
                        State.currentPlotShuriken = nil
                    end
                end
            end
            if not savedPosition then savedPosition = hrp.CFrame end
            local sign = currentPlot:FindFirstChild("PlotSign")
            if sign then
                local hum = char:FindFirstChild("Humanoid")
                if hum then hum.Sit = false end
                local grabPart = nil
                for _, desc in ipairs(sign:GetDescendants()) do
                    if desc:IsA("BasePart") and desc.Name == "PlusGrabPart" then
                        grabPart = desc
                        break
                    end
                end
                if grabPart then
                    hrp.CFrame = grabPart.CFrame * CFrame.new(0, 3, 0)
                else
                    hrp.CFrame = sign:GetPivot() * CFrame.new(0, 0, 10)
                end
                hrp.Velocity = Vector3.zero
                task.wait(0.25)
            end
            if myPlotFolder then
                local stale = myPlotFolder:FindFirstChild("AntiKick") or myPlotFolder:FindFirstChild("NinjaShuriken")
                if stale then
                    pcall(function() RemoteDispatcher:Fire(DeleteToyRE, stale) end)
                end
            end
            local kunai = SpawnToy("NinjaShuriken", currentPlot.Name)
            if kunai then
                kunai.Name = "AntiKick"
                activeKunai = kunai
                State.currentPlotShuriken = kunai
            else
                activeKunai = nil
                State.currentPlotShuriken = nil
            end
            if kunai and kunai.Parent and kunai:FindFirstChild("StickyPart") then
                local sp = kunai.StickyPart
                local isStuck = sp:FindFirstChild("StickyWeld") and sp.StickyWeld.Part1
                if not isStuck then
                    StickKunai(kunai)
                end
                local attemptStart = tick()
                while Settings.Anti.NewPlotAntiKick and runningPlotAntiKick do
                    if not kunai or not kunai.Parent or not kunai:FindFirstChild("StickyPart") then
                        activeKunai = nil
                        State.currentPlotShuriken = nil
                        break
                    end
                    sp = kunai.StickyPart
                    isStuck = sp:FindFirstChild("StickyWeld") and sp.StickyWeld.Part1
                    if isStuck then
                        break
                    end
                    if (hrp.Position - sp.Position).Magnitude >= 20 then
                        break
                    end
                    if tick() - attemptStart >= 2.5 then
                        break
                    end
                    StickKunai(kunai)
                    kunai.Name = "AntiKick"
                    task.wait(0.15)
                end
                if kunai and kunai.Parent and kunai:FindFirstChild("StickyPart") then
                    for _, obj in pairs(kunai:GetChildren()) do
                        if obj:IsA("BasePart") then
                            obj.CanTouch = false
                            obj.CanCollide = false
                            obj.CanQuery = false
                        end
                    end
                    if not kunai:FindFirstChild("Highlight") then
                        local high = Instance.new("Highlight", kunai)
                        high.FillColor = Color3.fromRGB(50, 50, 50)
                        high.OutlineColor = Color3.fromRGB(100, 100, 100)
                        high.Adornee = kunai
                    end
                    kunai.Name = "AntiKick"
                    activeKunai = kunai
                    State.currentPlotShuriken = kunai
                else
                    activeKunai = nil
                    State.currentPlotShuriken = nil
                end
            else
                activeKunai = nil
                State.currentPlotShuriken = nil
            end
            if savedPosition then
                task.wait(0.05)
                hrp.CFrame = savedPosition
                hrp.Velocity = Vector3.zero
                savedPosition = nil
            end
        end
    end)
end
antiKickSec:Toggle({Text = "Kunai Anti Kick", Flag = "AntiKickKunai", Default = false, Callback = function(enabled)
    Settings.Anti.AntiKickKunai = enabled
    if enabled then
        AntiFeature.createKunaiMessageGui()
        AntiFeature.attachKunai(false)
        if State.loops.kunaiCheck then task.cancel(State.loops.kunaiCheck) end
                State.loops.kunaiCheck = task.spawn(function()
            local plr = LocalPlayer
            local failCount = 0
            while Settings.Anti.AntiKickKunai do
                task.wait(0.2)
                if not Utility.isLocalAlive() then continue end
                local char = Utility.GetPlayerCharacter()
                if not char then continue end
                local leg = AntiFeature.getRightLeg(char)
                if not leg then continue end
                local hrp = char:FindFirstChild("HumanoidRootPart")
                if not hrp then continue end
                local myActive = State.currentKunai
                if myActive and (not myActive.Parent or not myActive:FindFirstChild("StickyPart")) then
                    myActive = nil
                    State.currentKunai = nil
                end
                if not myActive then
                    AntiFeature.attachKunai(true)
                    task.wait(0.3)
                    myActive = State.currentKunai
                end
                if not myActive or not myActive:FindFirstChild("StickyPart") then continue end
                local sticky = myActive:FindFirstChild("StickyPart")
                if not sticky then continue end
                local weld = sticky:FindFirstChild("StickyWeld")
                local weldPart = weld and weld.Part1
                if weld and weldPart == leg then
                    failCount = 0
                    continue
                end
                if (sticky.Position - leg.Position).Magnitude >= 20 then
                    pcall(function() RemoteDispatcher:Fire(DeleteToyRE, myActive) end)
                    State.currentKunai = nil
                    myActive = nil
                    task.wait(0.2)
                    continue
                end
                pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, sticky, sticky.CFrame) end)
                pcall(function() RemoteDispatcher:Fire(grabEventsFolder.CreateGrabLine, sticky, Vector3.zero, sticky.Position, false) end)
                pcall(function() RemoteDispatcher:Fire(destroyGrabLineEvent, sticky) end)
                pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, sticky, leg.CFrame) end)
                local attachCFrame = CFrame.new(0.0490287527, 0.5, 0, 0, 0.00739139877, -0.999561906, -0.998452604, -0.0478846952, 0.0282763243, -0.0476547107, 0.99882561, 0)
                pcall(function() RemoteDispatcher:Fire(StickyPartEvent, sticky, leg, attachCFrame) end)
                task.wait(0.2)
                local weld2 = sticky:FindFirstChild("StickyWeld")
                if weld2 and weld2.Part1 == leg then
                    failCount = 0
                    continue
                end
                failCount = failCount + 1
                if failCount > 3 then
                    AntiFeature.attachKunai(true)
                    task.wait(0.3)
                    failCount = 0
                end
            end
        end)
    else
        if State.loops.kunaiCheck then task.cancel(State.loops.kunaiCheck) State.loops.kunaiCheck = nil end
        if State.currentKunai and State.currentKunai.Parent then
        RemoteDispatcher:Fire(DeleteToyRE, State.currentKunai)
        end
        State.currentKunai = nil
        if kunaiTextLabel then kunaiTextLabel.Text = "" kunaiTextLabel.TextTransparency = 1 end
    end
end})
