do
    local AntiKickItemActive = false
    local MyPCLD = nil
    local pcldConn = nil
    local pcldListConn = nil
    local pcldDescConn = nil
    local LoopSetOwnActive = false
    local loopSetOwnConn = nil
    local function deleteItem()
        pcall(function()
            local inv = workspace:FindFirstChild(LocalPlayer.Name.."SpawnedInToys")
            local destroyToy = DeleteToyRE
            if inv and destroyToy then
                for _, v in pairs(inv:GetChildren()) do
                    if v.Name == "AntiKickItem" then
                        destroyToy:FireServer(v)
                    end
                end
            end
        end)
    end
    local function setupLoopSetOwn()
        if loopSetOwnConn then return end
