antiMiscSec:Toggle({Text = "Auto Anti Lag", Flag = "AutoAntiLag", Default = true, Callback = function(v)
    autoAntiLagEnabled = v
    autoAntilagActive = false
    autoAntilagFpsHoldUntil = 0
    refreshAntiLagScript()
    if v then
        task.spawn(function()
            autoAntilagLastCheck = tick()
            while autoAntiLagEnabled and task.wait(0.25) do
                if Settings.Anti.AutoAntiLagMethod == "Low FPS" then
                    local fps = autoAntilagCurrentFPS
                    if fps < 15 then
                        if not autoAntilagActive then
                            autoAntilagActive = true
                            refreshAntiLagScript()
                            pcall(function()
                                library:Notify({
                                    Title = "EndorisFTAP Reborn",
                                    Description = "Your FPS is less than 15, Anti Lag Enabled",
                                    Time = 6.5,
                                })
                            end)
                        end
                        autoAntilagFpsHoldUntil = tick() + 30
                    elseif autoAntilagActive then
                        if autoAntilagFpsHoldUntil == 0 then
                            autoAntilagFpsHoldUntil = tick() + 30
                        elseif tick() >= autoAntilagFpsHoldUntil then
                            autoAntilagActive = false
                            autoAntilagFpsHoldUntil = 0
                            refreshAntiLagScript()
                        end
                    end
                else
                    local now = tick()
                    local dt = math.min(now - autoAntilagLastCheck, 3)
                    autoAntilagLastCheck = now
                    local window = math.max(dt, 1)
                    local worst, worstRate = nil, 0
                    for name, list in pairs(autoAntilagPlayerTimes) do
                        local i = 1
                        while i <= #list do
                            if now - list[i] > window then
                                table.remove(list, i)
                            else
                                i = i + 1
                            end
                        end
                        if #list == 0 then
                            autoAntilagPlayerTimes[name] = nil
                        elseif #list > worstRate then
                            worstRate = #list
                            worst = name
                        end
                    end
                    if autoAntilagActive then
                        if worstRate >= AUTO_ANTILAG_OFF then
                            autoAntilagLastSpam = now
                        elseif now - autoAntilagLastSpam >= AUTO_ANTILAG_COOLDOWN then
                            autoAntilagActive = false
                            autoAntilagLagger = nil
                            refreshAntiLagScript()
                        end
                    elseif worst and worstRate >= AUTO_ANTILAG_ON then
                        autoAntilagActive = true
                        autoAntilagLagger = Players:FindFirstChild(worst)
                        autoAntilagLastSpam = now
                        refreshAntiLagScript()
                        pcall(function()
                            library:Notify({
                                Title = "EndorisFTAP Reborn",
                                Description = ((autoAntilagLagger and autoAntilagLagger.DisplayName) or worst) .. " Lagged Server",
                                Time = 6.5,
                            })
                        end)
                    end
                end
            end
        end)
    else
        autoAntilagPlayerTimes = {}
        autoAntilagLastSpam = 0
        autoAntilagLagger = nil
        autoAntilagFpsHoldUntil = 0
        autoAntilagLastCheck = 0
        refreshAntiLagScript()
    end
end})
