antiMiscSec:Toggle({Text = "Loop Ragdoll", Flag = "LoopRagdoll", Default = false, Callback = function(v)
    Settings.Anti.LoopRagdoll = v
    if v then
        if State.loopRagdollTask then pcall(function() task.cancel(State.loopRagdollTask) end) State.loopRagdollTask = nil end
        if State.loopRagdollCharAdded then State.loopRagdollCharAdded:Disconnect() State.loopRagdollCharAdded = nil end
        State.loopRagdollTask = task.spawn(function()
            local function cleanupHRPMovers(char)
                if not char then return end
                local hrp = char:FindFirstChild("HumanoidRootPart")
                if hrp then
                    for _, obj in ipairs(hrp:GetChildren()) do
                        if obj.Name == "LoopRagdollGyro" then
                            pcall(function() obj:Destroy() end)
                        end
                    end
                end
            end
            local function stabilizeHRP(r)
                if not r or not r.Parent or not Utility.isLocalAlive() then return end
                local gy = r:FindFirstChild("LoopRagdollGyro")
                if not gy then
                    gy = Instance.new("BodyGyro")
                    gy.Name = "LoopRagdollGyro"
                    gy.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
                    gy.P = 30000
                    gy.D = 500
                    gy.Parent = r
                end
                gy.CFrame = CFrame.new(r.Position) * (r.CFrame - r.CFrame.Position)
                r.AssemblyLinearVelocity = Vector3.new(r.AssemblyLinearVelocity.X, 0, r.AssemblyLinearVelocity.Z)
            end
            while Settings.Anti.LoopRagdoll do
                task.wait(0.05)
                if not Utility.isLocalAlive() then
                    local c = LocalPlayer.Character
                    if c then cleanupHRPMovers(c) end
                    continue
                end
                local c = LocalPlayer.Character
                local h = c and c:FindFirstChildOfClass("Humanoid")
                local r = c and c:FindFirstChild("HumanoidRootPart")
                if not h or not r or h.Health <= 0 or State.isRespawning then
                    if c then cleanupHRPMovers(c) end
                    continue
                end
                h.BreakJointsOnDeath = false
                RemoteDispatcher:Fire(ragdollRemoteEvent, r, 2)
                h.PlatformStand = true
                stabilizeHRP(r)
                local ragdollEnd = tick() + (Settings.Anti.LoopRagdollSpeed or 0.15)
                while Settings.Anti.LoopRagdoll and tick() < ragdollEnd do
                    task.wait()
                    if not Utility.isLocalAlive() then break end
                    c = LocalPlayer.Character
                    h = c and c:FindFirstChildOfClass("Humanoid")
                    r = c and c:FindFirstChild("HumanoidRootPart")
                    if not h or not r or h.Health <= 0 or State.isRespawning then break end
                    stabilizeHRP(r)
                end
                if not Utility.isLocalAlive() then
                    if c then cleanupHRPMovers(c) end
                    continue
                end
                c = LocalPlayer.Character
                h = c and c:FindFirstChildOfClass("Humanoid")
                r = c and c:FindFirstChild("HumanoidRootPart")
                if not h or not r or h.Health <= 0 or State.isRespawning then
                    if c then cleanupHRPMovers(c) end
                    continue
                end
                RemoteDispatcher:Fire(ragdollRemoteEvent, r, 0)
                h.PlatformStand = false
                h:ChangeState(Enum.HumanoidStateType.GettingUp)
                cleanupHRPMovers(c)
            end
            local c = LocalPlayer.Character
            if c then cleanupHRPMovers(c) end
        end)
        if State.loopRagdollCharAdded then State.loopRagdollCharAdded:Disconnect() end
        State.loopRagdollCharAdded = LocalPlayer.CharacterAdded:Connect(function(newChar)
            if not Settings.Anti.LoopRagdoll then
                if State.loopRagdollCharAdded then State.loopRagdollCharAdded:Disconnect() State.loopRagdollCharAdded = nil end
                return
            end
            task.wait(0.6)
            if not Settings.Anti.LoopRagdoll or not Utility.isLocalAlive() then return end
            local h = newChar:WaitForChild("Humanoid", 5)
            local r = newChar:WaitForChild("HumanoidRootPart", 5)
            if h and r and h.Health > 0 and Utility.isLocalAlive() then
                h.BreakJointsOnDeath = false
                RemoteDispatcher:Fire(ragdollRemoteEvent, r, 2)
                h.PlatformStand = true
                pcall(function()
                    local gy = Instance.new("BodyGyro")
                    gy.Name = "LoopRagdollGyro"
                    gy.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
                    gy.P = 30000
                    gy.D = 500
                    gy.CFrame = r.CFrame
                    gy.Parent = r
                end)
            end
        end)
    else
        if State.loopRagdollTask then pcall(function() task.cancel(State.loopRagdollTask) end) State.loopRagdollTask = nil end
        if State.loopRagdollCharAdded then State.loopRagdollCharAdded:Disconnect() State.loopRagdollCharAdded = nil end
        local c = LocalPlayer.Character
        local h = c and c:FindFirstChildOfClass("Humanoid")
        local r = c and c:FindFirstChild("HumanoidRootPart")
        if h and r and h.Health > 0 then
            RemoteDispatcher:Fire(ragdollRemoteEvent, r, 0)
            h.PlatformStand = false
            h:ChangeState(Enum.HumanoidStateType.GettingUp)
            for _, obj in ipairs(r:GetChildren()) do
                if obj.Name == "LoopRagdollGyro" then
                    pcall(function() obj:Destroy() end)
                end
            end
        end
    end
end})
