                State.antiRagBlobConns["ARSeat"] = hum:GetPropertyChangedSignal("SeatPart"):Connect(function()
                    if not Utility.isLocalAlive() then return end
                    if hum.SeatPart and hum.SeatPart.Parent and hum.SeatPart.Parent.Name == "CreatureBlobman" and not isGucciBlobman(hum.SeatPart.Parent) and not RagdolledSit then
                        RagdolledSit = true
                        local Seat = hum.SeatPart
                        local waitStart = tick()
                        while not hum.Sit do
                            if not Utility.isLocalAlive() or tick() - waitStart > 3 then RagdolledSit = false return end
                            task.wait(0.05)
                        end
                        RemoteDispatcher:Fire(RagdollRemote, HRP, 3)
                        waitStart = tick()
                        while not (hum:FindFirstChild("Ragdolled") and hum.Ragdolled.Value) and not hum.Sit do
                            if not Utility.isLocalAlive() or tick() - waitStart > 3 then RagdolledSit = false return end
                            task.wait(0.05)
                        end
                        task.wait(0.4)
                        if not Utility.isLocalAlive() then RagdolledSit = false return end
                        hum.Sit = false
                        if Seat and Seat:IsA("Part") then Seat:Sit(hum) end
                        task.delay(0.25, function()
                            while hum and hum.SeatPart and Utility.isLocalAlive() do
                                if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                                    RemoteDispatcher:Fire(RagdollRemote, LocalPlayer.Character.HumanoidRootPart, 1)
                                end
                                task.wait(0.05)
                            end
                            RagdolledSit = false
                        end)
                    end
                end)
            end
        end
        if Utility.isLocalAlive() and LocalPlayer.Character then setupCharacter(LocalPlayer.Character) end
        DiscAR("ARChar")
        State.antiRagBlobConns["ARChar"] = LocalPlayer.CharacterAdded:Connect(function(newChar)
            task.wait(0.6)
            if Utility.isLocalAlive() then setupCharacter(newChar) end
        end)
    else
        for _, conn in pairs(State.antiRagBlobConns) do if conn then conn:Disconnect() end end
        State.antiRagBlobConns = {}
    end
end})
