antiMiscSec:Toggle({Text = "Anti Fire", Flag = "AntiFire", Default = false, Callback = function(enabled)
    Settings.Anti.AntiFire = enabled
    pcall(function()
        if enabled then
            if State.antiFireConn then State.antiFireConn:Disconnect() State.antiFireConn = nil end
            if State.antiFireTask then task.cancel(State.antiFireTask) State.antiFireTask = nil end
            local function stopAntiFire()
                if State.antiFireConn then State.antiFireConn:Disconnect() State.antiFireConn = nil end
                if State.antiFireTask then task.cancel(State.antiFireTask) State.antiFireTask = nil end
            end
            State.antiFireTask = task.spawn(function()
                local extinguishPart = findExtinguishPart()
                if not extinguishPart then
                    for _ = 1, 60 do
                        task.wait(0.1)
                        if not Settings.Anti.AntiFire then return end
                        extinguishPart = findExtinguishPart()
                        if extinguishPart then break end
                    end
                end
                if not extinguishPart then return end
                State.antiFireOriginalCF = extinguishPart.CFrame
                local lastFireUpdate = 0
                State.antiFireLastUpdate = 0
                State.antiFireConn = RunService.Heartbeat:Connect(function()
                    if not Settings.Anti.AntiFire then return end
                    if not extinguishPart.Parent then
                        local newEP = findExtinguishPart()
                        if newEP then extinguishPart = newEP end
                    end
                    local now = tick()
                    if now - lastFireUpdate < 0.05 then return end
                    lastFireUpdate = now
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild("HumanoidRootPart")
                    if not root then return end
                    if isPlayerBurning() then
                        local fp = char:FindFirstChild("FirePlayerPart") or root
                        extinguishPart.CFrame = fp.CFrame
                        if firetouchinterest then
                            pcall(function()
                                firetouchinterest(fp, extinguishPart, 0)
                                firetouchinterest(fp, extinguishPart, 1)
                            end)
                        end
                    elseif State.antiFireOriginalCF then
                        extinguishPart.CFrame = State.antiFireOriginalCF
                    end
                end)
            end)
            State.antiFireStop = stopAntiFire
        else
            if State.antiFireTask then task.cancel(State.antiFireTask) State.antiFireTask = nil end
            if State.antiFireConn then State.antiFireConn:Disconnect() State.antiFireConn = nil end
            if State.antiFireOriginalCF then
                local ep = findExtinguishPart()
                if ep then ep.CFrame = State.antiFireOriginalCF end
            end
        end
    end)
end})
