antiMiscSec:Toggle({Text = "Anti Poison", Flag = "AntiPoison", Default = false, Callback = function(v)
    Settings.Anti.AntiPoison = v
    local poisonFolders = {
        workspace.Map.Hole.PoisonBigHole,
        workspace.Map.Hole.PoisonSmallHole,
    }
    for _, folder in pairs(poisonFolders) do
        if not folder then
            continue
        end
        for _, obj in pairs(folder:GetDescendants()) do
            if obj:IsA("Script") or obj:IsA("LocalScript") then
                obj.Disabled = v
            end
            if obj:IsA("BasePart") then
                if v then
                    obj.CanTouch = false
                    obj.CanCollide = false
                else
                    obj.CanTouch = true
                    obj.CanCollide = true
                end
            end
        end
    end
end})
