                local dist = (sticky.Position - curHRP.Position).Magnitude
                if dist < 2 then continue end
                local savedCF = curHRP.CFrame
                curHRP.CFrame = sticky.CFrame * CFrame.new(0, 0, 4)
                task.wait(0.2)
                if kunaiFrame % 3 == 0 then
