antiBlobSec:Button({Text = "Anti Gucci Fast", Callback = function()
    task.spawn(function()
        local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        local hum = char:WaitForChild("Humanoid")
        local hrp = char:WaitForChild("HumanoidRootPart")
        local savedHRPCF = hrp.CFrame
        hum.Sit = true
        task.wait(0.02)
        hum.Sit = false
        task.spawn(function()
            local t = tick()
            while tick() - t < 0.8 do
                for _, v in pairs(char:GetChildren()) do
                    if v:IsA("BasePart") then v.Velocity = Vector3.new() end
                end
                task.wait(0.01)
            end
        end)
        local spawnCF = CFrame.new(520.6094970703125, 70.42938995361328, -167.30728149414062)
        task.spawn(function() RemoteDispatcher:Invoke(SpawnToyRF, "CreatureBlobman", spawnCF, Vector3.new(0, -15.716, 0)) end)
        local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys", true)
        local invWait = tick()
        while tick() - invWait < 3 and not inv do
            inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys", true)
            if inv then break end
            task.wait(0.1)
        end
        local Blob = nil
        local conn
        if inv then
            Blob = inv:FindFirstChild("CreatureBlobman")
            if not Blob then
                conn = inv.ChildAdded:Connect(function(toy)
                    if toy.Name == "CreatureBlobman" and toy:IsA("Model") then
                        markGucciBlobman(toy)
                        Blob = toy
                    end
                end)
            end
        end
        local blobWait = tick()
        while not Blob do
            if tick() - blobWait > 5 then break end
            task.wait(0.01)
        end
        if conn then conn:Disconnect() end
        if not Blob then
            local scanWait = tick()
            while tick() - scanWait < 2 do
                local cand = Workspace:FindFirstChild("CreatureBlobman", true)
                if cand and cand:IsA("Model") then
                    local hd = cand:FindFirstChild("Head")
                    local isOurs = (not hd) or (not hd:FindFirstChild("PartOwner")) or hd.PartOwner.Value == LocalPlayer.Name
                    if isOurs then
                        Blob = cand
                        break
                    end
                end
                task.wait(0.1)
            end
        end
        if not Blob then return end
        markGucciBlobman(Blob)
        local Seat = Blob:FindFirstChildWhichIsA("VehicleSeat", true)
        local seatWait = tick()
        while tick() - seatWait < 2 and not Seat do
            Seat = Blob:FindFirstChildWhichIsA("VehicleSeat", true)
            if Seat then break end
            task.wait(0.05)
        end
        if not Seat then return end
        local BHead = Blob:FindFirstChild("Head")
        if not BHead then BHead = Blob:WaitForChild("Head", 2) end
        local HitBox = Blob:FindFirstChild("GrabbableHitbox")
        if not HitBox then HitBox = Blob:WaitForChild("GrabbableHitbox", 2) end
        task.spawn(function()
            while BHead and BHead.Parent do
                if HitBox and HitBox.Parent then
                    pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, HitBox, HitBox.CFrame) end)
                end
                if BHead:FindFirstChild("PartOwner") and BHead.PartOwner.Value == LocalPlayer.Name then
                    break
                end
                task.wait(0.06)
            end
        end)
        local settleT = tick()
        while tick() - settleT < 0.5 do
            if not Seat or not Seat.Parent then return end
            local prevPos = Seat.Position
            task.wait(0.03)
            if not Seat or not Seat.Parent then return end
            if (Seat.Position - prevPos).Magnitude < 0.05 then break end
        end
        hrp.CFrame = Seat.CFrame + Vector3.new(0, 1.5, 0)
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        local autoGucci = true
        task.spawn(function()
            local startTime = tick()
            while autoGucci and tick() - startTime < 0.3 do
                if Blob and Blob.Parent and Seat and Seat.Occupant ~= hum then
                    Seat:Sit(hum)
                end
                task.wait(0.01)
                if char and hum then hum:ChangeState(Enum.HumanoidStateType.Jumping) end
            end
            autoGucci = false
        end)
        task.spawn(function()
            while autoGucci do
                SafeFire(ragdollRemoteEvent, hrp, 0.05)
                task.wait(0.02)
            end
        end)
        task.wait(0.32)
        autoGucci = false
        hum.Sit = false
        if Blob and Blob.Parent then
            Blob.Name = "Gucci"
        end
        hrp.CFrame = savedHRPCF
    end)
end})
antiBlobSec:Button({Text = "Break PCLD", Callback = function()
    task.spawn(function()
        local plr = LocalPlayer
        local serverPos = CFrame.new(-272.2197265625, -7.350403785705566, 475.0108947753906)
        workspace.FallenPartsDestroyHeight = -100000
        local storedJoints = {}
        local root
        local conn
        local active = false
        local function breakPCLD()
            local char = plr.Character
            if not char then return end
            root = char:WaitForChild("HumanoidRootPart")
            for _, v in ipairs(char:GetDescendants()) do
                if v:IsA("Motor6D") then
                    storedJoints[v] = v.Part0
                    v.Part0 = nil
                end
            end
            root.CFrame = serverPos
            conn = RunService.RenderStepped:Connect(function()
                if root and root.Parent then
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end
            end)
        end
        local function restore()
            if conn then
                conn:Disconnect()
                conn = nil
            end
            for m, p0 in pairs(storedJoints) do
                if m and m.Parent then
                    m.Part0 = p0
                end
            end
            storedJoints = {}
        end
        local function press6()
            active = not active
            if active then
                breakPCLD()
            else
                restore()
            end
        end
        press6()
        task.wait(0.12)
        press6()
        plr.CharacterAdded:Once(function()
            task.wait(0.25)
            press6()
            task.wait(0.12)
            press6()
        end)
    end)
end})
antiBlobSec:Toggle({Text = "Auto Break PCLD", Flag = "AutoBreakPCLD", Default = false, Callback = function(v)
    Settings.Anti.autoBreakPCLD = v
    if v then
        if State.autoBreakPCLDTask then task.cancel(State.autoBreakPCLDTask) end
        State.autoBreakPCLDTask = task.spawn(function()
            local plr = LocalPlayer
            local isFirstCycle = true
            while Settings.Anti.autoBreakPCLD do
                local char = plr.Character or plr.CharacterAdded:Wait()
                local hrp = char:WaitForChild("HumanoidRootPart", 5)
                local hum = char:WaitForChild("Humanoid", 5)
                if not hrp or not hum then
                    task.wait(0.5)
                    continue
                end
                if hum.Health <= 0 then
                    char = plr.CharacterAdded:Wait()
                    hrp = char:WaitForChild("HumanoidRootPart", 5)
                    hum = char:WaitForChild("Humanoid", 5)
                end
                if not hrp or not hum then continue end
                if isFirstCycle then
                    local savedCFrame = hrp.CFrame
                    hrp.CFrame = CFrame.new(hrp.Position.X, 50000, hrp.Position.Z)
                    task.wait(0.05)
                    hum.Health = 0
                    char = plr.CharacterAdded:Wait()
                    if not Settings.Anti.autoBreakPCLD then break end
                    hrp = char:WaitForChild("HumanoidRootPart", 5)
                    hum = char:WaitForChild("Humanoid", 5)
                    if hrp and hum then
                        task.wait(0.1)
                        hrp.CFrame = savedCFrame
                        task.wait(0.05)
                        hum.Health = 0
                    end
                    isFirstCycle = false
                else
