ownershipKickSec:Keybind({Text = "Select Target (Look)", Flag = "OwnershipKickSelectLook", Mode = "Hold", Callback = function(held)
    if held then
        if ownershipKickLookTask then return end
        ownershipKickLookTask = task.spawn(function()
            while true do
                local cam = Workspace.CurrentCamera
                if cam then
                    local mPos = UserInputService:GetMouseLocation()
                    local best = nil
                    local bestDist = math.huge
                    for _, plr in ipairs(Players:GetPlayers()) do
                        if plr == LocalPlayer or not plr.Character or isProtectedPlayer(plr.Name) then continue end
                        local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                        local head = plr.Character:FindFirstChild("Head")
                        local part = hrp or head
                        if part then
                            local vec, onScreen = cam:WorldToViewportPoint(part.Position)
                            if onScreen then
                                local dx = vec.X - mPos.X
                                local dy = vec.Y - mPos.Y
                                local dist = dx * dx + dy * dy
                                if dist < bestDist then
                                    bestDist = dist
                                    best = plr
                                end
                            end
                        end
                    end
                    if best and best.Name ~= ownershipKickTarget then
                        local name = best.Name
                        ownershipKickTarget = name
                        local value = best.DisplayName .. " @" .. name
                        pcall(function()
                            if library._flagSetters and library._flagSetters["OwnershipKickTarget"] then
                                library._flagSetters["OwnershipKickTarget"](value)
                            end
                        end)
                        if updateTargetHighlight then updateTargetHighlight() end
                    end
                end
                task.wait(0.05)
            end
        end)
    else
        if ownershipKickLookTask then task.cancel(ownershipKickLookTask) ownershipKickLookTask = nil end
    end
end})
