        end
    end)
end})
local targetJoinLagMonitorTask = nil
local targetJoinLagApplyTask = nil
local targetJoinLagEnabled = false
local targetJoinLagOwnsInstant = false
local targetJoinLagObservedName = nil
local targetJoinLagPresent = false
local function targetJoinLagSetInstant(enabled)
    local function apply()
        local setter = library and library._flagSetters and library._flagSetters["OatLagInstant"]
        if not setter then return false end
        local ok = pcall(function() setter(enabled) end)
        if ok then
            targetJoinLagOwnsInstant = enabled
        end
        return ok
    end
    if targetJoinLagApplyTask then
        pcall(function() task.cancel(targetJoinLagApplyTask) end)
        targetJoinLagApplyTask = nil
    end
    if apply() then return end
    targetJoinLagApplyTask = task.spawn(function()
        for _ = 1, 100 do
            if apply() then
                targetJoinLagApplyTask = nil
                return
            end
            task.wait(0.1)
        end
        targetJoinLagApplyTask = nil
    end)
end
local function targetJoinLagHandleJoin(plr)
    if not targetJoinLagEnabled or not plr or plr == LocalPlayer then return end
    if not ownershipKickTarget or plr.Name ~= ownershipKickTarget then return end
    local alreadyEnabled = library.Flags and library.Flags["OatLagInstant"] == true
    targetJoinLagOwnsInstant = not alreadyEnabled
    if not alreadyEnabled then
        targetJoinLagSetInstant(true)
    end
    pcall(function()
        library:Notify({Title = "EndorisFTAP Reborn", Description = "Target Joined, Lag Server Enabled", Time = 7})
    end)
end
local function targetJoinLagHandleRemoving(targetName)
    if not targetJoinLagEnabled or not targetName then return end
    if not ownershipKickTarget or targetName ~= ownershipKickTarget then return end
    if targetJoinLagOwnsInstant then
        targetJoinLagSetInstant(false)
    end
end
ownershipKickSec:Toggle({Text = "Lag Server If Target On Server", Flag = "LagServerIfTargetJoin", Default = false, Callback = function(v)
    targetJoinLagEnabled = v
    if targetJoinLagMonitorTask then
        pcall(function() task.cancel(targetJoinLagMonitorTask) end)
        targetJoinLagMonitorTask = nil
    end
    if targetJoinLagApplyTask then
        pcall(function() task.cancel(targetJoinLagApplyTask) end)
        targetJoinLagApplyTask = nil
    end
    if not v then
        if targetJoinLagOwnsInstant then
            targetJoinLagSetInstant(false)
        else
            targetJoinLagOwnsInstant = false
        end
        targetJoinLagObservedName = nil
        targetJoinLagPresent = false
        return
    end
    targetJoinLagObservedName = nil
    targetJoinLagPresent = false
    targetJoinLagMonitorTask = task.spawn(function()
        while targetJoinLagEnabled do
            local selectedName = ownershipKickTarget
            if selectedName ~= targetJoinLagObservedName then
                if targetJoinLagPresent and targetJoinLagOwnsInstant then
                    targetJoinLagSetInstant(false)
                end
                targetJoinLagObservedName = selectedName
                targetJoinLagPresent = false
            end
            local target = selectedName and Players:FindFirstChild(selectedName)
            local isPresent = target ~= nil and target ~= LocalPlayer
            if isPresent and not targetJoinLagPresent then
                targetJoinLagPresent = true
                targetJoinLagHandleJoin(target)
            elseif not isPresent and targetJoinLagPresent then
                targetJoinLagPresent = false
                targetJoinLagHandleRemoving(selectedName)
            end
            task.wait(0.005)
        end
    end)
end})
local loopKickV3Task = nil
local loopKickV3FpsConn = nil
local palletRagdollV3Task = nil
local function cleanupOwnershipKickBodiesV3()
    pcall(function()
        local target = ownershipKickTarget and Players:FindFirstChild(ownershipKickTarget)
        local tChar = target and target.Character
        local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
