                    tHum.Sit = true
                    tHum.AutoRotate = false
                end)
                pcall(function() tHum:ChangeState(Enum.HumanoidStateType.Physics) end)
                pcall(function() ensureTargetIndicator(target) end)
                pcall(function()
                    local v3Rag = tHum:FindFirstChild("Ragdolled")
                    setTargetIndicator(v3Rag and v3Rag.Value == true)
                end)
                if not pausedRespawn() then
                    pcall(function() RemoteDispatcher:Fire(setNetworkOwnerEvent, tRoot, tRoot.CFrame) end)
                    local now = tick()
                    if now - lastGL >= GRAB_INTERVAL then
                        lastGL = now
                        pcall(function() RemoteDispatcher:Fire(grabEventsFolder.CreateGrabLine, tRoot, Vector3.zero, tRoot.Position, false) end)
                        pcall(function() RemoteDispatcher:Fire(destroyGrabLineEvent, tRoot) end)
                    end
                end
                if pausedRespawn() or not localCharValid() then
                    cleanupPhysicsObjects()
                    isGrabbing = false
                    startTime = nil
                    checkStartTime = nil
                    task.wait(0.15)
                    return
                end
                if attachments.bodyPos then
                    pcall(function()
                        attachments.bodyPos.Position = (lastMyRoot.CFrame * CFrame.new(5, 16, 2)).Position
                        if tRoot and tRoot.Parent then tRoot.AssemblyLinearVelocity = ZERO_VECTOR end
                    end)
                end
                if attachments.bodyGyro then
                    pcall(function()
                        v3SpinAngle = v3SpinAngle + V3_SPIN_SPEED
                        attachments.bodyGyro.CFrame = CFrame.Angles(0, v3SpinAngle, 0)
                    end)
                end
                if not checkStartTime then checkStartTime = tick() + 0.25 end
                if checkStartTime and tick() >= checkStartTime then
                    local tRootOk, tRootAlive = pcall(function() return tRoot.Parent ~= nil end)
                    if not tRoot or not tRootOk or not tRootAlive then cleanupPhysicsObjects() isGrabbing = false startTime = nil checkStartTime = nil return end
                    local dist = (lastMyRoot.Position - tRoot.Position).Magnitude
                    if dist > MAX_DISTANCE then
                        if pausedRespawn() then
                            cleanupPhysicsObjects()
                            isGrabbing = false
                            startTime = nil
                            checkStartTime = nil
                            task.wait(0.15)
                            return
                        end
                        if not ownershipKick.bring then
                            task.wait(0.1)
                            return
                        end
                        cleanupPhysicsObjects()
                        isGrabbing = false
                        startTime = tick()
                        checkStartTime = nil
                        executeBring(tRoot, savedPos)
                        return
                    end
                end
            end
            end)
        end
        cleanupPhysicsObjects()
        destroyTargetIndicator()
        pcall(function()
            if lastMyRoot and lastMyRoot.Parent then
                if savedPos then lastMyRoot.CFrame = savedPos end
                lastMyRoot.AssemblyLinearVelocity = Vector3.zero
                lastMyRoot.AssemblyAngularVelocity = Vector3.zero
            end
        end)
    end)
end
local loopKickV4Task = nil
ownershipKick["Loop Kick V4"] = function(v)
    Settings.Loop.ownershipKickV4Active = v
    if not v then
        Settings.Loop.ownershipKickV4Active = false
        if loopKickV4Task then
            local t = loopKickV4Task
            loopKickV4Task = nil
            task.delay(0.1, function() pcall(function() task.cancel(t) end) end)
        end
        task.spawn(function()
            cleanupOwnershipKickTarget()
        end)
        return
    end
    if not ownershipKickTarget then warn("[Loop Kick V4] Select target") Settings.Loop.ownershipKickV4Active = false return end
    loopKickV4Task = task.spawn(function()
        local myChar = LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then
            Settings.Loop.ownershipKickV4Active = false
            ownershipKick.on = false
            pcall(function()
                if library._flagSetters and library._flagSetters["OwnershipKick"] then
                    library._flagSetters["OwnershipKick"](false)
                end
            end)
            return
        end
        local savedPos = myRoot.CFrame
        rememberOwnershipSavedPos(savedPos)
        local lastMyRoot = myRoot
        local dragging = false
        local grabStartTime = 0
        local checkStartTime = 0
        local bodyPos = nil
        local bodyGyro = nil
        local function cleanupBodies()
            pcall(function()
                if bodyPos then bodyPos:Destroy() bodyPos = nil end
                if bodyGyro then bodyGyro:Destroy() bodyGyro = nil end
            end)
        end
        local function createBodies(targetRoot, pos)
            cleanupBodies()
            for _, v in pairs(targetRoot:GetChildren()) do
                if v:IsA("BodyPosition") or v:IsA("BodyGyro") then
                    v:Destroy()
                end
            end
            bodyPos = Instance.new("BodyPosition")
            bodyPos.MaxForce = Vector3.new(1000000, 1000000, 1000000)
            bodyPos.D = 500
            bodyPos.P = 50000
            bodyPos.Position = pos
            bodyPos.Parent = targetRoot
            bodyGyro = Instance.new("BodyGyro")
            bodyGyro.MaxTorque = Vector3.new(1000000, 1000000, 1000000)
            bodyGyro.D = 500
            bodyGyro.P = 50000
            bodyGyro.CFrame = CFrame.new(pos)
            bodyGyro.Parent = targetRoot
        end
        while Settings.Loop.ownershipKickV4Active do
            if not Utility.isLocalAlive() then
                cleanupBodies()
                dragging = false
                grabStartTime = 0
                checkStartTime = 0
                savedPos = nil
                lastMyRoot = nil
                task.wait(0.2)
                continue
            end
            local target = Players:FindFirstChild(ownershipKickTarget)
            if not target or not target.Character or not target.Parent then
                dragging = false
                grabStartTime = 0
                checkStartTime = 0
                cleanupBodies()
                repeat
                    RunService.Heartbeat:Wait()
                    target = Players:FindFirstChild(ownershipKickTarget)
                until not Settings.Loop.ownershipKickV4Active or (target and target.Character and target.Parent)
                if not Settings.Loop.ownershipKickV4Active then break end
            end
            myChar = LocalPlayer.Character
            myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if myRoot and myRoot ~= lastMyRoot then
                lastMyRoot = myRoot
                dragging = false
                grabStartTime = 0
                checkStartTime = 0
                cleanupBodies()
                if myRoot:IsDescendantOf(Workspace) then savedPos = myRoot.CFrame end
            end
            local tChar = target and target.Character
            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
            local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
            if tRoot and tHum and tHum.Health > 0 and myRoot then
                if tHum.SeatPart ~= nil then
                    cleanupBodies()
                    dragging = false
                    grabStartTime = 0
                    checkStartTime = 0
                    if ownershipKick.bring and not isAntiGucciActive() and myRoot and myRoot.Parent then
                        myRoot.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3)
                        myRoot.AssemblyLinearVelocity = Vector3.zero
                        myRoot.AssemblyAngularVelocity = Vector3.zero
                    end
                    for _ = 1, 3 do
                        pcall(function() setNetworkOwnerEvent:FireServer(tRoot, tRoot.CFrame) end)
                    end
                    RunService.Heartbeat:Wait()
                    continue
                end
                if TargetPCLDManager.checkDesync(target) then
                    cleanupBodies()
                    dragging = false
                    grabStartTime = 0
                    checkStartTime = 0
                    RunService.Heartbeat:Wait()
                    continue
                end
                if not dragging then
                    if (tRoot.Position - myRoot.Position).Magnitude > 29 then
                        if ownershipKick.bring then
                            executeBring(tRoot, savedPos)
                        else
                            RunService.Heartbeat:Wait()
                            continue
                        end
                    end
                    pauseOwnershipPosLock()
                    cleanupBodies()
                    checkStartTime = 0
                    if not isMyCharacterPart(tRoot) then
                        pcall(function()
                            tHum.PlatformStand = true
                            tHum.Sit = true
                            setNetworkOwnerEvent:FireServer(tRoot, tRoot.CFrame)
                            setNetworkOwnerEvent:FireServer(tRoot, tRoot.CFrame)
                            destroyGrabLineEvent:FireServer(tRoot)
                        end)
                    end
                    myRoot.AssemblyLinearVelocity = Vector3.zero
                    myRoot.AssemblyAngularVelocity = Vector3.zero
                    if grabStartTime == 0 then grabStartTime = tick() end
                    if tick() - grabStartTime > 0.2 then
                        dragging = true
                        grabStartTime = 0
                        checkStartTime = tick()
                        local lockPos = savedPos * CFrame.new(5, 20, 4)
                        createBodies(tRoot, lockPos.Position)
                    end
                else
                    if not Utility.isLocalAlive() then
                        cleanupBodies()
                        dragging = false
                        grabStartTime = 0
                        checkStartTime = 0
                        savedPos = nil
                        lastMyRoot = nil
                        task.wait(0.2)
                        continue
                    end
                    myChar = LocalPlayer.Character
                    myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    if not myRoot then continue end
                    myRoot.CFrame = savedPos
                    resumeOwnershipPosLock()
                    local lockPos = savedPos * CFrame.new(5, 20, 4)
                    myRoot.AssemblyLinearVelocity = Vector3.zero
                    myRoot.AssemblyAngularVelocity = Vector3.zero
                    if bodyPos and bodyPos.Parent then
                        bodyPos.Position = lockPos.Position
                        if bodyGyro then
                            bodyGyro.CFrame = lockPos
                        end
                    else
                        createBodies(tRoot, lockPos.Position)
                    end
                    tHum.PlatformStand = true
                    if not isMyCharacterPart(tRoot) then
                        pcall(function()
                            for i = 1, 4 do
                                setNetworkOwnerEvent:FireServer(tRoot, lockPos)
                            end
                            destroyGrabLineEvent:FireServer(tRoot)
                        end)
                    end
                    if checkStartTime > 0 and tick() - checkStartTime > 0.2 then
                        local currentDist = (tRoot.Position - myRoot.Position).Magnitude
                        if currentDist > 29 then
                            dragging = false
                            grabStartTime = 0
                            checkStartTime = 0
                            cleanupBodies()
                            if ownershipKick.bring then
                                executeBring(tRoot, savedPos)
                            end
                        else
                            checkStartTime = tick()
                        end
                    end
                end
            else
                dragging = false
                grabStartTime = 0
                checkStartTime = 0
                cleanupBodies()
            end
            RunService.Heartbeat:Wait()
        end
        cleanupBodies()
        if myRoot and myRoot.Parent and savedPos and Utility.isLocalAlive() then
            myRoot.CFrame = savedPos
            myRoot.AssemblyLinearVelocity = Vector3.zero
        end
        resumeOwnershipPosLock()
        Settings.Loop.ownershipKickV4Active = false
        ownershipKick.on = false
        pcall(function()
            if library._flagSetters and library._flagSetters["OwnershipKick"] then
                library._flagSetters["OwnershipKick"](false)
            end
        end)
    end)
end
