local blobLeftNotifyConn = nil
local blobLeftNotifyKickConn = nil
blobSec:Toggle({Text = "Kick/Left Notify", Flag = "BlobmanKillLeftNotify", Default = false, Callback = function(v)
    if blobLeftNotifyConn then blobLeftNotifyConn:Disconnect() blobLeftNotifyConn = nil end
    if blobLeftNotifyKickConn then blobLeftNotifyKickConn:Disconnect() blobLeftNotifyKickConn = nil end
    if not v then return end
    if not State.kickNotifyCache then State.kickNotifyCache = {} end
    local function playKickSound()
        local s = Instance.new("Sound")
        s.SoundId = "rbxassetid://86966498494980"
        s.Volume = 2.5 * 0.55
        s.PlayOnRemove = true
        s.Parent = game:GetService("SoundService")
        s:Destroy()
    end
    blobLeftNotifyKickConn = Workspace.ChildAdded:Connect(function(obj)
        if obj.Name ~= "BlackHoleKick" and obj.Name ~= "BlackHoleDetected" then return end
        task.wait(0.05)
        local pos
        if obj:IsA("BasePart") then
            pos = obj.Position
        elseif obj:IsA("Model") and obj.PrimaryPart then
            pos = obj.PrimaryPart.Position
        end
        if not pos then return end
        local tName = Settings.BlobmanBeta.selectedTarget
        local tgt = tName and Players:FindFirstChild(tName)
        if not tgt then return end
        local targetPCLD = GlobalPCLDTracker.getPCLDForPlayer(tgt)
        if targetPCLD and (targetPCLD.Position - pos).Magnitude < 50 then
            State.kickNotifyCache[tName] = os.clock()
            return
        end
        local closestPart, closestPlr = GlobalPCLDTracker.findClosestPCLD(pos, 50)
        if closestPlr and closestPlr == tgt then
            State.kickNotifyCache[tName] = os.clock()
            return
        end
        local tHRP = tgt.Character and tgt.Character:FindFirstChild("HumanoidRootPart")
        if tHRP and (tHRP.Position - pos).Magnitude < 50 then
            State.kickNotifyCache[tName] = os.clock()
        end
    end)
    blobLeftNotifyConn = Players.PlayerRemoving:Connect(function(plr)
        local tName = Settings.BlobmanBeta.selectedTarget
        if not (tName and plr.Name == tName) then return end
        playKickSound()
        local wasKicked = State.kickNotifyCache and State.kickNotifyCache[plr.Name] and os.clock() - State.kickNotifyCache[plr.Name] < 20
        if wasKicked then
            library:Notify({Title = "EndorisFTAP Reborn", Description = "Target: " .. plr.DisplayName .. " (" .. plr.Name .. ") has been kicked", Time = 7})
            pcall(function() game.TextChatService.TextChannels.RBXSystem:DisplaySystemMessage('<font color="rgb(255, 0, 67)">EndorisFTAP:</font><font color="rgb(255, 255, 255)"> Target: ' .. plr.DisplayName .. ' (' .. plr.Name .. ') Kicked</font>') end)
        else
            library:Notify({Title = "EndorisFTAP Reborn", Description = "Target: " .. plr.DisplayName .. " (" .. plr.Name .. ") left the server", Time = 7})
            pcall(function() game.TextChatService.TextChannels.RBXSystem:DisplaySystemMessage('<font color="rgb(255, 0, 67)">EndorisFTAP:</font><font color="rgb(255, 255, 255)"> Target: ' .. plr.DisplayName .. ' (' .. plr.Name .. ') Leaved</font>') end)
        end
    end)
end})
