                end
            end)
            pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, ToyName, CFrame.new(0, 999999, 0), Vector3.zero) end)
            local start = tick()
            while not spawned do
                if tick() - start > 2.5 then break end
                task.wait(0.01)
            end
            conn:Disconnect()
            return spawned
        end
        local banana, SoundPart
        local AlignPos
        local orbitAtt
        local lastSnoT = 0
        local snoCount = 0
        local setupDone = false
        local lastTargetPos = nil
        local bananaTarget = Instance.new("Part")
        bananaTarget.Name = "BananaTarget"
        bananaTarget.Anchored = true
        bananaTarget.CanCollide = false
        bananaTarget.Size = Vector3.new(1, 1, 1)
        bananaTarget.Transparency = 1
        bananaTarget.Parent = Workspace
        while Settings.BlobmanBeta.bananaRagdollActive and task.wait() do
            local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            if not inv then continue end
            banana = inv:FindFirstChild("FoodBanana")
            SoundPart = banana and banana:FindFirstChild("SoundPart")
            if not banana then
                setupDone = false
                banana = SpawnToy("FoodBanana")
                if not banana then continue end
                SoundPart = nil
            end
            if not setupDone then
                for _, v in pairs(inv:GetChildren()) do
                    if v.Name == "FoodBanana" and v ~= banana then
                        pcall(function() RemoteDispatcher:Fire(DeleteToyRE, v) end)
                    end
                end
                SoundPart = SoundPart or FWD(banana, "SoundPart", 5)
                if not SoundPart then
                    pcall(function() RemoteDispatcher:Fire(DeleteToyRE, banana) end)
                    continue
                end
                local holdPart = FWD(banana, "HoldPart", 5)
                if holdPart then
                    local holdRemote = FWD(holdPart, "HoldItemRemoteFunction", 5)
                    if holdRemote then
                        pcall(function() RemoteDispatcher:Invoke(holdRemote, banana, myChar) end)
                    end
                end
                pcall(function() RemoteDispatcher:Fire(holdEvents.Use, banana) end)
                while CFP(banana, "EdiblePart") and Settings.BlobmanBeta.bananaRagdollActive do task.wait() end
                pcall(function() RemoteDispatcher:Fire(holdEvents.Use, banana) end)
                if holdPart then
                    local dropRemote = FWD(holdPart, "DropItemRemoteFunction", 5)
                    if dropRemote then
                        pcall(function() RemoteDispatcher:Invoke(dropRemote, banana, myChar:GetPivot() * CFrame.new(0, 15, -10), Vector3.zero) end)
                    end
                end
                repeat
                    task.wait(0.01)
                    SoundPart = banana and banana:FindFirstChild("SoundPart")
                    if not SoundPart then break end
                    sno(SoundPart)
                until not SoundPart or CFP(SoundPart, "PartOwner") or not Settings.BlobmanBeta.bananaRagdollActive
                if not SoundPart then continue end
                unsno(SoundPart)
                sno(SoundPart)
                SoundPart.CanCollide = true
                local Atach = Instance.new("Attachment")
                Atach.Parent = SoundPart
                AlignPos = Instance.new("AlignPosition")
                AlignPos.Responsiveness = 200
                AlignPos.MaxForce = math.huge
                AlignPos.MaxVelocity = math.huge
                AlignPos.Parent = SoundPart
                AlignPos.Attachment0 = Atach
                setupDone = true
            end
            if banana then
                for _, v in pairs(banana:GetChildren()) do
                    if CFP(v, "PartOwner") and not CheckNetworkOwnerOnPart(v) then
                        pcall(function() RemoteDispatcher:Fire(DeleteToyRE, banana) end)
                        banana = nil
                        break
                    end
                end
            end
            if not banana then continue end
            AlignPos = SoundPart and SoundPart:FindFirstChild("AlignPosition")
            if not AlignPos then
                pcall(function() RemoteDispatcher:Fire(DeleteToyRE, banana) end)
                banana = nil
                continue
            end
            local tChar = targetPLR and targetPLR.Character
            local tHRP = tChar and tChar:FindFirstChild("HumanoidRootPart")
            if tHRP then lastTargetPos = tHRP.Position end
            local nowSno = os.clock()
            if snoCount < 2 and nowSno - lastSnoT > 0.5 then
                lastSnoT = nowSno
                snoCount = snoCount + 1
                unsno(SoundPart)
                sno(SoundPart)
                unsno(SoundPart)
            end
            if orbitAtt then orbitAtt:Destroy() end
            orbitAtt = Instance.new("Attachment", bananaTarget)
            orbitAtt.Name = "BananaOrbitAtt"
            local targetPos
            if tHRP then
                local roll = math.random()
                if roll < 0.15 then
                    local leftLeg = tChar:FindFirstChild("Left Leg")
                    local foot = leftLeg and leftLeg:FindFirstChild("LeftFootAttachment")
                    if foot then
                        targetPos = foot.WorldPosition
                    else
                        targetPos = tHRP.Position
                    end
                elseif roll < 0.4 then
                    local parts = {"HumanoidRootPart", "Head", "Torso", "Left Leg", "Right Leg"}
                    local bp = tChar:FindFirstChild(parts[math.random(1, #parts)]) or tHRP
                    targetPos = bp.Position
                else
                    local from = SoundPart.Position
                    local toT = tHRP.Position - from
                    local dir = toT.Magnitude > 0.01 and toT.Unit or Vector3.new(1, 0, 0)
                    local perp = dir:Cross(Vector3.new(0, 1, 0))
                    if perp.Magnitude < 0.1 then perp = Vector3.new(1, 0, 0) end
                    perp = perp.Unit
                    local up = dir:Cross(perp).Unit
                    local spread = dir + perp * ((math.random() - 0.5) * 2.4) + up * ((math.random() - 0.5) * 2)
                    if spread.Magnitude < 0.01 then spread = dir end
                    spread = spread.Unit
                    targetPos = tHRP.Position + spread * (6 + math.random() * 14)
                end
            else
                targetPos = lastTargetPos
            end
            if not targetPos then continue end
            if not Settings.Anti.AntiVoid and targetPos.Y < -24 then
                targetPos = Vector3.new(targetPos.X, -24, targetPos.Z)
            end
            orbitAtt.WorldPosition = targetPos
            AlignPos.Attachment1 = orbitAtt
        end
        if orbitAtt then orbitAtt:Destroy() end
        if bananaTarget then bananaTarget:Destroy() end
    end)
end})
local blobCloneFlingSec = BlobmanTab:Section({Text = "Clone Fling"})
Settings.BlobmanBeta.cloneFlingActive = false
Settings.BlobmanBeta.cloneFlingTarget = nil
Settings.BlobmanBeta.cloneFlingConn = nil
Settings.BlobmanBeta.cloneFlingCleanup = nil
local cloneFlingTargetCombo
blobCloneFlingSec:Button({Text = "Refresh Players", Callback = function()
    pcall(function() cloneFlingTargetCombo:Refresh({Text = "Select Target", List = BlobmanBetaFeature.GetPlayerList()}) end)
    fixSectionAfterRefresh()
end})
cloneFlingTargetCombo = blobCloneFlingSec:Dropdown({Text = "Select Target", Flag = "CloneFlingTargetDropdown", List = BlobmanBetaFeature.GetPlayerList(), Callback = function(value)
    local name = value:match("@(.+)$")
    if name then Settings.BlobmanBeta.cloneFlingTarget = name end
end})
blobCloneFlingSec:Toggle({Text = "Clone Fling", Flag = "CloneFling", Default = false, Callback = function(v)
    Settings.BlobmanBeta.cloneFlingActive = v
    if not v then
        RemoteDispatcher:NewGeneration()
        if Settings.BlobmanBeta.cloneFlingConn then
            Settings.BlobmanBeta.cloneFlingConn:Disconnect()
            Settings.BlobmanBeta.cloneFlingConn = nil
        end
        if Settings.BlobmanBeta.cloneFlingCleanup then
            Settings.BlobmanBeta.cloneFlingCleanup()
            Settings.BlobmanBeta.cloneFlingCleanup = nil
        end
        return
    end
    task.spawn(function()
        local targetName = Settings.BlobmanBeta.cloneFlingTarget
        if not targetName then
            Settings.BlobmanBeta.cloneFlingActive = false
            return
        end
        local myChar = LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then Settings.BlobmanBeta.cloneFlingActive = false return end
        local savedCF = myRoot.CFrame
        local GE = ReplicatedStorage:WaitForChild("GrabEvents")
        local SetNetworkOwner = GE:WaitForChild("SetNetworkOwner")
        local DestroyGrabLine = GE:WaitForChild("DestroyGrabLine")
        local minY = -45
        local function findClone()
            local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            if inv then
                for _, p in ipairs(inv:GetChildren()) do
                    if p.Name == "YouDecoy" then
                        local hrp = p:FindFirstChild("HumanoidRootPart")
                        if hrp then return p, hrp end
                    end
                end
            end
            return nil, nil
        end
        local function notify(text) end
        local clone, cloneHRP = findClone()
        if not clone or not cloneHRP then
            local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
            local spawnConn
            if inv then
                spawnConn = inv.ChildAdded:Connect(function(c)
                    if c.Name == "YouDecoy" then
                        clone = c
                        task.spawn(function()
                            for _ = 1, 100 do
                                cloneHRP = c:FindFirstChild("HumanoidRootPart")
                                if cloneHRP then break end
                                task.wait()
                            end
                            if cloneHRP then
                                pcall(function() RemoteDispatcher:Fire(SetNetworkOwner, cloneHRP, cloneHRP.CFrame) end)
                            end
                        end)
                    end
                end)
            end
            pcall(function() RemoteDispatcher:Invoke(SpawnToyRF, "YouDecoy", myRoot.CFrame * CFrame.new(0, -1, 13), Vector3.zero) end)
            for _ = 1, 100 do
                clone, cloneHRP = findClone()
                if clone and cloneHRP then break end
                task.wait()
            end
            if spawnConn then spawnConn:Disconnect() end
        end
        if not clone or not cloneHRP then
            notify("YouDecoy not found")
            Settings.BlobmanBeta.cloneFlingActive = false
            return
        end
        Settings.BlobmanBeta.cloneFlingCleanup = function()
            pcall(function()
                if cloneHRP and cloneHRP.Parent then
                    cloneHRP.AssemblyAngularVelocity = Vector3.zero
                    cloneHRP.AssemblyLinearVelocity = Vector3.zero
                end
            end)
        end
        myRoot.CFrame = cloneHRP.CFrame
        task.wait(0.1)
        RemoteDispatcher:Fire(SetNetworkOwner, cloneHRP, myRoot.CFrame)
        RunService.Heartbeat:Wait()
        RemoteDispatcher:Fire(DestroyGrabLine, cloneHRP)
        RunService.Heartbeat:Wait()
        myRoot.CFrame = savedCF
        task.wait(0.1)
        notify("Flinging " .. targetName)
        Settings.BlobmanBeta.cloneFlingConn = RunService.Heartbeat:Connect(function()
            if not Settings.BlobmanBeta.cloneFlingActive then return end
            if not clone or not clone.Parent or not cloneHRP or not cloneHRP.Parent then
                clone, cloneHRP = findClone()
                if not clone then return end
            end
            if cloneHRP.Position.Y < minY then
                pcall(function()
                    cloneHRP.CFrame = CFrame.new(0, 1000, 0)
                    cloneHRP.AssemblyLinearVelocity = Vector3.zero
                    cloneHRP.AssemblyAngularVelocity = Vector3.zero
                end)
            end
        end)
        while Settings.BlobmanBeta.cloneFlingActive do
            task.wait(0.05)
            if not Settings.BlobmanBeta.cloneFlingActive then break end
            local ct = Players:FindFirstChild(targetName)
            local ctChar = ct and ct.Character
            local ctHRP = ctChar and ctChar:FindFirstChild("HumanoidRootPart")
            if not ctHRP then
                if cloneHRP and cloneHRP.Parent then
                    pcall(function()
                        cloneHRP.CFrame = CFrame.new(0, 1000, 0)
                        cloneHRP.AssemblyLinearVelocity = Vector3.zero
                        cloneHRP.AssemblyAngularVelocity = Vector3.zero
                    end)
                end
                continue
            end
            if not clone or not clone.Parent then
                clone, cloneHRP = findClone()
                if not clone then continue end
            end
            if not cloneHRP or not cloneHRP.Parent then
                clone, cloneHRP = findClone()
                if not cloneHRP then continue end
            end
            pcall(function()
                cloneHRP.CFrame = ctHRP.CFrame * CFrame.new(0, 1, 0)
                cloneHRP.AssemblyLinearVelocity = Vector3.zero
                cloneHRP.AssemblyAngularVelocity = Vector3.zero
            end)
            task.wait(0.02)
            local flingDuration = 0.5
            local flingStart = tick()
            while tick() - flingStart < flingDuration and Settings.BlobmanBeta.cloneFlingActive do
                if not ctHRP or not ctHRP.Parent then break end
                local targetPos = ctHRP.Position
                local offsetX = math.random(-2, 2)
                local offsetZ = math.random(-2, 2)
                local offsetY = math.random(0, 1)
                pcall(function()
                    cloneHRP.CFrame = CFrame.new(targetPos + Vector3.new(offsetX, offsetY, offsetZ))
                    cloneHRP.AssemblyLinearVelocity = Vector3.new(math.random(-2000, 2000), math.random(500, 2000), math.random(-2000, 2000))
                    cloneHRP.AssemblyAngularVelocity = Vector3.new(math.random(-5000, 5000), math.random(-5000, 5000), math.random(-5000, 5000))
                end)
                task.wait(0.02)
            end
        end
    end)
end})
