miscUtilSec:Button({Text = "Join Low Players Server", Callback = function()
    task.spawn(function()
        local candidates = {}
        local cursor = ""
        repeat
            local url = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100&excludeFullGames=true"
            if cursor ~= "" then url = url .. "&cursor=" .. cursor end
            local ok, req = pcall(function() return game:HttpGet(url) end)
            if not ok or not req then break end
            local ok2, body = pcall(function() return HttpService:JSONDecode(req) end)
            if not ok2 or not body or not body.data then break end
            for _, server in ipairs(body.data) do
                if type(server.id) == "string" and server.id ~= game.JobId and type(server.playing) == "number" and type(server.maxPlayers) == "number" then
                    table.insert(candidates, {id = server.id, playing = server.playing})
                end
            end
            cursor = body.nextPageCursor or ""
        until cursor == ""
        table.sort(candidates, function(a, b) return a.playing < b.playing end)
        local targets = {}
        for i = 1, math.min(10, #candidates) do
            table.insert(targets, candidates[i].id)
        end
        if #targets == 0 then
            library:Notify({Title = "Low Server", Description = "Couldn't find a low player server", Time = 3})
            return
        end
        library:Notify({Title = "Low Server", Description = "Joining server with " .. candidates[1].playing .. " players...", Time = 3})
        local myId = game.JobId
        for attempt = 1, 3 do
            for _, id in ipairs(targets) do
                if id ~= myId then
                    local ok, err = pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, id, LocalPlayer) end)
                    if ok then
                        task.wait(3)
                        if game.JobId ~= myId then return end
                    end
                end
            end
            task.wait(1)
        end
        library:Notify({Title = "Low Server", Description = "All servers failed", Time = 3})
    end)
end})
miscUtilSec:Button({Text = "Server Hop", Callback = function()
    task.spawn(function()
        local allServers = {}
        local cursor = ""
        repeat
            local url = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Desc&limit=100&excludeFullGames=true"
            if cursor ~= "" then url = url .. "&cursor=" .. cursor end
            local ok, req = pcall(function() return game:HttpGet(url) end)
            if not ok or not req then break end
            local ok2, body = pcall(function() return HttpService:JSONDecode(req) end)
            if not ok2 or not body or not body.data then break end
            for _, v in ipairs(body.data) do
                if type(v) == "table" and tonumber(v.playing) and tonumber(v.maxPlayers) and v.id ~= game.JobId then
                    local free = v.maxPlayers - v.playing
                    table.insert(allServers, {id = v.id, free = free, playing = v.playing})
                end
            end
            cursor = body.nextPageCursor or ""
        until cursor == ""
        local targets = {}
        for _, s in ipairs(allServers) do
            if s.free >= 1 and s.free <= 2 then
                table.insert(targets, s.id)
                if #targets >= 10 then break end
            end
        end
        if #targets == 0 then
            for _, s in ipairs(allServers) do
                table.insert(targets, s.id)
                if #targets >= 10 then break end
            end
        end
        if #targets == 0 then
            library:Notify({Title = "Server Hop", Description = "API empty, random teleport...", Time = 3})
            pcall(function() TeleportService:Teleport(game.PlaceId, LocalPlayer) end)
            return
        end
        library:Notify({Title = "Server Hop", Description = "Joining...", Time = 3})
        local myId = game.JobId
        for attempt = 1, 3 do
            for _, id in ipairs(targets) do
                if id ~= myId then
                    local ok, err = pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, id, LocalPlayer) end)
                    if ok then
                        task.wait(3)
                        if game.JobId ~= myId then return end
                    end
                end
            end
            task.wait(1)
        end
        library:Notify({Title = "Server Hop", Description = "All targets failed, random teleport...", Time = 3})
        pcall(function() TeleportService:Teleport(game.PlaceId, LocalPlayer) end)
    end)
end})
