local packetLagActive = false
local packetLagSizeMB = 0.73
local packetLagDelay = 1
local packetLagType = "Resonance"
local packetLagCustomText = "0"
local packetLagCachedData = "0"
local packetLagMode = "ExtendGrabLine"
local packetLagCacheBuilt = false
local packetLagCount = 0
local packetLagLoopTask = nil
local function packetLagNotify(title, text)
    pcall(function()
        game.StarterGui:SetCore("SendNotification", { Title = title, Text = text, Duration = 2 })
    end)
end
local function packetLagGetPattern()
    if packetLagType == "Custom" then
        return (packetLagCustomText and packetLagCustomText ~= "") and packetLagCustomText or "0"
    end
    return packetLagPatterns[packetLagType] or "0"
end
local function packetLagRebuildCache()
    local pattern = packetLagGetPattern()
    local bytes = math.floor(packetLagSizeMB * 1024 * 1024)
    if bytes <= 0 then
        packetLagCachedData = pattern:sub(1, 1)
    else
        local patternLen = #pattern
        if patternLen == 0 then
            pattern = "0"
            patternLen = 1
        end
        packetLagCachedData = string.rep(pattern, math.ceil(bytes / patternLen)):sub(1, bytes)
    end
    packetLagCacheBuilt = true
end
local function packetLagGetRemote()
    local GrabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
    if not GrabEvents then return nil end
    local remote = GrabEvents:FindFirstChild(packetLagMode)
    if remote then return remote end
    return GrabEvents:FindFirstChild("ExtendGrabLine") or GrabEvents:FindFirstChild("SetNetworkOwner")
end
local function packetLagSendPacket(showNotif)
    if State.packetBlockOutgoing then return end
    if not packetLagCacheBuilt then packetLagRebuildCache() end
    local remote = packetLagGetRemote()
    if not remote then return end
    local startTime = tick()
    local success = pcall(function()
        if remote.ClassName == "RemoteFunction" then
            RemoteDispatcher:Invoke(remote, packetLagCachedData)
        else
            RemoteDispatcher:Fire(remote, packetLagCachedData)
        end
    end)
    if not success then
        local maxSize = 1
        local step = 0.5
        while maxSize > 0.01 do
            local testSize = math.floor(maxSize * 1024 * 1024)
            local testData = string.rep("0", testSize)
            local testSuccess = pcall(function()
                if remote.ClassName == "RemoteFunction" then
                    RemoteDispatcher:Invoke(remote, testData)
                else
                    RemoteDispatcher:Fire(remote, testData)
                end
            end)
            if testSuccess then
                if showNotif then
                    local actualMB = math.floor(testSize / (1024 * 1024) * 100) / 100
                    packetLagNotify("Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р РЋРІР‚СњР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљР’ВР В Р’В Р вЂ™Р’В Р В Р Р‹Р вЂ™Р’ВР В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљР’ВР В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћ Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В¦Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В Р вЂ Р Р†Р вЂљРЎвЂєР Р†Р вЂљРІР‚СљР В Р’В Р вЂ™Р’В Р В РЎС›Р Р†Р вЂљР’ВР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В¦", "Р В Р’В Р вЂ™Р’В Р В Р Р‹Р РЋРІвЂћСћР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В Р Р‹Р Р†Р вЂљРЎСљР В Р’В Р В Р вЂ№Р В Р’В Р РЋРІР‚Сљ Р В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ўР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В·Р В Р’В Р вЂ™Р’В Р В Р Р‹Р вЂ™Р’ВР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’ВµР В Р’В Р В Р вЂ№Р В Р’В Р Р†Р вЂљРЎв„ў: " .. actualMB .. " Р В Р’В Р вЂ™Р’В Р В Р Р‹Р РЋРІвЂћСћР В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р вЂ™Р’В")
                end
