            task.wait(0.1)
        end
        return
    end
    local elapsed = tick() - startTime
    packetLagCount = packetLagCount + 1
    if showNotif then
        packetLagNotify("Packet Sent", string.format("%.2f MB | #%d | %.2fs", packetLagSizeMB, packetLagCount, elapsed))
    end
end
