local rgHeartbeatConn = {}
if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
    rgLastHRP = LocalPlayer.Character.HumanoidRootPart.CFrame
end
LocalPlayer.CharacterAdded:Connect(function(char)
    rgLastHRP = char:WaitForChild("HumanoidRootPart").CFrame
end)
grabFuncSec:Toggle({Text = "Ragdoll Grab", Flag = "RagdollGrabToggle", Default = false, Callback = function(state)
    rgEnabled = state
    if not state then
        for _, conn in ipairs(rgGrabConn) do conn:Disconnect() end
        for _, conn in ipairs(rgRagdollConn) do conn:Disconnect() end
        for _, conn in ipairs(rgHeartbeatConn) do conn:Disconnect() end
        rgGrabConn = {}
        rgRagdollConn = {}
        rgHeartbeatConn = {}
        rgFollowList = {}
        rgCurrentPallet = nil
        return
    end
    local RS = ReplicatedStorage
    local spawnToyRF = RS:WaitForChild("MenuToys"):WaitForChild("SpawnToyRemoteFunction")
    local destroyToy = RS:WaitForChild("MenuToys"):WaitForChild("DestroyToy")
    local setNetworkOwner = RS:WaitForChild("GrabEvents"):WaitForChild("SetNetworkOwner")
    local function rgGetSpawnCFrame()
        local char = LocalPlayer.Character
        if char then
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                rgLastHRP = hrp.CFrame
                return hrp.CFrame
            end
        end
        return rgLastHRP
    end
    local function rgTeleAway(pallet)
        if not pallet then return end
        for _, part in ipairs(pallet:GetDescendants()) do
            if part:IsA("BasePart") then
                part.CFrame = CFrame.new(0, 9e18, 0)
                part.Anchored = false
                part.CanCollide = false
                part.Transparency = 1
            end
        end
    end
    local function rgSpawnPallet()
        local pos = rgGetSpawnCFrame()
        pcall(function()
            RemoteDispatcher:Invoke(spawnToyRF, 
                "PalletLightBrown",
                pos * CFrame.new(5, 0, 5),
                Vector3.new(0, 33, 0)
            )
        end)
    end
    local function rgHandlePallet(pallet)
        if pallet:GetAttribute(rgAttr) then return end
        if rgCurrentPallet and rgCurrentPallet.Parent then return end
        local soundPart = pallet:WaitForChild("SoundPart")
        local ownershipConfirmed = false
        pcall(function() RemoteDispatcher:Fire(setNetworkOwner, soundPart, soundPart.CFrame) end)
        local triesDelay = 0.25
        local maxTime = 3
        local lastTry = 0
        local startTime = tick()
        local conn
        conn = RunService.Heartbeat:Connect(function()
            if ownershipConfirmed then
                conn:Disconnect()
                return
            end
            local ownerTag = soundPart:FindFirstChild("PartOwner")
            if ownerTag and ownerTag.Value == LocalPlayer.Name then
                ownershipConfirmed = true
                pallet:SetAttribute(rgAttr, true)
                rgCurrentPallet = pallet
                for _, part in ipairs(pallet:GetDescendants()) do
                    if part:IsA("BasePart") then
                        if not part:FindFirstChild("RG_BV") then
                            local bv = Instance.new("BodyVelocity")
                            bv.Name = "RG_BV"
                            bv.Velocity = Vector3.new(0, 200, 0)
                            bv.MaxForce = Vector3.new(1e5, 1e5, 1e5)
                            bv.P = 1e4
                            bv.Parent = part
                        end
                        part.CanCollide = false
                        part.Transparency = 1
                    end
                end
                conn:Disconnect()
                return
            end
            if tick() - lastTry < triesDelay then return end
            lastTry = tick()
            if tick() - startTime >= maxTime then
                pcall(function() RemoteDispatcher:Fire(destroyToy, pallet) end)
                conn:Disconnect()
                return
            end
            pcall(function() RemoteDispatcher:Fire(setNetworkOwner, soundPart, soundPart.CFrame) end)
        end)
    end
    local function rgFollowLoop(player)
        if rgFollowList[player] then return end
        rgFollowList[player] = true
        local humanoid = player.Character and player.Character:FindFirstChildWhichIsA("Humanoid")
        local rag = humanoid and humanoid:FindFirstChild("Ragdolled")
        task.spawn(function()
            while rgEnabled and rgFollowList[player] and rgCurrentPallet do
                if not rag or not rag.Value then
                    local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        for _, part in ipairs(rgCurrentPallet:GetDescendants()) do
                            if part:IsA("BasePart") then
                                part.CFrame = hrp.CFrame
                                part.CanCollide = false
                                part.Transparency = 1
                            end
                        end
                    end
                else
                    break
                end
                task.wait(0.1)
            end
            rgFollowList[player] = nil
            rgTeleAway(rgCurrentPallet)
        end)
        if rag and rag:IsA("BoolValue") then
            local conn
            conn = rag.Changed:Connect(function(val)
                if val then
                    rgFollowList[player] = nil
                    rgTeleAway(rgCurrentPallet)
                    conn:Disconnect()
                end
            end)
            table.insert(rgRagdollConn, conn)
        end
    end
    local function rgMonitorGrabParts(container)
        task.spawn(function()
            while container.Parent and rgEnabled do
                local grabPart = container:FindFirstChild("GrabPart")
                local weld = grabPart and grabPart:FindFirstChildOfClass("WeldConstraint")
                if weld and weld.Part1 then
                    for _, plr in ipairs(Players:GetPlayers()) do
                        if plr.Character and weld.Part1:IsDescendantOf(plr.Character) then
                            rgFollowLoop(plr)
                        end
                    end
                else
                    for plr in pairs(rgFollowList) do
                        rgFollowList[plr] = nil
                    end
                end
                task.wait(0.1)
            end
        end)
    end
    rgToysFolder = rgToysFolder or Workspace:WaitForChild(LocalPlayer.Name .. "SpawnedInToys")
    table.insert(rgGrabConn, rgToysFolder.ChildAdded:Connect(function(c)
        if c.Name == "PalletLightBrown" then
            rgHandlePallet(c)
        end
    end))
    table.insert(rgGrabConn, rgToysFolder.ChildRemoved:Connect(function(c)
        if c == rgCurrentPallet then
            rgCurrentPallet = nil
        end
    end))
    table.insert(rgGrabConn, Workspace.ChildAdded:Connect(function(c)
        if c.Name == "GrabParts" then
            rgMonitorGrabParts(c)
        end
    end))
    table.insert(rgHeartbeatConn, RunService.Heartbeat:Connect(function()
        if not rgEnabled then return end
        if not rgCurrentPallet or not rgCurrentPallet.Parent then
            local owned
            for _, toy in ipairs(rgToysFolder:GetChildren()) do
                if toy:GetAttribute(rgAttr) then
                    owned = toy
                    break
                end
            end
            if owned then
                rgCurrentPallet = owned
            else
                rgSpawnPallet()
            end
        end
    end))
    for _, obj in ipairs(Workspace:GetChildren()) do
        if obj.Name == "GrabParts" then
            rgMonitorGrabParts(obj)
        end
    end
    rgSpawnPallet()
end})
grabFuncSec:Toggle({Text = 'Kick Grab', Flag = 'KickGrabToggle', Default = false, Callback = function(state)
    if not state then
        getgenv().KickGrabActive = false
        getgenv().FKeyAttackActive = false
        if getgenv().FKeyInputConnection then
            getgenv().FKeyInputConnection:Disconnect()
            getgenv().FKeyInputConnection = nil
        end
        return
    end
    if getgenv().KickGrabActive then
        return
    end
    getgenv().KickGrabActive = true
    getgenv().FKeyAttackActive = false
    local Players = game:GetService('Players')
    local ReplicatedStorage = game:GetService('ReplicatedStorage')
    local UserInputService = game:GetService('UserInputService')
    local RunService = game:GetService('RunService')
    local plr = Players.LocalPlayer
    local camera = workspace.CurrentCamera
    local GrabEvents = ReplicatedStorage:WaitForChild('GrabEvents')
    local CreateGrabLine = GrabEvents:WaitForChild('CreateGrabLine')
    local SetNetworkOwner = GrabEvents:WaitForChild('SetNetworkOwner')
    local DestroyGrabLine = GrabEvents:WaitForChild('DestroyGrabLine')
    task.spawn(function()
        while getgenv().KickGrabActive do
            local grabParts = workspace:FindFirstChild('GrabParts')
            if not grabParts then
                task.wait()
                continue
            end
            local gp = grabParts:FindFirstChild('GrabPart')
            local weld = gp and gp:FindFirstChildOfClass('WeldConstraint')
            local part1 = weld and weld.Part1
            if part1 then
                local ownerPlayer = nil
                for _, pl in ipairs(Players:GetPlayers())do
                    if pl.Character and part1:IsDescendantOf(pl.Character) then
                        ownerPlayer = pl
                        break
                    end
                end
                if not ownerPlayer then
                    task.wait()
                    continue
                end
                while getgenv().KickGrabActive and workspace:FindFirstChild('GrabParts') do
                    if ownerPlayer then
                        local tgtTorso = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('HumanoidRootPart')
                        local tgtHead = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('Head')
                        local myTorso = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart')
                        if tgtTorso and myTorso and tgtHead then
                            pcall(function()
                                RemoteDispatcher:Fire(SetNetworkOwner, tgtTorso, CFrame.lookAt(myTorso.Position, tgtTorso.Position))
                            end)
                            task.wait()
                            pcall(function()
                                RemoteDispatcher:Fire(DestroyGrabLine, tgtHead)
                            end)
                        end
                    end
                    task.wait()
                end
            end
            task.wait()
        end
    end)
    function getScreenCenterTarget()
        local screenCenter = Vector2.new(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2)
        local ray = camera:ViewportPointToRay(screenCenter.X, screenCenter.Y)
        local raycastParams = RaycastParams.new()
        raycastParams.FilterType = Enum.RaycastFilterType.Exclude
        if plr.Character then
            raycastParams.FilterDescendantsInstances = {
                plr.Character,
            }
        end
        local result = workspace:Raycast(ray.Origin, ray.Direction * 1000, raycastParams)
        if result and result.Instance then
            for _, pl in ipairs(Players:GetPlayers())do
                if pl ~= plr and pl.Character and result.Instance:IsDescendantOf(pl.Character) then
                    return pl
                end
            end
        end
        return nil
    end
    local fAttackTarget = nil
    local fAttackConnection = nil
    function stopFKeyAttack()
        getgenv().FKeyAttackActive = false
        fAttackTarget = nil
        if fAttackConnection then
            fAttackConnection:Disconnect()
            fAttackConnection = nil
        end
    end
    function startFKeyAttack(targetPlayer)
        getgenv().FKeyAttackActive = true
        fAttackTarget = targetPlayer
        fAttackConnection = RunService.RenderStepped:Connect(function()
            if not getgenv().FKeyAttackActive or not fAttackTarget then
                stopFKeyAttack()
                return
            end
            local myChar = plr.Character
            local myRoot = myChar and myChar:FindFirstChild('HumanoidRootPart')
            local tgtChar = fAttackTarget.Character
            local tgtRoot = tgtChar and tgtChar:FindFirstChild('HumanoidRootPart')
            if not myRoot or not tgtRoot then
                return
            end
            local camCF = camera.CFrame
            local teleportPos = camCF.Position + camCF.LookVector * 20
            pcall(function()
                tgtRoot.CFrame = CFrame.new(teleportPos)
            end)
            local grabCFrame = CFrame.new(-9.0301513671875E-2, 0.4190945625305176, 0.4999980926513672, 0.39632707834243774, 0, -0.9181094169616699, -1.0944717132588266E-7, 1, -4.7245869438938826E-8, 0.9181094169616699, 5.9604644775390625e-8, 0.39632707834243774)
            pcall(function()
                RemoteDispatcher:Fire(CreateGrabLine, tgtRoot, grabCFrame)
                RemoteDispatcher:Fire(SetNetworkOwner, tgtRoot, CFrame.lookAt(myRoot.Position, tgtRoot.Position))
                RemoteDispatcher:Fire(DestroyGrabLine, tgtRoot)
            end)
        end)
    end
    getgenv().FKeyInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed then
            return
        end
        if input.KeyCode ~= Enum.KeyCode.F then
            return
        end
        if getgenv().FKeyAttackActive then
            stopFKeyAttack()
            return
        end
        local target = getScreenCenterTarget()
        if not target then
            return
        end
        local myChar = plr.Character
        local myRoot = myChar and myChar:FindFirstChild('HumanoidRootPart')
        local tgtChar = target.Character
        local tgtRoot = tgtChar and tgtChar:FindFirstChild('HumanoidRootPart')
        if not myRoot or not tgtRoot then
            return
        end
        local distance = (myRoot.Position - tgtRoot.Position).Magnitude
        if distance > 25 then
            return
        end
        startFKeyAttack(target)
    end)
    if game.PlaceId ~= 6961824067 then
        return
    end
    local G = game:GetService('ReplicatedStorage'):WaitForChild('GrabEvents')
    G:WaitForChild('EndGrabEarly'):Destroy()
    Instance.new('RemoteEvent', G).Name = 'EndGrabEarly'
end})
grabFuncSec:Toggle({Text = 'Loop Grab', Flag = 'LoopGrabToggle', Default = false, Callback = function(state)
    if not state then
        getgenv().LoopGrabActive = false
        getgenv().FTargetGrabActive = false
        if getgenv().fGrabConnection then
            getgenv().fGrabConnection:Disconnect()
            getgenv().fGrabConnection = nil
        end
        if getgenv().LoopGrabInputConnection then
            getgenv().LoopGrabInputConnection:Disconnect()
            getgenv().LoopGrabInputConnection = nil
        end
        return
    end
    if getgenv().LoopGrabActive then
        return
    end
    getgenv().LoopGrabActive = true
    local Players = game:GetService('Players')
    local ReplicatedStorage = game:GetService('ReplicatedStorage')
    local UserInputService = game:GetService('UserInputService')
    local RunService = game:GetService('RunService')
    local plr = Players.LocalPlayer
    local SetNetworkOwner = ReplicatedStorage:WaitForChild('GrabEvents'):WaitForChild('SetNetworkOwner')
    task.spawn(function()
        while getgenv().LoopGrabActive do
            local grabParts = workspace:FindFirstChild('GrabParts')
            if not grabParts then
                task.wait()
                continue
            end
            local gp = grabParts:FindFirstChild('GrabPart')
            local weld = gp and gp:FindFirstChildOfClass('WeldConstraint')
            local part1 = weld and weld.Part1
            if part1 then
                local ownerPlayer = nil
                for _, pl in ipairs(Players:GetPlayers())do
                    if pl.Character and part1:IsDescendantOf(pl.Character) then
                        ownerPlayer = pl
                        break
                    end
                end
                while getgenv().LoopGrabActive and workspace:FindFirstChild('GrabParts') do
                    if ownerPlayer then
                        local tgtTorso = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('HumanoidRootPart')
                        local tgtHead = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('Head')
                        local myTorso = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart')
                        if tgtTorso and myTorso and tgtHead then
                            pcall(function()
                                RemoteDispatcher:Fire(SetNetworkOwner, tgtTorso, CFrame.lookAt(myTorso.Position, tgtTorso.Position))
                            end)
                        end
                    else
                        if part1.Parent then
                            local myTorso = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart')
                            if myTorso then
                                pcall(function()
                                    RemoteDispatcher:Fire(SetNetworkOwner, part1, CFrame.lookAt(myTorso.Position, part1.Position))
                                end)
                            end
                        end
                    end
                    task.wait()
                end
            end
            task.wait()
        end
    end)
    if game.PlaceId == 6961824067 then
        local G = game:GetService('ReplicatedStorage'):WaitForChild('GrabEvents')
        local existingEndGrab = G:FindFirstChild('EndGrabEarly')
        if existingEndGrab then
            existingEndGrab:Destroy()
        end
        Instance.new('RemoteEvent', G).Name = 'EndGrabEarly'
    end
    getgenv().FTargetGrabActive = false
    getgenv().fGrabConnection = nil
    function getCenterTarget()
        local cam = workspace.CurrentCamera
        local center = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
        local myTorso = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart')
        if not myTorso then
            return nil
        end
        local closestTarget = nil
        local minScreenDist = math.huge
        for _, p in ipairs(Players:GetPlayers())do
            if p ~= plr and p.Character and p.Character:FindFirstChild('HumanoidRootPart') then
                local tgtTorso = p.Character.HumanoidRootPart
                local dist = (tgtTorso.Position - myTorso.Position).Magnitude
                if dist <= 25 then
                    local screenPos, onScreen = cam:WorldToViewportPoint(tgtTorso.Position)
                    if onScreen then
                        local screenDist = (Vector2.new(screenPos.X, screenPos.Y) - center).Magnitude
                        if screenDist < minScreenDist then
                            minScreenDist = screenDist
                            closestTarget = p
                        end
                    end
                end
            end
        end
        return closestTarget
    end
    if getgenv().LoopGrabInputConnection then
        getgenv().LoopGrabInputConnection:Disconnect()
        getgenv().LoopGrabInputConnection = nil
    end
    getgenv().LoopGrabInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed then
            return
        end
        if not getgenv().LoopGrabActive then
            return
        end
        if input.KeyCode == Enum.KeyCode.F then
            if getgenv().FTargetGrabActive then
                getgenv().FTargetGrabActive = false
                if getgenv().fGrabConnection then
                    getgenv().fGrabConnection:Disconnect()
                    getgenv().fGrabConnection = nil
                end
            else
                local target = getCenterTarget()
                if target then
                    getgenv().FTargetGrabActive = true
                    local cam = workspace.CurrentCamera
                    getgenv().fGrabConnection = RunService.RenderStepped:Connect(function()
                        if not getgenv().FTargetGrabActive or not target or not target.Character then
                            getgenv().FTargetGrabActive = false
                            if getgenv().fGrabConnection then
                                getgenv().fGrabConnection:Disconnect()
                                getgenv().fGrabConnection = nil
                            end
                            return
                        end
                        local tgtTorso = target.Character:FindFirstChild('HumanoidRootPart')
                        local tgtHead = target.Character:FindFirstChild('Head')
                        local myTorso = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart')
                        if tgtTorso and myTorso and tgtHead then
                            RemoteDispatcher:Fire(SetNetworkOwner, tgtTorso, tgtTorso.CFrame)
                            if tgtHead:FindFirstChild('PartOwner') then
                                local targetPos = cam.CFrame.Position + (cam.CFrame.LookVector * 23)
                                local newCFrame = CFrame.new(targetPos)
                                tgtTorso.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                                tgtTorso.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                                tgtTorso.CFrame = newCFrame
                                RemoteDispatcher:Fire(SetNetworkOwner, tgtTorso, newCFrame)
                            end
                        end
                    end)
                end
            end
        end
    end)
end})
grabFuncSec:Toggle({Text = "Spin Grab", Flag = "SpinGrab", Default = false, Callback = function(v) Settings.Grab.SpinGrab = v end})
grabFuncSec:Toggle({Text = "Fling Grab", Flag = "FlingGrab", Default = false, Callback = function(v) Settings.Grab.FlingGrab = v end})
local function setupPhysicsGrab()
local physicsGrabEnabled = false
local physicsGrabLoop = nil
local physicsGrabChildConn = nil
grabFuncSec:Toggle({Text = "Physics Grab", Flag = "PhysicsGrab", Default = false, Callback = function(v)
    physicsGrabEnabled = v
    local function applyPhysicsGrab()
        pcall(function()
            local grabParts = workspace:FindFirstChild("GrabParts")
            if grabParts and grabParts:FindFirstChild("DragPart") then
                local dragPart = grabParts.DragPart
                local ao = dragPart:FindFirstChild("AlignOrientation")
                if ao then
                    ao.AlignType = Enum.AlignType.Perpendicular
                    ao.PrimaryAxisOnly = true
                end
            end
        end)
    end
    if v then
        applyPhysicsGrab()
        physicsGrabLoop = RunService.Heartbeat:Connect(function()
            if physicsGrabEnabled then applyPhysicsGrab()
            else physicsGrabLoop:Disconnect() end
        end)
        physicsGrabChildConn = workspace.ChildAdded:Connect(function(child)
            if child.Name == "GrabParts" and physicsGrabEnabled then
                task.wait(0.05)
                applyPhysicsGrab()
            end
        end)
    else
        if physicsGrabLoop then physicsGrabLoop:Disconnect() physicsGrabLoop = nil end
        if physicsGrabChildConn then physicsGrabChildConn:Disconnect() physicsGrabChildConn = nil end
    end
end})
end
setupPhysicsGrab()
do
    local infZoomValue = 0
    local infZoomConn1, infZoomConn2 = nil, nil
    grabFuncSec:Toggle({Text = "Inf Zoom", Flag = "InfZoom", Default = false, Callback = function(v)
        Settings.Grab.InfZoom = v
        if v then
            infZoomValue = 0
            infZoomConn1 = UserInputService.InputChanged:Connect(function(input)
                if not Settings.Grab.InfZoom then return end
                if input.UserInputType == Enum.UserInputType.MouseWheel then
                    if Workspace:FindFirstChild("GrabParts") then
                        if input.Position.Z ~= 1 then
                            infZoomValue = infZoomValue - 1.5
                        else
                            infZoomValue = infZoomValue + 1.5
                        end
                    else
                        infZoomValue = 0
                    end
                end
            end)
            infZoomConn2 = Workspace.ChildAdded:Connect(function(child)
                if not Settings.Grab.InfZoom then return end
                if child.Name == "GrabParts" then
                    infZoomValue = 0
                    local dragPart = child:WaitForChild("DragPart", 5)
                    local dragAttach = dragPart and dragPart:FindFirstChild("DragAttach")
                    if dragAttach then
                        while child.Parent and task.wait() do
                            if not Settings.Grab.InfZoom then break end
                            dragAttach.Position = Workspace.CurrentCamera.CFrame.LookVector * infZoomValue
                        end
                    end
                end
            end)
        else
            if infZoomConn1 then infZoomConn1:Disconnect() infZoomConn1 = nil end
            if infZoomConn2 then infZoomConn2:Disconnect() infZoomConn2 = nil end
            infZoomValue = 0
        end
    end})
end
grabFuncSec:Toggle({Text = "Noclip Grab", Flag = "NoclipGrab", Default = false, Callback = function(enabled)
    Settings.Grab.NoclipGrab = enabled
    GrabFeature.toggleNoclip(enabled)
end})
grabFuncSec:Toggle({Text = "Massless Grab", Flag = "MasslessGrab", Default = false, Callback = function(v)
    Settings.Grab.MasslessGrab = v
    if v then
        task.spawn(function()
            while Settings.Grab.MasslessGrab do
                local grabParts = workspace:FindFirstChild("GrabParts")
                if grabParts then
                    local isPlayerGrab = false
                    if Settings.Grab.MasslessGrabToys then
                        for _, gp in ipairs(grabParts:GetChildren()) do
                            local weld = gp:FindFirstChildOfClass("WeldConstraint")
                            if weld and weld.Part1 then
                                local part = weld.Part1
                                local char = Players:GetPlayerFromCharacter(part.Parent)
                                if not char then char = Players:GetPlayerFromCharacter(part) end
                                if char and char ~= LocalPlayer then
                                    isPlayerGrab = true
                                    break
                                end
                            end
                        end
                    end
                    if not isPlayerGrab then
                        local dragParts = {grabParts:FindFirstChild("DragPart"), grabParts:FindFirstChild("DragPart1")}
                        for _, dragPart in pairs(dragParts) do
                            if dragPart then
                                local alignOrientation = dragPart:FindFirstChildOfClass("AlignOrientation")
                                if alignOrientation then
                                    alignOrientation.MaxAngularVelocity = math.huge
                                    alignOrientation.MaxTorque = math.huge
                                    alignOrientation.Responsiveness = 9999999999999
                                end
                                local alignPosition = dragPart:FindFirstChildOfClass("AlignPosition")
                                if alignPosition then
                                    alignPosition.MaxAxesForce = Vector3.new(math.huge, math.huge, math.huge)
                                    alignPosition.MaxForce = math.huge
                                    alignPosition.MaxVelocity = math.huge
                                    alignPosition.Responsiveness = 9999999999999
                                end
                            end
                        end
                    end
                end
                task.wait()
            end
            local grabParts = workspace:FindFirstChild("GrabParts")
            if grabParts then
                local dragParts = {grabParts:FindFirstChild("DragPart"), grabParts:FindFirstChild("DragPart1")}
                for _, dragPart in pairs(dragParts) do
                    if dragPart then
                        local myChar = LocalPlayer.Character
                        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                        if myRoot then
                            myRoot.AssemblyLinearVelocity = dragPart.AssemblyLinearVelocity
                            myRoot.AssemblyAngularVelocity = dragPart.AssemblyAngularVelocity
                        end
                        local ao = dragPart:FindFirstChildOfClass("AlignOrientation")
                        if ao then ao.MaxAngularVelocity = 20000; ao.MaxTorque = 100000; ao.Responsiveness = 40 end
                        local ap = dragPart:FindFirstChildOfClass("AlignPosition")
                        if ap then ap.MaxAxesForce = Vector3.new(100000, 100000, 100000); ap.MaxForce = 100000; ap.MaxVelocity = 20000; ap.Responsiveness = 40 end
                    end
                end
            end
        end)
    end
end})
grabFuncSec:Toggle({Text = "Massless Grab Toys", Flag = "MasslessGrabToys", Default = false, Callback = function(v)
    Settings.Grab.MasslessGrabToys = v
    if v then
        task.spawn(function()
            while Settings.Grab.MasslessGrabToys do
                local grabParts = workspace:FindFirstChild("GrabParts")
                if grabParts then
                    for _, gp in ipairs(grabParts:GetChildren()) do
                        local weld = gp:FindFirstChildOfClass("WeldConstraint")
                        if weld and weld.Part1 then
                            local part = weld.Part1
                            local char = Players:GetPlayerFromCharacter(part.Parent)
                            if not char then char = Players:GetPlayerFromCharacter(part) end
                            if not char or char == LocalPlayer then
                                local dragParts = {grabParts:FindFirstChild("DragPart"), grabParts:FindFirstChild("DragPart1")}
                                for _, dragPart in pairs(dragParts) do
                                    if dragPart then
                                        local alignOrientation = dragPart:FindFirstChildOfClass("AlignOrientation")
                                        if alignOrientation then
                                            alignOrientation.MaxAngularVelocity = math.huge
                                            alignOrientation.MaxTorque = math.huge
                                            alignOrientation.Responsiveness = 9999999999999
                                        end
                                        local alignPosition = dragPart:FindFirstChildOfClass("AlignPosition")
                                        if alignPosition then
                                            alignPosition.MaxAxesForce = Vector3.new(math.huge, math.huge, math.huge)
                                            alignPosition.MaxForce = math.huge
                                            alignPosition.MaxVelocity = math.huge
                                            alignPosition.Responsiveness = 9999999999999
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                task.wait()
            end
            local grabParts = workspace:FindFirstChild("GrabParts")
            if grabParts then
                local dragParts = {grabParts:FindFirstChild("DragPart"), grabParts:FindFirstChild("DragPart1")}
                for _, dragPart in pairs(dragParts) do
                    if dragPart then
                        local myChar = LocalPlayer.Character
                        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                        if myRoot then
                            myRoot.AssemblyLinearVelocity = dragPart.AssemblyLinearVelocity
                            myRoot.AssemblyAngularVelocity = dragPart.AssemblyAngularVelocity
                        end
                        local ao = dragPart:FindFirstChildOfClass("AlignOrientation")
                        if ao then ao.MaxAngularVelocity = 20000; ao.MaxTorque = 100000; ao.Responsiveness = 40 end
                        local ap = dragPart:FindFirstChildOfClass("AlignPosition")
                        if ap then ap.MaxAxesForce = Vector3.new(100000, 100000, 100000); ap.MaxForce = 100000; ap.MaxVelocity = 20000; ap.Responsiveness = 40 end
                    end
                end
            end
        end)
    end
end})
