local loopBlobKillAllSec = LoopTab:Section({Text = "Blobman Kill All"})
loopBlobKillAllSec:Toggle({Text = "Kill All", Flag = "BlobmanKillAll", Default = false, Callback = function(v)
    Settings.BlobmanBeta.blobmanKillAllActive = v
    if v then
        task.spawn(function()
            local blob = BlobmanBetaFeature.getBlobman()
                or BlobmanBetaFeature.findAnyBlobman()
                or BlobmanBetaFeature.spawnBlobman()
            if not blob or not blob:FindFirstChild("VehicleSeat") then
                warn("No blobman") Settings.BlobmanBeta.blobmanKillAllActive = false return
            end
            if not BlobmanBetaFeature.isSittingOnBlobman() then
                local myRoot = BlobmanBetaFeature.getLocalRoot()
                local hum = BlobmanBetaFeature.getLocalHum()
                if myRoot and hum then
                    myRoot.CFrame = blob.VehicleSeat.CFrame + Vector3.new(0, 2, 0)
                    task.wait(0.05)
                    blob.VehicleSeat:Sit(hum)
                    task.wait(0.1)
                end
                if not BlobmanBetaFeature.isSittingOnBlobman() then
                    warn("Failed to sit") Settings.BlobmanBeta.blobmanKillAllActive = false return
                end
            end
            local MyBlob = BlobmanBetaFeature.getBlobman()
            if not MyBlob then Settings.BlobmanBeta.blobmanKillAllActive = false return end
            local safePos = MyBlob.VehicleSeat.CFrame
            while Settings.BlobmanBeta.blobmanKillAllActive and task.wait() do
                local mychar = LocalPlayer.Character
                local myHRP = mychar and mychar:FindFirstChild("HumanoidRootPart")
                local myhum = mychar and mychar:FindFirstChildOfClass("Humanoid")
                if not (myhum and myHRP) then continue end
                if not BlobmanBetaFeature.isSittingOnBlobman() then
                    local seat = MyBlob and MyBlob:FindFirstChild("VehicleSeat")
                    if seat then
                        myHRP.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
                        task.wait(0.05)
                        seat:Sit(myhum)
                        task.wait(0.1)
                    end
                    if not BlobmanBetaFeature.isSittingOnBlobman() then continue end
                end
                MyBlob = BlobmanBetaFeature.getBlobman()
                if not MyBlob then continue end
                for _, ct in ipairs(Players:GetPlayers()) do
                    if ct == LocalPlayer then continue end
                    if isProtectedPlayer(ct.Name) then continue end
                    if Settings.BlobmanBeta.ignoreFriends or Settings.Loop.WhitelistFriends then
                        local isFriend = false
                        pcall(function() isFriend = LocalPlayer:IsFriendsWith(ct.UserId) end)
                        if isFriend then continue end
                    end
                    if not Settings.BlobmanBeta.blobmanKillAllActive then break end
                    local ctChar = ct.Character
                    if not ctChar then continue end
                    local hum = ctChar:FindFirstChildOfClass("Humanoid")
                    local HRP = ctChar:FindFirstChild("HumanoidRootPart")
                    if not (hum and HRP and hum.Health > 0) then continue end
                    local killAttempts = 0
                    while Settings.BlobmanBeta.blobmanKillAllActive and killAttempts < 3 do
                        killAttempts = killAttempts + 1
                        ctChar = ct.Character
                        hum = ctChar and ctChar:FindFirstChildOfClass("Humanoid")
                        HRP = ctChar and ctChar:FindFirstChild("HumanoidRootPart")
                        if not (hum and HRP) then break end
                        if hum.Health == 0 then break end
                        MyBlob = BlobmanBetaFeature.getBlobman()
                        if not MyBlob then break end
                        local blobRoot = MyBlob:FindFirstChild("HumanoidRootPart")
                        local scr = MyBlob:FindFirstChild("BlobmanSeatAndOwnerScript")
                        local CG = scr and scr:FindFirstChild("CreatureGrab")
                        local CD = scr and scr:FindFirstChild("CreatureRelease")
                        local rd = MyBlob:FindFirstChild("RightDetector")
                        local rw = rd and rd:FindFirstChild("RightWeld")
                        if not (blobRoot and CG and CD and rw) then break end
                        local savedPos = myHRP.CFrame
                        blobRoot.CFrame = HRP.CFrame
                        task.wait(0.1)
                        repeat task.wait()
                            CG:FireServer(nil, HRP, rw)
                            CD:FireServer(rw)
                        until not Settings.BlobmanBeta.blobmanKillAllActive or isnetworkowner(HRP)
                        if not Settings.BlobmanBeta.blobmanKillAllActive then break end
                        task.wait()
                        if hum.Health ~= 0 then hum:ChangeState("Dead") end
                        pcall(function()
                            myHRP.AssemblyLinearVelocity = Vector3.zero
                            myHRP.AssemblyAngularVelocity = Vector3.zero
                        end)
                        pcall(function()
                            blobRoot.AssemblyLinearVelocity = Vector3.zero
                            blobRoot.AssemblyAngularVelocity = Vector3.zero
                        end)
                        blobRoot.CFrame = savedPos
                        task.wait(0.2)
                    end
                end
                MyBlob = BlobmanBetaFeature.getBlobman()
                if MyBlob then
                    MyBlob.VehicleSeat.CFrame = safePos
                    for _, p in ipairs(MyBlob:GetDescendants()) do
                        if p:IsA("BasePart") then
                            p.AssemblyLinearVelocity = Vector3.zero
                            p.AssemblyAngularVelocity = Vector3.zero
                        end
                    end
                end
                task.wait(0.3)
            end
        end)
    end
end})
local loopKickAllSec = LoopTab:Section({Text = "Blobman Kick All", Side = "Right"})
loopKickAllSec:Toggle({Text = "Kick All", Flag = "KickAll", Default = false, Callback = function(v)
    Settings.BlobmanBeta.kickAllActive = v
    if v then
        task.spawn(function()
            local blob = BlobmanBetaFeature.getBlobman()
                or BlobmanBetaFeature.findAnyBlobman()
                or BlobmanBetaFeature.spawnBlobman()
            if not blob or not blob:FindFirstChild("VehicleSeat") then
                warn("No blobman") Settings.BlobmanBeta.kickAllActive = false return
            end
            local myChar = LocalPlayer.Character
            local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
            if not myHRP or not myHum then Settings.BlobmanBeta.kickAllActive = false return end
            local seat = blob.VehicleSeat
            if not myHum.Sit or myHum.SeatPart ~= seat then
                if seat.Occupant and seat.Occupant ~= myHum then
                    pcall(function() seat.Occupant.Jump = true end)
                    task.wait(0.1)
                end
                local sitStart = tick()
                while tick() - sitStart < 0.5 do
                    if not blob or not blob.Parent then break end
                    myHRP.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
                    task.wait(0.03)
                    seat:Sit(myHum)
                    task.wait(0.05)
                    if myHum.Sit and myHum.SeatPart == seat then break end
                end
            end
            while Settings.BlobmanBeta.kickAllActive do
                if not BlobmanBetaFeature.isSittingOnBlobman() then
                    local s = blob and blob:FindFirstChild("VehicleSeat")
                    if not s then task.wait(0.1) continue end
                    local r = BlobmanBetaFeature.getLocalRoot()
                    local h = BlobmanBetaFeature.getLocalHum()
                    if r and h then
                        if s.Occupant and s.Occupant ~= h then
                            pcall(function() s.Occupant.Jump = true end)
                            task.wait(0.1)
                        end
                        r.CFrame = s.CFrame + Vector3.new(0, 2, 0)
                        task.wait(0.05)
                        s:Sit(h)
                        task.wait(0.1)
                    end
                    if not BlobmanBetaFeature.isSittingOnBlobman() then
                        task.wait(0.1)
                        continue
                    end
                end
                local targets = {}
                for _, plr in Players:GetPlayers() do
                    if plr == LocalPlayer then continue end
                    if not BlobmanBetaFeature.isValidTarget(plr) then continue end
                    local char = plr.Character
                    if not char then continue end
                    local root = char:FindFirstChild("HumanoidRootPart")
                    if not root then continue end
                    table.insert(targets, {plr = plr, root = root})
                end
                local blobPos = blob.VehicleSeat.Position
                table.sort(targets, function(a, b)
                    return (a.root.Position - blobPos).Magnitude < (b.root.Position - blobPos).Magnitude
                end)
                for _, t in ipairs(targets) do
                    if not Settings.BlobmanBeta.kickAllActive then break end
                    if not BlobmanBetaFeature.isSittingOnBlobman() then
                        local seat = blob and blob:FindFirstChild("VehicleSeat")
                        if not seat then break end
                        local myRoot = BlobmanBetaFeature.getLocalRoot()
                        local hum = BlobmanBetaFeature.getLocalHum()
                        if myRoot and hum then
                            myRoot.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
                            task.wait(0.05)
                            seat:Sit(hum)
                            task.wait(0.1)
                        end
                        if not BlobmanBetaFeature.isSittingOnBlobman() then break end
                    end
                    local myRoot = BlobmanBetaFeature.getLocalRoot()
                    if myRoot and t.root then
                        if (t.root.Position - myRoot.Position).Magnitude > 500000 then continue end
                        myRoot.CFrame = t.root.CFrame
                        task.wait(0.03)
                        BlobmanBetaFeature.blobKick(blob, t.root, Settings.BlobmanBeta.currentSide)
                        task.wait(0.03)
                        BlobmanBetaFeature.ungrab(myRoot)
                        task.wait(0.03)
                        myRoot.CFrame = blob.VehicleSeat.CFrame + Vector3.new(0, 2, 0)
                        task.wait(0.03)
                        local hum = BlobmanBetaFeature.getLocalHum()
                        if hum and blob:FindFirstChild("VehicleSeat") then
                            blob.VehicleSeat:Sit(hum)
                            task.wait(0.05)
                        end
                    end
                end
                task.wait(0.05)
            end
        end)
    end
end})
loopKickAllSec:Toggle({Text = "Kick All V2", Flag = "KickAllV2Loop", Default = false, Callback = function(v)
    Settings.BlobmanBeta.kickAllV2Active = v
    if v then
        task.spawn(function()
            local savedGravity = nil
            local function cleanupBodies()
                for _, p in ipairs(Players:GetPlayers()) do
                    local tRoot = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
                    if tRoot then
                        local bp = tRoot:FindFirstChild("KickV2BodyPosition")
                        if bp then pcall(function() bp:Destroy() end) end
                        local bg = tRoot:FindFirstChild("KickV2BodyGyro")
                        if bg then pcall(function() bg:Destroy() end) end
                    end
                end
            end
            local function stopSelf()
                if savedGravity ~= nil then
                    pcall(function() Workspace.Gravity = savedGravity end)
                end
                Settings.BlobmanBeta.kickAllV2Active = false
                cleanupBodies()
                pcall(function()
                    if library._flagSetters and library._flagSetters["KickAllV2Loop"] then
                        library._flagSetters["KickAllV2Loop"](false)
                    end
                end)
            end
            local function isStillActive()
                return Settings.BlobmanBeta.kickAllV2Active
            end
            local function ensureSitting()
                for attempt = 1, 50 do
                    if not isStillActive() then return false end
                    local myChar = LocalPlayer.Character
                    local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
                    if not myHRP or not myHum then task.wait(0.2) continue end
                    if myHum.Sit and myHum.SeatPart and myHum.SeatPart.Parent and myHum.SeatPart.Parent.Name == "CreatureBlobman" and not isGucciBlobman(myHum.SeatPart.Parent) then
                        return true
                    end
                    local blob = BlobmanBetaFeature.getBlobman()
                        or BlobmanBetaFeature.findAnyBlobman()
                        or BlobmanBetaFeature.spawnBlobman()
                    if not blob or not blob:FindFirstChild("VehicleSeat") then
                        task.wait(0.2)
                        continue
                    end
                    local seat = blob.VehicleSeat
                    if seat.Occupant and seat.Occupant ~= myHum then
                        pcall(function() seat.Occupant.Jump = true end)
                        task.wait(0.1)
                    end
                    myHRP.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
                    pcall(function() seat:Sit(myHum) end)
                    task.wait(0.05)
                end
                return false
            end
            if not ensureSitting() then
                stopSelf()
                return
            end
            local myChar = LocalPlayer.Character
            local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
            if not myHRP or not myHum then stopSelf() return end
            local MyBlob = myHum.SeatPart.Parent
            local scr = MyBlob:FindFirstChild("BlobmanSeatAndOwnerScript") or MyBlob:FindFirstChild("BlobmanSeatAndOwnerScript[old]")
            local CreatureGrab = scr and scr:FindFirstChild("CreatureGrab")
            local CreatureRelease = scr and scr:FindFirstChild("CreatureRelease")
            local CreatureDrop = scr and scr:FindFirstChild("CreatureDrop")
            if not CreatureGrab or not CreatureRelease then stopSelf() return end
            if not isStillActive() then stopSelf() return end
            local allPlayers = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and not isProtectedPlayer(p.Name) then
                    if Settings.BlobmanBeta.ignoreFriends or Settings.Loop.WhitelistFriends then
                        local isFriend = false
                        pcall(function() isFriend = LocalPlayer:IsFriendsWith(p.UserId) end)
                        if isFriend then continue end
                    end
                    local tChar = p.Character
                    local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                    local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
                    if tRoot and tHum and tHum.Health > 0 then
                        table.insert(allPlayers, p)
                    end
                end
            end
            if #allPlayers == 0 then stopSelf() return end
            for _, targetPlayer in ipairs(allPlayers) do
                if not isStillActive() then stopSelf() return end
                myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                myHum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if not myHRP or not myHum then break end
                if not myHum.Sit or not myHum.SeatPart or myHum.SeatPart.Parent.Name ~= "CreatureBlobman" then
                    stopSelf()
                    return
                end
                local targetRoot = targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                if targetRoot then
                    myHRP.CFrame = targetRoot.CFrame
                    task.wait(0.02)
                    for i = 1, 3 do
                        if not isStillActive() then break end
                        pcall(function()
                            setNetworkOwnerEvent:FireServer(targetRoot, targetRoot.CFrame)
                            CreatureGrab:FireServer(MyBlob.LeftDetector, targetRoot, MyBlob.LeftDetector.LeftWeld)
                            CreatureRelease:FireServer(MyBlob.LeftDetector.LeftWeld)
                        end)
                        if i < 3 then task.wait(0.08) end
                    end
                end
            end
            if not isStillActive() then stopSelf() return end
            myHRP = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not myHRP then stopSelf() return end
            if not (myHum and myHum.Sit and myHum.SeatPart and myHum.SeatPart.Parent and myHum.SeatPart.Parent.Name == "CreatureBlobman" and MyBlob and MyBlob.Parent) then
                stopSelf()
                return
            end
            myHRP.CFrame = CFrame.new(0, 100, 0)
            pcall(function()
                myHRP.AssemblyLinearVelocity = Vector3.zero
                myHRP.AssemblyAngularVelocity = Vector3.zero
            end)
            pcall(function()
                local bh = MyBlob and MyBlob:FindFirstChild("HumanoidRootPart")
                if bh then
                    bh.AssemblyLinearVelocity = Vector3.zero
                    bh.AssemblyAngularVelocity = Vector3.zero
                end
            end)
            savedGravity = Workspace.Gravity
            pcall(function() Workspace.Gravity = 0 end)
            local holdMeStart = tick()
            local didGrab = false
            while tick() - holdMeStart < 2 and isStillActive() do
                pcall(function()
                    myHRP.CFrame = CFrame.new(0, 100, 0)
                    myHRP.AssemblyLinearVelocity = Vector3.zero
                    myHRP.AssemblyAngularVelocity = Vector3.zero
                    local bh = MyBlob and MyBlob:FindFirstChild("HumanoidRootPart")
                    if bh then
                        bh.CFrame = CFrame.new(0, 100, 0)
                        bh.AssemblyLinearVelocity = Vector3.zero
                        bh.AssemblyAngularVelocity = Vector3.zero
                    end
                end)
                local center = myHRP.Position
                local radius = (10 * 1.4) * 1.2
                for _, targetPlayer in ipairs(allPlayers) do
                    if not isStillActive() then break end
                    local targetRoot = targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if targetRoot then
                        local idx = table.find(allPlayers, targetPlayer) or 1
                        local angle = math.rad((idx - 1) * (360 / #allPlayers))
                        local x = center.X + radius * math.cos(angle)
                        local z = center.Z + radius * math.sin(angle)
                        local cf = CFrame.new(x, center.Y + 10, z)
                        targetRoot.CFrame = cf
                        targetRoot.AssemblyLinearVelocity = Vector3.zero
                        targetRoot.AssemblyAngularVelocity = Vector3.zero
                    end
                end
                if not didGrab then
                    didGrab = true
                    cleanupBodies()
                    for _ = 1, 2 do
                        if not isStillActive() then break end
                        for _, targetPlayer in ipairs(allPlayers) do
                            if not isStillActive() then break end
                            local targetRoot = targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                            if targetRoot then
                                pcall(function()
                                    setNetworkOwnerEvent:FireServer(targetRoot, CFrame.new(targetRoot.Position))
                                end)
                                pcall(function()
                                    destroyGrabLineEvent:FireServer(targetRoot)
                                end)
                            end
                        end
                        task.wait(0.05)
                    end
                    for _, part in ipairs(MyBlob:GetDescendants()) do
                        if part:IsA("BasePart") then pcall(function() part.Anchored = false end) end
                    end
                    local LeftDetector = MyBlob:FindFirstChild("LeftDetector")
                    local RightDetector = MyBlob:FindFirstChild("RightDetector")
                    if CreatureDrop then
                        for _, targetPlayer in ipairs(allPlayers) do
                            if not isStillActive() then break end
                            local targetRoot = targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                            if targetRoot then
                                pcall(function()
                                    CreatureDrop:FireServer(LeftDetector.LeftWeld, targetRoot:FindFirstChild("RootAttachment") or targetRoot)
                                end)
                                if RightDetector then
                                    pcall(function()
                                        CreatureDrop:FireServer(RightDetector.RightWeld, targetRoot:FindFirstChild("RootAttachment") or targetRoot)
                                    end)
                                end
                            end
                        end
                    end
                    for _, targetPlayer in ipairs(allPlayers) do
                        if not isStillActive() then break end
                        local targetRoot = targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                        if targetRoot then
                            pcall(function()
                                CreatureGrab:FireServer(LeftDetector, targetRoot, LeftDetector.LeftWeld)
                                CreatureRelease:FireServer(LeftDetector.LeftWeld)
                            end)
                            if RightDetector then
                                pcall(function()
                                    CreatureGrab:FireServer(RightDetector, targetRoot, RightDetector.RightWeld)
                                    CreatureRelease:FireServer(RightDetector.RightWeld)
                                end)
                            end
                        end
                    end
                    task.wait(0.2)
                    for attempt = 1, 5 do
                        if not isStillActive() then break end
                        for _, targetPlayer in ipairs(allPlayers) do
                            if not isStillActive() then break end
                            local targetRoot = targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                            if targetRoot then
                                pcall(function()
                                    CreatureGrab:FireServer(LeftDetector, targetRoot, LeftDetector.LeftWeld)
                                end)
                                if RightDetector then
                                    pcall(function()
                                        CreatureGrab:FireServer(RightDetector, targetRoot, RightDetector.RightWeld)
                                    end)
                                end
                            end
                        end
                        task.wait(0.05)
                    end
                end
                task.wait(0.03)
            end
            stopSelf()
        end)
    else
        for _, p in ipairs(Players:GetPlayers()) do
            local tRoot = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
            if tRoot then
                local bp = tRoot:FindFirstChild("KickV2BodyPosition")
                if bp then pcall(function() bp:Destroy() end) end
                local bg = tRoot:FindFirstChild("KickV2BodyGyro")
                if bg then pcall(function() bg:Destroy() end) end
            end
        end
    end
end})
loopKickAllSec:Toggle({Text = "Kick All V3", Flag = "KickAllV3Loop", Default = false, Callback = function(v)
    Settings.BlobmanBeta.kickV3Active = v
    if v then
        task.spawn(function()
            local function isActive()
                return Settings.BlobmanBeta.kickV3Active
            end
            local function snapBlobTo(blob, targetCFrame)
                local hrp = blob:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                hrp.CFrame = targetCFrame
                local att0 = hrp:FindFirstChild("BlobAttachment") or Instance.new("Attachment", hrp)
                att0.Name = "BlobAttachment"
                local targetPart = Workspace:FindFirstChild("BlobTarget") or Instance.new("Part")
                targetPart.Anchored = true
                targetPart.CanCollide = false
                targetPart.Size = Vector3.new(1,1,1)
                targetPart.Transparency = 1
                targetPart.CFrame = targetCFrame
                targetPart.Name = "BlobTarget"
                targetPart.Parent = Workspace
                local att1 = targetPart:FindFirstChild("BlobTargetAttachment") or Instance.new("Attachment", targetPart)
                att1.Name = "BlobTargetAttachment"
                local ap = hrp:FindFirstChild("BlobAlignPos") or Instance.new("AlignPosition", hrp)
                ap.Name = "BlobAlignPos"
                ap.Attachment0 = att0
                ap.Attachment1 = att1
                ap.RigidityEnabled = true
                ap.Responsiveness = 300
                ap.MaxForce = math.huge
                local ao = hrp:FindFirstChild("BlobAlignOri") or Instance.new("AlignOrientation", hrp)
                ao.Name = "BlobAlignOri"
                ao.Attachment0 = att0
                ao.Attachment1 = att1
                ao.Responsiveness = 300
                ao.MaxTorque = math.huge
                ao.RigidityEnabled = true
            end
            local function releaseBlobAlign(blob)
                local hrp = blob:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                if hrp:FindFirstChild("BlobAlignPos") then hrp.BlobAlignPos:Destroy() end
                if hrp:FindFirstChild("BlobAlignOri") then hrp.BlobAlignOri:Destroy() end
                if hrp:FindFirstChild("BlobAttachment") then hrp.BlobAttachment:Destroy() end
                local targetPart = Workspace:FindFirstChild("BlobTarget")
                if targetPart then targetPart:Destroy() end
            end
            local function stopRun(blob)
                pcall(function()
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Sit then
                        hum.Sit = false
                        task.wait(0.05)
                    end
                end)
                if blob then
                    pcall(function()
                        local det = blob:FindFirstChild("LeftDetector")
                        local w = det and det:FindFirstChild("LeftWeld")
                        local scr = blob:FindFirstChild("BlobmanSeatAndOwnerScript", true)
                        if scr and w then
                            local releaseRemote = scr:FindFirstChild("CreatureRelease")
                            if releaseRemote then releaseRemote:FireServer(w) end
                            local dropRemote = scr:FindFirstChild("CreatureDrop")
                            if dropRemote then dropRemote:FireServer(w) end
                        end
                    end)
                    releaseBlobAlign(blob)
                end
                Settings.BlobmanBeta.kickV3Active = false
                pcall(function()
                    if library._flagSetters and library._flagSetters["KickAllV3Loop"] then
                        library._flagSetters["KickAllV3Loop"](false)
                    end
                end)
            end
            local blob = BlobmanBetaFeature.getBlobman()
                or BlobmanBetaFeature.findAnyBlobman()
                or BlobmanBetaFeature.spawnBlobman()
            if not blob or not blob:FindFirstChild("VehicleSeat") then
                library:Notify({Title = "Kick All V3", Description = "Blobman not found!", Time = 3})
                stopRun(nil)
                return
            end
            local myChar2 = LocalPlayer.Character
            local myHRP2 = myChar2 and myChar2:FindFirstChild("HumanoidRootPart")
            local myHum2 = myChar2 and myChar2:FindFirstChildOfClass("Humanoid")
            if not myHRP2 or not myHum2 then
                stopRun(blob)
                return
            end
            local vehicleSeat = blob.VehicleSeat
            if not myHum2.Sit or myHum2.SeatPart ~= vehicleSeat then
                if vehicleSeat.Occupant and vehicleSeat.Occupant ~= myHum2 then
                    pcall(function() vehicleSeat.Occupant.Jump = true end)
                    task.wait(0.1)
                end
                local sitStart = tick()
                while isActive() and tick() - sitStart < 0.5 do
                    if not blob or not blob.Parent then break end
                    myHRP2.CFrame = vehicleSeat.CFrame + Vector3.new(0, 2, 0)
                    pcall(function() vehicleSeat:Sit(myHum2) end)
                    if myHum2.Sit and myHum2.SeatPart == vehicleSeat then break end
                    task.wait(0.03)
                end
            end
            for _ = 1, 20 do
                if not isActive() then stopRun(blob) return end
                if myHum2.Sit and myHum2.SeatPart and myHum2.SeatPart.Parent and myHum2.SeatPart.Parent.Name == "CreatureBlobman" and not isGucciBlobman(myHum2.SeatPart.Parent) then break end
                BlobmanBetaFeature.forceSitBlobman()
                task.wait(0.2)
            end
            if not (myHum2.Sit and myHum2.SeatPart and myHum2.SeatPart.Parent and myHum2.SeatPart.Parent.Name == "CreatureBlobman" and not isGucciBlobman(myHum2.SeatPart.Parent)) then
                library:Notify({Title = "Kick All V3", Description = "Failed to sit on blobman!", Time = 3})
                stopRun(blob)
                return
            end
            blob = myHum2.SeatPart.Parent
            local players = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and not isProtectedPlayer(p.Name) then
                    if Settings.BlobmanBeta.ignoreFriends or Settings.Loop.WhitelistFriends then
                        local isFriend = false
                        pcall(function() isFriend = LocalPlayer:IsFriendsWith(p.UserId) end)
                        if isFriend then continue end
                    end
                    table.insert(players, p.Name)
                end
            end
            if #players == 0 then
                library:Notify({Title = "Kick All V3", Description = "No players to kick!", Time = 3})
                stopRun(blob)
                return
            end
            local seatScript = blob:FindFirstChild("BlobmanSeatAndOwnerScript") or blob:FindFirstChild("BlobmanSeatAndOwnerScript[old]")
            if not seatScript then
                library:Notify({Title = "Kick All V3", Description = "Blobman script not found!", Time = 3})
                stopRun(blob)
                return
            end
            local grab = seatScript:FindFirstChild("CreatureGrab")
            local release = seatScript:FindFirstChild("CreatureRelease")
            local drop = seatScript:FindFirstChild("CreatureDrop")
            local set = setNetworkOwnerEvent
            local del = destroyGrabLineEvent
            local detector = blob:FindFirstChild("LeftDetector")
            local weld = detector and detector:FindFirstChild("LeftWeld")
            local localHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not localHrp then
                stopRun(blob)
                return
            end
            for _, playerName in ipairs(players) do
                if not isActive() then stopRun(blob) return end
                local plr = Players:FindFirstChild(playerName)
                if plr and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                    local targetHrp = plr.Character.HumanoidRootPart
                    snapBlobTo(blob, targetHrp.CFrame)
                    task.wait(0.15)
                    pcall(function() grab:FireServer(blob.RightDetector, targetHrp, blob.RightDetector.RightWeld) end)
                    pcall(function() release:FireServer(blob.RightDetector.RightWeld) end)
                    task.wait(0.05)
                end
            end
            if not isActive() then stopRun(blob) return end
            snapBlobTo(blob, CFrame.new(Vector3.new(0, 100, 0)))
            task.wait(0.1)
            local center = Vector3.new(0, 100, 0)
            local baseRadius = 40
            local radius = (baseRadius + (#players * 5)) * 1.4
            local numPlayers = #players
            local angleIncrement = (2 * math.pi) / numPlayers
            for i, playerName in ipairs(players) do
                if not isActive() then stopRun(blob) return end
                local angle = angleIncrement * (i - 1)
                local x = center.X + radius * math.cos(angle)
                local z = center.Z + radius * math.sin(angle)
                local blobPosition = Vector3.new(x, center.Y, z)
                snapBlobTo(blob, CFrame.new(blobPosition))
                task.wait(0.1)
                local plr = Players:FindFirstChild(playerName)
                if plr and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                    local targetHrp = plr.Character.HumanoidRootPart
                    local blobHrp = blob:FindFirstChild("HumanoidRootPart")
                    if blobHrp then
                        targetHrp.CFrame = CFrame.new(blobHrp.Position.X, blobHrp.Position.Y + 20, blobHrp.Position.Z)
                        task.wait(0.15)
                        pcall(function() set:FireServer(targetHrp, targetHrp.CFrame) end)
                        pcall(function() del:FireServer(targetHrp) end)
                        pcall(function() grab:FireServer(detector, localHrp, weld) end)
                        pcall(function() grab:FireServer(detector, targetHrp, weld) end)
                        pcall(function() drop:FireServer(weld, targetHrp.RootAttachment) end)
                    end
                end
                task.wait(0)
            end
            if not isActive() then stopRun(blob) return end
            task.wait(1)
            releaseBlobAlign(blob)
            stopRun(blob)
        end)
    end
end})
local loopAuraSec = LoopTab:Section({Text = "Blobman Kick Aura", Side = "Left"})
loopAuraSec:Toggle({Text = "Kick Aura", Flag = "KickAura", Default = false, Callback = function(v)
    Settings.BlobmanBeta.kickAuraActive = v
    if v then
        Settings.BlobmanBeta.auraKickedPlayers = {}
        local auraSide = "Left"
        task.spawn(function()
            while Settings.BlobmanBeta.kickAuraActive do
                if not BlobmanBetaFeature.isSittingOnBlobman() then
                    local blob = BlobmanBetaFeature.getBlobman()
                        or BlobmanBetaFeature.findAnyBlobman()
                        or BlobmanBetaFeature.spawnBlobman()
                    if not blob then task.wait(0.1) continue end
                    BlobmanBetaFeature.ensureSitBlobman()
                    task.wait(0.05)
                    continue
                end
                local blob = BlobmanBetaFeature.getBlobman()
                if not blob then task.wait(0.1) continue end
                local myRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if not myRoot then task.wait(0.1) continue end
                local currentTime = tick()
                for playerId, kickTime in pairs(Settings.BlobmanBeta.auraKickedPlayers) do
                    if currentTime - kickTime >= 1.5 then
                        Settings.BlobmanBeta.auraKickedPlayers[playerId] = nil
                    end
                end
                local nearbyPlayers = {}
                for _, plr in Players:GetPlayers() do
                    if plr == LocalPlayer then continue end
                    if Settings.BlobmanBeta.auraKickedPlayers[plr.UserId] then continue end
                    if not BlobmanBetaFeature.isValidTarget(plr, myRoot) then continue end
                    local char = plr.Character
                    local root = char and char:FindFirstChild("HumanoidRootPart")
                    if not root then continue end
                    local dist = (root.Position - myRoot.Position).Magnitude
                    if dist < 50 then
                        table.insert(nearbyPlayers, {plr = plr, root = root, dist = dist})
                    end
                end
                table.sort(nearbyPlayers, function(a, b) return a.dist < b.dist end)
                if #nearbyPlayers > 0 then
                    local target = nearbyPlayers[1]
                    local targetHum = target.root.Parent:FindFirstChildOfClass("Humanoid")
                    if BlobmanBetaFeature.isSittingOnBlobman() then
                        myRoot.AssemblyLinearVelocity = Vector3.zero
                        BlobmanBetaFeature.blobGrab(blob, myRoot, auraSide)
                        task.wait(0.03)
                        BlobmanBetaFeature.SetNetworkOwner(target.root)
                        task.wait(0.03)
                        target.root.CFrame = target.root.CFrame + Vector3.new(0, Settings.BlobmanBeta.FloatAmount, 0)
                        task.wait(0.03)
                        BlobmanBetaFeature.ungrab(target.root)
                        BlobmanBetaFeature.blobGrab(blob, target.root, auraSide)
                        task.wait(0.03)
                        BlobmanBetaFeature.blobDrop(blob, target.root, auraSide)
                        task.wait(0.03)
                        BlobmanBetaFeature.ungrab(target.root)
                        local healthAfter = targetHum and targetHum.Health or 0
                        if healthAfter <= 0 then
                            Settings.BlobmanBeta.auraKickedPlayers[target.plr.UserId] = nil
                        else
                            Settings.BlobmanBeta.auraKickedPlayers[target.plr.UserId] = tick()
                        end
                        auraSide = (auraSide == "Left") and "Right" or "Left"
                    end
                end
                task.wait(0.05)
            end
            Settings.BlobmanBeta.auraKickedPlayers = {}
        end)
    end
end})
local function reconnect()
    local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    local humanoid = character:FindFirstChildWhichIsA("Humanoid") or character:WaitForChild("Humanoid")
    local hrp = character:WaitForChild("HumanoidRootPart")
    character:WaitForChild("Head")
    State.IsCharacterInRagdoll = false
    humanoid.Changed:Connect(function(prop)
        if prop == "Sit" and humanoid.Sit == true then
            if humanoid.SeatPart == nil and Settings.Anti.AntiGrab then
                humanoid:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
                humanoid.Sit = false
            end
        end
    end)
    if Settings.Anti.AntiKickKunai then
        task.delay(0.8, function()
            if Settings.Anti.AntiKickKunai then AntiFeature.attachKunai(true) end
        end)
    end
    if Settings.Anti.AntiKickKunai2 then
        task.delay(0.8, function()
            if Settings.Anti.AntiKickKunai2 then AntiFeature.attachKunaiLeft(true) end
        end)
    end
    if Settings.Anti.AntiExplosion and character then
        AntiFeature.setupAntiExplosion(character)
    end
end
LocalPlayer.CharacterAdded:Connect(reconnect)
task.spawn(reconnect)
local function autoSitOnRespawn(char)
    local isAnyActive = Settings.BlobmanBeta.loopKillActive
        or Settings.BlobmanBeta.kickActive
        or Settings.BlobmanBeta.kickV2Active
        or Settings.BlobmanBeta.kickV4Active
        or Settings.BlobmanBeta.driftKickActive
        or Settings.BlobmanBeta.kickAllV2Active
        or Settings.BlobmanBeta.kickAuraActive
    if not isAnyActive then return end
    char:WaitForChild("Humanoid")
    char:WaitForChild("HumanoidRootPart")
    task.wait(0.5)
    for _ = 1, 30 do
        if not isAnyActive then return end
        if BlobmanBetaFeature.isSittingOnBlobman() then return end
        pcall(function() BlobmanBetaFeature.forceSitBlobman() end)
        task.wait(1)
        if BlobmanBetaFeature.isSittingOnBlobman() then return end
    end
end
if State.connections.autoSitOnRespawn then State.connections.autoSitOnRespawn:Disconnect() end
State.connections.autoSitOnRespawn = LocalPlayer.CharacterAdded:Connect(autoSitOnRespawn)
local loopOwnershipSec = LoopTab:Section({Text = "Ownership"})
local destroyHeight = "Spawn"
local function ownershipGetAllPlayers()
    local players = {}
    for _, plr in pairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer then
            if not _G.isWhitelisted or not _G.isWhitelisted(plr) then
                table.insert(players, plr)
            end
        end
    end
    return players
end
local function ownershipSpamOwnership(hrp)
    if not grabEventsFolder then return end
    local setOwner = grabEventsFolder:FindFirstChild("SetNetworkOwner")
    if setOwner and hrp then pcall(function() setOwner:FireServer(hrp, hrp.CFrame) end) end
end
local function ownershipTeleportToPlayer(myHrp, targetHrp)
    if not myHrp or not targetHrp then return end
    pcall(function()
        myHrp.CFrame = targetHrp.CFrame * CFrame.new(0, 0, -5)
        myHrp.AssemblyLinearVelocity = Vector3.zero
    end)
end
local function ownershipDestroyLineOnPlayer(hrp)
    if not grabEventsFolder then return end
    local createLine = grabEventsFolder:FindFirstChild("CreateGrabLine")
    local destroyLine = grabEventsFolder:FindFirstChild("DestroyGrabLine")
    if not createLine or not destroyLine then return end
    pcall(function()
        createLine:FireServer(hrp, CFrame.new(0, 1e9, 0))
        task.wait()
        destroyLine:FireServer(hrp)
    end)
end
local lineLagThread = nil
local lineLagEnabled = false
local function startLineLag()
    if lineLagEnabled then return end
    lineLagEnabled = true
    lineLagThread = coroutine.create(function()
        if not grabEventsFolder then return end
        local createLine = grabEventsFolder:FindFirstChild("CreateGrabLine")
        if not createLine then return end
        while lineLagEnabled do
            local spawnLocation = Workspace:FindFirstChild("SpawnLocation") or Workspace:FindFirstChild("Spawn") or (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart"))
            if spawnLocation then
                pcall(function()
                    RemoteDispatcher:Fire(createLine, spawnLocation, CFrame.new(math.random(-9e9, 9e9), 0, math.random(-9e9, 9e9)))
                end)
            end
            task.wait()
        end
    end)
    coroutine.resume(lineLagThread)
end
local function stopLineLag()
    lineLagEnabled = false
    if lineLagThread then coroutine.close(lineLagThread); lineLagThread = nil end
end
loopOwnershipSec:Dropdown({Text = "Destroy Height", Flag = "OwnershipDestroyHeight", List = {"Spawn", "Heaven"}, Default = "Spawn", Callback = function(v)
    destroyHeight = v
end})
loopOwnershipSec:Button({Text = "Destroy Server", Callback = function()
    task.spawn(function()
        local height = (destroyHeight == "Heaven") and 1e9 or 35
        startLineLag()
        task.wait(1)
        local players = ownershipGetAllPlayers()
        if #players == 0 then
            stopLineLag()
            return
        end
        local myChar = LocalPlayer.Character
        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHrp then stopLineLag() return end
        local playerData = {}
        for _, plr in ipairs(players) do
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then table.insert(playerData, {player = plr, hrp = hrp}) end
        end
        if #playerData == 0 then stopLineLag() return end
        local processedPlayers = {}
        for _, data in ipairs(playerData) do
            if not processedPlayers[data.player] then
                local targetHrp = data.hrp
                if targetHrp and targetHrp.Parent then
                    ownershipTeleportToPlayer(myHrp, targetHrp)
                    task.wait(0.2)
                    ownershipSpamOwnership(targetHrp)
                    processedPlayers[data.player] = true

                    -- The teleport puts us next to the primary target. Claim nearby
                    -- players from that same position instead of teleporting to each one.
                    local scanPosition = myHrp.Position
                    for _, nearbyData in ipairs(playerData) do
                        if not processedPlayers[nearbyData.player] then
                            local nearbyHrp = nearbyData.hrp
                            if nearbyHrp and nearbyHrp.Parent
                                and (nearbyHrp.Position - scanPosition).Magnitude <= 30 then
                                ownershipSpamOwnership(nearbyHrp)
                                processedPlayers[nearbyData.player] = true
                                task.wait()
                            end
                        end
                    end
                    task.wait()
                else
                    processedPlayers[data.player] = true
                end
            end
        end
        local radius = 40
        local angleStep = (math.pi * 2) / #playerData
        for idx, data in ipairs(playerData) do
            local angle = (idx - 1) * angleStep
            local x = math.cos(angle) * radius
            local z = math.sin(angle) * radius
            pcall(function()
                data.hrp.CFrame = CFrame.new(x, height, z)
                data.hrp.AssemblyLinearVelocity = Vector3.zero
            end)
            local bp = Instance.new("BodyPosition")
            bp.MaxForce = Vector3.new(1e9, 1e9, 1e9)
            bp.P = 40000000
            bp.Position = Vector3.new(x, height, z)
            bp.Parent = data.hrp
            task.delay(2, function() pcall(function() bp:Destroy() end) end)
            task.wait()
        end
        for i = 1, 8 do
            for _, data in ipairs(playerData) do ownershipDestroyLineOnPlayer(data.hrp) end
            task.wait(0.3)
        end
    end)
end})
