local function auraGetRoot()
    local c = LocalPlayer.Character
    return c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("Torso"))
end
local function auraIsFriend(player)
    if not Settings.Aura.auraFriendWhitelist then return false end
    return pcall(function() return LocalPlayer:IsFriendsWith(player.UserId) end) and LocalPlayer:IsFriendsWith(player.UserId)
end
local function auraSetNetworkOwner(part)
    RemoteDispatcher:Fire(ReplicatedStorage.GrabEvents.SetNetworkOwner, part, auraGetRoot().CFrame)
end
local function auraBodyVelocity(part, vel, lifetime)
    local bv = Instance.new("BodyVelocity")
    bv.MaxForce = Vector3.one * math.huge
    bv.Velocity = vel
    bv.Parent = part
    Debris:AddItem(bv, lifetime or 1)
end
local function auraGetPlayersInRange()
    local root = auraGetRoot()
    if not root then return {} end
    local list = {}
    for _, player in pairs(Players:GetPlayers()) do
        if player ~= LocalPlayer and not auraIsFriend(player) and not isProtectedPlayer(player.Name) and player.Character then
            local hrp = player.Character:FindFirstChild("HumanoidRootPart") or player.Character:FindFirstChild("Torso")
            if hrp and (hrp.Position - root.Position).Magnitude <= Settings.Aura.auraRadius then
                table.insert(list, player)
            end
        end
    end
    return list
end
local function isMySpawnedToy(part)
    if not part then return false end
    local folder = spawnedInToysFolder or Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
    if folder and part:IsDescendantOf(folder) then return true end
    -- Check if this is the player's plot shuriken / AntiKick
    local currentShur = State.currentPlotShuriken
    if currentShur and (part == currentShur or part:IsDescendantOf(currentShur)) then
        return true
    end
    -- Check if toy is in the local player's claimed plot
    local plotItems = Workspace:FindFirstChild("PlotItems")
    if plotItems then
        for i = 1, 5 do
            local plot = Workspace.Plots:FindFirstChild("Plot"..i)
            if plot then
                local sign = plot:FindFirstChild("PlotSign")
                local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
                if owners then
                    local isMine = false
                    for _, desc in ipairs(owners:GetDescendants()) do
                        if desc.Name == "TimeRemainingNum" then
                            local valObj = desc.Parent
                            if valObj and valObj:IsA("StringValue") and valObj.Value == LocalPlayer.Name then
                                isMine = true
                                break
                            end
                        end
                    end
                    if isMine then
                        local plotFolder = plotItems:FindFirstChild("Plot"..i)
                        if plotFolder and part:IsDescendantOf(plotFolder) then
                            local model = part
                            while model and model.Parent ~= plotFolder do
                                model = model.Parent
                            end
                            if model and (model.Name == "AntiKick" or model.Name == "NinjaShuriken") then
                                return true
                            end
                        end
                    end
                end
            end
        end
    end
    return false
end
