local playerFlySec = PlayerTab:Section({Text = "Fly", Side = "Right"})
local playerTeleSec = PlayerTab:Section({Text = "Teleport", Side = "Right"})
    local flyActive = false
    local flyBV, flyBG, flyConn
    local flyCurrentVelocity = Vector3.zero
    local flyAltConn, flyCharAddedConn
    local flyKeyDown, flyKeyUp, flyVehConn
    local flyControl = {F = 0, B = 0, L = 0, R = 0, Q = 0, E = 0}
    function flyStart()
        if flyActive then return end
        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        flyActive = true
        if (Settings.Player.flyStyle or "Normal") == "Vehicle" then
            flyStartVehicle(hrp)
        else
            flyStartNormal(hrp)
        end
    end
    function flyStartNormal(hrp)
        flyBG = Instance.new("BodyGyro")
        flyBG.P = 20000 flyBG.D = 500
        flyBG.MaxTorque = Vector3.new(1e5, 1e5, 1e5)
        flyBG.CFrame = hrp.CFrame
        flyBG.Parent = hrp
        flyBV = Instance.new("BodyVelocity")
        flyBV.MaxForce = Vector3.new(1e5, 1e5, 1e5)
        flyBV.Velocity = Vector3.zero
        flyBV.Parent = hrp
        flyConn = RunService.Heartbeat:Connect(function(dt)
            if not flyActive then flyConn:Disconnect() flyConn = nil return end
            local cam = Workspace.CurrentCamera
            local hum2 = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
            if not cam or not hum2 then return end
            local md = hum2.MoveDirection
            local tv = Vector3.zero
            if md.Magnitude > 0.01 then
                local cl = cam.CFrame.LookVector
                local cr = cam.CFrame.RightVector
                local cfh = Vector3.new(cl.X, 0, cl.Z).Unit
                local crh = Vector3.new(cr.X, 0, cr.Z).Unit
                local fa = md:Dot(cfh)
                local ra = md:Dot(crh)
                local sp = Settings.Player.flySpeed
                tv = (cfh * fa + crh * ra) * sp + Vector3.new(0, cl.Y * fa * sp, 0)
            end
            flyCurrentVelocity = flyCurrentVelocity:Lerp(tv, math.clamp(dt * (tv.Magnitude > flyCurrentVelocity.Magnitude and 8 or 6), 0, 1))
            if flyBV then flyBV.Velocity = flyCurrentVelocity end
            if flyBG then flyBG.CFrame = cam.CFrame end
        end)
    end
    function flyStartVehicle(hrp)
        flyBG = Instance.new("BodyGyro")
        flyBG.P = 9e4
        flyBG.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
        flyBG.CFrame = hrp.CFrame
        flyBG.Parent = hrp
        flyBV = Instance.new("BodyVelocity")
        flyBV.MaxForce = Vector3.new(9e9, 9e9, 9e9)
        flyBV.Velocity = Vector3.zero
        flyBV.Parent = hrp
        flyVehConn = RunService.Heartbeat:Connect(function()
            if not flyActive then return end
            local cam = Workspace.CurrentCamera
            if not cam then return end
            local moving = (flyControl.F + flyControl.B + flyControl.L + flyControl.R + flyControl.Q + flyControl.E) ~= 0
            if moving then
                flyBV.Velocity = ((cam.CFrame.LookVector * (flyControl.F + flyControl.B)) + ((cam.CFrame * CFrame.new(flyControl.L + flyControl.R, (flyControl.F + flyControl.B + flyControl.Q + flyControl.E) * 0.2, 0).p) - cam.CFrame.p)) * Settings.Player.flySpeed
            else
                flyBV.Velocity = Vector3.new(0, 0, 0)
            end
            flyBG.CFrame = cam.CFrame
        end)
        flyKeyDown = UserInputService.InputBegan:Connect(function(input, processed)
            if processed then return end
            if input.KeyCode == Enum.KeyCode.W then flyControl.F = 1
            elseif input.KeyCode == Enum.KeyCode.S then flyControl.B = -1
            elseif input.KeyCode == Enum.KeyCode.A then flyControl.L = -1
            elseif input.KeyCode == Enum.KeyCode.D then flyControl.R = 1
            elseif input.KeyCode == Enum.KeyCode.E then flyControl.Q = 1
            elseif input.KeyCode == Enum.KeyCode.Q then flyControl.E = -1
            end
        end)
        flyKeyUp = UserInputService.InputEnded:Connect(function(input, processed)
            if processed then return end
            if input.KeyCode == Enum.KeyCode.W then flyControl.F = 0
            elseif input.KeyCode == Enum.KeyCode.S then flyControl.B = 0
            elseif input.KeyCode == Enum.KeyCode.A then flyControl.L = 0
            elseif input.KeyCode == Enum.KeyCode.D then flyControl.R = 0
            elseif input.KeyCode == Enum.KeyCode.E then flyControl.Q = 0
            elseif input.KeyCode == Enum.KeyCode.Q then flyControl.E = 0
            end
        end)
    end
    function flyStop()
        flyActive = false
        flyCurrentVelocity = Vector3.zero
        if flyBG then flyBG:Destroy() flyBG = nil end
        if flyBV then flyBV:Destroy() flyBV = nil end
        if flyConn then flyConn:Disconnect() flyConn = nil end
        if flyVehConn then flyVehConn:Disconnect() flyVehConn = nil end
        if flyKeyDown then flyKeyDown:Disconnect() flyKeyDown = nil end
        if flyKeyUp then flyKeyUp:Disconnect() flyKeyUp = nil end
        flyControl = {F = 0, B = 0, L = 0, R = 0, Q = 0, E = 0}
        local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
