                local part = State.pcldParts[i]
                if not part.Parent then
                    table.remove(State.pcldParts, i)
                    if State.pcldProxies then local proxy = State.pcldProxies[part]; if proxy then pcall(function() proxy:Destroy() end) State.pcldProxies[part] = nil end end
                    if State.pcldOutlines then local o = State.pcldOutlines[part]; if o then pcall(function() o.model:Destroy() end) State.pcldOutlines[part] = nil end end
                    if State.pcldOutlineCFrames then State.pcldOutlineCFrames[part] = nil end
                elseif style == "Default V2" then
                    local entry = State.pcldOutlines and State.pcldOutlines[part]
                    if not (entry and entry.model and entry.model.Parent) then
                        entry = buildPCLDOutline(part)
                        if not State.pcldOutlines then State.pcldOutlines = {} end
                        State.pcldOutlines[part] = entry
                        if not State.pcldOutlineCFrames then State.pcldOutlineCFrames = {} end
                        State.pcldOutlineCFrames[part] = part.CFrame
                    end
                    local hidden = (part.Position.X == 0 and part.Position.Y == 0 and part.Position.Z == 0)
                    for _, b in ipairs(entry.bars) do
                        b[1].Transparency = hidden and 1 or (Settings.Misc.pcldAlpha or 0.5)
                    end
                    part.Transparency = 1
                    if not Settings.Misc.smoothPCLD then
                        placeOutline(entry, part.CFrame)
                    end
                    if State.pcldProxies and State.pcldProxies[part] then pcall(function() State.pcldProxies[part]:Destroy() end) State.pcldProxies[part] = nil end
                else
