local skyboxEnabled = false
local currentSkybox = "HD"
local defaultSkySettings = nil
local function captureDefaultSky()
    local sky = game:GetService("Lighting"):FindFirstChildOfClass("Sky")
    if sky then
        defaultSkySettings = {
            SkyboxBk = sky.SkyboxBk, SkyboxDn = sky.SkyboxDn,
            SkyboxFt = sky.SkyboxFt, SkyboxLf = sky.SkyboxLf,
            SkyboxRt = sky.SkyboxRt, SkyboxUp = sky.SkyboxUp,
        }
    end
end
captureDefaultSky()
local function applySkybox(value)
    local preset = skyboxPresets[value]
    if not preset then return end
    local sky = game:GetService("Lighting"):FindFirstChildOfClass("Sky") or Instance.new("Sky", game:GetService("Lighting"))
    sky.Name = "Sky"
    sky.SkyboxBk = preset.Bk
    sky.SkyboxDn = preset.Dn
    sky.SkyboxFt = preset.Ft
    sky.SkyboxLf = preset.Lf
    sky.SkyboxRt = preset.Rt
    sky.SkyboxUp = preset.Up
    currentSkybox = value
end
local function restoreDefaultSky()
    local sky = game:GetService("Lighting"):FindFirstChildOfClass("Sky")
    if sky and defaultSkySettings and defaultSkySettings.SkyboxBk then
        sky.SkyboxBk = defaultSkySettings.SkyboxBk
        sky.SkyboxDn = defaultSkySettings.SkyboxDn
        sky.SkyboxFt = defaultSkySettings.SkyboxFt
        sky.SkyboxLf = defaultSkySettings.SkyboxLf
        sky.SkyboxRt = defaultSkySettings.SkyboxRt
        sky.SkyboxUp = defaultSkySettings.SkyboxUp
    elseif sky then
        sky:Destroy()
    end
end
local skyboxList = {}
for k in pairs(skyboxPresets) do table.insert(skyboxList, k) end
table.sort(skyboxList)
