do
    local EditorTab = Window:Tab({Text = "Editor"})
    local editorSec = EditorTab:Section({Text = "Objects", Side = "Left"})
    local editorSettingsSec = EditorTab:Section({Text = "Settings", Side = "Right"})
    local editorCollisions = true
    local editorModels = {}
    local function applyCollisions()
        for model, _ in pairs(editorModels) do
            if model and model.Parent then
                for _, v in pairs(model:GetDescendants()) do
                    if v:IsA("BasePart") then
                        v.CanCollide = editorCollisions
                    end
                end
            end
        end
    end
    editorSettingsSec:Toggle({Text = "Collisions", Flag = "EditorCollisions", Default = true, Callback = function(v)
        editorCollisions = v
        applyCollisions()
    end})
    local function buildPalm(cf)
        local model = Instance.new("Model")
        model.Name = "EditorPalm"
        local origin = cf.Position
        local lookDir = cf.LookVector
        local rightDir = cf.RightVector
        local TRUNK_COLOR1 = Color3.fromRGB(130, 80, 30)
        local TRUNK_COLOR2 = Color3.fromRGB(110, 65, 20)
        local function cylCF(bottom, top)
            local dir = (top - bottom)
            if dir.Magnitude < 0.001 then return CFrame.new(bottom) end
            local mid = bottom + dir * 0.5
            return CFrame.new(mid, mid + dir.Unit) * CFrame.Angles(0, -math.rad(90), 0)
        end
        local segCount = 7
        local segH = 1.1
        local baseR = 0.50
        local topR = 0.25
        local leanStrength = 0.4
        local segBottom = origin
        for i = 1, segCount do
            local t = (i - 1) / math.max(segCount - 1, 1)
            local r = baseR + (topR - baseR) * t
            local leanFrac = math.sin(t * math.pi * 0.5) * leanStrength
            local segTop = segBottom + Vector3.new(0, segH, 0) + lookDir * leanFrac
            local p = Instance.new("Part")
            p.Name = "Trunk" .. i
            p.Size = Vector3.new(segH + 0.2, r * 2, r * 2)
            p.Shape = Enum.PartType.Cylinder
            p.Anchored = true
            p.CanCollide = false
            p.Material = Enum.Material.Wood
            p.Color = (i % 2 == 0) and TRUNK_COLOR1 or TRUNK_COLOR2
            p.TopSurface = Enum.SurfaceType.Smooth
            p.BottomSurface = Enum.SurfaceType.Smooth
            p.CFrame = cylCF(segBottom, segTop)
            p.Parent = model
            segBottom = segTop
        end
        local topPos = segBottom + Vector3.new(0, 0.2, 0)
        local function makeLeaf(angleY, tiltAngle, length, curvature)
            local segments = 5
            local segLen = length / segments
            local basePos = topPos
            local darkGreen = Color3.fromRGB(35, 85, 30)
            local midGreen = Color3.fromRGB(45, 110, 40)
            local lightGreen = Color3.fromRGB(55, 140, 48)
            local prevPos = basePos
            for i = 1, segments do
                local t = i / segments
                local currentTilt = tiltAngle + curvature * i * 8
                local droop = t * t * curvature * 4
                local rad = math.rad(currentTilt)
                local offset = i * segLen
                local x = math.sin(rad) * offset
                local y = math.cos(rad) * offset - droop
                local rotY = math.rad(angleY)
                local finalX = x * math.cos(rotY)
                local finalZ = x * math.sin(rotY)
                local segPos = basePos + Vector3.new(finalX, y, finalZ)
                local segDir = (segPos - prevPos)
                if segDir.Magnitude < 0.01 then
                    prevPos = segPos
                    continue
                end
                local width
                if t < 0.15 then
                    width = 0.5 + t * 7
                elseif t < 0.4 then
                    width = 1.5
                else
                    width = 1.5 * (1 - (t - 0.4) / 0.6)
                end
                width = math.max(width, 0.3)
                local thick = 0.12
                local lookTarget = prevPos - segDir
                local partCF = CFrame.lookAt((prevPos + segPos) * 0.5, lookTarget)
                local part = Instance.new("Part")
                part.Name = "Leaf_" .. angleY .. "_" .. i
                part.Size = Vector3.new(width, thick, segDir.Magnitude + 0.05)
                part.Anchored = true
                part.CanCollide = false
                part.Material = Enum.Material.SmoothPlastic
                part.TopSurface = Enum.SurfaceType.Smooth
                part.BottomSurface = Enum.SurfaceType.Smooth
                if t < 0.3 then
                    part.Color = darkGreen
                elseif t < 0.7 then
                    part.Color = midGreen
                else
                    part.Color = lightGreen
                end
                part.CFrame = partCF
                part.Parent = model
                prevPos = segPos
            end
        end
        local leafAngles = {0, 36, 72, 108, 144, 180, 216, 252, 288, 324}
        for _, a in ipairs(leafAngles) do
            makeLeaf(
                a + (math.random() - 0.5) * 12,
                40 + math.random() * 20,
                7 + math.random() * 4,
                0.3 + math.random() * 0.4
            )
        end
        local basePart = Instance.new("Part")
        basePart.Name = "Base"
        basePart.Size = Vector3.new(2.0, 0.3, 2.0)
        basePart.Anchored = true
        basePart.CanCollide = false
        basePart.Material = Enum.Material.Grass
        basePart.Color = Color3.fromRGB(60, 130, 40)
        basePart.TopSurface = Enum.SurfaceType.Smooth
        basePart.BottomSurface = Enum.SurfaceType.Smooth
        basePart.CFrame = CFrame.new(origin - Vector3.new(0, 0.15, 0))
        basePart.Parent = model
        model.PrimaryPart = basePart
        model.Parent = Workspace
        return model
    end
    local function buildLejak(cf)
        local model = Instance.new("Model")
        model.Name = "EditorLejak"
        local origin = cf.Position
        local look = cf.LookVector
        local right = cf.RightVector
        local function W(f, r, u)
            return origin + look * f + right * r + Vector3.new(0, u, 0)
        end
        local function P(name, sx, sy, sz, pos, color, mat)
            local part = Instance.new("Part")
            part.Name = name
            part.Size = Vector3.new(sx, sy, sz)
            part.CFrame = CFrame.new(pos)
            part.Color = color
            part.Material = mat or Enum.Material.SmoothPlastic
            part.Anchored = true
            part.CanCollide = false
            part.TopSurface = Enum.SurfaceType.Smooth
            part.BottomSurface = Enum.SurfaceType.Smooth
            part.Parent = model
            return part
        end
        local function PO(name, sx, sy, sz, from, to, color, mat)
            local d = to - from
            local len = d.Magnitude
            if len < 0.01 then return nil end
            local part = Instance.new("Part")
            part.Name = name
            part.Size = Vector3.new(sx, sy, len)
            part.CFrame = CFrame.new((from + to) / 2, to)
            part.Color = color
            part.Material = mat or Enum.Material.SmoothPlastic
            part.Anchored = true
            part.CanCollide = false
            part.TopSurface = Enum.SurfaceType.Smooth
            part.BottomSurface = Enum.SurfaceType.Smooth
            part.Parent = model
            return part
        end
        local WOOD = Color3.fromRGB(130, 90, 45)
        local CUSH = Color3.fromRGB(240, 240, 235)
        local STRIPE1 = Color3.fromRGB(50, 130, 180)
        local STRIPE2 = Color3.fromRGB(250, 250, 245)
        local METAL = Color3.fromRGB(180, 180, 185)
        local PILLOW = Color3.fromRGB(215, 100, 80)
        local HW = 1.1
        local F_LEG = 0.5
        local B_LEG = 1.2
        local SEAT_T = 0.2
        local BACK_ANG = 45
        local BACK_LEN = 2.2
        local BACK_SIN = math.sin(math.rad(BACK_ANG))
        local BACK_COS = math.cos(math.rad(BACK_ANG))
        local railFrontFwd = -2.8
        local railBackFwd = BACK_COS * BACK_LEN + 0.3
        local legBackFwd = BACK_COS * BACK_LEN - 0.3
        local legBackRailT = (legBackFwd - railFrontFwd) / (railBackFwd - railFrontFwd)
        local legBackH = F_LEG + (B_LEG - F_LEG) * legBackRailT
        local seatFront = W(-2.8, 0, F_LEG + 0.1)
        local seatBackFwd = legBackFwd
        local seatBackH = legBackH + 0.15
        local seatBack = W(seatBackFwd, 0, seatBackH)
        local backBottom = seatBack
        local backTop = W(seatBackFwd + BACK_COS * BACK_LEN * 0.7, 0, seatBackH + BACK_SIN * BACK_LEN * 0.7)
        for _, side in ipairs({-1, 1}) do
            local sx = HW * side
            P("LegF_" .. side, 0.1, F_LEG, 0.1,
                W(-2.5, sx, F_LEG / 2), METAL)
            P("LegB_" .. side, 0.1, legBackH, 0.1,
                W(legBackFwd, sx, legBackH / 2), METAL)
            local railMidH = (F_LEG + B_LEG) / 2
            local railFront = W(-2.8, sx, F_LEG)
            local railBack = W(legBackFwd, sx, legBackH)
            PO("Rail_" .. side, 0.12, 0.12, 1, railFront, railBack, WOOD, Enum.Material.Wood)
        end
        PO("CrossF", 0.08, 0.08, 1,
            W(-2.5, -HW, F_LEG * 0.3),
            W(-2.5, HW, F_LEG * 0.3), METAL)
        PO("CrossB", 0.08, 0.08, 1,
            W(BACK_COS * BACK_LEN - 0.3, -HW, B_LEG * 0.3),
            W(BACK_COS * BACK_LEN - 0.3, HW, B_LEG * 0.3), METAL)
        PO("SeatCush", HW * 2 - 0.2, SEAT_T, 1,
            seatFront, seatBack, CUSH, Enum.Material.Fabric)
        for si = -2, 2 do
            local r = si * 0.4
            local sc = (si % 2 == 0) and STRIPE1 or STRIPE2
            PO("SeatStr_" .. si, 0.24, SEAT_T, 1,
                W(-2.8, r, F_LEG + 0.1 + 0.02),
                W(seatBackFwd, r, seatBackH + 0.02), sc, Enum.Material.Fabric)
        end
        PO("BackCush", HW * 2 - 0.2, SEAT_T, 1,
            backBottom, backTop, CUSH, Enum.Material.Fabric)
        for si = -2, 2 do
            local r = si * 0.4
            local sc = (si % 2 == 0) and STRIPE1 or STRIPE2
            local bBot = W(seatBackFwd, r, seatBackH + 0.02)
            local bTop = W(seatBackFwd + BACK_COS * BACK_LEN * 0.7, r, seatBackH + BACK_SIN * BACK_LEN * 0.7 + 0.02)
            PO("BackStr_" .. si, 0.24, SEAT_T, 1,
                bBot, bTop, sc, Enum.Material.Fabric)
        end
        for _, side in ipairs({-1, 1}) do
            local sx = HW * side
            local armF = W(-2.6, sx, F_LEG + 0.7)
            local armB = W(seatBackFwd, sx, seatBackH + 0.3)
            PO("Arm_" .. side, 0.1, 0.1, 1, armF, armB, WOOD, Enum.Material.Wood)
            PO("ArmS_F_" .. side, 0.08, 0.08, 1,
                W(-2.6, sx, F_LEG),
                W(-2.6, sx, F_LEG + 0.7), WOOD, Enum.Material.Wood)
            PO("ArmS_B_" .. side, 0.08, 0.08, 1,
                W(seatBackFwd, sx, seatBackH - 0.5),
                W(seatBackFwd, sx, seatBackH + 0.3), WOOD, Enum.Material.Wood)
        end
        local pillowPos = W(seatBackFwd + BACK_COS * BACK_LEN * 0.4, 0, seatBackH + BACK_SIN * BACK_LEN * 0.4 + 0.05)
        local pillowEnd = pillowPos + look * BACK_COS * 0.5 + Vector3.new(0, BACK_SIN * 0.5, 0)
        PO("Pillow", 1.6, 0.22, 0.55, pillowPos, pillowEnd, PILLOW, Enum.Material.Fabric)
        model.PrimaryPart = model:FindFirstChild("SeatCush")
        model.Parent = Workspace
        return model
    end
    local function buildGrass(cf)
        local model = Instance.new("Model")
        model.Name = "Grass"
        local POT = Color3.fromRGB(130, 80, 50)
        local GRASS = Color3.fromRGB(60, 150, 50)
        local pot = Instance.new("Part")
        pot.Name = "Pot"
        pot.Size = Vector3.new(4.6, 1.5, 2.0)
        pot.CFrame = cf * CFrame.new(0, 0.75, 0)
        pot.Color = POT
        pot.Material = Enum.Material.SmoothPlastic
        pot.Anchored = true
        pot.CanCollide = false
        pot.TopSurface = Enum.SurfaceType.Smooth
        pot.BottomSurface = Enum.SurfaceType.Smooth
        pot.Parent = model
        local blade = Instance.new("Part")
        blade.Name = "Blade"
        blade.Size = Vector3.new(4.2, 2.5, 1.6)
        blade.CFrame = cf * CFrame.new(0, 2.75, 0)
        blade.Color = GRASS
        blade.Material = Enum.Material.Grass
        blade.Anchored = true
        blade.CanCollide = false
        blade.TopSurface = Enum.SurfaceType.Smooth
        blade.BottomSurface = Enum.SurfaceType.Smooth
        blade.Parent = model
        model.PrimaryPart = pot
        model.Parent = Workspace
        return model
    end
    local function buildFonarStolb(cf)
        local model = Instance.new("Model")
        model.Name = "EditorFonarStolb"
        local origin = cf.Position
        local look = cf.LookVector
        local right = cf.RightVector
        local DARK = Color3.fromRGB(45, 48, 52)
        local MID = Color3.fromRGB(70, 73, 78)
        local LIGHT = Color3.fromRGB(100, 103, 108)
        local GLOW = Color3.fromRGB(255, 230, 170)
        local GLASS = Color3.fromRGB(255, 245, 210)
        local CONC = Color3.fromRGB(140, 140, 140)
        local function mp(name, size, pos, color, mat)
            local p = Instance.new("Part")
            p.Name = name
            p.Size = size
            p.CFrame = CFrame.new(pos)
            p.Color = color
            p.Material = mat or Enum.Material.Metal
            p.Anchored = true
            p.CanCollide = false
            p.TopSurface = Enum.SurfaceType.Smooth
            p.BottomSurface = Enum.SurfaceType.Smooth
            p.Parent = model
            return p
        end
        mp("BasePlate", Vector3.new(1.0, 0.15, 1.0), origin + Vector3.new(0, 0.075, 0), CONC, Enum.Material.Concrete)
        mp("BaseCollar", Vector3.new(0.5, 0.1, 0.5), origin + Vector3.new(0, 0.2, 0), MID, Enum.Material.Metal)
        local bH = 0.25
        local pH = 8.5
        local pR = 0.09
        local pBot = origin + Vector3.new(0, bH, 0)
        local pTop = pBot + Vector3.new(0, pH, 0)
        local p1H = pH * 0.55
        mp("PoleLower", Vector3.new(pR*2, p1H, pR*2), pBot + Vector3.new(0, p1H/2, 0), MID, Enum.Material.Metal)
        local p2H = pH * 0.45
        mp("PoleUpper", Vector3.new(pR*1.8, p2H, pR*1.8), pBot + Vector3.new(0, p1H+p2H/2, 0), DARK, Enum.Material.Metal)
        local lH = 0.55
        local lW = 0.7
        local lD = 0.5
        local lPos = pTop + Vector3.new(0, lH*0.35, 0)
        mp("LampBody", Vector3.new(lW, lH*0.45, lD), lPos + Vector3.new(0, lH*0.27, 0), DARK, Enum.Material.Metal)
        mp("LampRoof", Vector3.new(lW+0.12, 0.12, lD+0.12), lPos + Vector3.new(0, lH*0.52+0.06, 0), DARK, Enum.Material.Metal)
        local bulbPos = lPos + Vector3.new(0, lH*0.1, 0)
