local Camera                = Workspace.CurrentCamera
local LocalPlayer           = Players.LocalPlayer
--=======================================================================
-- Remote
--=======================================================================
local CharacterEvents, GrabEvents, PlayerEvents, BombEvents, MenuToys, HoldEvents
local Struggle, RagdollRemote, SetNetworkOwner, StickyEvent, BombEvent
local SpawnRemote, DestroyRemote, CanSpawn, CreateGrabLine, DestroyGrabLine
local ExtendGrabLine, UseRemote

do
    CharacterEvents = ReplicatedStorage:FindFirstChild("CharacterEvents")
    GrabEvents      = ReplicatedStorage:FindFirstChild("GrabEvents")
    PlayerEvents    = ReplicatedStorage:FindFirstChild("PlayerEvents")
    BombEvents      = ReplicatedStorage:FindFirstChild("BombEvents")
    MenuToys        = ReplicatedStorage:FindFirstChild("MenuToys")
    HoldEvents      = ReplicatedStorage:FindFirstChild("HoldEvents")

    if CharacterEvents then
        Struggle       = CharacterEvents:FindFirstChild("Struggle")
        RagdollRemote  = CharacterEvents:FindFirstChild("RagdollRemote")
    end
    if GrabEvents then
        SetNetworkOwner = GrabEvents:FindFirstChild("SetNetworkOwner")
        CreateGrabLine  = GrabEvents:FindFirstChild("CreateGrabLine")
        ExtendGrabLine  = GrabEvents:FindFirstChild("ExtendGrabLine")
        DestroyGrabLine = GrabEvents:FindFirstChild("DestroyGrabLine")
    end
    if PlayerEvents then
        StickyEvent    = PlayerEvents:FindFirstChild("StickyPartEvent")
    end
    if BombEvents then
        BombEvent      = BombEvents:FindFirstChild("BombExplode")
    end
    if MenuToys then
        SpawnRemote    = MenuToys:FindFirstChild("SpawnToyRemoteFunction")
        DestroyRemote  = MenuToys:FindFirstChild("DestroyToy")
    end
    if HoldEvents then
        UseRemote      = HoldEvents:FindFirstChild("Use")
    end
    
    CanSpawn = LocalPlayer:FindFirstChild("CanSpawnToy")
end
