--=======================================================================
-- Anti Grab
--=======================================================================
do
    local Cons = {}
    local AntiGrab = false
    local AntiGrabProc = false
    local OriginalHipHeight = nil
    local OriginalAnchored = nil
    local AnimationTracks = {}
    local CharacterConnections = {}
    local FreezeConnection = nil

    local function FWC(Parent, Name, Time)
        return Parent:FindFirstChild(Name) or Parent:WaitForChild(Name, Time)
    end

    local function Disc(Name)
        for i, v in pairs(Cons) do
            if i:find(Name) then
                pcall(function()
                    v:Disconnect()
                end)
                Cons[i] = nil
            end
        end
    end

    local function DisconnectCharacterConnections()
        for _, conn in ipairs(CharacterConnections) do
            pcall(function()
                conn:Disconnect()
            end)
        end
        CharacterConnections = {}
    end

    local function ClearAnimationTracks()
        for _, conn in ipairs(AnimationTracks) do
            pcall(function()
                conn:Disconnect()
            end)
        end
        AnimationTracks = {}
    end

    local PART_NAMES = {
        "Head",
        "Torso",        "UpperTorso",    "LowerTorso",
        "Left Arm",     "LeftUpperArm",  "LeftLowerArm",  "LeftHand",
        "Right Arm",    "RightUpperArm", "RightLowerArm", "RightHand",
        "Left Leg",     "LeftUpperLeg",  "LeftLowerLeg",  "LeftFoot",
        "Right Leg",    "RightUpperLeg", "RightLowerLeg", "RightFoot",
    }

    local function GetIdleOffsets(char, hrp)
        local offsets = {}
        local isR15 = char:FindFirstChild("UpperTorso") ~= nil

        if isR15 then
            offsets["Head"]          = CFrame.new(0, 1.5, 0)
            offsets["UpperTorso"]    = CFrame.new(0, 0.5, 0)
            offsets["LowerTorso"]    = CFrame.new(0, 0, 0)
            offsets["LeftUpperArm"]  = CFrame.new(-0.75, 0.75, 0)
            offsets["LeftLowerArm"]  = CFrame.new(-1.25, 0.75, 0)
            offsets["LeftHand"]      = CFrame.new(-1.6, 0.75, 0)
            offsets["RightUpperArm"] = CFrame.new(0.75, 0.75, 0)
            offsets["RightLowerArm"] = CFrame.new(1.25, 0.75, 0)
            offsets["RightHand"]     = CFrame.new(1.6, 0.75, 0)
            offsets["LeftUpperLeg"]  = CFrame.new(-0.25, -0.5, 0)
            offsets["LeftLowerLeg"]  = CFrame.new(-0.25, -1.0, 0)
            offsets["LeftFoot"]      = CFrame.new(-0.25, -1.5, 0)
            offsets["RightUpperLeg"] = CFrame.new(0.25, -0.5, 0)
            offsets["RightLowerLeg"] = CFrame.new(0.25, -1.0, 0)
            offsets["RightFoot"]     = CFrame.new(0.25, -1.5, 0)
        else
            offsets["Head"]      = CFrame.new(0, 1.5, 0)
            offsets["Torso"]     = CFrame.new(0, 0, 0)
            offsets["Left Arm"]  = CFrame.new(-1.5, 0, 0)
            offsets["Right Arm"] = CFrame.new(1.5, 0, 0)
            offsets["Left Leg"]  = CFrame.new(-0.5, -2, 0)
            offsets["Right Leg"] = CFrame.new(0.5, -2, 0)
        end

        return offsets
    end

    local function LockLimbs(char, hrp, offsets, alpha)
        alpha = alpha or 1
        for name, offset in pairs(offsets) do
            local part = char:FindFirstChild(name)
            if part and part ~= hrp then
                local targetCF = hrp.CFrame * offset
                part.CFrame = part.CFrame:Lerp(targetCF, alpha)
                part.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                part.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                part.Velocity = Vector3.new(0, 0, 0)
                part.RotVelocity = Vector3.new(0, 0, 0)
            end
        end
    end

    local function UnlockLimbs(char, hrp)
        if not char or not hrp then return end
        for _, name in ipairs(PART_NAMES) do
            local part = char:FindFirstChild(name)
            if part and part ~= hrp then
                part.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                part.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                part.Velocity = Vector3.new(0, 0, 0)
                part.RotVelocity = Vector3.new(0, 0, 0)
            end
        end
    end

    local function ResetHRPState(hrp)
        if not hrp or not hrp.Parent then return end
        hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        hrp.Velocity = Vector3.new(0, 0, 0)
        hrp.RotVelocity = Vector3.new(0, 0, 0)
        pcall(function()
            hrp:SetNetworkOwner(LocalPlayer)
        end)
    end

    local function SaveOriginalState(hum, hrp)
        if hum and OriginalHipHeight == nil then
            OriginalHipHeight = hum.HipHeight
        end
        if hrp and OriginalAnchored == nil then
            OriginalAnchored = hrp.Anchored
        end
    end

    local function StartFreeze(hrp)
        if not hrp or not hrp.Parent then return end
        if OriginalAnchored == nil then
            OriginalAnchored = hrp.Anchored
        end
        hrp.Anchored = true
        hrp.Massless = true
        pcall(function()
            hrp.CustomPhysicalProperties = PhysicalProperties.new(0, 0, 0, 0, 0)
        end)
    end

    local function EndFreeze(hrp, char)
        if not hrp or not hrp.Parent then return end

        hrp.Massless = false
        pcall(function()
            hrp.CustomPhysicalProperties = nil
        end)

        if OriginalAnchored ~= nil then
            hrp.Anchored = OriginalAnchored
        else
            hrp.Anchored = false
        end

        pcall(function()
            hrp:SetNetworkOwner(LocalPlayer)
        end)

        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.AutoRotate = true
                hum.PlatformStand = false
                hum.Sit = false
                if OriginalHipHeight ~= nil then
                    hum.HipHeight = OriginalHipHeight
                end
                pcall(function()
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end)
                pcall(function()
                    hum:ChangeState(Enum.HumanoidStateType.Running)
                end)
            end
        end
    end

    local function StopFreeze()
        if FreezeConnection then
            pcall(function()
                FreezeConnection:Disconnect()
            end)
            FreezeConnection = nil
        end
    end

    local function FreezeWhile(char, hrp, condFunc)
        task.wait(0.05)

        local hum = char:FindFirstChildOfClass("Humanoid")

        local frozenOffsets = GetIdleOffsets(char, hrp)

        local lockedPosition = hrp.Position
        local lockedRotation = hrp.CFrame.Rotation
        local currentRotation = lockedRotation

        StartFreeze(hrp)
        ResetHRPState(hrp)

        if hum then
            hum.Sit = false
            hum.PlatformStand = false
            hum.AutoRotate = false
            hum.HipHeight = OriginalHipHeight
        end

        StopFreeze()

        local ROT_SPEED = 12
        local MOVE_ALPHA = 0.35

        FreezeConnection = RunService.Heartbeat:Connect(function(dt)
            if not condFunc() then
                StopFreeze()
                EndFreeze(hrp, char)
                UnlockLimbs(char, hrp)
                return
            end

            if not hrp or not hrp.Parent then
                StopFreeze()
                return
            end

            local h = char:FindFirstChildOfClass("Humanoid")
            if h then
                h.Sit = false
                h.PlatformStand = false
                h.AutoRotate = false
                h.HipHeight = OriginalHipHeight
            end

            local moveDir = h and h.MoveDirection or Vector3.new(0, 0, 0)
            local flat = Vector3.new(moveDir.X, 0, moveDir.Z)

            if flat.Magnitude > 0.01 then
                local dir = flat.Unit
                local speed = h and h.WalkSpeed or 16

                lockedPosition = lockedPosition + dir * speed * dt

                local targetRot = CFrame.lookAt(Vector3.zero, dir).Rotation
                currentRotation = currentRotation:Lerp(targetRot, math.clamp(ROT_SPEED * dt, 0, 1))
            end

            local targetCF = CFrame.new(lockedPosition) * currentRotation
            hrp.Anchored = true
            hrp.CFrame = hrp.CFrame:Lerp(targetCF, MOVE_ALPHA)
            ResetHRPState(hrp)
            LockLimbs(char, hrp, frozenOffsets, MOVE_ALPHA)
        end)
    end

    local function CleanupCharacterState(char)
        if not char then return end

        StopFreeze()

        local hum = char:FindFirstChildOfClass("Humanoid")
        local hrp = char:FindFirstChild("HumanoidRootPart")

        if hrp then
            EndFreeze(hrp, char)
            ResetHRPState(hrp)
            UnlockLimbs(char, hrp)
        elseif hum then
            if OriginalHipHeight ~= nil then
                hum.HipHeight = OriginalHipHeight
            end
            hum.AutoRotate = true
            hum.Sit = false
            hum.PlatformStand = false
            pcall(function()
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            end)
        end

        char:SetAttribute("AntiGrabAnimBlocked", nil)
        ClearAnimationTracks()
        AntiGrabProc = false
    end

    local function WaitForCharacterReady(char, timeout)
        timeout = timeout or 10
        local startTime = tick()

        local hrp = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        local head = char:FindFirstChild("Head")

        while (not hrp or not hum or not head) and tick() - startTime < timeout do
            task.wait(0.05)
            hrp = char:FindFirstChild("HumanoidRootPart")
            hum = char:FindFirstChildOfClass("Humanoid")
            head = char:FindFirstChild("Head")
        end

        return hrp, hum, head
    end

    local function SetupAntiGrab(char)
        if not char then return end

        DisconnectCharacterConnections()

        local hrp, hum, head = WaitForCharacterReady(char)
        if not hrp or not hum or not head then return end
        SaveOriginalState(hum, hrp)

        local conn1 = LocalPlayer.IsHeld.Changed:Connect(function()
            if LocalPlayer.IsHeld.Value and not AntiGrabProc then
                AntiGrabProc = true

                ResetHRPState(hrp)

                hum.Sit = false
                hum.AutoRotate = false
                hum.PlatformStand = false

                task.spawn(function()
                    while LocalPlayer.IsHeld.Value and AntiGrabProc do
                        if Struggle then
                            Struggle:FireServer(LocalPlayer)
                        end
                        if RagdollRemote then
                            RagdollRemote:FireServer(hrp, 0)
                        end
                        task.wait()
                    end
                end)

                FreezeWhile(char, hrp, function()
                    return LocalPlayer.IsHeld.Value and AntiGrabProc
                end)

                if hum.Parent then
                    hum.HipHeight = OriginalHipHeight
                end
                AntiGrabProc = false
            end
        end)
        table.insert(CharacterConnections, conn1)
        Cons["AGIsHeld"] = conn1

        local conn2 = head.ChildAdded:Connect(function(child)
            if child.Name == "PartOwner" then
                hum.Sit = false
                hum.AutoRotate = false
                if Struggle then
                    Struggle:FireServer(LocalPlayer)
                end
            end
        end)
        table.insert(CharacterConnections, conn2)
        Cons["AGHead"] = conn2

        local ragdolled = FWC(hum, "Ragdolled", 3)
        if ragdolled then
            local conn3 = ragdolled.Changed:Connect(function()
                if hum.Ragdolled.Value then
                    task.spawn(function()
                        FreezeWhile(char, hrp, function()
                            return hum.Ragdolled.Value and LocalPlayer.IsHeld.Value
                        end)
                    end)
                end
            end)
            table.insert(CharacterConnections, conn3)
            Cons["AGRagdoll"] = conn3
        end

        local weld = FWC(hrp, "WeldHRP", 3)
        if weld then
            local conn4 = weld.Changed:Connect(function()
                if hrp.WeldHRP.Enabled then
                    while not hum.Sit and hrp.Parent do task.wait() end
                    if not hrp.Parent then return end
                    hum.Sit = false
                    hum.AutoRotate = false

                    FreezeWhile(char, hrp, function()
                        return hrp.WeldHRP.Enabled and hrp.Parent ~= nil
                    end)
                end
            end)
            table.insert(CharacterConnections, conn4)
            Cons["AGWeld"] = conn4
        end
    end

    local function OnCharacterAdded(char)
        OriginalHipHeight = nil
        OriginalAnchored = nil

        if not AntiGrab then return end

        Disc("AGIsHeld")
        Disc("AGHead")
        Disc("AGRagdoll")
        Disc("AGWeld")
        DisconnectCharacterConnections()
        ClearAnimationTracks()
        StopFreeze()
        AntiGrabProc = false

        task.wait(0.1)

        if AntiGrab and char and char.Parent then
            SetupAntiGrab(char)
        end
    end

    local function OnCharacterRemoving(char)
        CleanupCharacterState(char)
    end

    local AntiGrabCheckbox = AntiGroupbox:AddCheckbox("AntiGrabCheckbox", {
        Text = "Anti Grab",
        Default = false,
    })

    AntiGrabCheckbox:OnChanged(function(Value)
        AntiGrab = Value

        if AntiGrab then
            if LocalPlayer.Character then
                SetupAntiGrab(LocalPlayer.Character)
            end

            Cons["AGChar"] = LocalPlayer.CharacterAdded:Connect(OnCharacterAdded)
            Cons["AGCharRemoving"] = LocalPlayer.CharacterRemoving:Connect(OnCharacterRemoving)
        else
            if LocalPlayer.Character then
                CleanupCharacterState(LocalPlayer.Character)
            end

            Disc("AGIsHeld")
            Disc("AGHead")
            Disc("AGRagdoll")
            Disc("AGWeld")
            Disc("AGChar")
            Disc("AGCharRemoving")
            DisconnectCharacterConnections()
            StopFreeze()
            OriginalHipHeight = nil
            OriginalAnchored = nil
        end
    end)
end
--=======================================================================
-- Anti Blobman
--=======================================================================
do
	local antiBlobmanConnection = nil
	local massConnection = nil

	local function isWeld(object, ignoreFolder)
		return object:IsA("BasePart")
			and (object.Name == "LeftWeld"
			or object.Name == "RightWeld"
			or object.Name == "LeftAlignOrientation"
			or object.Name == "RightAlignOrientation")
			and object.Parent and object.Parent.Parent
			and object.Parent.Parent.Parent ~= ignoreFolder
	end

	local function toggleWelds(state, ignoreFolder)
		for _, object in ipairs(Workspace:GetDescendants()) do
			if isWeld(object, ignoreFolder) then
				object.Enabled = state
			end
		end
	end

	local function removeAttach()
		for _, object in ipairs(Workspace:GetDescendants()) do
			if object.Name == "AttachPlayer" then
				object:Destroy()
			end
		end
	end

	local function fixMass(character)
		if not character then return end
		for _, part in ipairs(character:GetDescendants()) do
			if part:IsA("BasePart") and part.Massless then
				part.Massless = false
			end
		end
	end

	local AntiBlobmanToggle = AntiGroupbox:AddCheckbox("AntiBlobmanToggle", {
		Text = "Anti Blobman",
		Default = false,
	})

	AntiBlobmanToggle:OnChanged(function()
		local Value = Toggles.AntiBlobmanToggle.Value
		local ignoreFolder = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")

		if Value then
			if antiBlobmanConnection then antiBlobmanConnection:Disconnect() end
			if massConnection then massConnection:Disconnect() end

			toggleWelds(false, ignoreFolder)
			removeAttach()

			antiBlobmanConnection = Workspace.DescendantAdded:Connect(function(object)
				if isWeld(object, ignoreFolder) then
					object.Enabled = false
				end
				if object.Name == "AttachPlayer" then
					task.wait()
					if object and object.Parent then object:Destroy() end
				end
			end)

			massConnection = RunService.Heartbeat:Connect(function()
				fixMass(LocalPlayer.Character)
			end)
		else
			toggleWelds(true, ignoreFolder)
			if antiBlobmanConnection then antiBlobmanConnection:Disconnect() antiBlobmanConnection = nil end
			if massConnection then massConnection:Disconnect() massConnection = nil end
		end
	end)
end
--=======================================================================
-- Anti Kick
--=======================================================================
do
    local tpActive = false
    local antiKickThread = nil
    
    local function ClearKunai()
        local plr = Players.LocalPlayer
        local inv = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
        if inv and DestroyRemote then
            for _, v in pairs(inv:GetChildren()) do
                if v.Name == "AntiKick" or v.Name == "NinjaShuriken" then
                    pcall(function()
                        DestroyRemote:FireServer(v)
                    end)
                end
            end
        end
    end

    local function startAntiKick()
        if antiKickThread then
            task.cancel(antiKickThread)
            antiKickThread = nil
        end

        antiKickThread = task.spawn(function()
            local plr = Players.LocalPlayer
            
            local function getHRP()
                if plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                    return plr.Character.HumanoidRootPart
                else
                    local character = plr.CharacterAdded:Wait()
                    return character:WaitForChild("HumanoidRootPart")
                end
            end
            
            local function CheckForHome()
                if not Workspace.PlotItems.PlayersInPlots:FindFirstChild(plr.Name) then
                    return false
                end
                for _, v in pairs(Workspace.Plots:GetChildren()) do
                    local sign = v:FindFirstChild("PlotSign")
                    local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
                    if owners then
                        for _, b in pairs(owners:GetChildren()) do
                            if b.Value == plr.Name then
                                local folder = Workspace.PlotItems:FindFirstChild(v.Name)
                                if folder then
                                    return true, folder
                                end
                            end
                        end
                    end
                end
                return false
            end
            
            local function StickKunai(kunai)
                if not kunai or not kunai:FindFirstChild("StickyPart") then
                    return
                end
                local currentHRP = getHRP()
                if not currentHRP then
                    return
                end
                if kunai:FindFirstChild("SoundPart") then
                    if not kunai.SoundPart:FindFirstChild("PartOwner") or kunai.SoundPart.PartOwner.Value ~= plr.Name then
                        if SetNetworkOwner then
                            SetNetworkOwner:FireServer(kunai.SoundPart, kunai.SoundPart.CFrame)
                        end
                    end
                end
                local firePart = currentHRP:FindFirstChild("FirePlayerPart") or currentHRP:WaitForChild("FirePlayerPart", 5)
                if firePart and StickyEvent then
                    StickyEvent:FireServer(
                        kunai.StickyPart,
                        firePart,
                        CFrame.new(0, 0, 0) * CFrame.Angles(0, math.rad(90), math.rad(90))
                    )
                end
                for _, obj in pairs(kunai:GetChildren()) do
                    if obj.Name == "Pyramid" then
                        obj.CanTouch = false
                        obj.CanCollide = false
                        obj.CanQuery = false
                        obj.Transparency = 0
                        if not obj:FindFirstChild("Highlight") then
                            local high = Instance.new("Highlight", obj)
                            high.FillColor = Color3.fromRGB(0, 0, 0)
                        end
                    elseif obj.Name == "Main" then
                        obj.CanTouch = false
                        obj.CanCollide = false
                        obj.CanQuery = false
                        obj.Transparency = 0
                        if not obj:FindFirstChild("Highlight") then
                            local high = Instance.new("Highlight", obj)
                            high.FillColor = Color3.fromRGB(255, 255, 255)
                        end
                    elseif obj:IsA("BasePart") then
                        obj.CanTouch = false
                        obj.CanCollide = false
                        obj.CanQuery = false
                        obj.Transparency = 1
                    end
                end
            end
            
            local function SpawnToy(name)
                local t = tick()
                while CanSpawn and not CanSpawn.Value do
                    if not _G.ShurikenAntiKick or tick() - t > 5 then
                        return nil
                    end
                    task.wait(0.1)
                end
                local currentHRP = getHRP()
                if currentHRP and SpawnRemote then
                    task.spawn(function()
                        pcall(function()
                            SpawnRemote:InvokeServer(name, currentHRP.CFrame * CFrame.new(0, 12, 20), Vector3.new(0, 0, 0))
                        end)
                    end)
                end
                local boolik, house = CheckForHome()
                local inv = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
                if boolik and house then
                    return house:WaitForChild(name, 2)
                elseif not Workspace.PlotItems.PlayersInPlots:FindFirstChild(plr.Name) and inv then
                    return inv:WaitForChild(name, 2)
                end
                return nil
            end
            
            while _G.ShurikenAntiKick do
                task.wait(0.005)
                if not plr.Character or not plr.Character:FindFirstChild("Humanoid") or plr.Character.Humanoid.Health <= 0 then
                    continue
                end
                local inv = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
                local kunai = inv and inv:FindFirstChild("NinjaShuriken")
                if Workspace.PlotItems.PlayersInPlots:FindFirstChild(plr.Name) then
                    local boolik, house = CheckForHome()
                    if boolik and house and Workspace.Plots:FindFirstChild(house.Name) then
                        local sign = Workspace.Plots[house.Name]:FindFirstChild("PlotSign")
                        if sign and sign.ThisPlotsOwners.Value.TimeRemainingNum.Value > 89 then
                            kunai = SpawnToy("NinjaShuriken")
                            if kunai == nil then
                                continue
                            end
                            kunai.Name = "AntiKick"
                            StickKunai(kunai)
                        end
                    end
                end
                if not kunai then
                    if Workspace.PlotItems.PlayersInPlots:FindFirstChild(plr.Name) then
                        continue
                    end
                    kunai = SpawnToy("NinjaShuriken")
                    if kunai == nil then
                        continue
                    end
                    kunai.Name = "AntiKick"
                    if not kunai then
                        continue
                    end
                end
                repeat
                    if kunai and kunai:FindFirstChild("StickyPart") and kunai.StickyPart.CanTouch == true then
                        StickKunai(kunai)
                        kunai.Name = "AntiKick"
                    end
                    task.wait(0.3)
                until not kunai or not _G.ShurikenAntiKick
                    or not kunai:FindFirstChild("StickyPart")
                    or kunai.StickyPart.CanTouch == false 
                    or not plr.Character or not plr.Character:FindFirstChild("HumanoidRootPart") 
                    or not kunai:FindFirstChild("StickyPart") 
                    or (plr.Character.HumanoidRootPart.Position - kunai.StickyPart.Position).Magnitude >= 20
                if not kunai or not kunai:FindFirstChild("StickyPart") or not plr.Character or not plr.Character:FindFirstChild("HumanoidRootPart") or (plr.Character.HumanoidRootPart.Position - kunai.StickyPart.Position).Magnitude >= 20 then
                    ClearKunai()
                end
                pcall(function()
                    repeat
                        task.wait(0.05)
                    until not _G.ShurikenAntiKick or not plr.Character or not plr.Character:FindFirstChild("Humanoid") or not kunai or not kunai:FindFirstChild("StickyPart") or not kunai.StickyPart:FindFirstChild("StickyWeld") or not kunai.StickyPart.StickyWeld.Part1
                    if not kunai or not kunai:FindFirstChild("StickyPart") or (plr.Character and plr.Character:FindFirstChild("Humanoid") and plr.Character.Humanoid.Health <= 0) or not kunai["StickyPart"]:FindFirstChild("StickyWeld").Part1 then
                        ClearKunai()
                    end
                end)
            end
        end)
    end

    AntiGroupbox:AddCheckbox("ShurikenAntiKick", {
        Text = "Anti Kick",
        Default = false,
        Callback = function(Value)
            _G.ShurikenAntiKick = Value
            
            if Value then
                startAntiKick()
            else
                _G.ShurikenAntiKick = false
                if antiKickThread then
                    task.cancel(antiKickThread)
                    antiKickThread = nil
                end
                ClearKunai()
            end
        end
    })

    LocalPlayer.CharacterAdded:Connect(function(char)
        if _G.ShurikenAntiKick then

            if antiKickThread then
                task.cancel(antiKickThread)
                antiKickThread = nil
            end

            ClearKunai()
            task.wait(0.5)
            startAntiKick()
        end
    end)
end
--=======================================================================
-- Break PCLD
--=======================================================================
do
    local resetting = false
    local autoResetEnabled = false

    local function doDoubleReset()
        if resetting then return end      
        resetting = true

        if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Humanoid")
            and LocalPlayer.Character.Humanoid.Health > 0 then
            LocalPlayer.Character.Humanoid.Health = 0
        end

        local char2 = LocalPlayer.CharacterAdded:Wait()
        local hum2 = char2:WaitForChild("Humanoid", 5)
        task.wait(0.15)
        if hum2 then hum2.Health = 0 end

        LocalPlayer.CharacterAdded:Wait()
        task.wait(0.5)
        resetting = false
    end
    
    local BreakPCLDToggle = AntiGroupbox:AddCheckbox("BreakPCLDToggle", {
        Text = "Anti Kick [Break PCLD]",
        Default = false,
    })

    BreakPCLDToggle:OnChanged(function()
        autoResetEnabled = BreakPCLDToggle.Value
        if not autoResetEnabled then return end  

        task.spawn(function()
            doDoubleReset()

            while autoResetEnabled do
                local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
                local hum = char:WaitForChild("Humanoid", 10)

                if hum then
                    hum.Died:Wait()          
                    if autoResetEnabled and not resetting then
                        task.wait(0.5)
                        doDoubleReset()     
                    end
                end
                task.wait(0.1)
            end
        end)
    end)
end
