--=======================================================================
-- Anti Burn
--=======================================================================
do
	local antiBurnConnection = nil
	local antiBurnCharacterConnection = nil

	local function setupAntiBurnLogic(character)
		if antiBurnConnection then antiBurnConnection:Disconnect() end
		
		if not character then return end
		local humanoid = character:WaitForChild("Humanoid", 5)
		local humanoidRootPart = character:WaitForChild("HumanoidRootPart", 5)
		
		if not humanoid or not humanoidRootPart then return end
		
		local fireDebounce = humanoid:WaitForChild("FireDebounce", 5)
		if not fireDebounce then return end

		antiBurnConnection = fireDebounce.Changed:Connect(function()
			if fireDebounce.Value == true then
				local plot1 = Workspace:FindFirstChild("Plots") and Workspace.Plots:FindFirstChild("Plot1")
				local barrier = plot1 and plot1:FindFirstChild("Barrier") and plot1.Barrier:FindFirstChild("PlotBarrier")
				
				if barrier then
					local originalPosition = barrier.CFrame
					
					task.spawn(function()
						repeat 
							task.wait() 
							if humanoidRootPart and humanoidRootPart.Parent and barrier then
								barrier.CFrame = humanoidRootPart.CFrame 
							end
						until not fireDebounce or fireDebounce.Parent == nil or fireDebounce.Value == false
					end)
					
					task.wait(1)
					if fireDebounce and fireDebounce.Parent then
						fireDebounce.Value = false
					end
					task.wait()
					
					if barrier then barrier.CFrame = originalPosition end
				end
			end
		end)
	end

	AntiGroupbox:AddCheckbox("AntiBurn", {
		Text = "Anti Burn",
		Default = false,
		Callback = function(value)
			if value then
				setupAntiBurnLogic(LocalPlayer.Character)
				antiBurnCharacterConnection = LocalPlayer.CharacterAdded:Connect(setupAntiBurnLogic)
			else
				if antiBurnConnection then antiBurnConnection:Disconnect() antiBurnConnection = nil end
				if antiBurnCharacterConnection then antiBurnCharacterConnection:Disconnect() antiBurnCharacterConnection = nil end
			end
		end
	})
end
--=======================================================================
-- Anti Poison
--=======================================================================
do
    local antiPoison = false
    local antipcon = nil

    AntiGroupbox:AddCheckbox('AntiPoison', {
        Text = 'Anti Poison',
        Default = false,
    }):OnChanged(function(v)
        antiPoison = v

        local map = Workspace:FindFirstChild("Map")
        if not map then return end
        
        local hole = map:FindFirstChild("Hole")
        if not hole then return end

        local poisonFolders = {
            hole:FindFirstChild("PoisonBigHole"),
            hole:FindFirstChild("PoisonSmallHole"),
        }

        for _, folder in pairs(poisonFolders) do
            if folder then
                for _, obj in pairs(folder:GetDescendants()) do
                    if obj:IsA('Script') or obj:IsA('LocalScript') then
                        obj.Disabled = v
                    end
                    
                    if obj:IsA('BasePart') then
                        if v then
                            obj.CanTouch = false
                            obj.CanCollide = false
                        else
                            obj.CanTouch = true
                            obj.CanCollide = true
                        end
                    end
                end
            end
        end
    end)
end
--=======================================================================
-- Anti Explode
--=======================================================================
do
	local connectionsExplosion = { Connection = nil }

	AntiGroupbox:AddCheckbox("AntiExplosionToggle", {
		Text = "Anti Explode",
		Default = false,
		Callback = function(Value)
			if Value then
				if connectionsExplosion.Connection then 
					connectionsExplosion.Connection:Disconnect() 
				end

				if BombEvent then
					connectionsExplosion.Connection = BombEvent.OnClientEvent:Connect(function(data, position)
						local character = LocalPlayer.Character
						if not character then return end

						local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
						local humanoid = character:FindFirstChild("Humanoid")

						if not humanoidRootPart or not humanoid or humanoid.Health <= 0 then return end

						local radius = (data and data.Radius) or 0

						if radius + 10 > (position - humanoidRootPart.Position).Magnitude then
							task.spawn(function()
								humanoidRootPart.Anchored = true
								task.wait()

								if humanoid.Parent then
									humanoid:ChangeState(Enum.HumanoidStateType.Running)
								end

								for index = 1, 6 do
									if humanoidRootPart and humanoid and humanoidRootPart.Parent then
										humanoidRootPart.CFrame = humanoidRootPart.CFrame + humanoid.MoveDirection
									end
									task.wait()
								end

								if humanoidRootPart and humanoidRootPart.Parent then
									humanoidRootPart.Anchored = false
								end
							end)
						end
					end)
				end
			else
				if connectionsExplosion.Connection then
					connectionsExplosion.Connection:Disconnect()
					connectionsExplosion.Connection = nil
				end
			end
		end
	})
end
--=======================================================================
-- Anti Paint
--=======================================================================
do
	local paintPartsBackup = {}
	local paintConnections = {}

	local function deleteAllPaintParts()
		for _, obj in ipairs(Workspace:GetDescendants()) do
			if obj:IsA("BasePart") and obj.Name == "PaintPlayerPart" then
				local clone = obj:Clone()
				clone.Archivable = true
				paintPartsBackup[obj:GetDebugId()] = {
					clone = clone,
					parent = obj.Parent
				}
				obj:Destroy()
			end
		end
	end

	local function restorePaintParts()
		for _, data in pairs(paintPartsBackup) do
			if data.clone and data.parent then
				data.clone.Parent = data.parent
			end
		end
		paintPartsBackup = {}
	end

	local function watchNewPaintParts()
		table.insert(paintConnections, Workspace.DescendantAdded:Connect(function(obj)
			if obj:IsA("BasePart") and obj.Name == "PaintPlayerPart" then
				task.defer(function()
					if obj and obj.Parent then
						local clone = obj:Clone()
						clone.Archivable = true
						paintPartsBackup[obj:GetDebugId()] = {
							clone = clone,
							parent = obj.Parent
						}
						obj:Destroy()
					end
				end)
			end
		end))
	end

	local function disconnectWatchers()
		for _, conn in ipairs(paintConnections) do
			if conn.Connected then
				conn:Disconnect()
			end
		end
		paintConnections = {}
	end

	AntiGroupbox:AddCheckbox("PaintDeleteToggle", {
		Text = "Anti Paint",
		Default = false,
		Callback = function(state)

			if state then
				deleteAllPaintParts()
				watchNewPaintParts()
				if setTouchQuery then setTouchQuery(false) end
			else
				restorePaintParts()
				disconnectWatchers()
				if setTouchQuery then setTouchQuery(true) end
			end
		end
	})
end
