--=======================================================================
-- Anti Gucci [Blobman]
--=======================================================================
do
    local AutoGucciT = false
    local sitJumpT = false
    local ragdollLoopD = false

    local blobmanInstanceS = nil
    local blobConnection = nil
    local respawnConnection = nil
    local isTogglingOff = false

    local jumpConnection = nil
    local jumpLoopRunning = false
    local lastJumpTick = 0
    local spaceWasDown = false
    local JUMP_COOLDOWN = 0.1

    if not (DestroyRemote and SpawnRemote and RagdollRemote and Struggle and SetNetworkOwner) then
        return
    end

    local function isChatting()
        return UserInputService:GetFocusedTextBox() ~= nil
    end

    local function tryJump()
        if isChatting() then return end

        local now = tick()
        if now - lastJumpTick < JUMP_COOLDOWN then return end

        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end

        if hum.FloorMaterial == Enum.Material.Air then return end

        lastJumpTick = now

        hum:ChangeState(Enum.HumanoidStateType.Jumping)
    end

    local function startJumpLoop()
        if jumpConnection then
            jumpConnection:Disconnect()
            jumpConnection = nil
        end

        jumpConnection = UserInputService.JumpRequest:Connect(function()
            tryJump()
        end)

        if not jumpLoopRunning then
            jumpLoopRunning = true
            spaceWasDown = false
            task.spawn(function()
                while jumpLoopRunning do
                    local isDown = UserInputService:IsKeyDown(Enum.KeyCode.Space)
                    if isDown and not spaceWasDown then
                        tryJump()
                    end
                    spaceWasDown = isDown
                    RunService.RenderStepped:Wait()
                end
            end)
        end
    end

    local function stopJumpLoop()
        if jumpConnection then
            jumpConnection:Disconnect()
            jumpConnection = nil
        end
        jumpLoopRunning = false
        spaceWasDown = false
    end

    startJumpLoop()

    local function destroySeat(targetBlobman)
        if not targetBlobman or not targetBlobman.Parent then return end
        local seat = targetBlobman:FindFirstChildWhichIsA("VehicleSeat")
                      or targetBlobman:FindFirstChildOfClass("VehicleSeat")
        if seat then
            pcall(function()
                DestroyRemote:FireServer(seat)
            end)
            seat:Destroy()
        end
    end

    local function recoverCharacterClean()
        pcall(function()
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                Struggle:FireServer(LocalPlayer)
                hum.PlatformStand = false
                hum.Sit = true
                task.wait(0.01)
                hum.Sit = false
            end
        end)
    end

    local function executeRagdollAndRecover()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")

        if hrp then
            task.spawn(function()
                RagdollRemote:FireServer(hrp, 0.2)
                if hum then
                    hum.PlatformStand = true
                end
                task.wait(0.02)
                recoverCharacterClean()
            end)
        end
    end

    local function bindBlobDestroyRagdoll(blob)
        if blobConnection then
            blobConnection:Disconnect()
            blobConnection = nil
        end

        if not blob then return end

        blobConnection = blob.AncestryChanged:Connect(function(_, parent)
            if not parent then
                if blobConnection then
                    blobConnection:Disconnect()
                    blobConnection = nil
                end

                if AutoGucciT or isTogglingOff then return end
                executeRagdollAndRecover()
                blobmanInstanceS = nil
            end
        end)
    end

    local function spawnBlobmanF()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end

        if blobmanInstanceS and blobmanInstanceS.Parent
           and blobmanInstanceS:IsDescendantOf(Workspace) then
            return true
        end

        local inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
        local blob = inv and inv:FindFirstChild("CreatureBlobman")
        if blob then
            blobmanInstanceS = blob
            return true
        end

        if SpawnRemote then
            task.spawn(function()
                pcall(function()
                    SpawnRemote:InvokeServer(
                        "CreatureBlobman",
                        CFrame.new(192, 324, 389),
                        Vector3.new(0, 0, 0)
                    )
                end)
            end)

            local tries = 0
            repeat
                if not AutoGucciT then return false end
                task.wait(0.05)
                inv = Workspace:FindFirstChild(LocalPlayer.Name .. "SpawnedInToys")
                blobmanInstanceS = inv and inv:FindFirstChild("CreatureBlobman")
                tries += 1
            until (blobmanInstanceS and blobmanInstanceS.Parent) or tries > 60

            if not blobmanInstanceS or not blobmanInstanceS.Parent then
                return false
            end
        else
            return false
        end
        return true
    end

    local function ragdollLoopF()
        if ragdollLoopD then return end
        ragdollLoopD = true

        while sitJumpT and AutoGucciT do
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if char and hrp then
                RagdollRemote:FireServer(hrp, 0)
            end
            task.wait()
        end
        ragdollLoopD = false
    end

    local function sitJumpF()
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not char or not hum then return false end

        local seat = blobmanInstanceS
                     and blobmanInstanceS:FindFirstChildWhichIsA("VehicleSeat")
        if seat and seat.Occupant ~= hum then
            seat:Sit(hum)

            local hrp = char:FindFirstChild("HumanoidRootPart")
            local blobHRP = blobmanInstanceS
                            and blobmanInstanceS:FindFirstChild("HumanoidRootPart")
            if hrp and blobHRP then
                pcall(function()
                    SetNetworkOwner:FireServer(blobHRP, hrp)
                end)
            end

            sitJumpT = false
            task.defer(function()
                destroySeat(blobmanInstanceS)
            end)
            return true
        end
        return false
    end

    local function AutoGucciF()
        while AutoGucciT do
            pcall(function()
                if not AutoGucciT then return end
                if not spawnBlobmanF() then
                    task.wait(0.5)
                    return
                end

                local char = LocalPlayer.Character
                if not char then task.wait(0.05) return end

                local hrp = char:WaitForChild("HumanoidRootPart", 2)
                local hum = char:WaitForChild("Humanoid", 2)
                if not hrp or not hum then return end

                local rag = hum:FindFirstChild("Ragdolled")
                local held = LocalPlayer:FindFirstChild("IsHeld")

                if not blobmanInstanceS or not AutoGucciT then return end

                bindBlobDestroyRagdoll(blobmanInstanceS)

                local OCF = hrp.CFrame

                if not sitJumpT then
                    task.spawn(sitJumpF)
                    sitJumpT = true
                end

                task.spawn(ragdollLoopF)
                task.wait(0.15)
                if not AutoGucciT then return end
                if hrp and hrp.Parent then
                    hrp.CFrame = OCF
                end

                local successCheck = true
                sitJumpT = false

                RagdollRemote:FireServer(hrp, 0.001)

                while successCheck and AutoGucciT do
                    if not blobmanInstanceS
                       or not blobmanInstanceS.Parent
                       or not blobmanInstanceS:IsDescendantOf(Workspace) then
                        if hrp and hrp.Parent and not isTogglingOff then
                            executeRagdollAndRecover()
                        end
                        blobmanInstanceS = nil
                        successCheck = false
                        break
                    end

                    if hum.Health <= 0 then
                        if blobmanInstanceS then
                            DestroyRemote:FireServer(blobmanInstanceS)
                        end
                        successCheck = false
                        break
                    end

                    local currentSeat = blobmanInstanceS:FindFirstChildWhichIsA("VehicleSeat")
                    if currentSeat and currentSeat.Occupant ~= nil
                       and currentSeat.Occupant ~= hum then
                        DestroyRemote:FireServer(blobmanInstanceS)
                        if hrp and hrp.Parent and not isTogglingOff then
                            executeRagdollAndRecover()
                        end
                        blobmanInstanceS = nil
                        successCheck = false
                        break
                    end

                    if (rag and rag.Value == true) or (held and held.Value == true) then
                        while ((rag and rag.Value == true) or (held and held.Value == true))
                              and AutoGucciT do
                            Struggle:FireServer()
                            task.wait()
                        end
                        successCheck = false
                        break
                    end

                    local blobHRP = blobmanInstanceS:FindFirstChild("HumanoidRootPart")
                    if blobHRP then
                        blobHRP.CFrame = CFrame.new(192, 324, 389)
                    end
                    task.wait()
                end

                if not successCheck then
                    if not isTogglingOff then
                        recoverCharacterClean()
                    end
                    sitJumpT = false
                    task.wait(0.05)
                end
            end)
            task.wait()
        end
    end

    local function toggleGucci(state)
        if AutoGucciT == state then return end
        AutoGucciT = state

        if AutoGucciT then
            isTogglingOff = false
            if respawnConnection then
                respawnConnection:Disconnect()
                respawnConnection = nil
            end

            respawnConnection = LocalPlayer.CharacterAdded:Connect(function(newCharacter)
                if AutoGucciT then
                    if blobmanInstanceS then
                        pcall(function()
                            DestroyRemote:FireServer(blobmanInstanceS)
                        end)
                        blobmanInstanceS = nil
                    end
                    sitJumpT = false

                    task.spawn(function()
                        local hum = newCharacter:WaitForChild("Humanoid", 5)
                        local hrp = newCharacter:WaitForChild("HumanoidRootPart", 5)

                        if not hum or not hrp then return end

                        task.wait(1.5)

                        if AutoGucciT and hum.Health > 0 then
                            task.spawn(AutoGucciF)
                        end
                    end)
                end
            end)

            task.spawn(AutoGucciF)
        else
            isTogglingOff = true

            if respawnConnection then
                respawnConnection:Disconnect()
                respawnConnection = nil
            end
            if blobConnection then
                blobConnection:Disconnect()
                blobConnection = nil
            end

            local currentBlob = blobmanInstanceS
            blobmanInstanceS = nil

            if currentBlob then
                pcall(function()
                    DestroyRemote:FireServer(currentBlob)
                end)
            end

            executeRagdollAndRecover()
            sitJumpT = false

            task.delay(0.2, function()
                isTogglingOff = false
            end)
        end
    end

    GucciGroupbox:AddCheckbox("AntiGucci", {
        Text = "Anti Gucci [Blob]",
        Default = false,
        Callback = function(Value)
            toggleGucci(Value)
        end
    })
end
--=======================================================================
-- Anti Gucci [train]
--=======================================================================
do
    local antiGucciConnectionTrain
    local safePositionTrain
    local restoreFramesTrain = 0
    local jumpConnectionTrain = nil

    local autoGucciActiveTrain = false
    local trainLoopRunning = false
    local respawnConnectionTrain = nil
    local startingTrain = false 

    local function startAntiGucciTrain()
        if startingTrain then return end
        startingTrain = true

        local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        local humanoid = character:WaitForChild("Humanoid")
        local rootPart = character:WaitForChild("HumanoidRootPart")
        safePositionTrain = rootPart.Position

        if antiGucciConnectionTrain then
            antiGucciConnectionTrain:Disconnect()
            antiGucciConnectionTrain = nil
        end
        if jumpConnectionTrain then
            jumpConnectionTrain:Disconnect()
            jumpConnectionTrain = nil
        end

        local folder = Workspace.Map.AlwaysHereTweenedObjects
        local train = folder and folder:FindFirstChild("Train")
        local seat

        if train then
            for _, d in ipairs(train:GetDescendants()) do
                if d:IsA("Seat") then
                    seat = d
                    break
                end
            end
        end

        if seat then
            rootPart.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
            seat:Sit(humanoid)
        end

        jumpConnectionTrain = humanoid:GetPropertyChangedSignal("Jump"):Connect(function()
            if humanoid.Jump and humanoid.Sit then
                restoreFramesTrain = 15
                safePositionTrain = rootPart.Position
            end
        end)

        antiGucciConnectionTrain = RunService.Heartbeat:Connect(function()
            if not rootPart or not rootPart.Parent or not humanoid or not humanoid.Parent then
                return
            end
            RagdollRemote:FireServer(rootPart, 0)
            if restoreFramesTrain > 0 then
                rootPart.CFrame = CFrame.new(safePositionTrain)
                restoreFramesTrain = restoreFramesTrain - 1
            end
        end)

        task.spawn(function()
            while humanoid and humanoid.Parent and humanoid.Sit do
                task.wait(1)
            end
            task.wait(0.5)
            if rootPart and rootPart.Parent then
                rootPart.CFrame = CFrame.new(safePositionTrain)
            end
        end)

        task.wait(0.1)  
        startingTrain = false
    end

    local function stopAntiGucciTrain()
        if antiGucciConnectionTrain then
            antiGucciConnectionTrain:Disconnect()
            antiGucciConnectionTrain = nil
        end
        if jumpConnectionTrain then
            jumpConnectionTrain:Disconnect()
            jumpConnectionTrain = nil
        end
        local trainFolder = Workspace.Map.AlwaysHereTweenedObjects
        if trainFolder and trainFolder:FindFirstChild("Train") then
            ResetPlayer(LocalPlayer)
        end
    end

    local function startTrainAutoLoop()
        if trainLoopRunning then return end
        trainLoopRunning = true

        task.spawn(function()
            while autoGucciActiveTrain do
                local trainFolder = Workspace.Map.AlwaysHereTweenedObjects
                local trainExists = trainFolder and trainFolder:FindFirstChild("Train")

                if trainExists then

                    if not antiGucciConnectionTrain and not startingTrain then
                        startAntiGucciTrain()
                    end
                else
                    if antiGucciConnectionTrain then
                        stopAntiGucciTrain()
                    end

                    local retries = 0
                    repeat
                        task.wait(0.2)
                        retries = retries + 1
                        trainFolder = Workspace.Map.AlwaysHereTweenedObjects
                    until (trainFolder and trainFolder:FindFirstChild("Train"))
                          or retries > 25
                          or not autoGucciActiveTrain

                    if autoGucciActiveTrain
                       and trainFolder
                       and trainFolder:FindFirstChild("Train")
                       and not antiGucciConnectionTrain
                       and not startingTrain then
                        startAntiGucciTrain()
                    end
                end

                task.wait(0.5)
            end

            trainLoopRunning = false
        end)
    end

    GucciGroupbox:AddCheckbox("AutoGucciTrain", {
        Text = "Anti Gucci [Train]",
        Default = false,
        Callback = function(Value)
            autoGucciActiveTrain = Value
            if Value then
                if respawnConnectionTrain then
                    respawnConnectionTrain:Disconnect()
                    respawnConnectionTrain = nil
                end

                respawnConnectionTrain = LocalPlayer.CharacterAdded:Connect(function(newCharacter)
                    if autoGucciActiveTrain then
                        if antiGucciConnectionTrain then
                            antiGucciConnectionTrain:Disconnect()
                            antiGucciConnectionTrain = nil
                        end
                        if jumpConnectionTrain then
                            jumpConnectionTrain:Disconnect()
                            jumpConnectionTrain = nil
                        end
                        startingTrain = false

                        task.spawn(function()
                            local hum = newCharacter:WaitForChild("Humanoid", 5)
                            local hrp = newCharacter:WaitForChild("HumanoidRootPart", 5)
                            if not hum or not hrp then return end

                            task.wait(1.5)

                            if autoGucciActiveTrain and hum.Health > 0 then
                                if not antiGucciConnectionTrain and not startingTrain then
                                    startAntiGucciTrain()
                                end
                            end
                        end)
                    end
                end)

                startAntiGucciTrain()
                startTrainAutoLoop()
            else
                autoGucciActiveTrain = false
                startingTrain = false

                if respawnConnectionTrain then
                    respawnConnectionTrain:Disconnect()
                    respawnConnectionTrain = nil
                end

                stopAntiGucciTrain()
            end
        end
    })
end
