-- Anti Input Lag
--=======================================================================
do
    local ToyList = {
        ["Coconut"]     = "FoodCoconut",
        ["Banana"]      = "FoodBanana",
        ["Fries"]       = "FoodFrenchFries",
        ["MeatStick"]   = "FoodMeatStick",
        ["Poop"]        = "PoopPile",
        ["Donut"]       = "FoodDonut",
        ["Cake"]        = "FoodCakePink",
        ["Burger"]      = "FoodHamburger",
        ["Pizza"]       = "FoodPizzaCheese",
        ["Hotdog"]      = "FoodHotdog",
        ["Mushroom"]    = "FoodMushroomPoison",
        ["Pepperoni"]   = "FoodPizzaPepperoni",
        ["Bread"]       = "FoodBread",
        ["Egg"]         = "FoodDippyEgg",
        ["Mayo"]        = "FoodMayonnaise",
        ["SparklePoop"] = "PoopPileSparkle",
        ["Banjo"]       = "InstrumentGuitarBanjo",
        ["Violin"]      = "InstrumentGuitarViolin",
        ["Ukulele"]     = "InstrumentGuitarUkulele",
        ["Sax"]         = "InstrumentWoodwindSaxophone",
        ["Vuvuzela"]    = "InstrumentBrassVuvuzela",
        ["Bongos"]      = "InstrumentDrumBongos",
        ["Mic"]         = "InstrumentVoiceMicrophone",
        ["Piano"]       = "InstrumentPianoMelodica",
        ["WhiteMug"]    = "CupMugWhite",
        ["Ocarina"]     = "InstrumentWoodwindOcarina",
        ["BrownMug"]    = "CupMugBrown",
        ["Trumpet"]     = "InstrumentBrassTrumpet",
        ["Snare"]       = "InstrumentDrumSnare",
        ["Lyre"]        = "InstrumentGuitarLyre",
    }

    local DropdownValues = {}
    for shortName, _ in pairs(ToyList) do
        table.insert(DropdownValues, shortName)
    end
    table.sort(DropdownValues)

    local SelectedToy = ToyList["Banana"] or ToyList[DropdownValues[1]]

    local HoldDuration = 0.02
    local CycleSpeed = 0.02

    local function ClearToys()
        local plr = Players.LocalPlayer
        local inv = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
        if inv then
            for _, v in pairs(inv:GetChildren()) do
                if v.Name == SelectedToy then
                    pcall(function()
                        if DestroyRemote then
                            DestroyRemote:FireServer(v)
                        else
                            v:Destroy()
                        end
                    end)
                end
            end
        end
    end
        
    GucciGroupbox:AddDivider()
    GucciGroupbox:AddDropdown("AntiInputLagToy", {
        Text = "Select Toy",
        Values = DropdownValues,
        Default = "Banana",
        Callback = function(Value)
            ClearToys()
            SelectedToy = ToyList[Value]
        end
    })

    GucciGroupbox:AddCheckbox("AntiInputLag", {
        Text = "Anti Input Lag",
        Default = false,
        Callback = function(Value)
            _G.InstantLagActive = Value

            if Value then
                task.spawn(function()
                    local plr = game.Players.LocalPlayer
                    local RS = game:GetService("ReplicatedStorage")
                    local SpawnRemote = RS:WaitForChild("MenuToys"):WaitForChild("SpawnToyRemoteFunction")

                    while _G.InstantLagActive do
                        local char = plr.Character
                        local hrp = char and char:FindFirstChild("HumanoidRootPart")
                        
                        if hrp then
                            local toysFolder = workspace:FindFirstChild(plr.Name.."SpawnedInToys")
                            local name = SelectedToy
                            local item = toysFolder and toysFolder:FindFirstChild(name)

                            if item then
                                local holdPart = item:FindFirstChild("HoldPart")
                                local holdingPlayer = holdPart and holdPart:FindFirstChild("HoldingPlayer")
                                if holdingPlayer and holdingPlayer.Value and holdingPlayer.Value ~= plr then
                                    item = nil
                                end
                            end

                            for _, obj in pairs(workspace:GetChildren()) do
                                if obj.Name == "Shuriken" and obj:IsA("Model") then
                                    for _, part in pairs(obj:GetDescendants()) do
                                        if part:IsA("BasePart") then 
                                            part.CanCollide = false 
                                            part.Massless = true 
                                        end
                                    end
                                end
                            end

                            if not item or not item.Parent then
                                task.spawn(function()
                                    pcall(function()
                                        SpawnRemote:InvokeServer(name, hrp.CFrame * CFrame.new(0, -12, 0), Vector3.zero)
                                    end)
                                end)
                                task.wait(0.1)
                            else
                                local holdPart = item:FindFirstChild("HoldPart")
                                if holdPart then
                                    for _, v in pairs(item:GetDescendants()) do
                                        if v:IsA("BasePart") then 
                                            v.CanCollide = false 
                                            v.Massless = true 
                                        end
                                    end

                                    task.spawn(function()
                                        pcall(function()
                                            holdPart.HoldItemRemoteFunction:InvokeServer(item, char)
                                        end)
                                    end)

                                    task.wait(HoldDuration)

                                    task.spawn(function()
                                        pcall(function()
                                            holdPart.DropItemRemoteFunction:InvokeServer(
                                                item, 
                                                CFrame.new(0, 5000, 0), 
                                                Vector3.zero
                                            )
                                        end)
                                    end)
                                end
                            end
                        end
                        task.wait(CycleSpeed)
                    end
                end)
            else
                ClearToys()
            end
        end
    })
end
--=======================================================================
-- Anti Hold Item Part
--=======================================================================
do
    local AllowedItems = {
        FoodHamburger = true, FoodCoconut = true, FoodPizzaCheese = true,
        FoodPizzaPepperoni = true, FoodHotdog = true, FoodMushroomPoison = true,
        FoodBread = true, FoodDippyEgg = true, FoodMayonnaise = true,
        FoodFrenchFries = true, FoodMeatStick = true, FoodDonut = true,
        FoodCakePink = true, FoodBanana = true, FoodBroccoli = true,
        FoodSodaCan = true,

        InstrumentGuitarBanjo = true, InstrumentGuitarViolin = true,
        InstrumentGuitarUkulele = true, InstrumentWoodwindSaxophone = true,
        InstrumentWoodwindOcarina = true, InstrumentBrassVuvuzelaQwizik = true,
        InstrumentBrassTrumpet = true, InstrumentDrumBongos = true,
        InstrumentDrumSnare = true, InstrumentPianoMelodica = true,
        InstrumentVoiceMicrophone = true, InstrumentBrassBugle = true,
        InstrumentBrassVuvuzela = true, InstrumentGuitarAcoustic = true,
        InstrumentGuitarLyre = true, InstrumentPianoKeyboard = true,

        CupMugWhite = true, CupMugBrown = true,
        PoopPile = true, PoopPileSparkle = true,
    }

    local TICK_RATE = 0.05

    local State = {
        enabled = false,
        items = {},
        itemSet = {},
        descendantConn = nil,  
        loopRunning = false,
    }

    local function addItem(obj)
        if not obj or not obj.Parent then return end
        if not AllowedItems[obj.Name] then return end
        if not obj:IsA("Model") then return end
        if State.itemSet[obj] then return end
        State.itemSet[obj] = true
        State.items[#State.items + 1] = obj
    end

    local function scanAll()
        for _, v in ipairs(workspace:GetDescendants()) do
            addItem(v)
        end
    end

    local function startDescendantListener()
        if State.descendantConn then
            State.descendantConn:Disconnect()
            State.descendantConn = nil
        end
        State.descendantConn = workspace.DescendantAdded:Connect(function(obj)
            if not State.enabled then return end
            if AllowedItems[obj.Name] and obj:IsA("Model") then
                addItem(obj)
            end
        end)
    end

    local function processLoop()
        if State.loopRunning then return end
        State.loopRunning = true

        task.spawn(function()
            local plr = game.Players.LocalPlayer

            while State.enabled do
                local loopStart = os.clock()

                local char = plr.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")

                if hrp then
                    for i = #State.items, 1, -1 do
                        local b = State.items[i]

                        if not b or not b.Parent then
                            State.itemSet[b] = nil
                            table.remove(State.items, i)
                        else
                            local hp = b:FindFirstChild("HoldPart")
                            if hp then
                                pcall(function()
                                    hp.HoldItemRemoteFunction:InvokeServer(b, char)
                                end)
                                pcall(function()
                                    hp.DropItemRemoteFunction:InvokeServer(
                                        b,
                                        CFrame.new(hrp.Position + Vector3.new(0, -2000, 0)),
                                        Vector3.new(0, 0, 0)
                                    )
                                end)
                            end
                        end
                    end
                end

                local elapsed = os.clock() - loopStart
                local waitTime = TICK_RATE - elapsed
                task.wait(waitTime > 0 and waitTime or nil)
            end

            State.loopRunning = false
        end)
    end

    GucciGroupbox:AddCheckbox("Remove AntiInputLag", {
        Text = "Anti Hold Item Part",
        Default = false,
        Callback = function(on)
            if on then
                State.enabled = true

                State.items = {}
                State.itemSet = {}
                scanAll()

                startDescendantListener()

                processLoop()
            else
                State.enabled = false

                if State.descendantConn then
                    State.descendantConn:Disconnect()
                    State.descendantConn = nil
                end

                State.items = {}
                State.itemSet = {}

            end
        end,
    })
end
--=======================================================================
-- Barrier Break
--=======================================================================
do
    AntiETCGroupbox:AddButton({
        Text = "Break Barrier",
        Func = function()
            local player = LocalPlayer
            if not player then
                OrionLib:MakeNotification({Name="Error", Content="Player not found", Time = 4})
                return
            end

            if not (player.Character and player.Character:FindFirstChild("HumanoidRootPart")) then  
                OrionLib:MakeNotification({Name="Error", Content="Character not ready", Time = 4})  
                return  
            end  

            local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")  
            local originalWalkSpeed, originalJumpPower  
            if humanoid then  
                originalWalkSpeed = humanoid.WalkSpeed  
                originalJumpPower = humanoid.JumpPower  
                pcall(function() humanoid.WalkSpeed = 0 humanoid.JumpPower = 0 end)  
            end  

            local success, err = pcall(function()  
                local hrp = player.Character.HumanoidRootPart  
                local originalCFrame = hrp.CFrame  

                hrp.CFrame = CFrame.new(246.052, -7.35, 431.821)  
                task.wait(0.05)  

                SpawnRemote:InvokeServer(  
                    "InstrumentWoodwindOcarina",  
                    CFrame.new(184.148834, -5.54824972, 498.136749,  
                        0.829037189, -0.214714944, 0.516328275,  
                        0, 0.923344612, 0.383972496,  
                        -0.559193552, -0.318327487, 0.765486956),  
                    Vector3.new(0, 34, 0)  
                )  

                task.wait(0.2)  

                local toyFolder = Workspace:FindFirstChild(player.Name .. "SpawnedInToys")  
                if not toyFolder then error("SpawnedInToys folder not found") end  

                local ocarina = toyFolder:FindFirstChild("InstrumentWoodwindOcarina")  
                if not ocarina then error("InstrumentWoodwindOcarina not found") end  

                if ocarina:FindFirstChild("HoldPart") and ocarina.HoldPart:FindFirstChild("HoldItemRemoteFunction") then  
                    pcall(function()  
                        ocarina.HoldPart.HoldItemRemoteFunction:InvokeServer(ocarina, player.Character)  
                    end)  
                    task.wait(0.2)  
                end  

                player.Character.HumanoidRootPart.CFrame = CFrame.new(304.06, 25.77, 488.54)  
                task.wait(0.05)  

                DestroyRemote:FireServer(ocarina)  

                task.wait(0.05)  

                if player.Character and player.Character:FindFirstChild("HumanoidRootPart") then  
                    player.Character.HumanoidRootPart.CFrame = originalCFrame  
                end  

                OrionLib:MakeNotification({Name="Success", Content="Barrier break executed", Time = 3})  
            end)  

            local function tryRestore()  
                if originalWalkSpeed == nil and originalJumpPower == nil then return end  
                local curHum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")  
                if curHum then  
                    pcall(function()  
                        if originalWalkSpeed ~= nil then curHum.WalkSpeed = originalWalkSpeed end  
                        if originalJumpPower ~= nil then curHum.JumpPower = originalJumpPower end  
                    end)  
                end  
            end  

            tryRestore()  

            if not success then  
                OrionLib:MakeNotification({Name="Error", Content=tostring(err), Time = 6})  
            end  
        end
    })
end
--=======================================================================
-- Noclip Barrier
--=======================================================================
do
	local barrierNoclipActive = false
	local barrierConnection = nil

	local function setBarrierNoclip(state)
		local plots = Workspace:FindFirstChild("Plots")
		if not plots then return end

		for index = 1, 5 do
			local plot = plots:FindFirstChild("Plot" .. index)
			local barrier = plot and plot:FindFirstChild("Barrier")
			if barrier then
				for _, part in ipairs(barrier:GetDescendants()) do
					if part:IsA("BasePart") then
						part.CanCollide = not state
					end
				end
			end
		end
	end

	AntiETCGroupbox:AddCheckbox("barriernoclip", {
		Text = "Noclip barrier",
		Default = false,
		Callback = function(value)
			barrierNoclipActive = value
			if barrierConnection then barrierConnection:Disconnect() barrierConnection = nil end

			setBarrierNoclip(value)

			if value then

				barrierConnection = RunService.Stepped:Connect(function()
					if barrierNoclipActive then
						setBarrierNoclip(true)
					end
				end)
			else
				setBarrierNoclip(false)
			end
		end
	})
end
--=======================================================================
-- Ocean Walk
--=======================================================================
do
	local oceanWallActive = false
	local oceanTransparency = 0.5
	local oceanConnection = nil

	local function getOceanObject()
		local map = Workspace:FindFirstChild("Map")
		local tweenedObjects = map and map:FindFirstChild("AlwaysHereTweenedObjects")
		local oceanGroup = tweenedObjects and tweenedObjects:FindFirstChild("Ocean")
		return oceanGroup and oceanGroup:FindFirstChild("Object")
	end

	local function applyProperties(part, value)
		if not part:IsA("BasePart") then return end
		part.CanCollide = value
		part.CanTouch = value
		part.CanQuery = value

		if value then
			part.Transparency = oceanTransparency
		else
			part.Transparency = 0
		end
	end

	local function updateOcean(value)
		local oceanObject = getOceanObject()
		if not oceanObject then return end

		if oceanObject:IsA("BasePart") then
			applyProperties(oceanObject, value)
		end

		for _, descendantPart in ipairs(oceanObject:GetDescendants()) do
			applyProperties(descendantPart, value)
		end
	end

	AntiETCGroupbox:AddCheckbox("OceanWalk", {
		Text = "Ocean Walk",
		Default = false,
		Callback = function(value)
			oceanWallActive = value
			if oceanConnection then oceanConnection:Disconnect() oceanConnection = nil end

			updateOcean(value)

			if value then

				oceanConnection = Workspace.DescendantAdded:Connect(function(descendant)
					if oceanWallActive then
						local oceanObject = getOceanObject()
						if oceanObject and (descendant == oceanObject or descendant:IsDescendantOf(oceanObject)) then
							applyProperties(descendant, true)
						end
					end
				end)
			else
				updateOcean(false)
			end
		end
	})
end
--=======================================================================
-- Loop Ragdoll
--=======================================================================
do
    local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    local humanoidRootPart = character:WaitForChild("HumanoidRootPart", 5)
    local humanoid = character:WaitForChild("Humanoid", 5)

    local loopRagdoll = false
    local ragdollThread = nil

    LocalPlayer.CharacterAdded:Connect(function(newCharacter)
        character = newCharacter
        humanoidRootPart = newCharacter:WaitForChild("HumanoidRootPart", 5)
        humanoid = newCharacter:WaitForChild("Humanoid", 5)
    end)

    AntiETCGroupbox:AddCheckbox("LoopRagdoll", {
        Text = "Loop Ragdoll",
        Default = false,
        Callback = function(value)
            loopRagdoll = value

            if value then
                if ragdollThread then
                    task.cancel(ragdollThread)
                    ragdollThread = nil
                end

                ragdollThread = task.spawn(function()
                    while loopRagdoll do
                        if not character or not character.Parent then
                            character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
                            humanoidRootPart = character:WaitForChild("HumanoidRootPart", 5)
                            humanoid = character:WaitForChild("Humanoid", 5)
                        end

                        if humanoidRootPart and humanoidRootPart.Parent and humanoid and humanoid.Health > 0 and RagdollRemote then
                            RagdollRemote:FireServer(humanoidRootPart, 0.5)
                        end

                        task.wait(0.05)
                    end
                    ragdollThread = nil
                end)
            else
                if ragdollThread then
                    task.cancel(ragdollThread)
                    ragdollThread = nil
                end
            end
        end
    })
end
--=======================================================================
-- Loop Reset
--=======================================================================
AntiETCGroupbox:AddCheckbox("AutoResetToggle", {
    Text = "Loop Reset",
    Default = false,
    Callback = function(on)
        autoResetEnabled = on
        if not on then
            autoResetEnabled = false
            return
        end
        task.spawn(function()
            local plr = game.Players.LocalPlayer
            while autoResetEnabled do
                local char = plr.Character
                local hum = char and char:FindFirstChild("Humanoid")
                if hum and hum.Health > 0 then
                    hum.Health = 0
                end
                task.wait(0.5)
            end
        end)
    end
})
--=======================================================================
-- Loop Teleport
--=======================================================================
do
	local teleportActive = false

	AntiETCGroupbox:AddCheckbox("LoopTPToggle", {
		Text = "Loop TP",
		Default = false,
		Callback = function(value)
			teleportActive = value

			local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
			local humanoidRootPart = character:WaitForChild("HumanoidRootPart")
			local humanoid = character:FindFirstChildOfClass("Humanoid")

			if teleportActive then
				if humanoid then
					humanoid.PlatformStand = true
				end

				task.spawn(function()
					while teleportActive and humanoidRootPart do
						local randomPositionX = math.random(-500, 500)
						local randomPositionY = math.random(30, 480)
						local randomPositionZ = math.random(-500, 500)

						humanoidRootPart.CFrame = CFrame.new(randomPositionX, randomPositionY, randomPositionZ)
						task.wait(0.03)
					end
				end)
			else
				if humanoid then
					humanoid.PlatformStand = false
				end
			end
		end
	})
end
--=======================================================================
-- Kill Grab
--=======================================================================
local KillGrabC = nil
local killGrabEnabled = false

local c = {
    torso = humanoidRootPart,
    c = character
}

LocalPlayer.CharacterAdded:Connect(function(newChar)
    character = newChar
    humanoidRootPart = newChar:WaitForChild("HumanoidRootPart")
    humanoid = newChar:WaitForChild("Humanoid")
    c.torso = humanoidRootPart
    c.c = newChar
end)

local function ifnet(part)
    if typeof(isnetworkowner) == "function" then
        return isnetworkowner(part)
    end
    return true
end

local function updateKillGrab()
    if KillGrabC then
        KillGrabC:Disconnect()
        KillGrabC = nil
    end

    if not killGrabEnabled then return end

    KillGrabC = RunService.Heartbeat:Connect(function()
        local GrabParts = Workspace:FindFirstChild("GrabParts")
        if not GrabParts then return end

        local GrabPart = GrabParts:FindFirstChild("GrabPart")
        local WeldConstraint = GrabPart and GrabPart:FindFirstChild("WeldConstraint")
        if not WeldConstraint then return end

        local Target = WeldConstraint.Part1
        if not Target then return end

        local Tchar = Target.Parent
        if not Tchar then return end

        local Thum = Tchar:FindFirstChild("Humanoid") or Tchar:FindFirstChild("HumanoidCreature")
        local Thrp = Tchar:FindFirstChild("HumanoidRootPart")
        if not Thrp or not Thum then return end

        local Ttorso = Tchar:FindFirstChild("Torso") or Tchar:FindFirstChild("UpperTorso")

        if Thum.Health <= 0 then
            GrabParts:Destroy()
        end
        WeldConstraint.Part0 = nil
        Thum.BreakJointsOnDeath = false
        Thum:ChangeState(Enum.HumanoidStateType.Dead)
        SetNetworkOwner:FireServer(Target, CFrame.lookAt(c.torso.Position, Target.Position))

        if Ttorso and ifnet(Thrp) and (c.torso.Position - Thrp.Position).Magnitude <= 40 and Workspace.FallenPartsDestroyHeight == -100 then
            Ttorso.CFrame = CFrame.new(0, -99, 777)
        end
    end)
end

_G.StartKillGrab = function()
    killGrabEnabled = true
    updateKillGrab()
end

_G.StopKillGrab = function()
    killGrabEnabled = false
    updateKillGrab()
end

--=======================================================================
-- Ragdoll Grab
--=======================================================================
local RagdollGrabActive = false
local RagdollGrabConnection = nil

do
	local humanoidRootPart = character.HumanoidRootPart
	local humanoid = character.Humanoid
	local inventory = Workspace[LocalPlayer.Name .. "SpawnedInToys"]
	local cons = {}

	local function spawntoy(toy, cframe)
		if not CanSpawn.Value then
			CanSpawn.Changed:Wait()
		end
		local spawnedToy
		local toyadded
		toyadded = inventory.ChildAdded:Connect(function(child)
			if child.Name == toy then
				spawnedToy = child
				toyadded:Disconnect()
			end
		end)
		task.spawn(function()
			SpawnRemote:InvokeServer(toy, cframe, Vector3.new(0, 0, 0))
		end)
		local time = tick() + 1
		repeat task.wait() until spawnedToy or tick() > time
		if spawnedToy then
			return spawnedToy
		end
	end

	local function sno(object)
		SetNetworkOwner:FireServer(object, object.CFrame)
	end

	LocalPlayer.CharacterAdded:Connect(function(newCharacter)
		task.wait(0.1)
		if newCharacter then
			character = newCharacter
			humanoidRootPart = newCharacter:FindFirstChild("HumanoidRootPart") or newCharacter:WaitForChild("HumanoidRootPart", 1)
			humanoid = newCharacter:FindFirstChild("Humanoid") or newCharacter:WaitForChild("Humanoid", 1)
		end
	end)

	local function StartRagdollGrab()
		if RagdollGrabActive then return end
		RagdollGrabActive = true

		local ragd = spawntoy("PalletLightBrown", humanoidRootPart.CFrame * CFrame.new(5, 5, 20))
		local partt = ragd:WaitForChild("SoundPart", 0.1)
		ragd.Name = "ragdoll"
		repeat sno(partt) task.wait() until partt:FindFirstChild("PartOwner")
		partt.AssemblyLinearVelocity = Vector3.new(0, 10000, 0)
		spawn(function()
			for i, v in pairs(ragd:GetDescendants()) do
				if v:IsA("Part") then
					v.Transparency = 1
					v.CanCollide = false
				end
			end
		end)

		cons["rgarab1"] = Workspace.ChildAdded:Connect(function(c)
			if c.Name == "GrabParts" then
				local part = c:FindFirstChild("GrabPart") or c:WaitForChild("GrabPart", 3)
				if part then
					local obj = part.WeldConstraint.Part1
					while Workspace:FindFirstChild("GrabParts") and task.wait() do
						if obj then
							if obj.Parent and obj.Parent:FindFirstChild("HumanoidRootPart") and obj.Parent:FindFirstChild("Humanoid") and obj.Parent.Humanoid:FindFirstChild("Ragdolled") and obj.Parent.Humanoid.Ragdolled.Value == false then
								spawn(function()
									partt.AssemblyLinearVelocity = Vector3.new(0, 100, 0)
									partt.CFrame = obj.Parent.HumanoidRootPart.CFrame
									task.wait(0.05)
									partt.CFrame = CFrame.new(0, 1e9, 0)
								end)
							end
						end
					end
				end
			end
		end)
	end

	local function StopRagdollGrab()
		RagdollGrabActive = false
		if cons["rgarab1"] then
			cons["rgarab1"]:Disconnect()
			cons["rgarab1"] = nil
		end
		if inventory and inventory:FindFirstChild("ragdoll") then
			DestroyRemote:FireServer(inventory.ragdoll)
		end
	end

	_G.StartRagdollGrab = StartRagdollGrab
	_G.StopRagdollGrab = StopRagdollGrab
end

--=======================================================================
-- Loop Grab
--=======================================================================
local LoopGrabActive = false

do
	local function ApplyLoopGrab(on)
		if on then
			if LoopGrabActive then return end
			LoopGrabActive = true
			getgenv().LoopGrabActive = true

			local Player = Players.LocalPlayer
			local SetNetworkOwnerRemote = ReplicatedStorage:WaitForChild('GrabEvents'):WaitForChild('SetNetworkOwner')

			task.spawn(function()
				while getgenv().LoopGrabActive do
					local grabParts = Workspace:FindFirstChild('GrabParts')

					if not grabParts then
						task.wait()
						continue
					end

					local grabPart = grabParts:FindFirstChild('GrabPart')
					local weldConstraint = grabPart and grabPart:FindFirstChildOfClass('WeldConstraint')
					local targetPart = weldConstraint and weldConstraint.Part1

					if targetPart then
						local ownerPlayer = nil

						for _, targetPlayer in ipairs(Players:GetPlayers()) do
							if targetPlayer.Character and targetPart:IsDescendantOf(targetPlayer.Character) then
								ownerPlayer = targetPlayer
								break
							end
						end

						while getgenv().LoopGrabActive and Workspace:FindFirstChild('GrabParts') do
							if ownerPlayer then
								local targetTorso = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('HumanoidRootPart')
								local targetHead = ownerPlayer.Character and ownerPlayer.Character:FindFirstChild('Head')
								local myTorso = Player.Character and Player.Character:FindFirstChild('HumanoidRootPart')

								if targetTorso and myTorso and targetHead then
									pcall(function()
										SetNetworkOwnerRemote:FireServer(targetTorso, CFrame.lookAt(myTorso.Position, targetTorso.Position))
									end)
								end
							else
								if targetPart.Parent then
									local myTorso = Player.Character and Player.Character:FindFirstChild('HumanoidRootPart')

									if myTorso then
										pcall(function()
											SetNetworkOwnerRemote:FireServer(targetPart, CFrame.lookAt(myTorso.Position, targetPart.Position))
										end)
									end
								end
							end

							task.wait()
						end
					end

					task.wait()
				end
			end)

			if game.PlaceId == 6961824067 then
				local GrabEventsFolder = game:GetService('ReplicatedStorage'):WaitForChild('GrabEvents')
				local existingEndGrab = GrabEventsFolder:FindFirstChild('EndGrabEarly')

				if existingEndGrab then
					existingEndGrab:Destroy()
				end

				Instance.new('RemoteEvent', GrabEventsFolder).Name = 'EndGrabEarly'
			end

			getgenv().FTargetGrabActive = false
			getgenv().fGrabConnection = nil

			function getCenterTarget()
				local camera = workspace.CurrentCamera
				local center = Vector2.new(camera.ViewportSize.X / 2, camera.ViewportSize.Y / 2)
				local myTorso = Player.Character and Player.Character:FindFirstChild('HumanoidRootPart')

				if not myTorso then
					return nil
				end

				local closestTarget = nil
				local minScreenDist = math.huge

				for _, targetPlayer in ipairs(Players:GetPlayers()) do
					if targetPlayer ~= Player and targetPlayer.Character and targetPlayer.Character:FindFirstChild('HumanoidRootPart') then
						local targetTorso = targetPlayer.Character.HumanoidRootPart
						local distance = (targetTorso.Position - myTorso.Position).Magnitude

						if distance <= 25 then
							local screenPosition, onScreen = camera:WorldToViewportPoint(targetTorso.Position)

							if onScreen then
								local screenDistance = (Vector2.new(screenPosition.X, screenPosition.Y) - center).Magnitude

								if screenDistance < minScreenDist then
									minScreenDist = screenDistance
									closestTarget = targetPlayer
								end
							end
						end
					end
				end

				return closestTarget
			end

			if getgenv().LoopGrabInputConnection then
				getgenv().LoopGrabInputConnection:Disconnect()
				getgenv().LoopGrabInputConnection = nil
			end

			getgenv().LoopGrabInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
				if gameProcessed then return end
				if not getgenv().LoopGrabActive then return end

				if input.KeyCode == Enum.KeyCode.F then
					if getgenv().FTargetGrabActive then
						getgenv().FTargetGrabActive = false

						if getgenv().fGrabConnection then
							getgenv().fGrabConnection:Disconnect()
							getgenv().fGrabConnection = nil
						end
					else
						local target = getCenterTarget()

						if target then
							getgenv().FTargetGrabActive = true

							local camera = workspace.CurrentCamera

							getgenv().fGrabConnection = RunService.RenderStepped:Connect(function()
								if not getgenv().FTargetGrabActive or not target or not target.Character then
									getgenv().FTargetGrabActive = false

									if getgenv().fGrabConnection then
										getgenv().fGrabConnection:Disconnect()
										getgenv().fGrabConnection = nil
									end

									return
								end

								local targetTorso = target.Character:FindFirstChild('HumanoidRootPart')
								local targetHead = target.Character:FindFirstChild('Head')
								local myTorso = Player.Character and Player.Character:FindFirstChild('HumanoidRootPart')

								if targetTorso and myTorso and targetHead then
									SetNetworkOwnerRemote:FireServer(targetTorso, targetTorso.CFrame)

									if targetHead:FindFirstChild('PartOwner') then
										local targetPosition = camera.CFrame.Position + (camera.CFrame.LookVector * 23)
										local newCFrame = CFrame.new(targetPosition)

										targetTorso.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
										targetTorso.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
										targetTorso.CFrame = newCFrame

										SetNetworkOwnerRemote:FireServer(targetTorso, newCFrame)
									end
								end
							end)
						end
					end
				end
			end)
		else
			LoopGrabActive = false
			getgenv().LoopGrabActive = false
			getgenv().FTargetGrabActive = false

			if getgenv().fGrabConnection then
				getgenv().fGrabConnection:Disconnect()
				getgenv().fGrabConnection = nil
			end
			if getgenv().LoopGrabInputConnection then
				getgenv().LoopGrabInputConnection:Disconnect()
				getgenv().LoopGrabInputConnection = nil
			end
		end
	end

	_G.StartLoopGrab = function() ApplyLoopGrab(true) end
	_G.StopLoopGrab = function() ApplyLoopGrab(false) end
end

--=======================================================================
-- Kick Grab
--=======================================================================
local KickGrabActive = false
local KickGrabConnection = nil

do
	if game.PlaceId == 6961824067 then
		local function StartKickGrab()
			if KickGrabActive then return end
			KickGrabActive = true

			local G = game:GetService("ReplicatedStorage"):WaitForChild("GrabEvents")
			if G:FindFirstChild("EndGrabEarly") then
				G.EndGrabEarly:Destroy()
			end
			Instance.new("RemoteEvent", G).Name = "EndGrabEarly"

			local Player = Players.LocalPlayer
			local SetNetworkOwnerRemote = G:WaitForChild('SetNetworkOwner')
			local DestroyGrabLineRemote = G:WaitForChild('DestroyGrabLine')

			KickGrabConnection = RunService.Heartbeat:Connect(function()
				if not KickGrabActive then return end

				local myCharacter = Player.Character
				if not myCharacter then return end

				local myTorso = myCharacter:FindFirstChild('Torso')
					or myCharacter:FindFirstChild('HumanoidRootPart')
				if not myTorso then return end

				local grabParts = Workspace:FindFirstChild('GrabParts')
				if not grabParts then return end

				for _, grabPart in ipairs(grabParts:GetChildren()) do
					if grabPart.Name == 'GrabPart' then
						local weld = grabPart:FindFirstChildOfClass('WeldConstraint')
						if not weld then continue end

						local originalPart1 = weld.Part1
						if not originalPart1 then continue end

						local ownerPlayer
						for _, targetPlayer in ipairs(Players:GetPlayers()) do
							if targetPlayer ~= Player
								and targetPlayer.Character
								and originalPart1:IsDescendantOf(targetPlayer.Character) then
								ownerPlayer = targetPlayer
								break
							end
						end

						if not ownerPlayer then continue end

						local tgtTorso = ownerPlayer.Character:FindFirstChild('HumanoidRootPart')
						if not tgtTorso then continue end

						local tgtHum = ownerPlayer.Character:FindFirstChild('Humanoid')
						if not tgtHum then continue end

						weld.Part1 = tgtTorso

						if not tgtHum.Sit then
							pcall(function()
								SetNetworkOwnerRemote:FireServer(
									tgtTorso,
									CFrame.lookAt(myTorso.Position, tgtTorso.Position)
								)
							end)
						end

						if tgtHum.Sit then
							pcall(function()
								DestroyGrabLineRemote:FireServer(tgtTorso)
							end)
						end

						if ownerPlayer.IsHeld then
							pcall(function()
								SetNetworkOwnerRemote:FireServer(
									tgtTorso,
									CFrame.lookAt(myTorso.Position, tgtTorso.Position)
								)
							end)
						end

						if tgtHum.Sit then
							pcall(function()
								DestroyGrabLineRemote:FireServer(tgtTorso)
							end)
						end
					end
				end
			end)
		end

		local function StopKickGrab()
			KickGrabActive = false
			if KickGrabConnection then
				KickGrabConnection:Disconnect()
				KickGrabConnection = nil
			end
		end

		_G.StartKickGrab = StartKickGrab
		_G.StopKickGrab = StopKickGrab
	else
		_G.StartKickGrab = function() end
		_G.StopKickGrab = function() end
	end
end

--=======================================================================
-- MassLess Grab
--=======================================================================
local MassLessGrabActive = false
local MassLessGrabConnection = nil

do
	local massLessGrabSensitivity = 200

	local function StartMassLessGrab()
		if MassLessGrabActive then return end
		MassLessGrabActive = true

		MassLessGrabConnection = RunService.Heartbeat:Connect(function()
			if not MassLessGrabActive then return end

			local grabPartsFolder = Workspace:FindFirstChild("GrabParts")
			if not grabPartsFolder then return end

			local dragPart = grabPartsFolder:FindFirstChild("DragPart")
