		Callback = function(enabled)
			if enabled then
				throwStrengthConnection = Workspace.ChildAdded:Connect(function(addedChild)
					if addedChild.Name == "GrabParts" then
						local grabPart = addedChild:FindFirstChild("GrabPart")
						if not grabPart then return end
						
						local weldConstraint = grabPart:FindFirstChild("WeldConstraint")
						if not weldConstraint then return end

