-- Blobman Kill
--=======================================================================
local killThread = nil

    BlobGroupbox:AddCheckbox("LoopKill", {
        Text = "Blob Kill",
        Default = false,
        Callback = function(v)
            local applymethod = v
            local tt = selectedKickPlayer

            if v then
                local char = LocalPlayer.Character
                local hum = char and char:FindFirstChild("Humanoid")
                local seat = hum and hum.SeatPart

                if not seat or not seat.Parent or (seat.Parent.Name ~= "CreatureBlobman" and seat.Parent.Name ~= "AutoSitBlobman") then
                    if Toggles and Toggles.LoopKill then
                        Toggles.LoopKill:SetValue(false)
                    end
                    return
                end
            end

            if not tt then
                if v then
                    if Toggles and Toggles.LoopKill then
                        Toggles.LoopKill:SetValue(false)
                    end
                end
                return
            end

            if v then
                killThread = task.spawn(function()
                    while applymethod and task.wait(0.05) do
                        tt = selectedKickPlayer

                        local char = LocalPlayer.Character
                        local hum = char and char:FindFirstChild("Humanoid")
                        local seat = hum and hum.SeatPart

                        if not seat or not seat.Parent or (seat.Parent.Name ~= "CreatureBlobman" and seat.Parent.Name ~= "AutoSitBlobman") then
                            applymethod = false
                            if Toggles and Toggles.LoopKill then
                                Toggles.LoopKill:SetValue(false)
                            end
                            break
                        end

                        local Blob = seat.Parent

                        if tt and tt.Character and tt.Character:FindFirstChild("HumanoidRootPart") and char and char:FindFirstChild("HumanoidRootPart") then
                            local HRP = char.HumanoidRootPart
                            local hum2 = char.Humanoid

                            local CD, CG = Blob.BlobmanSeatAndOwnerScript.CreatureRelease, Blob.BlobmanSeatAndOwnerScript.CreatureGrab
                            local pos = HRP.CFrame
                            if tt.Character and tt.Character:FindFirstChild("HumanoidRootPart") and tt.Character.Humanoid.Health ~= 0 then
                                Blob.HumanoidRootPart.CFrame = tt.Character.HumanoidRootPart.CFrame
                                task.wait(0.1)
                                repeat task.wait()
                                    CG:FireServer(nil, tt.Character.HumanoidRootPart, Blob.RightDetector.RightWeld)
                                    CD:FireServer(Blob.RightDetector.RightWeld)
                                until isnetworkowner(tt.Character.HumanoidRootPart)
                                task.wait()
                                tt.Character.Humanoid:ChangeState("Dead")
                                stvel(HRP)
                                stvel(Blob.HumanoidRootPart)
                                Blob.HumanoidRootPart.CFrame = pos
                            end
                        end
                    end

                    applymethod = false
                    if Toggles and Toggles.LoopKill then
                        Toggles.LoopKill:SetValue(false)
                    end
                end)
            else
                applymethod = false
                if killThread then
                    task.cancel(killThread)
                    killThread = nil
                end
            end
        end
    })
--=======================================================================
-- Blob Kick
--=======================================================================
BlobGroupbox:AddCheckbox("LoopKickToggle", {
        Text = "Blob Kick",
        Default = false,
        Callback = function(on)
            kickLoopEnabled = on

            if not on then
                return
            end

            local targetCheck = selectedKickPlayer
            if not targetCheck or not targetCheck.Parent then
                if Toggles and Toggles.LoopKickToggle then
                    Toggles.LoopKickToggle:SetValue(false)
                end
                kickLoopEnabled = false
                return
            end

            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChild("Humanoid")
            local seat = hum and hum.SeatPart

            if not seat or not seat.Parent or (seat.Parent.Name ~= "CreatureBlobman" and seat.Parent.Name ~= "AutoSitBlobman") then
                if Toggles and Toggles.LoopKickToggle then
                    Toggles.LoopKickToggle:SetValue(false)
                end
                kickLoopEnabled = false
                return
            end

            task.spawn(function()
                local blob = seat.Parent
                local blobRoot = blob:FindFirstChild("HumanoidRootPart") or blob.PrimaryPart
                local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                local CG = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                local CD = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
                local R_Det = blob:FindFirstChild("RightDetector")
                local R_Weld = R_Det and (R_Det:FindFirstChild("RightWeld") or R_Det:FindFirstChildWhichIsA("Weld"))

                if not blobRoot then
                    kickLoopEnabled = false
                    if Toggles and Toggles.LoopKickToggle then
                        Toggles.LoopKickToggle:SetValue(false)
                    end
                    return
                end

                local SavedPos = blobRoot.CFrame
                local packetTimer = 0
                local lastTargetChar = nil
                local PACKET_DELAY = 0.01  
                local BRING_DURATION = 0.15 

                while kickLoopEnabled do
                    local target = selectedKickPlayer

                    if not blobRoot or not blobRoot.Parent then
                        break
                    end

                    if not target or not target.Parent then
                        lastTargetChar = nil
                        task.wait(0.2)  
                        continue
                    end

                    local tCharCurrent = target.Character
                    local tRootCurrent = tCharCurrent and tCharCurrent:FindFirstChild("HumanoidRootPart")
                    local tHumCurrent = tCharCurrent and tCharCurrent:FindFirstChild("Humanoid")

                    if not tCharCurrent or not tRootCurrent or not tHumCurrent or tHumCurrent.Health <= 0 then
                        lastTargetChar = nil 
                        task.wait(0.03) 
                        continue
                    end

                    if tCharCurrent ~= lastTargetChar then
                        lastTargetChar = tCharCurrent
                        local bringStart = tick()

                        while tick() - bringStart < BRING_DURATION do
                            if not kickLoopEnabled then break end

                            blobRoot.CFrame = tRootCurrent.CFrame
                            blobRoot.AssemblyLinearVelocity = Vector3.zero
                            blobRoot.AssemblyAngularVelocity = Vector3.zero

                            pcall(function()
                                if CG and R_Det then
                                    CG:FireServer(R_Det, tRootCurrent, R_Weld)
                                end
                                if CreateGrabLine then CreateGrabLine:FireServer(tRootCurrent, Vector3.zero, tRootCurrent.Position, false) end
                                if SetNetworkOwner then SetNetworkOwner:FireServer(tRootCurrent, blobRoot.CFrame) end
                            end)
                            RunService.Heartbeat:Wait()
                        end

                        blobRoot.CFrame = SavedPos
                        blobRoot.AssemblyLinearVelocity = Vector3.zero
                        blobRoot.AssemblyAngularVelocity = Vector3.zero
                        task.wait(0.01)  
                    end

                    blobRoot.CFrame = SavedPos
                    blobRoot.AssemblyLinearVelocity = Vector3.zero
                    blobRoot.AssemblyAngularVelocity = Vector3.zero

                    local lockPos = SavedPos * CFrame.new(0, 23, 0)
                    tRootCurrent.CFrame = lockPos
                    tRootCurrent.AssemblyLinearVelocity = Vector3.zero
                    tRootCurrent.AssemblyAngularVelocity = Vector3.zero
                    tRootCurrent.Velocity = Vector3.zero
                    tRootCurrent.RotVelocity = Vector3.zero

                    if tick() - packetTimer > PACKET_DELAY then
                        packetTimer = tick()
                        pcall(function()
                            tHumCurrent.PlatformStand = true
                            tHumCurrent.Sit = true
                            if SetNetworkOwner then SetNetworkOwner:FireServer(tRootCurrent, lockPos) end
                            if R_Det and CD then
                                local weld = R_Det:FindFirstChild("RightWeld") or R_Det:FindFirstChildWhichIsA("Weld")
                                if weld then CD:FireServer(weld) end
                            end
                            if DestroyGrabLine then DestroyGrabLine:FireServer(tRootCurrent) end
                            if R_Det and CG then CG:FireServer(R_Det, tRootCurrent, R_Weld) end
                            if CreateGrabLine then CreateGrabLine:FireServer(tRootCurrent, Vector3.zero, tRootCurrent.Position, false) end
                        end)
                    end

                    RunService.Heartbeat:Wait()
                end

                kickLoopEnabled = false
                if Toggles and Toggles.LoopKickToggle then
                    Toggles.LoopKickToggle:SetValue(false)
                end

                if blobRoot and blobRoot.Parent then
                    blobRoot.CFrame = SavedPos
                    blobRoot.AssemblyLinearVelocity = Vector3.zero
                    blobRoot.AssemblyAngularVelocity = Vector3.zero
                end
            end)
        end
    })
--=======================================================================
-- Blob Kick : v2
--=======================================================================
BlobGroupbox:AddCheckbox("DualHandLoopKick", {
        Text = "Blob Kick [V2]",
        Default = false,
        Callback = function(on)
            loopKickDualActive = on

            if not on then
                if activeBp then
                    pcall(function() activeBp:Destroy() end)
                    activeBp = nil
                end
                return
            end

            local targetCheck = selectedKickPlayer
            if not targetCheck or not targetCheck.Parent then
                if Toggles and Toggles.DualHandLoopKick then
                    Toggles.DualHandLoopKick:SetValue(false)
                end
                loopKickDualActive = false
                return
            end

            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChild("Humanoid")
            local seat = hum and hum.SeatPart

            if not seat or not seat.Parent or (seat.Parent.Name ~= "CreatureBlobman" and seat.Parent.Name ~= "AutoSitBlobman") then
                if Toggles and Toggles.DualHandLoopKick then
                    Toggles.DualHandLoopKick:SetValue(false)
                end
                loopKickDualActive = false
                return
            end

            task.spawn(function()
                local lastTargetCharDual = nil

                while loopKickDualActive do
                    local target = selectedKickPlayer
                    local char = LocalPlayer.Character
                    local hum = char and char:FindFirstChild("Humanoid")
                    local seat = hum and hum.SeatPart

                    if not seat or not seat.Parent or (seat.Parent.Name ~= "CreatureBlobman" and seat.Parent.Name ~= "AutoSitBlobman") then
                        loopKickDualActive = false
                        if activeBp then
                            pcall(function() activeBp:Destroy() end)
                            activeBp = nil
                        end
                        break
                    end

                    if not target or not target.Parent then
                        if activeBp then
                            pcall(function() activeBp:Destroy() end)
                            activeBp = nil
                        end
                        lastTargetCharDual = nil
                        task.wait(0.5)
                        continue
                    end

                    local seatParent = seat.Parent
                    local scriptObj = seatParent:FindFirstChild("BlobmanSeatAndOwnerScript")
                    local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                    local drop = scriptObj and scriptObj:FindFirstChild("CreatureDrop")

                    if not grab or not drop then
                        task.wait(0.5)
                        continue
                    end

                    local leftDet = seatParent:FindFirstChild("LeftDetector")
                    local rightDet = seatParent:FindFirstChild("RightDetector")
                    local leftWeld = leftDet and (leftDet:FindFirstChild("LeftWeld") or leftDet:FindFirstChildWhichIsA("Weld"))
                    local rightWeld = rightDet and (rightDet:FindFirstChild("RightWeld") or rightDet:FindFirstChildWhichIsA("Weld"))

                    local hrp = char:FindFirstChild("HumanoidRootPart")
                    local targetChar = target.Character
                    local targetHRP = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                    local targetHum = targetChar and targetChar:FindFirstChild("Humanoid")

                    if not targetChar or not targetHRP or not targetHum or targetHum.Health <= 0 then
                        if activeBp then
                            pcall(function() activeBp:Destroy() end)
                            activeBp = nil
                        end
                        lastTargetCharDual = nil
                        task.wait(0.5)
                        continue
                    end

                    if targetChar ~= lastTargetCharDual then
                        lastTargetCharDual = targetChar
                        
                        if activeBp then
                            pcall(function() activeBp:Destroy() end)
                            activeBp = nil
                        end

                        if hrp then
                            hrp.CFrame = targetHRP.CFrame * CFrame.new(0, 25, 0)
                        end

                        task.wait(0.2)
                        pcall(function() grab:FireServer(leftDet, targetHRP, leftWeld) end)
                        task.wait(0.3)
                        pcall(function() drop:FireServer(leftWeld, targetHRP) end)
                        task.wait(0.1)

                        local newBp = Instance.new("BodyPosition")
                        newBp.Position = Vector3.new(0, 999999, 0)
                        newBp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                        newBp.Parent = targetHRP
                        activeBp = newBp

                        pcall(function() grab:FireServer(leftDet, targetHRP, leftWeld) end)
                        task.wait(0.2)
                        pcall(function() drop:FireServer(leftWeld, targetHRP) end)
                    end

                    pcall(function()
                        grab:FireServer(leftDet, targetHRP, leftWeld)
                        task.wait()
                        drop:FireServer(leftWeld, targetHRP)
                        task.wait()
                        grab:FireServer(rightDet, targetHRP, rightWeld)
                        task.wait()
                        drop:FireServer(rightWeld, targetHRP)
                        task.wait()
                        grab:FireServer(leftDet, targetHRP, leftWeld)
                        grab:FireServer(rightDet, targetHRP, rightWeld)
                        task.wait()
                        drop:FireServer(leftWeld, targetHRP)
                        drop:FireServer(rightWeld, targetHRP)
                    end)
                    
                    task.wait()
                end

                loopKickDualActive = false
                if Toggles and Toggles.DualHandLoopKick then
                    Toggles.DualHandLoopKick:SetValue(false)
                end

                if activeBp then
                    pcall(function() activeBp:Destroy() end)
                    activeBp = nil
                end
            end)
        end
    })
--=======================================================================
-- Fly
--=======================================================================
do
	local Flying = false
	local FlyConn = nil
	local charConnection = nil
	local currentBG = nil
	local currentBV = nil

	local function StopFly()
		if FlyConn then
			FlyConn:Disconnect()
			FlyConn = nil
		end
		if currentBG then
			pcall(function() currentBG:Destroy() end)
			currentBG = nil
		end
		if currentBV then
			pcall(function() currentBV:Destroy() end)
			currentBV = nil
		end
	end

	local function StartFly()
		StopFly() 

		local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
		local hrp = char:WaitForChild("HumanoidRootPart", 5)
		if not hrp then return end

		local cam = Workspace.CurrentCamera

		local bg = Instance.new("BodyGyro")
		bg.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
		bg.P = 9e4
		bg.D = 2000 
		bg.CFrame = hrp.CFrame
		bg.Parent = hrp
		currentBG = bg

		local bv = Instance.new("BodyVelocity")
		bv.MaxForce = Vector3.new(9e9, 9e9, 9e9)
		bv.Velocity = Vector3.zero
		bv.Parent = hrp
		currentBV = bv

		local speed = 300
		local currentVelocity = Vector3.zero
		local smoothing = 0.7 

		FlyConn = RunService.Stepped:Connect(function(_, deltaTime)
			if not Flying or not hrp or not hrp.Parent then
				StopFly()
				return
			end

			local move = Vector3.zero
			if UserInputService:IsKeyDown(Enum.KeyCode.W) then move += cam.CFrame.LookVector end
			if UserInputService:IsKeyDown(Enum.KeyCode.S) then move -= cam.CFrame.LookVector end
			if UserInputService:IsKeyDown(Enum.KeyCode.A) then move -= cam.CFrame.RightVector end
			if UserInputService:IsKeyDown(Enum.KeyCode.D) then move += cam.CFrame.RightVector end
			if UserInputService:IsKeyDown(Enum.KeyCode.Space) then move += cam.CFrame.UpVector end
			if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then move -= cam.CFrame.UpVector end

			if move.Magnitude > 0 then
				move = move.Unit * speed
			end

			local lerpAlpha = math.min(1, smoothing * deltaTime * 60)
			currentVelocity = currentVelocity:Lerp(move, lerpAlpha)
			
			if move.Magnitude == 0 and currentVelocity.Magnitude < 2 then
				currentVelocity = Vector3.zero
			end
			
			if bv and bv.Parent then
				bv.Velocity = currentVelocity
			end

			if bg and bg.Parent then

				bg.CFrame = CFrame.new(hrp.Position, hrp.Position + cam.CFrame.LookVector)
			end
		end)
	end

	local function setupRespawnHandler()
		if charConnection then charConnection:Disconnect() end

		charConnection = LocalPlayer.CharacterAdded:Connect(function()
			task.wait(0.3) 
			if Flying then
				StartFly()
			end
		end)
	end

	local function setFlyState(state)
		Flying = state
		if Flying then
			StartFly()
			setupRespawnHandler()
		else
			StopFly()
			if charConnection then
				charConnection:Disconnect()
				charConnection = nil
			end
		end
	end

	local FlyToggle = BlobMethodGroupbox:AddCheckbox("FlyToggle", {
		Text = "Fly",
		Default = false,
		Callback = function(Value)
			setFlyState(Value)
		end,
	})

	FlyToggle:AddKeyPicker("FlyKeybind", {
		Text = "Fly Keybind",
		Default = "T",
		Mode = "Toggle",
		Callback = function(Value)
			setFlyState(Value)

			task.defer(function()
				if FlyToggle and FlyToggle.SetValue then
					FlyToggle:SetValue(Value)
				end
			end)
		end,
	})
end
--=======================================================================
-- Click Teleport
--=======================================================================
do
    local TeleportToggle = BlobMethodGroupbox:AddCheckbox("ClickTeleport", {
        Text = "Click Teleport",
        Default = true, 
    })

    local TeleportKeybind = TeleportToggle:AddKeyPicker("ClickTeleportKey", {
        Text = "Click Teleport Key",
        Default = "X",
        Mode = "Toggle", 
        SyncToggleState = false, 
    })

    local OFFSET = Vector3.new(0, 3, 0)

    local activeConnection = nil
    local activeState = nil 

    local function restoreState()
        if not activeState then return end
        local s = activeState
        activeState = nil

        if s.hrp and s.hrp.Parent then
            s.hrp.Anchored = s.oldAnchored
            s.hrp.AssemblyLinearVelocity = s.oldVelocity
            s.hrp.CanCollide = s.oldCanCollide
        end
        if s.humanoid and s.humanoid.Parent then
            s.humanoid.AutoRotate = s.oldAutoRotate
        end
    end

    local function stopTeleport()
        if activeConnection then
            activeConnection:Disconnect()
            activeConnection = nil
        end
        restoreState()
    end

    local function quadOut(t)
        return 1 - (1 - t) * (1 - t)
    end

    UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed then return end

        if Toggles.ClickTeleport.Value and input.KeyCode == Enum.KeyCode[Options.ClickTeleportKey.Value] then
            local char = LocalPlayer.Character
            if not char then return end
            
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end

            local humanoid = char:FindFirstChildOfClass("Humanoid")
            if not humanoid then return end

            local mousePos = UserInputService:GetMouseLocation()
            local ray = Camera:ViewportPointToRay(mousePos.X, mousePos.Y)
            
            local rayParams = RaycastParams.new()
            rayParams.FilterDescendantsInstances = {char}
            rayParams.FilterType = Enum.RaycastFilterType.Exclude

            local result = Workspace:Raycast(ray.Origin, ray.Direction * 10000, rayParams)
            if result then 
                stopTeleport()

                local targetPosition = result.Position + result.Normal * 3

                local lookDir = targetPosition - hrp.Position
                lookDir = Vector3.new(lookDir.X, 0, lookDir.Z)

                local targetCFrame
                if lookDir.Magnitude > 0.001 then
                    targetCFrame = CFrame.lookAt(targetPosition, targetPosition + lookDir.Unit)
                else
                    targetCFrame = CFrame.new(targetPosition) * (hrp.CFrame - hrp.CFrame.Position)
                end

                local startCFrame = hrp.CFrame
                local startPos = startCFrame.Position
                local endPos = targetCFrame.Position

                local distance = (startPos - endPos).Magnitude
                local duration = math.clamp(distance / 400, 0.10, 0.32)

                activeState = {
                    hrp = hrp,
                    humanoid = humanoid,
                    oldAnchored = hrp.Anchored,
                    oldAutoRotate = humanoid.AutoRotate,
                    oldVelocity = hrp.AssemblyLinearVelocity,
                    oldCanCollide = hrp.CanCollide,
                }

                humanoid.AutoRotate = false
                hrp.Anchored = false         
                hrp.CanCollide = false       
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero

                local elapsed = 0
                local myState = activeState

                activeConnection = RunService.Heartbeat:Connect(function(dt)
                    if activeState ~= myState then
                        if activeConnection then
                            activeConnection:Disconnect()
                            activeConnection = nil
                        end
                        return
                    end

                    if not hrp or not hrp.Parent then
                        stopTeleport()
                        return
                    end

                    elapsed += dt
                    local alpha = math.clamp(elapsed / duration, 0, 1)
                    local eased = quadOut(alpha)

                    local newPos = startPos:Lerp(endPos, eased)
                    hrp.CFrame = CFrame.lookAt(newPos, newPos + targetCFrame.LookVector)

                    if alpha >= 1 then
                        hrp.CFrame = targetCFrame

                        if activeConnection then
                            activeConnection:Disconnect()
                            activeConnection = nil
                        end
                        restoreState()
                    end
                end)
            end
        end
    end)
end
--=======================================================================
-- Auto Sit Blob
--=======================================================================
do
    local autoSitThread = nil
    local currentBlobman = nil

    local function ClearBlobman()
        local plr = Players.LocalPlayer
        local inv = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
        if inv then
            for _, v in pairs(inv:GetChildren()) do
                if v.Name == "CreatureBlobman" or v.Name == "AutoSitBlobman" or v.Name == "blob" then
                    pcall(function()
                        if DestroyRemote then
                            DestroyRemote:FireServer(v)
                        else
                            v:Destroy()
                        end
                    end)
                end
            end
        end
        currentBlobman = nil
    end

    local function getHRP(plr)
        if plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
            return plr.Character.HumanoidRootPart
        else
            local character = plr.CharacterAdded:Wait()
            return character:WaitForChild("HumanoidRootPart")
        end
    end

    local function CheckForHome(plr)
        if not Workspace.PlotItems or not Workspace.PlotItems.PlayersInPlots:FindFirstChild(plr.Name) then
            return false
        end
        for _, v in pairs(Workspace.Plots:GetChildren()) do
            local sign = v:FindFirstChild("PlotSign")
            local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
            if owners then
                for _, b in pairs(owners:GetChildren()) do
                    if b.Value == plr.Name then
                        local folder = Workspace.PlotItems:FindFirstChild(v.Name)
                        if folder then
                            return true, folder
                        end
                    end
                end
            end
        end
        return false
    end

    local function WaitForCanSpawn()
        if not CanSpawn then
            return true
        end
        
        local t = tick()
        while not CanSpawn.Value do
            if not _G.AutoSitBlob or tick() - t > 5 then
                return false
            end
            task.wait(0.1)
        end
        return true
    end

    local function SpawnBlobman()
        local plr = Players.LocalPlayer
        local currentHRP = getHRP(plr)
        if not currentHRP then
            return nil
        end

        if not WaitForCanSpawn() then
            return nil
        end

        if CanSpawnToy then
            pcall(function()
                CanSpawnToy:InvokeServer("CreatureBlobman")
            end)
        end

        task.wait(0.01)

        if SpawnRemote then
            task.spawn(function()
                pcall(function()
                    SpawnRemote:InvokeServer("CreatureBlobman", currentHRP.CFrame * CFrame.new(0, 5, 5), Vector3.zero)
                end)
            end)
        end

        local boolik, house = CheckForHome(plr)
        local inv = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
        local blob = nil
        
        if boolik and house then
            blob = house:WaitForChild("CreatureBlobman", 3)
        elseif not Workspace.PlotItems.PlayersInPlots:FindFirstChild(plr.Name) and inv then
            blob = inv:WaitForChild("CreatureBlobman", 3)
        end

        if blob then
            blob.Name = "AutoSitBlobman"
            currentBlobman = blob
        end

        return blob
    end

    local function SetupBlobman(blob, character, humanoid, rootPart)
        if not blob or not character or not humanoid or not rootPart then
            return false
        end

        blob.Name = "AutoSitBlobman"
        currentBlobman = blob

        local seat = blob:FindFirstChildWhichIsA("VehicleSeat")
        if not seat then
            seat = blob:WaitForChild("VehicleSeat", 3)
        end

        if not seat or not seat:IsA("VehicleSeat") then
            return false
        end

        if humanoid.SeatPart == seat then
            return true
        end

        for attempt = 1, 5 do
            if humanoid.SeatPart == seat then
                return true
            end

            rootPart.CFrame = seat.CFrame * CFrame.new(0, 2, 0)
            rootPart.Velocity = Vector3.zero
            rootPart.RotVelocity = Vector3.zero
            task.wait(0.05)

            pcall(function()
                seat:Sit(humanoid)
            end)

            task.wait(0.05)

            if humanoid.SeatPart == seat then
                return true
            end
        end

        return false
    end

    local function startAutoSit()
        if autoSitThread then
            task.cancel(autoSitThread)
            autoSitThread = nil
        end

        autoSitThread = task.spawn(function()
            local plr = Players.LocalPlayer
            local unseatedAt = tick() - 1
            
            while _G.AutoSitBlob do
                task.wait(0.05)

                if not plr.Character or not plr.Character:FindFirstChild("Humanoid") or plr.Character.Humanoid.Health <= 0 then
                    unseatedAt = nil
                    continue
                end

                local character = plr.Character
                local humanoid = character:FindFirstChild("Humanoid")
                local rootPart = character:FindFirstChild("HumanoidRootPart")
                
                if not humanoid or not rootPart then
                    unseatedAt = nil
                    continue
                end

                if kickLoopEnabled then
                    unseatedAt = nil
                    continue
                end

                if humanoid.SeatPart then
                    unseatedAt = nil
                    continue
                end

                if not unseatedAt then
                    unseatedAt = tick()
                end

                if tick() - unseatedAt < 1 then
                    continue
                end

                unseatedAt = nil

                local inv = Workspace:FindFirstChild(plr.Name .. "SpawnedInToys")
                local blob = inv and (inv:FindFirstChild("AutoSitBlobman") or inv:FindFirstChild("CreatureBlobman") or inv:FindFirstChild("blob"))
                
                if not blob then
                    local boolik, house = CheckForHome(plr)
                    if boolik and house then
                        blob = house:FindFirstChild("AutoSitBlobman") or house:FindFirstChild("CreatureBlobman") or house:FindFirstChild("blob")
                    end
                end

                if not blob then
                    blob = SpawnBlobman()
                    if not blob then
                        continue
                    end
                end

                SetupBlobman(blob, character, humanoid, rootPart)
            end

            if not _G.AutoSitBlob then
                ClearBlobman()
            end
        end)
    end

    local function stopAutoSit()
        _G.AutoSitBlob = false
        
        if autoSitThread then
            task.cancel(autoSitThread)
            autoSitThread = nil
        end

        if not kickLoopEnabled then
            ClearBlobman()
        end
    end

    local AutoSitBlobToggle = BlobMethodGroupbox:AddCheckbox("AutoSitBlob", {
        Text = "Loop Seat on Blobman",
        Default = false,
    })

    AutoSitBlobToggle:OnChanged(function(Value)
        _G.AutoSitBlob = Value
        
        if Value then
            startAutoSit()
        else
            stopAutoSit()
        end
    end)

    LocalPlayer.CharacterAdded:Connect(function()
        if _G.AutoSitBlob then
            if autoSitThread then
                task.cancel(autoSitThread)
                autoSitThread = nil
            end
            
            if not kickLoopEnabled then
                ClearBlobman()
            end
            
            task.wait(0.5)
            startAutoSit()
        end
    end)
end

end
--=======================================================================
-- Freeze on Blobman
--=======================================================================
do
    local mainThread = nil
    local freezeHeartbeat = nil
    local frozenRoot = nil
    local frozenSeat = nil
    local lockedCFrame = nil
    local teleporting = false     

    local function Unfreeze()
        if freezeHeartbeat then
            task.cancel(freezeHeartbeat)
            freezeHeartbeat = nil
        end
        if frozenRoot and frozenRoot.Parent then
            pcall(function()
                frozenRoot.Anchored = false
            end)
        end
        frozenRoot = nil
        frozenSeat = nil
        lockedCFrame = nil
        teleporting = false
    end

    local function StartFreeze(rootPart)
        if freezeHeartbeat then
            task.cancel(freezeHeartbeat)
        end

        frozenRoot = rootPart
        lockedCFrame = rootPart.CFrame

        pcall(function()
            rootPart.Velocity = Vector3.zero
            rootPart.RotVelocity = Vector3.zero
            rootPart.AssemblyLinearVelocity = Vector3.zero
            rootPart.AssemblyAngularVelocity = Vector3.zero
            rootPart.Anchored = true
        end)

        freezeHeartbeat = task.spawn(function()
            while _G.FreezeBlobman and frozenRoot == rootPart and rootPart.Parent do
                pcall(function()
                    local dist = (rootPart.CFrame.Position - lockedCFrame.Position).Magnitude

                    if dist > 3 and not teleporting then
                        teleporting = true

                        rootPart.Anchored = false
                        rootPart.Velocity = Vector3.zero
                        rootPart.RotVelocity = Vector3.zero

                        task.wait(0.3)

                        lockedCFrame = rootPart.CFrame

                        rootPart.Velocity = Vector3.zero
                        rootPart.RotVelocity = Vector3.zero
                        rootPart.AssemblyLinearVelocity = Vector3.zero
                        rootPart.AssemblyAngularVelocity = Vector3.zero
                        rootPart.Anchored = true

                        teleporting = false
                    else
                        if not teleporting then
                            if not rootPart.Anchored then
                                rootPart.Anchored = true
                            end
                            rootPart.Velocity = Vector3.zero
                            rootPart.RotVelocity = Vector3.zero
                            rootPart.AssemblyLinearVelocity = Vector3.zero
                            rootPart.AssemblyAngularVelocity = Vector3.zero
                        end
                    end
                end)
                task.wait(0.05)
            end
        end)
    end

    local function startFreeze()
        if mainThread then
            task.cancel(mainThread)
            mainThread = nil
        end

        local plr = Players.LocalPlayer

        mainThread = task.spawn(function()
            while _G.FreezeBlobman do
                task.wait(0.1)

                local character = plr.Character
                if not character then
                    if frozenRoot then Unfreeze() end
                    continue
                end

                local humanoid = character:FindFirstChild("Humanoid")
                local rootPart = character:FindFirstChild("HumanoidRootPart")

                if not humanoid or not rootPart or humanoid.Health <= 0 then
                    if frozenRoot then Unfreeze() end
                    continue
                end

                local seat = humanoid.SeatPart

                if seat then
                    if frozenRoot ~= rootPart then
                        frozenSeat = seat
                        StartFreeze(rootPart)
                    end
                else
                    if frozenRoot then
                        Unfreeze()
                    end
                end
            end

            Unfreeze()
        end)
    end

    local function stopFreeze()
        _G.FreezeBlobman = false

        if mainThread then
            task.cancel(mainThread)
            mainThread = nil
        end

        Unfreeze()
    end

    local FreezeBlobmanToggle = BlobMethodGroupbox:AddCheckbox("FreezeBlobman", {
        Text = "Freeze on Blobman",
        Default = false,
    })

    FreezeBlobmanToggle:OnChanged(function(Value)
        _G.FreezeBlobman = Value

        if Value then
            startFreeze()
        else
            stopFreeze()
        end
    end)

    LocalPlayer.CharacterAdded:Connect(function()
        Unfreeze()
        if _G.FreezeBlobman then
            task.wait(0.5)
            startFreeze()
        end
    end)
end
--=======================================================================
-- Set Owner All Kick
--=======================================================================
do
    lineLagThread = nil
    lineLagEnabled = false

    function getAllPlayers()
        local players = {}
        for _, plr in pairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer then
                table.insert(players, plr)
            end
        end
        return players
    end

    function spamOwnership(hrp)
        if not GrabEvents then return end
        local setOwner = GrabEvents:FindFirstChild("SetNetworkOwner")
        if setOwner and hrp then pcall(function() setOwner:FireServer(hrp, hrp.CFrame) end) end
    end

    function teleportToPlayer(myHrp, targetHrp)
        if not myHrp or not targetHrp then return end
        pcall(function()
            myHrp.CFrame = targetHrp.CFrame * CFrame.new(0, 5, 5)
            myHrp.AssemblyLinearVelocity = Vector3.zero
        end)
    end

    function destroyLineOnPlayer(hrp)
        if not GrabEvents then return end
        local createLine = GrabEvents:FindFirstChild("CreateGrabLine")
        local destroyLine = GrabEvents:FindFirstChild("DestroyGrabLine")
        if not createLine or not destroyLine then return end
        pcall(function()
            createLine:FireServer(hrp, CFrame.new(0, 1e9, 0))
            task.wait()
            destroyLine:FireServer(hrp)
        end)
    end

    function startLineLag()
        if lineLagEnabled then return end
        lineLagEnabled = true
        lineLagThread = coroutine.create(function()
            if not GrabEvents then return end
            local createLine = GrabEvents:FindFirstChild("CreateGrabLine")
            if not createLine then return end
            while lineLagEnabled do
                local spawnLocation = Workspace:FindFirstChild("SpawnLocation")
                    or Workspace:FindFirstChild("Spawn")
                    or (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart"))
                if spawnLocation then
                    local randomX = math.random(-9e9, 9e9)
                    local randomZ = math.random(-9e9, 9e9)
                    local directions = {
                        CFrame.new(randomX,  0, randomZ),
                        CFrame.new(-randomX, 0, -randomZ),
                        CFrame.new(randomX,  0, -randomZ),
                        CFrame.new(-randomX, 0, randomZ),
                    }
                    for _, pos in pairs(directions) do
                        pcall(function() createLine:FireServer(spawnLocation, pos) end)
                    end
                end
                task.wait()
            end
        end)
        coroutine.resume(lineLagThread)
    end

    function stopLineLag()
        if not lineLagEnabled then return end
        lineLagEnabled = false
        if lineLagThread then coroutine.close(lineLagThread) lineLagThread = nil end
    end

    ServerAllGroupbox:AddButton({
        Text = "Set Owner All Kick",
        Func = function()
            task.spawn(function()
                local height = 35
                startLineLag()
                task.wait(1)
                local players = getAllPlayers()
                if #players == 0 then
                    stopLineLag()
                    return
                end
                local myChar = LocalPlayer.Character
                local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if not myHrp then
                    stopLineLag()
                    return
                end
                local playerData = {}
                for _, plr in ipairs(players) do
                    local char = plr.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    if hrp then table.insert(playerData, {player = plr, hrp = hrp}) end
                end
                for _, data in ipairs(playerData) do
                    teleportToPlayer(myHrp, data.hrp)
                    task.wait(0.2)
                    spamOwnership(data.hrp)
                    task.wait()
                end
                local radius = 40
                local angleStep = (math.pi * 2) / #playerData
                for idx, data in ipairs(playerData) do
                    local angle = (idx - 1) * angleStep
                    local x = math.cos(angle) * radius
                    local z = math.sin(angle) * radius
                    pcall(function()
                        data.hrp.CFrame = CFrame.new(x, height, z)
                        data.hrp.AssemblyLinearVelocity = Vector3.zero
                        data.hrp.Velocity = Vector3.zero
                    end)
                    local bp = Instance.new("BodyPosition")
                    bp.MaxForce = Vector3.new(9e9, 9e9, 9e9)
                    bp.P = 50000000
                    bp.Position = Vector3.new(x, height, z)
                    bp.Parent = data.hrp
                    task.delay(2, function() pcall(function() bp:Destroy() end) end)
                    task.wait()
                end
                for i = 1, 8 do
                    for _, data in ipairs(playerData) do
                        destroyLineOnPlayer(data.hrp)
                    end
                    task.wait(0.3)
                end
                stopLineLag()
            end)
        end
    })
end
--=======================================================================
-- Blob All Kick
--=======================================================================
do
    local function stvel(hrp)
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end

    local function sno(obj)
        SetNetworkOwner:FireServer(obj, obj.CFrame)
    end

    ServerAllGroupbox:AddButton("Blob All Kick", function()
            
        for _, targetPlayer in Players:GetPlayers() do
            local hum = targetPlayer.Character and targetPlayer.Character:FindFirstChild("Humanoid")
            local HRP = targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart")
            
            if not hum or not HRP then continue end
            
            local blob = hum and hum.SeatPart and hum.SeatPart.Parent and hum.SeatPart.Parent:FindFirstChild("BlobmanSeatAndOwnerScript") and hum.SeatPart.Parent
            if not blob then continue end
            blob.Name = "blob"
            
            local CD = blob.BlobmanSeatAndOwnerScript.CreatureDrop
            local CR = blob.BlobmanSeatAndOwnerScript.CreatureRelease
            local CG = blob.BlobmanSeatAndOwnerScript.CreatureGrab
            
            local pos = blob.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0)

            local validPlayers = {}
            for _, v in Players:GetPlayers() do
                if v ~= targetPlayer and v.Character and v.Character:FindFirstChild("HumanoidRootPart") then
                    table.insert(validPlayers, v)
                end
            end

            for i, v in validPlayers do
                pcall(function()
                    blob.HumanoidRootPart.CFrame = v.Character.HumanoidRootPart.CFrame
                    task.wait(0.18)
                    CG:FireServer(nil, v.Character.HumanoidRootPart, blob.RightDetector.RightWeld)
                    CR:FireServer(blob.RightDetector.RightWeld)
                end)
                task.wait(0.08)
            end
            
            blob.HumanoidRootPart.CFrame = pos
            task.wait(0.08)
            
            blob.HumanoidRootPart.Anchored = true
            
            local playerCount = #validPlayers
            local angleStep = 360 / playerCount
            local radius = math.max(5, playerCount * 1.5) 
            
            for i, v in validPlayers do
                pcall(function()
                    if v.Character and v.Character:FindFirstChild("HumanoidRootPart") and isnetworkowner(v.Character.HumanoidRootPart) then
                        local bg = Instance.new("BodyGyro", v.Character.HumanoidRootPart)
                        bg.CFrame = CFrame.new(0, 0, 0)
                        stvel(blob.HumanoidRootPart)
                        stvel(v.Character.HumanoidRootPart)

                        local angle = math.rad(angleStep * (i - 1))
                        local x = math.cos(angle) * radius
                        local z = math.sin(angle) * radius
                        
                        v.Character.HumanoidRootPart.CFrame = CFrame.new(HRP.Position + Vector3.new(x, 0, z))
                        stvel(blob.HumanoidRootPart)
                        task.wait(0.18)
                        sno(v.Character.HumanoidRootPart)
                        DestroyGrabLine:FireServer(v.Character.HumanoidRootPart)
                        task.wait()
                        CG:FireServer(nil, v.Character.HumanoidRootPart, blob.RightDetector.RightWeld)
                    end
                end)
                task.wait(0.08)
            end
            
            task.wait(0.08)
            blob.HumanoidRootPart.Anchored = false
        end
    end)
end
--=======================================================================
-- Loop Kick All
--=======================================================================
do
    local KickHB = nil
    local LoopKickOn = false
    local KickQueue = {}
    local CurrentKickIndex = 1
    local LastKickTime = 0
    local KickInterval = 0.2  

    local function isTooHigh(plr)
        local c = plr.Character
        local hrp = c and c:FindFirstChild("HumanoidRootPart")
        return not hrp or hrp.Position.Y > 100000
    end

    local function DisableCollisions(char)
        for _, v in ipairs(char:GetDescendants()) do
            if v:IsA("BasePart") then
                v.CanCollide = false
            end
        end
    end

    local function sendToSky(root, hum)
        DisableCollisions(hum.Parent)
        local BV = Instance.new("BodyVelocity")
        BV.Velocity = Vector3.new(0, 1e9, 0)      
        BV.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        BV.P = 1e8
        BV.Parent = root
        hum.Sit = false
        hum.Jump = true
        task.delay(3, function() if BV.Parent then BV:Destroy() end end)
    end

    local function executeKick(targetPlayer)
        if not targetPlayer then return false end
        local p = Players:FindFirstChild(targetPlayer.Name)
        local c = p and p.Character
        local root = c and c:FindFirstChild("HumanoidRootPart")
        local head = c and c:FindFirstChild("Head")
        local hum  = c and c:FindFirstChild("Humanoid")

        if not (root and head and hum) or hum.Health <= 0 then return false end
        if isTooHigh(p) then return false end
        if p:FindFirstChild("InPlot") and p.InPlot.Value then return false end

        local selfChar = LocalPlayer.Character
        local selfRoot = selfChar and selfChar:FindFirstChild("HumanoidRootPart")
        if not selfRoot then return false end

        local saved = selfChar:GetPivot()
        selfChar:PivotTo(CFrame.new(root.Position + Vector3.new(0, 0, -3)))  

        DisableCollisions(c)
        if SetNetworkOwner then
            SetNetworkOwner:FireServer(root, root.CFrame)
        end
        task.wait(0.15)  
        selfChar:PivotTo(saved)                    
        task.wait(0.1)
        if DestroyGrabLine then
            DestroyGrabLine:FireServer(root)
        end
        task.wait(0.15)  

        local po = head:FindFirstChild("PartOwner")
        if po and po.Value == LocalPlayer.Name then
            sendToSky(root, hum)  
            return true                    
        end
        return false
    end

    local function updateKickQueue()
        KickQueue = {}
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                table.insert(KickQueue, player)
            end
        end
        CurrentKickIndex = 1
    end

    local function StartLoopKick()
        if KickHB then KickHB:Disconnect() end
        LoopKickOn = true
        updateKickQueue() 
        
        KickHB = RunService.Heartbeat:Connect(function()
            if not LoopKickOn then return end
            
            local currentTime = tick()
            
            if currentTime - LastKickTime >= KickInterval then
                if #KickQueue > 0 then
                    local targetPlayer = KickQueue[CurrentKickIndex]
                    if targetPlayer then
                        local success = executeKick(targetPlayer)
                        LastKickTime = currentTime
                        
                        CurrentKickIndex = CurrentKickIndex + 1
                        if CurrentKickIndex > #KickQueue then
                            CurrentKickIndex = 1 
                        end
                    end
                else
                    updateKickQueue() 
                end
            end
            
            if currentTime - LastKickTime > 3 then
                updateKickQueue()
            end
        end)
    end

    local function StopLoopKick()
        LoopKickOn = false
        if KickHB then KickHB:Disconnect() KickHB = nil end
        KickQueue = {}
        CurrentKickIndex = 1
        LastKickTime = 0
    end

    ServerAllGroupbox:AddCheckbox("LoopKickAllToggle", {
        Text = "Loop Kick All",
        Default = false,
        Callback = function(v)
            if v then StartLoopKick() else StopLoopKick() end
        end
    })
end
--=======================================================================
-- Loop Kill All
--=======================================================================
do
    local KillHB = nil
    local HEIGHT_LIMIT = 100000
    local TELEPORT_OFFSET = Vector3.new(6, -18.5, 0)
    local KILL_COOLDOWN = 0.1 
    local lastKillTime = 0

    local function isTooHigh(plr)
        local c = plr.Character
        local hrp = c and c:FindFirstChild("HumanoidRootPart")
        return not hrp or hrp.Position.Y > HEIGHT_LIMIT
    end

    local function setNoCollideChar(char)
        for _, v in ipairs(char:GetDescendants()) do
            if v:IsA("BasePart") then v.CanCollide = false end
        end
    end

    local function saveOriginalPosAttr()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hrp then
            char:SetAttribute("OriginalPosition", hrp:GetPivot())
        end
    end

    local function getOriginalPosAttr()
        local char = LocalPlayer.Character
        return char and char:GetAttribute("OriginalPosition") or nil
    end

    local CameraAnchor = {}
    CameraAnchor.__index = CameraAnchor
    
    function CameraAnchor.new() 
        return setmetatable({}, CameraAnchor) 
    end
    
    function CameraAnchor:attach(cf)
        self:detach()
        local p = Instance.new("Part")
        p.Name = "CameraAnchor"
        p.Size = Vector3.new(0.2, 0.2, 0.2)
        p.Transparency = 1
        p.Anchored = true
        p.CanCollide = false
        p.CFrame = cf
        p.Parent = Workspace
        self.part = p
        
        local cam = Workspace.CurrentCamera
        cam.CameraType = Enum.CameraType.Custom
        cam.CameraSubject = p
    end
    
    function CameraAnchor:detach()
        if self.part then 
            self.part:Destroy() 
            self.part = nil 
        end
        
        local cam = Workspace.CurrentCamera
        local char = LocalPlayer.Character
        if char and char:FindFirstChild("Humanoid") then
            cam.CameraSubject = char.Humanoid
            cam.CameraType = Enum.CameraType.Custom
        end
    end
    
    local cameraAnchor = CameraAnchor.new()

    local function modifyTarget(root, hum)
        if not (root and hum) or hum.Health <= 0 then return end
        
        hum.Sit = false
        hum:ChangeState(Enum.HumanoidStateType.Running)
        hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
        hum:ChangeState(Enum.HumanoidStateType.GettingUp)

        local plr = Players:GetPlayerFromCharacter(hum.Parent)
        if plr and plr:FindFirstChild("IsHeld") then plr.IsHeld.Value = false end
        local rag = hum:FindFirstChild("Ragdolled")
        if rag then rag.Value = false end

        local bv, bav = Instance.new("BodyVelocity"), Instance.new("BodyAngularVelocity")
        bv.MaxForce = Vector3.new(1e7, -1e7, 1e7)
        bv.P = 1e6
        bv.Velocity = Vector3.new(math.random(-500, 50), -50, math.random(-50, 50))
        bav.MaxTorque = Vector3.new(-1e7, -1e7, -1e7)
        bav.P = 1e6
        bav.AngularVelocity = Vector3.new(math.random(-500, 300), math.random(-300, 300), math.random(-500, 500))
        bv.Parent, bav.Parent = root, root

        hum.BreakJointsOnDeath = false
        hum:ChangeState(Enum.HumanoidStateType.Dead)
        hum.RigType = Enum.HumanoidRigType.R15

        task.delay(2, function()
            if bv.Parent then bv:Destroy() end
            if bav.Parent then bav:Destroy() end
        end)
    end

    local function performKillAll()
        local currentTime = tick()
        if currentTime - lastKillTime < KILL_COOLDOWN then
            return
        end
        lastKillTime = currentTime

        for _, target in ipairs(Players:GetPlayers()) do
            if target ~= LocalPlayer then
                local tChar = target.Character
                local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                local tHum = tChar and tChar:FindFirstChild("Humanoid")
                local tHead = tChar and tChar:FindFirstChild("Head")

                if not (tRoot and tHum and tHead) then continue end
                if isTooHigh(target) then continue end
                if target:FindFirstChild("InPlot") and target.InPlot.Value then continue end
                if tHum:GetState() == Enum.HumanoidStateType.Dead then continue end

                local char = LocalPlayer.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if not (char and hrp) then continue end

                if not char:GetAttribute("SavingOriginalPos") then
                    saveOriginalPosAttr()
                end
                char:SetAttribute("SavingOriginalPos", true)

                getgenv().originalFallenHeight = Workspace.FallenPartsDestroyHeight
                Workspace.FallenPartsDestroyHeight = 0/0

                local originalPos = getOriginalPosAttr()
                if originalPos then
                    cameraAnchor:attach(originalPos)
                end

                local desiredCFrame = CFrame.new(tRoot.Position + TELEPORT_OFFSET)
                hrp:PivotTo(desiredCFrame)

                setNoCollideChar(tChar)
                SetNetworkOwner:FireServer(tRoot, tRoot.CFrame)
                task.wait(0.05)
                DestroyGrabLine:FireServer(tRoot)
                task.wait(0.05)

                if tHead:FindFirstChild("PartOwner") and tHead.PartOwner.Value == LocalPlayer.Name then
                    task.wait(0.05)
                    modifyTarget(tRoot, tHum)
                end
            end
        end

        task.wait(0.05)
    end

    local function StartLoopKillAll()
        if KillHB then KillHB:Disconnect() end
        KillHB = RunService.Heartbeat:Connect(performKillAll)
    end

    local function StopLoopKillAll()
        if KillHB then
            KillHB:Disconnect()
            KillHB = nil
        end
        
        local originalPos = getOriginalPosAttr()
        if originalPos then
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then
                hrp:PivotTo(originalPos)
                if getgenv().originalFallenHeight then
                    Workspace.FallenPartsDestroyHeight = getgenv().originalFallenHeight
                end
                char:SetAttribute("SavingOriginalPos", false)
            end
        end
        
        cameraAnchor:detach()
        
        task.wait(0.1)
        if char and char:FindFirstChild("HumanoidRootPart") and originalPos then
            char.HumanoidRootPart:PivotTo(originalPos)
        end
    end

    ServerAllGroupbox:AddCheckbox("LoopKillAll", {
        Text = "Loop Kill All",
        Default = false,
        Callback = function(value)
            if value then
                StartLoopKillAll()
            else
                StopLoopKillAll()
            end
        end
    })
end
--=======================================================================
-- Blob All Kill
--=======================================================================
do
    local function stvel(hrp)
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end

    ServerAllGroupbox:AddCheckbox("Loop Kill", {
        Text = "Blob All Kill",
        Default = false,
        Callback = function(v)
            local applymethod = v

            if v then
                local char = LocalPlayer.Character
                local hum = char and char:FindFirstChild("Humanoid")
                local seat = hum and hum.SeatPart

                if not seat or not seat.Parent or (seat.Parent.Name ~= "CreatureBlobman" and seat.Parent.Name ~= "AutoSitBlobman") then
                    applymethod = false
                    task.defer(function()
                        if Toggles and Toggles["Loop Kill"] then
                            Toggles["Loop Kill"]:SetValue(false)
                        end
                    end)
                    return
                end
            end

            if v then
                killThread = task.spawn(function()
                    while applymethod and task.wait(0.05) do
                        local char = LocalPlayer.Character
                        local hum = char and char:FindFirstChild("Humanoid")
                        local seat = hum and hum.SeatPart

                        if not seat or not seat.Parent or (seat.Parent.Name ~= "CreatureBlobman" and seat.Parent.Name ~= "AutoSitBlobman") then
                            applymethod = false
                            task.defer(function()
                                if Toggles and Toggles["Loop Kill"] then
                                    Toggles["Loop Kill"]:SetValue(false)
                                end
                            end)
                            break
                        end

                        local Blob = seat.Parent

                        if Blob and char and char:FindFirstChild("HumanoidRootPart") then
                            local HRP = char.HumanoidRootPart
                            
                            local CD, CG = Blob.BlobmanSeatAndOwnerScript.CreatureRelease, Blob.BlobmanSeatAndOwnerScript.CreatureGrab
                            
                            for _, tt in ipairs(Players:GetPlayers()) do
                                if tt ~= LocalPlayer and tt.Character and tt.Character:FindFirstChild("HumanoidRootPart") and tt.Character.Humanoid.Health ~= 0 then
                                    local pos = HRP.CFrame
                                    Blob.HumanoidRootPart.CFrame = tt.Character.HumanoidRootPart.CFrame
                                    task.wait(0.1)
                                    repeat task.wait()
                                        CG:FireServer(nil, tt.Character.HumanoidRootPart, Blob.RightDetector.RightWeld)
                                        CD:FireServer(Blob.RightDetector.RightWeld)
                                    until isnetworkowner(tt.Character.HumanoidRootPart)
                                    task.wait()
                                    tt.Character.Humanoid:ChangeState("Dead")
                                    stvel(HRP)
                                    stvel(Blob.HumanoidRootPart)
                                    Blob.HumanoidRootPart.CFrame = pos
                                end
                            end
                        end
                    end

                    applymethod = false
                    task.defer(function()
                        if Toggles and Toggles["Loop Kill"] then
                            Toggles["Loop Kill"]:SetValue(false)
                        end
                    end)
                end)
            else
                applymethod = false
                if killThread then
                    task.cancel(killThread)
                    killThread = nil
                end
            end
        end
    })
end
--=======================================================================
-- Line Lag
--=======================================================================
do
    local connection = nil
    local isActive = false
    local LineLagStrength = 0 

    ServerGroupbox:AddSlider("LineLagStrength", {
        Text = "Strength",
        Default = 0,
        Min = 0,
        Max = 100,        
        Rounding = 0,
        Callback = function(Value)
            LineLagStrength = Value
        end
    })

    ServerGroupbox:AddCheckbox("LineLag", {
        Text = "Line",
        Default = false,
        Callback = function(v)
            isActive = v  
            
            if v then
                if connection then connection:Disconnect() end
                connection = game:GetService("RunService").Heartbeat:Connect(function()
                    if not isActive then return end  
                    if LineLagStrength <= 0 then return end 

                    local repeats = math.clamp(math.ceil(LineLagStrength / 33), 1, 3)
                    for i = 1, repeats do
                        if not isActive or LineLagStrength <= 0 then break end
                        pcall(function()
                            CreateGrabLine:FireServer(Workspace.SpawnLocation, CFrame.new(0, 9e9, 0))
                        end)
                    end

                    task.wait(1) 
                end)
            else
                isActive = false
                if connection then
                    connection:Disconnect()
                    connection = nil
                end

                task.spawn(function()
                    task.wait(0.1) 
                    pcall(function()
                        CreateGrabLine:FireServer(Workspace.SpawnLocation, CFrame.new(0, 0, 0))
                    end)
                end)
            end
        end
    })
end
--=======================================================================
-- Packet Lag
--=======================================================================
do
    local PacketLagEnabled = false
    local packetStrength = 0

    local packetSize = 0.35
    local sendingDelay = 0.1

    ServerGroupbox:AddSlider("PacketStrength", {
        Text = "Strength",
        Default = 0,
        Min = 0,
        Max = 100,
        Rounding = 0,
        Callback = function(v)
            packetStrength = v / 5
        end
    })

    ServerGroupbox:AddCheckbox("PacketLagServer", {
        Text = "Packet",
        Default = false,
        Callback = function(v)
            PacketLagEnabled = v
            if v then
                task.spawn(function()
                    while PacketLagEnabled do
                        if packetStrength <= 0 then
                            task.wait(sendingDelay)
                            continue
                        end

                        local stringCount = math.floor(3000 * (packetSize / 0.35)) * packetStrength
                        local payload = string.rep("Gomojji", stringCount)

                        for i = 1, packetStrength do
                            CreateGrabLine:FireServer(payload)
                        end

                        task.wait(sendingDelay / packetStrength)
                    end
                end)
            end
        end
    })
end
--=======================================================================
-- PCLD View
--=======================================================================
do
    local pcldViewEnabled = false
    local pcldVisuals = {}
    local descendantConnection = nil
    local boxColor = Color3.fromRGB(0, 0, 0) 
    local edgeColor = Color3.fromRGB(255, 255, 255) 
    
    local activeList = {}
    local mainConnection = nil
    local cachedSpeedMultiplier = 1
    
    local cachedEdgeR, cachedEdgeG, cachedEdgeB = edgeColor.R, edgeColor.G, edgeColor.B
    local cachedBoxR, cachedBoxG, cachedBoxB = boxColor.R, boxColor.G, boxColor.B
    local colorsDirty = false
    
    local springSettings = {
        stiffness = 450,      
        damping = 55,         
        mass = 0.65,          
        maxVelocity = 550     
    }
    
    local function createSpring()
        return {
            position = Vector3.new(0, 0, 0),
            velocity = Vector3.new(0, 0, 0),
            rotation = CFrame.new(),
            size = Vector3.new(1, 1, 1),
            sizeVelocity = Vector3.new(0, 0, 0)
        }
    end
    
    local function updateSpring(spring, target, current, velocity, dt, speedMultiplier)
        local stiffness = springSettings.stiffness * speedMultiplier
        local damping = springSettings.damping * (0.5 + speedMultiplier * 0.5)
        local mass = springSettings.mass
        local maxVelocity = springSettings.maxVelocity * speedMultiplier

        local force = (target - current) * stiffness
        local dampingForce = velocity * damping

        local acceleration = (force - dampingForce) / mass

        local newVelocity = velocity + acceleration * dt

        if newVelocity.Magnitude > maxVelocity then
            newVelocity = newVelocity.Unit * maxVelocity
        end

        local newPosition = current + newVelocity * dt
        
        return newPosition, newVelocity
    end
    
    local function getPlayerSpeed()
        local player = Players.LocalPlayer
        if not player then return 1 end
        local character = player.Character
        if not character then return 1 end
        
        local rootPart = character:FindFirstChild("HumanoidRootPart")
        if not rootPart then return 1 end
        
        local speed = rootPart.AssemblyLinearVelocity.Magnitude
        return math.clamp(speed / 16, 0.5, 3)
    end
    
    local visualFolder = nil
    local function getVisualFolder()
        if visualFolder and visualFolder.Parent then return visualFolder end
        visualFolder = workspace:FindFirstChild("PCLDVisuals")
        if not visualFolder then
            visualFolder = Instance.new("Folder")
            visualFolder.Name = "PCLDVisuals"
            visualFolder.Parent = workspace
        end
        return visualFolder
    end
    
    local function createSmoothBox(parent)
        local container = Instance.new("Part")
        container.Name = "SmoothPCLDVisual"
        container.Size = Vector3.new(1, 1, 1)
        container.Transparency = 1
        container.CanCollide = false
        container.Anchored = true
        container.CastShadow = false
        container.Massless = true
        container.CanQuery = false 
        container.CanTouch = false  
        container.Parent = getVisualFolder()

        local boxFrame = Instance.new("SelectionBox")
        boxFrame.Adornee = container
        boxFrame.LineThickness = 0.005  
        boxFrame.Color3 = edgeColor  
        boxFrame.SurfaceColor3 = boxColor  
        boxFrame.SurfaceTransparency = 0.7
        boxFrame.Transparency = 0.2
        boxFrame.Visible = true
        boxFrame.Parent = container

        local targetPart = parent
        local spring = createSpring()
        spring.position = targetPart.Position
        spring.rotation = targetPart.CFrame.Rotation
        spring.size = targetPart.Size

        local data = {
            container = container,
            boxFrame = boxFrame,
            targetPart = targetPart,
            spring = spring,
            pulseTime = 0,
            frameCounter = 0,
        }
        
        table.insert(activeList, data)
        return data
    end
    
    local function startMainLoop()
        if mainConnection then return end
        
        mainConnection = RunService.RenderStepped:Connect(function(deltaTime)
            if not pcldViewEnabled then return end
            local count = #activeList
            if count == 0 then return end
            
            local dt = math.min(deltaTime, 0.05) 
            
            cachedSpeedMultiplier = getPlayerSpeed()
            
            if colorsDirty then
                cachedEdgeR = edgeColor.R
                cachedEdgeG = edgeColor.G
                cachedEdgeB = edgeColor.B
                cachedBoxR = boxColor.R
                cachedBoxG = boxColor.G
                cachedBoxB = boxColor.B
                
                for i = 1, count do
                    local data = activeList[i]
                    if data.boxFrame then
                        data.boxFrame.Color3 = edgeColor
                        data.boxFrame.SurfaceColor3 = boxColor
                    end
                end
                colorsDirty = false
            end
            
            local speedMul = cachedSpeedMultiplier
            
            for i = count, 1, -1 do
                local data = activeList[i]
                local targetPart = data.targetPart
                
                if not targetPart or not targetPart.Parent then
                    if data.container then data.container:Destroy() end
                    pcldVisuals[targetPart] = nil
                    activeList[i] = activeList[#activeList]
                    activeList[#activeList] = nil
                else
                    local spring = data.spring
                    
                    local targetPos = targetPart.Position
                    local newPos, newVel = updateSpring(spring, targetPos, spring.position, spring.velocity, dt, speedMul)
                    spring.position = newPos
                    spring.velocity = newVel
                    
                    local targetRot = targetPart.CFrame.Rotation
                    local rotAlpha = 1 - math.exp(-dt * 18 * speedMul) 
                    spring.rotation = spring.rotation:Lerp(targetRot, math.clamp(rotAlpha, 0, 1))
                    
                    local newSize, newSizeVel = updateSpring(spring, targetPart.Size, spring.size, spring.sizeVelocity, dt, speedMul)
                    spring.size = newSize
                    spring.sizeVelocity = newSizeVel
                    
                    data.container.Size = spring.size
                    data.container.CFrame = CFrame.new(spring.position) * spring.rotation
                    
                    data.frameCounter = data.frameCounter + 1
                    if data.frameCounter >= 2 then
                        data.frameCounter = 0
                        data.pulseTime = data.pulseTime + dt * 4 
                        
                        local pulseSpeed = 1.0 * speedMul
                        local lineBrightness = 0.75 + math.sin(data.pulseTime * pulseSpeed) * 0.08 
                        if lineBrightness > 1 then lineBrightness = 1 end
                        
                        data.boxFrame.Color3 = Color3.new(
                            cachedEdgeR * lineBrightness,
                            cachedEdgeG * lineBrightness,
                            cachedEdgeB * lineBrightness
                        )
                    end
                end
            end
        end)
    end
    
    local function stopMainLoop()
        if mainConnection then
            mainConnection:Disconnect()
            mainConnection = nil
        end
    end
    
    local function updateVisualColors()
        colorsDirty = true
    end
    
    local function createPcldVisual(obj)
        if obj.Name == "PlayerCharacterLocationDetector" and obj:IsA("BasePart") then
            if pcldVisuals[obj] then return end
            
            local visual = createSmoothBox(obj)
            pcldVisuals[obj] = visual
        end
    end
    
    local function clearPcldVisuals()
        for i = 1, #activeList do
            local data = activeList[i]
            if data.container then
                pcall(function() data.container:Destroy() end)
            end
        end
        
        pcldVisuals = {}
        activeList = {}
    end
    
    local function togglePcldView(enable)
        pcldViewEnabled = enable
        
        if descendantConnection then
            descendantConnection:Disconnect()
            descendantConnection = nil
        end
        
        if enable then
            startMainLoop()
            
            local descendants = Workspace:GetDescendants()
            for i = 1, #descendants do
                createPcldVisual(descendants[i])
            end
            
            descendantConnection = Workspace.DescendantAdded:Connect(function(obj)
                if pcldViewEnabled then
                    createPcldVisual(obj)
                end
            end)
        else
            stopMainLoop()
            clearPcldVisuals()
        end
    end

    local PcldViewCheckbox = VisualGroupbox:AddCheckbox("PcldViewToggle", {
        Text = "PCLD View",
        Default = false,
        Callback = function(Value)
            togglePcldView(Value)
        end
    })
    
    local BoxColorPicker = PcldViewCheckbox:AddColorPicker("PcldBoxColorPicker", {
        Default = Color3.fromRGB(0, 0, 0),
        Title = "Fill Color",
        Resizable = true,
        Callback = function(Value)
            boxColor = Value
            updateVisualColors()
        end
    })
    
    local EdgeColorPicker = PcldViewCheckbox:AddColorPicker("PcldEdgeColorPicker", {
        Default = Color3.fromRGB(255, 255, 255),
        Title = "Outline Color",
        Resizable = true,
        Callback = function(Value)
            edgeColor = Value
            updateVisualColors()
        end
    })
end
--=======================================================================
-- Highlight Esp
--=======================================================================
do
	local espEnabled = false
	local espCache = {}
	local fillColor = Color3.fromRGB(0, 0, 0)
	local outlineColor = Color3.fromRGB(255, 255, 255) 

	local function applyHighlight(player, character)
		if not espEnabled or player == LocalPlayer or not character then return end
		if espCache[player] then espCache[player]:Destroy() end

		local highlight = Instance.new("Highlight")
		highlight.FillColor = fillColor
		highlight.OutlineColor = outlineColor
		highlight.FillTransparency = 0.5
		highlight.OutlineTransparency = 0
		highlight.Parent = character
		espCache[player] = highlight
	end

	local function updateHighlightColors()
		for player, highlight in pairs(espCache) do
			if highlight then
				highlight.FillColor = fillColor
				highlight.OutlineColor = outlineColor
			end
		end
	end

	local function trackPlayer(player)
		if player == LocalPlayer then return end

		if player.Character then
			applyHighlight(player, player.Character)
		end

		player.CharacterAdded:Connect(function(character)
			applyHighlight(player, character)
		end)
	end
	
	local HighlightToggle = VisualGroupbox:AddCheckbox("HighlightToggle", {
		Text = "Highlight ESP",
		Default = false,
		Callback = function(value)
			espEnabled = value
			if not value then
				for _, highlight in pairs(espCache) do
					if highlight then highlight:Destroy() end
				end
				espCache = {}
			else
				for _, player in pairs(Players:GetPlayers()) do
					if player.Character then
						applyHighlight(player, player.Character)
					end
				end
			end
		end
	})

	local FillColorPicker = HighlightToggle:AddColorPicker("HighlightFillColor", {
		Default = Color3.fromRGB(0, 0, 0), 
		Title = "Fill Color",
		Resizable = true,
		Callback = function(value)
			fillColor = value
			updateHighlightColors()
		end
	})

	local OutlineColorPicker = HighlightToggle:AddColorPicker("HighlightOutlineColor", {
		Default = Color3.fromRGB(255, 255, 255), 
		Title = "Outline Color",
		Resizable = true,
		Callback = function(value)
			outlineColor = value
			updateHighlightColors()
		end
	})

	for _, player in pairs(Players:GetPlayers()) do
		trackPlayer(player)
	end

	Players.PlayerAdded:Connect(function(player)
		trackPlayer(player)
	end)

	Players.PlayerRemoving:Connect(function(player)
		if espCache[player] then
			espCache[player]:Destroy()
			espCache[player] = nil
		end
	end)
end
--=======================================================================
-- Sticky Esp
--=======================================================================
do
    local cons = cons or {}
    local stickyColor = Color3.fromRGB(255, 255, 255) 

    local function applyEsp(toy)
        if not toy or not toy:FindFirstChild("StickyPart") then return end

        local stickyPart = toy.StickyPart
        local stickyWeld = stickyPart:FindFirstChild("StickyWeld")
        if not stickyWeld then return end

        local existingHighlight = toy:FindFirstChildOfClass("Highlight")
        if existingHighlight then
            existingHighlight:Destroy()
        end

        local highlight = Instance.new("Highlight")
        highlight.Adornee = toy
        highlight.Parent = toy

        local function updateColor()
            highlight.FillColor = stickyColor
        end

        updateColor()

        stickyWeld:GetPropertyChangedSignal("Part1"):Connect(updateColor)
    end

    local function updateAllEsp()
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                local spawnedToys = Workspace:FindFirstChild(player.Name .. "SpawnedInToys")
                if spawnedToys then
                    for _, toy in ipairs(spawnedToys:GetChildren()) do
                        applyEsp(toy)
                    end
                end
            end
        end
    end

    local function updateStickyColors()
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                local spawnedToys = Workspace:FindFirstChild(player.Name .. "SpawnedInToys")
                if spawnedToys then
                    for _, toy in ipairs(spawnedToys:GetChildren()) do
                        local highlight = toy:FindFirstChildOfClass("Highlight")
                        if highlight then
                            highlight.FillColor = stickyColor
                        end
                    end
                end
            end
        end
    end
    
    local StickyCheckbox = VisualGroupbox:AddCheckbox("AntiKickEsp", {
        Text = "Sticky ESP",
        Default = false,
        Callback = function(Value)
            if Value then
                updateAllEsp()
                
                cons["antikickesp_update"] = task.spawn(function()
                    while true do
                        task.wait(0.1) 
                        updateAllEsp()
                    end
                end)
            else
                if cons["antikickesp_update"] then
                    task.cancel(cons["antikickesp_update"])
                    cons["antikickesp_update"] = nil
                end

                for _, player in ipairs(Players:GetPlayers()) do
                    if player ~= LocalPlayer then
                        local spawnedToys = Workspace:FindFirstChild(player.Name .. "SpawnedInToys")
                        if spawnedToys then
                            for _, toy in ipairs(spawnedToys:GetChildren()) do
                                local highlight = toy:FindFirstChildOfClass("Highlight")
                                if highlight then
                                    highlight:Destroy()
                                end
                            end
                        end
                    end
                end
            end
        end
    })
    
    local StickyColorPicker = StickyCheckbox:AddColorPicker("StickyColorPicker", {
        Default = Color3.fromRGB(255, 255, 255),
        Title = "Sticky Color",
        Resizable = true,
        Callback = function(value)
            stickyColor = value
            updateStickyColors()
        end
    })
end
--=======================================================================
-- Name & Profile Esp
--=======================================================================
do
	local nameEspEnabled = false
	local nameEspCache = {}
	local profileEspEnabled = false
	local profileEspCache = {}
	local selectedFont = Enum.Font.SourceSansBold 

	local function applyName(player, character)
		if not nameEspEnabled or player == LocalPlayer or not character then return end

		if nameEspCache[player] then
			nameEspCache[player]:Destroy()
			nameEspCache[player] = nil
		end

		local headPart = character:WaitForChild("Head", 5)
		if not headPart or not nameEspEnabled then return end

		if headPart:FindFirstChild("NameESP") then
			headPart.NameESP:Destroy()
		end

		local billboardGui = Instance.new("BillboardGui")
		billboardGui.Name = "NameESP"
		billboardGui.Size = UDim2.new(0, 200, 0, 40)
		billboardGui.Adornee = headPart
		billboardGui.AlwaysOnTop = true
		billboardGui.StudsOffset = Vector3.new(0, 2, 0)

		local textLabel = Instance.new("TextLabel")
		textLabel.Size = UDim2.new(1, 0, 1, 0)
		textLabel.BackgroundTransparency = 1
		textLabel.Text = player.DisplayName .. " (@" .. player.Name .. ")"
		textLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
		textLabel.TextStrokeTransparency = 0
		textLabel.TextScaled = false
		textLabel.TextSize = 14
		textLabel.Font = selectedFont 
		textLabel.Parent = billboardGui
		billboardGui.Parent = headPart

		nameEspCache[player] = billboardGui
	end

	local function applyProfile(player, character)
		if not profileEspEnabled or player == LocalPlayer or not character then return end

		if profileEspCache[player] then
			profileEspCache[player]:Destroy()
			profileEspCache[player] = nil
		end

		local headPart = character:WaitForChild("Head", 5)
		if not headPart or not profileEspEnabled then return end

		if headPart:FindFirstChild("ProfileESP") then
			headPart.ProfileESP:Destroy()
		end

		local userId = player.UserId
		local thumbType = Enum.ThumbnailType.HeadShot
		local thumbSize = Enum.ThumbnailSize.Size420x420
		local content, isReady = Players:GetUserThumbnailAsync(userId, thumbType, thumbSize)

		local billboardGui = Instance.new("BillboardGui")
		billboardGui.Name = "ProfileESP"
		billboardGui.Size = UDim2.new(0, 80, 0, 110)
		billboardGui.Adornee = headPart
		billboardGui.AlwaysOnTop = true
		billboardGui.StudsOffset = Vector3.new(0, 2.5, 0)

		local imageLabel = Instance.new("ImageLabel")
		imageLabel.Size = UDim2.new(1, 0, 0, 80)
		imageLabel.BackgroundTransparency = 1
		imageLabel.Image = content
		imageLabel.Parent = billboardGui

		local textLabel = Instance.new("TextLabel")
		textLabel.Size = UDim2.new(1, 0, 0, 30)
		textLabel.Position = UDim2.new(0, 0, 0, 80)
		textLabel.BackgroundTransparency = 1
		textLabel.Text = player.DisplayName .. " (@" .. player.Name .. ")"
		textLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
		textLabel.TextStrokeTransparency = 0
		textLabel.TextScaled = true
		textLabel.TextSize = 12
		textLabel.Font = selectedFont 
		textLabel.Parent = billboardGui

		billboardGui.Parent = headPart

		profileEspCache[player] = billboardGui
	end

	local function trackNamePlayer(player)
		if player == LocalPlayer then return end

		if player.Character then
			task.spawn(applyName, player, player.Character)
		end

		player.CharacterAdded:Connect(function(character)
			task.spawn(applyName, player, character)
		end)
	end

	local function trackProfilePlayer(player)
		if player == LocalPlayer then return end

		if player.Character then
			task.spawn(applyProfile, player, player.Character)
		end

		player.CharacterAdded:Connect(function(character)
			task.spawn(applyProfile, player, character)
		end)
	end
	
	VisualGroupbox:AddDivider()
	local fontDropdown = VisualGroupbox:AddDropdown("FontDropdown", {
		Text = "Font",
		Values = {
			"SourceSansBold",
			"GothamBold",
			"ArialBold",
			"FredokaOne",
			"Jura"
		},
		Default = 1,
		Multi = false,
		Callback = function(value)
			selectedFont = Enum.Font[value]

			if nameEspEnabled then
				for player, billboard in pairs(nameEspCache) do
					if billboard then billboard:Destroy() end
				end
				nameEspCache = {}
				
				for _, player in pairs(Players:GetPlayers()) do
					if player ~= LocalPlayer and player.Character then
						task.spawn(applyName, player, player.Character)
					end
				end
			end

			if profileEspEnabled then
				for player, billboard in pairs(profileEspCache) do
					if billboard then billboard:Destroy() end
				end
				profileEspCache = {}
				
				for _, player in pairs(Players:GetPlayers()) do
					if player ~= LocalPlayer and player.Character then
						task.spawn(applyProfile, player, player.Character)
					end
				end
			end
		end
	})
	
	local nameToggle = VisualGroupbox:AddCheckbox("NameToggle", {
		Text = "Name ESP",
		Default = false,
		Callback = function(value)
			nameEspEnabled = value
			if not value then
				for player, billboard in pairs(nameEspCache) do
					if billboard then billboard:Destroy() end
				end
				nameEspCache = {}
			else
				for _, player in pairs(Players:GetPlayers()) do
					if player ~= LocalPlayer and player.Character then
						task.spawn(applyName, player, player.Character)
					end
				end
			end
		end
	})

	local profileToggle = VisualGroupbox:AddCheckbox("ProfileToggle", {
		Text = "Profile & Name ESP",
		Default = false,
		Callback = function(value)
			profileEspEnabled = value
			if not value then
				for player, billboard in pairs(profileEspCache) do
					if billboard then billboard:Destroy() end
				end
				profileEspCache = {}
			else
				for _, player in pairs(Players:GetPlayers()) do
					if player ~= LocalPlayer and player.Character then
						task.spawn(applyProfile, player, player.Character)
					end
				end
			end
		end
	})

	for _, player in pairs(Players:GetPlayers()) do
		trackNamePlayer(player)
		trackProfilePlayer(player)
	end

	Players.PlayerAdded:Connect(function(player)
		trackNamePlayer(player)
		trackProfilePlayer(player)
	end)

	Players.PlayerRemoving:Connect(function(player)
		if nameEspCache[player] then
			nameEspCache[player]:Destroy()
			nameEspCache[player] = nil
		end
		if profileEspCache[player] then
			profileEspCache[player]:Destroy()
			profileEspCache[player] = nil
		end
	end)
end
--=======================================================================
-- Field of View & Zoom
--=======================================================================
do
	local currentCamera = Workspace.CurrentCamera
	local defaultFieldOfView = 70
	local targetFOV = defaultFieldOfView
	local currentFOV = defaultFieldOfView
	local tweenInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	local isFOVEnabled = false
	local renderSteppedConnection = nil
	local savedFOVValue = defaultFieldOfView
	
	local minZoomFOV = 70  
	local maxZoomFOV = 10   
	local isHoldingZoom = false
	local zoomRenderConnection = nil
	local holdStartTime = 0
	local isKeyPressed = false
	local isZoomActive = false
	local originalMouseSensitivity = nil

	if currentCamera then
		currentCamera.FieldOfView = defaultFieldOfView
	end

	local function updateMouseSensitivity()
		local camera = Workspace.CurrentCamera
		if not camera then return end
		
		if isZoomActive then
			local zoomRatio = (minZoomFOV - camera.FieldOfView) / (minZoomFOV - maxZoomFOV)
			local sensitivityMultiplier = 1 - (zoomRatio * 0.85) 
			
			UserInputService.MouseDeltaSensitivity = (originalMouseSensitivity or UserInputService.MouseDeltaSensitivity) * sensitivityMultiplier
		else
			if originalMouseSensitivity then
				UserInputService.MouseDeltaSensitivity = originalMouseSensitivity
				originalMouseSensitivity = nil
			end
		end
	end

	local function startFOVControl()
		if renderSteppedConnection then
			renderSteppedConnection:Disconnect()
			renderSteppedConnection = nil
		end

		targetFOV = savedFOVValue
		currentFOV = defaultFieldOfView

		renderSteppedConnection = RunService.RenderStepped:Connect(function(deltaTime)
			if isZoomActive then return end
			
			local camera = Workspace.CurrentCamera
			if camera and math.abs(currentFOV - targetFOV) > 0.1 then
				local alpha = 1 - math.exp(-15 * deltaTime) 
				currentFOV = currentFOV + (targetFOV - currentFOV) * alpha
				camera.FieldOfView = currentFOV
			elseif camera and math.abs(currentFOV - targetFOV) <= 0.1 then
				currentFOV = targetFOV
				camera.FieldOfView = targetFOV
			end
		end)
	end

	local function stopFOVControl()
		if renderSteppedConnection then
			renderSteppedConnection:Disconnect()
			renderSteppedConnection = nil
		end
		
		if not isZoomActive then
			local camera = Workspace.CurrentCamera
			if camera then
				camera.FieldOfView = defaultFieldOfView
				currentFOV = defaultFieldOfView
			end
		end
	end

	local function stopZoomRender()
		if zoomRenderConnection then
			zoomRenderConnection:Disconnect()
			zoomRenderConnection = nil
		end
	end

	local function startZoom()
		if isZoomActive then return end
		
		isZoomActive = true
		
		local camera = Workspace.CurrentCamera
		if not camera then return end
		
		if renderSteppedConnection then
			renderSteppedConnection:Disconnect()
			renderSteppedConnection = nil
		end

		originalMouseSensitivity = UserInputService.MouseDeltaSensitivity
		
		currentFOV = camera.FieldOfView
	end

	local function stopZoom()
		if not isZoomActive then return end
		
		isZoomActive = false
		isHoldingZoom = false
		
		local camera = Workspace.CurrentCamera
		if not camera then return end
		
		stopZoomRender()
		
		if originalMouseSensitivity then
			UserInputService.MouseDeltaSensitivity = originalMouseSensitivity
			originalMouseSensitivity = nil
		end
		
		if isFOVEnabled then
			targetFOV = savedFOVValue
			currentFOV = camera.FieldOfView
			startFOVControl()
		else
			camera.FieldOfView = defaultFieldOfView
			currentFOV = defaultFieldOfView
		end
	end

	local function updateZoomHold()
		if not isHoldingZoom or not isZoomActive then return end
		
		local camera = Workspace.CurrentCamera
		if not camera then return end
		
		local holdDuration = tick() - holdStartTime

		local zoomProgress = math.clamp(holdDuration / 1.0, 0, 1)

		local targetZoomFOV = minZoomFOV - ((minZoomFOV - maxZoomFOV) * zoomProgress)

		camera.FieldOfView = camera.FieldOfView + (targetZoomFOV - camera.FieldOfView) * 0.2

		currentFOV = camera.FieldOfView
		
		updateMouseSensitivity()
	end

	CameraGroupbox:AddSlider("FieldOfViewSlider", {
		Text = "Field of View",
		Default = defaultFieldOfView,
		Min = 40,
		Max = 120,
		Rounding = 0,
		Callback = function(value)
			savedFOVValue = value
			
			if isFOVEnabled and not isZoomActive then
				targetFOV = value
			end
		end
	})

	CameraGroupbox:AddCheckbox("FOVToggle", {
		Text = "Toggle",
		Default = false,
		Callback = function(value)
			isFOVEnabled = value
			if isFOVEnabled and not isZoomActive then
				startFOVControl()
			else
				stopFOVControl()
			end
		end
	})
--=======================================================================
-- First Person
--=======================================================================
do
    _G.FP_ESP = _G.FP_ESP or {}
    local State = _G.FP_ESP

    State.boxes = State.boxes or {}
    State.running = State.running or false
    State.lastCheck = State.lastCheck or 0
    State.lastChar = State.lastChar or nil
    State.pendingEnable = false
    State.color = State.color or Color3.new(1, 1, 1) 

    local firstPersonBoxes = State.boxes

    local EXCLUDED_PARTS = {
        Head = true,
    }

    local DEFAULT_PARTS = {
        "Left Arm", "Right Arm", "Left Leg", "Right Leg",
        "Torso", "UpperTorso", "LowerTorso",
        "LeftUpperArm", "RightUpperArm",
        "LeftLowerArm", "RightLowerArm",
        "LeftUpperLeg", "RightUpperLeg",
        "LeftLowerLeg", "RightLowerLeg",
    }

    local function getParts()
        if type(targetParts) == "table" and #targetParts > 0 then
            return targetParts
        end
        return DEFAULT_PARTS
    end

    local function getChar()
        if type(getCurrentCharacter) == "function" then
            local ok, c = pcall(getCurrentCharacter)
            if ok and c then return c end
        end
        local lp = game:GetService("Players").LocalPlayer
        if lp and lp.Character then return lp.Character end
        return nil
    end

    local function clearBoxes()
        for part, box in pairs(firstPersonBoxes) do
            if box then box:Destroy() end
        end
        table.clear(firstPersonBoxes)
    end

    local function createCharESP(char)
        if not char then return end
        if State.lastChar ~= char then
            clearBoxes()
            State.lastChar = char
        end
        for _, partName in ipairs(getParts()) do
            if not EXCLUDED_PARTS[partName] then
                local part = char:FindFirstChild(partName)
                if part and part:IsA("BasePart") and not firstPersonBoxes[part] then
                    local box = Instance.new("SelectionBox")
                    box.Adornee = part
                    box.LineThickness = 0.002
                    box.Color3 = State.color
                    box.SurfaceTransparency = 1
                    box.Parent = part
                    firstPersonBoxes[part] = box
                end
            end
        end
    end

    local function updatePCLDESP(isFirstPerson)
        local now = tick()
        if now - State.lastCheck < 0.15 then return end
        State.lastCheck = now

        if type(cachedPCLDs) ~= "table" then return end

        local char = getChar()
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end

        for detector in pairs(cachedPCLDs) do
            if detector and detector.Parent then
                local dist = (hrp.Position - detector.Position).Magnitude
                if isFirstPerson and dist <= 3 then
                    if selectionBoxes and selectionBoxes[detector] then
                        if type(removeESP) == "function" then removeESP(detector) end
                        hiddenPCLDs = hiddenPCLDs or {}
                        hiddenPCLDs[detector] = true
                    end
                else
                    if hiddenPCLDs and hiddenPCLDs[detector] then
                        if type(createESP) == "function" then createESP(detector) end
                        hiddenPCLDs[detector] = nil
                    end
                end
            end
        end
    end

    local function applyColor()
        for part, box in pairs(firstPersonBoxes) do
            if box and box.Parent then
                box.Color3 = State.color
            else
                firstPersonBoxes[part] = nil
            end
        end
    end

    local function startLoop()
        if State.running then return end
        State.running = true
        State.lastChar = nil

        task.spawn(function()
            local char = getChar()
            local waited = 0
            while State.running and (not char or not char:FindFirstChild("Head")) and waited < 10 do
                task.wait(0.2)
                waited = waited + 0.2
                char = getChar()
            end

            if not State.running then return end

            while State.running and not workspace.CurrentCamera do
                task.wait(0.1)
            end

            while State.running do
                char = getChar()
                local isFirstPerson = false

                if char and char:FindFirstChild("Head") then
                    if State.lastChar ~= char then
                        clearBoxes()
                        State.lastChar = char
                    end

                    local cam = workspace.CurrentCamera
                    if cam then
                        local dist = (cam.CFrame.Position - char.Head.Position).Magnitude
                        if dist < 1.5 then
                            isFirstPerson = true
                            createCharESP(char)
                        elseif next(firstPersonBoxes) ~= nil then
                            clearBoxes()
                        end
                    end
                elseif next(firstPersonBoxes) ~= nil then
                    clearBoxes()
                end

                applyColor()
                updatePCLDESP(isFirstPerson)
                task.wait(0.1)
            end

            clearBoxes()
            updatePCLDESP(false)
        end)
    end

    local function stopLoop()
        State.running = false
        clearBoxes()
        updatePCLDESP(false)
    end

    local function requestEnable()
        State.pendingEnable = true
        startLoop()
    end

    local function requestDisable()
        State.pendingEnable = false
        stopLoop()
    end

    local function setColor(color)
        State.color = color
        applyColor()
    end

    local FP_Checkbox = nil
    if type(CameraGroupbox) == "table" and type(CameraGroupbox.AddCheckbox) == "function" then
        pcall(function()
            FP_Checkbox = CameraGroupbox:AddCheckbox("FP_ESP", {
                Text = "First Person",
                Default = false,
                Callback = function(v)
                    if v then requestEnable() else requestDisable() end
                end
            })
        end)
    end

    if FP_Checkbox and type(FP_Checkbox.AddColorPicker) == "function" then
        pcall(function()
            FP_Checkbox:AddColorPicker("FP_ESP_Color", {
                Default = State.color,
                Title = "First Person Color",
                Resizable = true,
                Callback = function(color)
                    setColor(color)
                end
            })
        end)
    end

    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer

    local function onCharacter(char)
        if State.pendingEnable and not State.running then
            task.wait(0.5)
            if State.pendingEnable then
                startLoop()
            end
        end
    end

    if lp then
        lp.CharacterAdded:Connect(onCharacter)
        if State.pendingEnable and lp.Character then
            task.spawn(onCharacter, lp.Character)
        end
    end

    _G.FP_ESP.enable = requestEnable
    _G.FP_ESP.disable = requestDisable
    _G.FP_ESP.setColor = setColor
end
--=======================================================================
-- Third Person Unlock
--=======================================================================
do
	local thirdPersonUnlocked = false
	local thirdPersonToggle = nil
	local renderConnection = nil
	local charConnection = nil
	local cameraConnection = nil

	local MAX_ZOOM = 50000

	local function applyCameraState(state)
		thirdPersonUnlocked = state

		if LocalPlayer then
			if thirdPersonUnlocked then
				LocalPlayer.CameraMode = Enum.CameraMode.Classic
				LocalPlayer.CameraMinZoomDistance = 0.5
				LocalPlayer.CameraMaxZoomDistance = MAX_ZOOM
			else
				LocalPlayer.CameraMode = Enum.CameraMode.LockFirstPerson
				LocalPlayer.CameraMinZoomDistance = 0.5
				LocalPlayer.CameraMaxZoomDistance = 0.5
			end
		end

		local currentCamera = Workspace.CurrentCamera
		if currentCamera then
			currentCamera.CameraType = Enum.CameraType.Custom
		end
	end

	local function startCameraLoop()
		if renderConnection then renderConnection:Disconnect() end

		renderConnection = RunService.RenderStepped:Connect(function()
			if thirdPersonUnlocked and LocalPlayer then
				if LocalPlayer.CameraMode ~= Enum.CameraMode.Classic then
					LocalPlayer.CameraMode = Enum.CameraMode.Classic
				end
				if LocalPlayer.CameraMaxZoomDistance < MAX_ZOOM then
					LocalPlayer.CameraMinZoomDistance = 0.5
					LocalPlayer.CameraMaxZoomDistance = MAX_ZOOM
				end
				local currentCamera = Workspace.CurrentCamera
				if currentCamera and currentCamera.CameraType ~= Enum.CameraType.Custom then
					currentCamera.CameraType = Enum.CameraType.Custom
				end
			end
		end)
	end

	local function setupRespawnHandler()
		if charConnection then charConnection:Disconnect() end
		if cameraConnection then cameraConnection:Disconnect() end

		charConnection = LocalPlayer.CharacterAdded:Connect(function()
			task.wait(0.2)
			if thirdPersonUnlocked then
				applyCameraState(true)
			end
		end)

		cameraConnection = Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
			task.wait(0.1)
			if thirdPersonUnlocked then
				applyCameraState(true)
			end
		end)
	end

	local function stopAll()
		if renderConnection then renderConnection:Disconnect() renderConnection = nil end
		if charConnection then charConnection:Disconnect() charConnection = nil end
		if cameraConnection then cameraConnection:Disconnect() cameraConnection = nil end
	end

	thirdPersonToggle = CameraGroupbox:AddCheckbox("ThirdPersonToggle", {
		Text = "Third Person Unlock",
		Default = false,
		Callback = function(state)
			applyCameraState(state)

			if state then
				startCameraLoop()
				setupRespawnHandler()
			else
				stopAll()
			end
		end,
	})

	thirdPersonToggle:AddKeyPicker("ThirdPersonKeyPicker", {
		Text = "Toggle Key",
		Default = "V",
		Mode = "Toggle",
		Callback = function()
			thirdPersonUnlocked = not thirdPersonUnlocked
			applyCameraState(thirdPersonUnlocked)

			if thirdPersonUnlocked then
				startCameraLoop()
				setupRespawnHandler()
			else
				stopAll()
			end

			task.defer(function()
				if thirdPersonToggle and thirdPersonToggle.SetValue then
					thirdPersonToggle:SetValue(thirdPersonUnlocked)
				end
			end)
		end,
	})
end

	local zoomToggle = CameraGroupbox:AddCheckbox("ZoomToggle", {
		Text = "Zoom",
		Default = false,
		Callback = function(state)
			if not isKeyPressed then
				if state then
					zoomToggle:SetValue(false)
				end
			end
		end,
	})

	local ZoomKeybind = zoomToggle:AddKeyPicker("ZoomKey", {
		Text = "Zoom Key",
		Default = "Z",
		Mode = "Hold",
		SyncToggleState = false,
	})

	UserInputService.InputBegan:Connect(function(input, gameProcessed)
		if gameProcessed then return end
		
		if input.KeyCode == Enum.KeyCode[Options.ZoomKey.Value] and not isKeyPressed then
			isKeyPressed = true

			zoomToggle:SetValue(true)

			startZoom()

			isHoldingZoom = true
			holdStartTime = tick()

			stopZoomRender()
			zoomRenderConnection = RunService.RenderStepped:Connect(function()
				updateZoomHold()
			end)
		end
	end)

	UserInputService.InputEnded:Connect(function(input, gameProcessed)
		if input.KeyCode == Enum.KeyCode[Options.ZoomKey.Value] then
			isKeyPressed = false

			zoomToggle:SetValue(false)

			stopZoom()
		end
	end)
end
--=======================================================================
-- UI Setting
--=======================================================================
_G.PacketAlertEnabled = true

do
    local ALERT_COOLDOWN = 2
    local lastAlertTime = {}  

    local function playKickSound()
        local s = Instance.new("Sound")
        s.SoundId = "rbxassetid://17208361335"
        s.Volume = 10
        s.PlayOnRemove = true
        s.Parent = SoundService
        s:Destroy()
    end

    local function alert(player)
        if not player then return end
        if _G.PacketAlertEnabled == false then return end

        local now = tick()
        local last = lastAlertTime[player]
        if last and (now - last) < ALERT_COOLDOWN then
            return
        end
        lastAlertTime[player] = now

        local displayName = player.DisplayName or "Unknown"
        local name = player.Name or "Unknown"

        playKickSound()
        Library:Notify({
            Title = "<b>Packet Detected</b>",
            Description = string.format("<b>%s</b> <font color='#888888'>(@%s)</font> was detected execute packet.", displayName, name),
            Icon = "11738671901",
            Time = 3,
            IconSize = 32,
        })
    end

    local function watchRemote(remote)
        if not remote or not remote:IsA("RemoteEvent") then return end

        remote.OnClientEvent:Connect(function(...)
            local args = {...}
            local suspect = nil
            local bigData = nil

            for _, v in ipairs(args) do
                if typeof(v) == "Instance" then
                    if v:IsA("Player") then
                        suspect = v
                    elseif v:IsA("Model") and Players:GetPlayerFromCharacter(v) then
                        suspect = Players:GetPlayerFromCharacter(v)
                    end
                elseif type(v) == "string" and #v > 5000 then
                    bigData = v
                end
            end

            if bigData then
                if not suspect then
                    if LocalPlayer then
                        suspect = LocalPlayer
                    else
                        for _, p in ipairs(Players:GetPlayers()) do
                            suspect = p
                            break
                        end
                    end
                end

                if suspect then
                    alert(suspect)
                end
            end
        end)
    end

    local function initRemoteWatch()
        local remotes = {
            Struggle, RagdollRemote,
            SetNetworkOwner, CreateGrabLine,
            ExtendGrabLine, DestroyGrabLine,
            StickyEvent,
            BombEvent,
            SpawnRemote, DestroyRemote,
            UseRemote,
        }

        for _, remote in ipairs(remotes) do
            if remote and remote:IsA("RemoteEvent") then
                watchRemote(remote)
            end
        end

        local folders = {
            CharacterEvents, GrabEvents, PlayerEvents,
            BombEvents, MenuToys, HoldEvents,
        }

        for _, folder in ipairs(folders) do
            if folder then
                folder.ChildAdded:Connect(function(child)
                    if child:IsA("RemoteEvent") then
                        watchRemote(child)
                    end
                end)
            end
        end
    end

    initRemoteWatch()
end

    MenuGroup:AddCheckbox("ShowCustomCursor", {
        Text = "Custom Cursor",
        Default = true,
        Callback = function(Value) Library.ShowCustomCursor = Value end,
    })

    MenuGroup:AddCheckbox("PacketAlertToggle", {
        Text = "Packet Notification",
