local pcall = function(func, ...)
	return pcall(function(...)
		return func(...)
	end, ...)
end
local xpcall = function(func, ...)
	return xpcall(function(...)
		return func(...)
	end, ...)
end
local b_getfenv = getfenv

local hiddenParts = setmetatable({}, { __mode = "k" })
local oldIndex

local function getRealPosition(part)
	if oldIndex and typeof(part) == "Instance" then
		return oldIndex(part, "Position")
	end
	return part.Position
end

local function getRealCFrame(part)
	if oldIndex and typeof(part) == "Instance" then
		return oldIndex(part, "CFrame")
	end
	return part.CFrame
end

local hookSuccess, hookError = pcall(function()
	if hookmetamethod then
		oldIndex = hookmetamethod(game, "__index", newcclosure(function(self, key)
			if typeof(self) == "Instance" and hiddenParts[self] then
				if key == "Position" or key == "CFrame" then
					return (key == "CFrame" and CFrame.new(0, -99999, 0) or Vector3.new(0, -99999, 0))
				elseif key == "GetPivot" then
					return newcclosure(function()
						return CFrame.new(0, -99999, 0)
					end)
				end
			end
			return oldIndex(self, key)
		end))
	elseif getrawmetatable then
		local mt = getrawmetatable(game)
		local oldIdx = mt.__index
		setreadonly(mt, false)
		mt.__index = newcclosure(function(self, key)
			if typeof(self) == "Instance" and hiddenParts[self] then
				if key == "Position" or key == "CFrame" then
					return (key == "CFrame" and CFrame.new(0, -99999, 0) or Vector3.new(0, -99999, 0))
				elseif key == "GetPivot" then
					return newcclosure(function()
						return CFrame.new(0, -99999, 0)
					end)
				end
			end
			return oldIdx(self, key)
		end)
		setreadonly(mt, true)
		oldIndex = oldIdx
	end
end)

local hookSuccess2, hookError2 = pcall(function()
	if hookfunction and gethiddenproperty then
		local oldGHP
		oldGHP = hookfunction(gethiddenproperty, newcclosure(function(self, prop)
			if typeof(self) == "Instance" and hiddenParts[self] then
				if prop == "Position" or prop == "CFrame" then
					return (prop == "CFrame" and CFrame.new(0, -99999, 0) or Vector3.new(0, -99999, 0))
				end
			end
			return oldGHP(self, prop)
		end))
	end
end)


