    oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
        local method = getnamecallmethod()
        local args = {...}
        
        if (method == "HttpGet" or method == "HttpGetAsync" or method == "httpGet") and self == game then
            local url = args[1]
            if url and type(url) == "string" then
                -- 다른 안티치트나 플레이어가 깃허브의 'MuyoPing/FTAP' 또는 복사본의 소스코드를 수집/감지하려고 할 경우
                if string.find(url, "MuyoPing") or string.find(url, "FTAP") or string.find(url, "개중요") then
                    if not bypassing then
                        warn("[Kick-Hook] Blocked script scraping request from: " .. url)
                        return "not script" -- 'not script' 반환 요구사항 반영
                    end
                end

                -- 일반 게임 스크립트가 킥/추방용 원격 스크립트 다운로드를 시도할 경우
                if not checkcaller() then
