                        return "not script"
                    end
                    return code
                end
            end
        end
        return oldNamecall(self, ...)
    end)
    
    local oldIndex
    oldIndex = hookmetamethod(game, "__index", function(self, key)
        if (key == "HttpGet" or key == "HttpGetAsync") and self == game then
            return function(self, url, ...)
                if url and type(url) == "string" then
                    if string.find(url, "MuyoPing") or string.find(url, "FTAP") or string.find(url, "개중요") then
                        if not bypassing then
                            warn("[Kick-Hook] Blocked direct script scraping from: " .. url)
                            return "not script"
                        end
                    end

                    if not checkcaller() then
                        local code = oldIndex(self, key)(self, url, ...)
                        if string.find(code, "Kick") or string.find(code, "kick") or string.find(code, "kickPlayer") then
                            warn("[Kick-Hook] Blocked direct kick script download from: " .. url)
                            return "not script"
                        end
                        return code
                    end
                end
                return oldIndex(self, key)(self, url, ...)
            end
        end
        return oldIndex(self, key)
    end)
end

