function getPlayer(targetName)
    local plr = Players:FindFirstChild(targetName)
    if plr then return plr end

    for _, player in ipairs(Players:GetPlayers()) do
        local display = player.Name .. " [ " .. player.DisplayName .. " ]"
        if targetName == display or targetName == player.DisplayName or targetName == player.Name then return player end
    end
end

local targetValueImages = {}
local targetDisplayMap = {}
local thumbnailCache = {}

function updateDropdown()
    local options = {}

    table.clear(targetDisplayMap)
    table.clear(targetValueImages)

    for _, player in ipairs(Players:GetPlayers()) do
        if not table.find(OwnerName, player.Name) or Owner then
            local display = player.Name .. " [ " .. player.DisplayName .. " ]"
            targetDisplayMap[display] = player.Name
            table.insert(options, display)

            local thumbnail = thumbnailCache[player.UserId]
            if not thumbnail then
                thumbnail = "rbxassetid://0"
                task.spawn(function()
                    local success, result = pcall(function()
                        return Players:GetUserThumbnailAsync(player.UserId, Enum.ThumbnailType.AvatarThumbnail, Enum.ThumbnailSize.Size420x420)
                    end)
                    if success then
                        thumbnailCache[player.UserId] = result
                    end
                end)
            end
            targetValueImages[display] = thumbnail
        end
    end

    for _, targetName in ipairs(currentTargets) do
        local found = false

        for _, option in ipairs(options) do
            if option == targetName then
                found = true
                break
            end
        end

        if not found then table.insert(options, targetName) end
    end

    TargetList:SetValues(options)
    TargetList.ValueImages = targetValueImages
end

function getAliveTargets(limit)
    local alive = {}

    for _, targetName in ipairs(currentTargets) do
        if #alive >= limit then break end

        local plr = getPlayer(targetName)
        local char = plr and plr.Character

        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local torso = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))

        if plr and char and hum and torso and hum.Health > 0 then table.insert(alive, targetName) end
    end

    return alive
end

local pp = {}
local PARTS = {
    {"Humanoid",         "hum"},
    {"HumanoidRootPart", "hrp"},
    {"Head",             "head"},
    {"Torso",            "torso"},
    {"Left Arm",         "la"},
    {"Right Arm",        "ra"},
    {"Left Leg",         "ll"},
    {"Right Leg",        "rl"},
}

local LIMB_CHILDREN = {
    {"Left Arm",  "la"},
    {"Right Arm", "ra"},
    {"Left Leg",  "ll"},
    {"Right Leg", "rl"},
}

local function fetch(parent, name, key)
    task.spawn(function()
        repeat rs2.PreSimulation:Wait() until parent:FindFirstChild(name)
        pp[key] = parent[name]
    end)
end

function clearChar()
    table.clear(pp)
end

function plrpart(char)
    pp.char = char

    for _, v in ipairs(PARTS) do
        fetch(char, v[1], v[2])
    end

    task.spawn(function()
        repeat rs2.PreSimulation:Wait() until char:FindFirstChild("Humanoid")
        local hum = char.Humanoid
        fetch(hum, "FireDebounce", "brn")
        fetch(hum, "Ragdolled",    "rag")
    end)

    task.spawn(function()
        repeat rs2.PreSimulation:Wait() until char:FindFirstChild("HumanoidRootPart")
        local hrp = char.HumanoidRootPart
        fetch(hrp, "RagdollTouchedHitbox", "raghit")
        task.spawn(function()
            task.wait(0.3)
            repeat rs2.PreSimulation:Wait() until hrp:FindFirstChild("RootAttachment")
            pp.att = hrp.RootAttachment
        end)
    end)

    for _, v in ipairs(LIMB_CHILDREN) do
        task.spawn(function()
            repeat rs2.PreSimulation:Wait() until char:FindFirstChild(v[1])
            local limb = char[v[1]]
            fetch(limb, "RagdollLimbPart",      v[2] .. "_p")
            fetch(limb, "BallSocketConstraint", v[2] .. "_c")
        end)
    end

    task.spawn(function()
        repeat rs2.PreSimulation:Wait() until char:FindFirstChild("Head")
        local head = char.Head
        fetch(head, "BallSocketConstraint", "head_c")
    end)
end

plr.CharacterAdded:Connect(plrpart)
plr.CharacterRemoving:Connect(clearChar)
if plr.Character then plrpart(plr.Character) end

function PcldOwner()
    task.spawn(function()
        while task.wait(0.1) do
            usedNames = {}

            for _, pcld in pairs(workspace:GetChildren()) do
                if pcld.Name == "PlayerCharacterLocationDetector" then
                    if pcld.CFrame == CFrame.new(0, 0, 0, 1, 0, 0, 0, 1, 0, 0, 0, 1) then
                        continue
                    end

                    existingBoolValues = {}
                    for _, child in pairs(pcld:GetChildren()) do
                        if child:IsA("BoolValue") then
                            table.insert(existingBoolValues, child)
                        end
                    end

                    if #existingBoolValues >= 2 then 
                        for _, boolValue in pairs(existingBoolValues) do
                            boolValue:Destroy()
                        end
                        existingBoolValues = {}
                    end

                    if #existingBoolValues == 1 then
                        continue
                    end

                    closestPlayer = nil
                    closestDist = 30
                    candidates = {}

                    for _, player in pairs(Players:GetPlayers()) do
                        if player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
                            local hrp = player.Character.HumanoidRootPart
                            dist = (pcld.Position - hrp.Position).Magnitude
                            if dist < closestDist then
                                table.insert(candidates, {player = player, dist = dist, hrp = hrp})
                            end
                        end
                    end

                    table.sort(candidates, function(a, b)
                        return a.dist < b.dist
                    end)

                    for _, candidate in pairs(candidates) do
                        ownerName = string.format("[ %s ] ( @%s )",
                            candidate.player.DisplayName,
                            candidate.player.Name)

                        if not usedNames[ownerName] then
                            closestPlayer = candidate.player
                            closestDist = candidate.dist
                            usedNames[ownerName] = true
                            break
                        end
                    end

                    if closestPlayer then
                        ownerName = string.format("[ %s ] ( @%s )", 
                            closestPlayer.DisplayName, 
                            closestPlayer.Name)

                        boolValue = Instance.new("BoolValue")
                        boolValue.Name = ownerName
                        boolValue.Parent = pcld

                        task.spawn(function(player, value, detectorPart)
                            while value and value.Parent do
                                isValid = Players:FindFirstChild(player.Name) and
                                    player.Character and
                                    player.Character:FindFirstChild("Humanoid") and
                                    player.Character.Humanoid.Health > 0 and
                                    player.Character:FindFirstChild("HumanoidRootPart")

                                if not isValid then
                                    value:Destroy()
                                    break
                                end

                                local LocalPlayer = Players.LocalPlayer
                                if LocalPlayer and player == LocalPlayer then
                                    task.wait(0.1)
                                --else
                                    local hrp = player.Character.HumanoidRootPart
                                    local hum = player.Character.Humanoid
                                    
                                    --if hrp.Massless == true and not hum.SeatPart then
                                    --    hrp.Massless = false
                                    --    hrp.CFrame = detectorPart.CFrame
                                    --end
                                end

                                task.wait(0.1)
                            end
                        end, closestPlayer, boolValue, pcld)
                    end
                end
            end
        end
    end)
end

