function isnetworkowner(part)
    return not part.AssemblyRootPart.Anchored and part.AssemblyRootPart.ReceiveAge > 0.05
end
end

ServerHrp = CFrame.zero
local Chrp
LoopGotoMode = "Original CFrame"

function Fake(state, part)
    if state == isFaking then 
        if state and part and part.Parent and pp.hrp then
            pcall(sethiddenproperty, pp.hrp, "PhysicsRepRootPart", part)
        end
        return 
    end
    isFaking = state
    if state then
        if pp.torso then Chrp = pp.torso.CFrame end
        if LoopGotoMode == "Original CFrame" then
            heartbeatConnection = rs2.Heartbeat:Connect(function()
                if pp.torso and ServerHrp and ServerHrp == ServerHrp then
                    pp.torso.CFrame = ServerHrp
                    if part and part.Parent and pp.hrp then 
                        pcall(sethiddenproperty, pp.hrp, "PhysicsRepRootPart", part) 
                    else
                        pcall(sethiddenproperty, pp.hrp, "PhysicsRepRootPart", nil)
                    end
                end
            end)
        elseif LoopGotoMode == "DeSync" then
            rs2:BindToRenderStep("ClientVision", Enum.RenderPriority.Camera.Value - 1, function()
                if pp.torso and Chrp then pp.torso.CFrame = Chrp end
            end)
            heartbeatConnection = rs2.Heartbeat:Connect(function()
                if pp.torso and ServerHrp and ServerHrp == ServerHrp then
                    Chrp = pp.torso.CFrame
                    pp.torso.CFrame = ServerHrp
                    if part and part.Parent and pp.hrp then 
                        pcall(sethiddenproperty, pp.hrp, "PhysicsRepRootPart", part) 
                    else
                        pcall(sethiddenproperty, pp.hrp, "PhysicsRepRootPart", nil)
                    end
                    if pp.hum then
                        if not pp.hum.Sit then pp.hum:ChangeState(Enum.HumanoidStateType.PlatformStanding) end
                        if pp.hum.Sit then pp.torso.AssemblyLinearVelocity = pp.torso.AssemblyLinearVelocity * 1.5 end
                    end
                end
            end)
        end
    else
        pcall(function() rs2:UnbindFromRenderStep("ClientVision") end)
        if heartbeatConnection then heartbeatConnection:Disconnect() heartbeatConnection = nil end
        if pp.hrp then pcall(sethiddenproperty, pp.hrp, "PhysicsRepRootPart", nil) end
        if pp.torso and Chrp then
            pp.torso.CFrame = Chrp
        end
    end
end

