function focusOnTorso(character)
    local torso = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or character:FindFirstChild("HumanoidRootPart")
    if torso then viewCam.CFrame = CFrame.new(torso.Position + (torso.CFrame.LookVector * 4), torso.Position) end
end

