LBox:AddButton({
    Text = "블랙홀 쉐이더",
    Callback = function()
        -- v1.4 (간소화된 버전)
        local RunService = game:GetService("RunService")
        local targetAssetId = "rbxassetid://97380840444927"
        local loadedModel = nil

        pcall(function()
            loadedModel = game:GetObjects(targetAssetId)[1]
        end)

        local function applyChanges(child)
            if child.Name == "BillboardGui" and child:IsA("BillboardGui") then
                local function hideGui()
                    child.Enabled = false
                    for _, element in pairs(child:GetDescendants()) do
                        pcall(function() element.BackgroundTransparency = 1 end)
                        pcall(function() element.TextTransparency = 1 end)
                        pcall(function() element.ImageTransparency = 1 end)
                    end
                end
                hideGui()
                child.Changed:Connect(hideGui)
                child.DescendantAdded:Connect(hideGui)
            elseif child.Name == "Hole" and child:IsA("BasePart") then
                task.wait(0.1)
                
                child.Transparency = 1
                child:GetPropertyChangedSignal("Transparency"):Connect(function()
                    if child.Transparency ~= 1 then
                        child.Transparency = 1
                    end
                end)
                
                if loadedModel and not child:FindFirstChild("CustomHoleModel") then
                    local clone = loadedModel:Clone()
                    clone.Name = "CustomHoleModel"
                    clone.Parent = child
                    
                    local scaleFactor = 0.5
                    
                    if clone:IsA("Model") then
                        local modelGroup = Instance.new("Model")
                        modelGroup.Name = "ModelGroup"
                        modelGroup.Parent = clone
                        
                        for _, part in pairs(clone:GetDescendants()) do
                            if part:IsA("BasePart") then
                                part.Material = Enum.Material.Neon
                                part.Color = Color3.new(0, 0, 0)
                                part.Size = part.Size * scaleFactor
                                part.Anchored = false
                                part.CanCollide = false
                                part.Parent = modelGroup
                            end
                        end
                        
                        local function updateModelRotation()
                            local camera = workspace.CurrentCamera
                            if camera and modelGroup.Parent then
                                local lookDirection = (camera.CFrame.Position - child.Position).Unit
                                local rotation = CFrame.lookAt(Vector3.new(0,0,0), lookDirection, Vector3.new(0,1,0))
                                modelGroup:SetPrimaryPartCFrame(child.CFrame * rotation * CFrame.new(0, 0, 0))
                            end
                        end
                        
                        local firstPart = modelGroup:FindFirstChildWhichIsA("BasePart")
                        if firstPart then
                            modelGroup.PrimaryPart = firstPart
                        end
                        
                        updateModelRotation()
                        
                        RunService.RenderStepped:Connect(function()
                            if modelGroup.Parent then
                                updateModelRotation()
                            end
                        end)
                        
                    elseif clone:IsA("BasePart") then
                        clone.Material = Enum.Material.Neon
                        clone.Color = Color3.new(0, 0, 0)
                        clone.Size = clone.Size * scaleFactor
                        clone.Anchored = false
                        clone.CanCollide = false
                        
                        local function updatePartRotation()
                            local camera = workspace.CurrentCamera
                            if camera and clone.Parent then
                                local lookDirection = (camera.CFrame.Position - child.Position).Unit
                                local rotation = CFrame.lookAt(Vector3.new(0,0,0), lookDirection, Vector3.new(0,1,0))
                                clone.CFrame = child.CFrame * rotation
                            end
                        end
                        
                        updatePartRotation()
                        
                        RunService.RenderStepped:Connect(function()
                            if clone.Parent then
                                updatePartRotation()
                            end
                        end)
                    end
                end
            end
        end

        local function handleBlackHoleKick(obj)
            for _, descendant in pairs(obj:GetDescendants()) do
                applyChanges(descendant)
            end
            obj.DescendantAdded:Connect(applyChanges)
        end

        for _, descendant in pairs(workspace:GetDescendants()) do
            if descendant.Name == "BlackHoleKick" then
                handleBlackHoleKick(descendant)
            end
        end

        workspace.DescendantAdded:Connect(function(descendant)
            if descendant.Name == "BlackHoleKick" then
                handleBlackHoleKick(descendant)
            end
        end)

        Library:Notify({
            Title = "[ FTPA Lu V2.SAYS ]",
            Description = "블랙홀 적용됨",
            Icon = "eye",
            Time = 2
        })
        NS:Play()
    end
})

LBox:AddButton({
    Text = "현실적인 바다",
    Callback = function()
        if workspace.Map.AlwaysHereTweenedObjects.Ocean.Object:FindFirstChild("ObjectModel") then
            for _,prt in pairs(workspace.Map.AlwaysHereTweenedObjects.Ocean.Object.ObjectModel:GetChildren()) do 
                if prt:IsA("Part") then 
                    prt.Transparency = 1
                end
            end
        end

        local Terrain = workspace.Terrain

        local oceanSize = 12000
        local oceanDepth = 130
        local oceanLevel = -14
        local chunkSize = 1000

        local spawnPosition = Vector3.new(0, oceanLevel - (oceanDepth / 2), 0)
        local spawnClearSize = Vector3.new(750, oceanDepth, 750)

        local steps = math.ceil(oceanSize / chunkSize)
        local startOffset = -oceanSize / 2

        for x = 0, steps - 1 do
            for z = 0, steps - 1 do
                local xPos = startOffset + (x * chunkSize) + (chunkSize / 2)
                local zPos = startOffset + (z * chunkSize) + (chunkSize / 2)

                local centerPos = Vector3.new(xPos, oceanLevel - (oceanDepth / 2), zPos)
                local size = Vector3.new(chunkSize, oceanDepth, chunkSize)

                Terrain:FillBlock(CFrame.new(centerPos), size, Enum.Material.Water)
            end
        end

        Terrain:FillBlock(CFrame.new(spawnPosition), spawnClearSize, Enum.Material.Air)

        Terrain.WaterWaveSize = 0.7
        Terrain.WaterWaveSpeed = 9
        Terrain.WaterReflectance = 1
        Terrain.WaterTransparency = 0.07
        Terrain.WaterColor = Color3.fromRGB(0, 100, 200)

        Library:Notify({
            Title = "[ FTPA Lu V2.SAYS ]",
            Description = "현실적인 바다 생성 완료",
            Icon = "waves",
            Time = 2
        })
        NS:Play()
    end
})

LBox:AddButton({
    Text = "자동차 소환",
    Callback = function()
        local assetId = 106844475991344
        print("🏎️ 차량 로드 중... (Asset ID: " .. assetId .. ")")

        local car = nil
        local container = nil

        -- ==================== Asset Loading ====================
        local function tryLoad(methodName, loadFunc)
            local success, result = pcall(loadFunc)
            if success and result then
                container = result
                print("✅ " .. methodName .. " 로드 성공")
                return true
            end
            return false
        end

        if not container then tryLoad("GetObjects", function() return game:GetObjects("rbxassetid://" .. assetId) end) end
        if not container then tryLoad("InsertService", function() return game:GetService("InsertService"):LoadAsset(assetId) end) end
        if not container then tryLoad("MarketplaceService", function() return game:GetService("MarketplaceService"):LoadAsset(assetId) end) end

        if not container then warn("❌ 로드 실패") return end

        local function findCarModel(obj)
            if obj:IsA("Model") then return obj end
            if obj:IsA("Folder") then
                for _, child in ipairs(obj:GetChildren()) do
                    if child:IsA("Model") then return child end
                end
            end
            if obj:FindFirstChildWhichIsA("BasePart") then return obj end
            return nil
        end

        car = findCarModel(container[1] or container)
        if not car then warn("❌ Model 찾기 실패") return end

        if car.Parent then car.Parent = nil end
        car.Parent = workspace
        car.Name = "Car_" .. assetId

        print("📦 모델 로드됨:", car.Name)

        -- ==================== 스크립트 활성화 ====================
        for _, obj in ipairs(car:GetDescendants()) do
            if obj:IsA("Script") or obj:IsA("LocalScript") then
                obj.Disabled = false
            end
        end

        -- ==================== PrimaryPart & Physics ====================
        local allParts = {}
        for _, part in ipairs(car:GetDescendants()) do
            if part:IsA("BasePart") then table.insert(allParts, part) end
        end

        local primary = nil
        local maxVol = 0
        for _, p in ipairs(allParts) do
            local v = p.Size.X * p.Size.Y * p.Size.Z
            if v > maxVol then
                maxVol = v
                primary = p
            end
        end

        if primary then
            car.PrimaryPart = primary
            primary.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.3, 0.5, 1, 1)
            
            -- ==================== 중력 증가 설정 (VectorForce 추가) ====================
            local totalMass = 0
            for _, part in ipairs(allParts) do
                totalMass = totalMass + part:GetMass()
            end
            
            local attachment = Instance.new("Attachment")
            attachment.Name = "GravityAttachment"
            attachment.Parent = primary
            
            local vectorForce = Instance.new("VectorForce")
            vectorForce.Name = "ExtraGravityForce"
            vectorForce.Attachment0 = attachment
            vectorForce.Force = Vector3.new(0, -totalMass * workspace.Gravity * 1.5, 0) -- 기본 중력의 1.5배 하향 힘 추가
            vectorForce.RelativeTo = Enum.ActuatorRelativeTo.World
            vectorForce.Parent = primary
            
            print("⚖️ 추가 중력 설정 완료! (배율: 1.5배, 총 질량: " .. totalMass .. ")")
        end

        -- ==================== 최소한의 용접 ====================
        for _, part in ipairs(allParts) do
            if part ~= primary and part.Parent == car then
                local isCritical = part.Name:lower():find("wheel") or part.Name:lower():find("tire") or 
                                  part:FindFirstChildWhichIsA("VehicleSeat") or part:FindFirstChildWhichIsA("Seat")
                
                if not isCritical then
                    local hasJoint = false
                    for _, c in ipairs(part:GetChildren()) do
                        if c:IsA("Weld") or c:IsA("WeldConstraint") or c:IsA("Motor6D") then
                            hasJoint = true
                            break
                        end
                    end
                    if not hasJoint then
                        local wc = Instance.new("WeldConstraint")
                        wc.Part0 = primary
                        wc.Part1 = part
                        wc.Parent = part
                    end
                end
            end
        end

        -- ==================== Spawn Position ====================
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local UserInputService = game:GetService("UserInputService")

        local LocalPlayer = Players.LocalPlayer
        local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        local hrp = character:WaitForChild("HumanoidRootPart")
        local humanoid = character:WaitForChild("Humanoid")

        local spawnCFrame = hrp.CFrame * CFrame.new(0, 5, -25) * CFrame.Angles(0, math.rad(180), 0)
        car:SetPrimaryPartCFrame(spawnCFrame)
        print("✅ 차량 스폰 완료!")

        -- ==================== 🏎️ 제어 시스템 ====================
        local seat = car:FindFirstChildWhichIsA("VehicleSeat", true) or car:FindFirstChildWhichIsA("Seat", true)

        if seat then
            local prompt = seat:FindFirstChildWhichIsA("ProximityPrompt") or Instance.new("ProximityPrompt", seat)
            prompt.RequiresLineOfSight = false
            prompt.MaxActivationDistance = 30
            prompt.HoldDuration = 0
            prompt.ActionText = "차량 탑승"
            
            local isSitting = false
            local loopConnection = nil
            local jumpConnection = nil
            local diedConnection = nil
            local sitAnimTrack = nil
            local speedometerGui = nil 
            
            local anim = Instance.new("Animation")
            anim.AnimationId = "rbxassetid://2506281707" 
            
            -- 주행 변수 설정
            local maxSpeed = 410      
            local baseAccel = 110     
            local decelRate = 130     
            
            local function exitVehicle()
                if not isSitting then return end
                isSitting = false
                prompt.ActionText = "차량 탑승"
                
                if loopConnection then loopConnection:Disconnect() loopConnection = nil end
                if jumpConnection then jumpConnection:Disconnect() jumpConnection = nil end
                if diedConnection then diedConnection:Disconnect() diedConnection = nil end
                if sitAnimTrack then sitAnimTrack:Stop() sitAnimTrack = nil end
                if speedometerGui then speedometerGui:Destroy() speedometerGui = nil end 
                
                humanoid.PlatformStand = false
                humanoid.Sit = false
                task.wait(0.05)
                
                hrp.CFrame = seat.CFrame * CFrame.new(-6, 2, 0)
                print("🚶 하차 완료!")
            end

            prompt.Triggered:Connect(function(player)
                if player ~= LocalPlayer then return end
                
                if not isSitting then
                    isSitting = true
                    prompt.ActionText = "운전 중... (Space 하차 / V 바로세우기)"
                    
                    sitAnimTrack = humanoid:LoadAnimation(anim)
                    sitAnimTrack:Play()
                    
                    humanoid.PlatformStand = true 
                    hrp.AssemblyLinearVelocity = Vector3.new(0,0,0)
                    hrp.AssemblyAngularVelocity = Vector3.new(0,0,0)
                    
                    -- ==================== 📊 모던 계기판 UI 동적 생성 ====================
                    speedometerGui = Instance.new("ScreenGui")
                    speedometerGui.Name = "SpeedometerGui"
                    speedometerGui.ResetOnSpawn = false
                    speedometerGui.Parent = LocalPlayer:WaitForChild("PlayerGui")
                    
                    local mainFrame = Instance.new("Frame")
                    mainFrame.Name = "MainFrame"
                    mainFrame.Size = UDim2.new(0, 220, 0, 110)
                    mainFrame.Position = UDim2.new(0.5, 0, 0.85, 0)
                    mainFrame.AnchorPoint = Vector2.new(0.5, 0.5)
                    mainFrame.BackgroundColor3 = Color3.fromRGB(15, 15, 22)
                    mainFrame.BackgroundTransparency = 0.25 
                    mainFrame.BorderSizePixel = 0
                    mainFrame.Parent = speedometerGui
                    
                    local uiCorner = Instance.new("UICorner")
                    uiCorner.CornerRadius = UDim.new(0, 16)
                    uiCorner.Parent = mainFrame
                    
                    local uiStroke = Instance.new("UIStroke")
                    uiStroke.Thickness = 2
                    uiStroke.Color = Color3.fromRGB(0, 204, 255)
                    uiStroke.Transparency = 0.3
                    uiStroke.Parent = mainFrame
                    
                    -- 드리프트 알림 텍스트 레이블 (계기판 위에 띄움)
                    local driftLabel = Instance.new("TextLabel")
                    driftLabel.Name = "DriftLabel"
                    driftLabel.Size = UDim2.new(1, 0, 0.2, 0)
                    driftLabel.Position = UDim2.new(0, 0, -0.25, 0)
                    driftLabel.BackgroundTransparency = 1
                    driftLabel.Text = "DRIFT"
                    driftLabel.TextColor3 = Color3.fromRGB(255, 102, 0) -- 네온 오렌지
                    driftLabel.TextSize = 20
                    driftLabel.Font = Enum.Font.GothamBold
                    driftLabel.TextTransparency = 1 -- 평소엔 투명화
                    driftLabel.Parent = mainFrame
                    
                    local driftStroke = Instance.new("UIStroke")
                    driftStroke.Thickness = 1.5
                    driftStroke.Color = Color3.fromRGB(255, 102, 0)
                    driftStroke.Transparency = 1
                    driftStroke.Parent = driftLabel
                    
                    local speedLabel = Instance.new("TextLabel")
                    speedLabel.Name = "SpeedLabel"
                    speedLabel.Size = UDim2.new(1, 0, 0.6, 0)
                    speedLabel.Position = UDim2.new(0, 0, 0.1, 0)
                    speedLabel.BackgroundTransparency = 1
                    speedLabel.Text = "0"
                    speedLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
                    speedLabel.TextSize = 46
                    speedLabel.Font = Enum.Font.GothamBold
                    speedLabel.Parent = mainFrame
                    
                    local unitLabel = Instance.new("TextLabel")
                    unitLabel.Name = "UnitLabel"
                    unitLabel.Size = UDim2.new(1, 0, 0.2, 0)
                    unitLabel.Position = UDim2.new(0, 0, 0.65, 0)
                    unitLabel.BackgroundTransparency = 1
                    unitLabel.Text = "KM/H"
                    unitLabel.TextColor3 = Color3.fromRGB(0, 204, 255)
                    unitLabel.TextSize = 13
                    unitLabel.Font = Enum.Font.GothamBold
                    unitLabel.Parent = mainFrame
                    
                    local barBackground = Instance.new("Frame")
                    barBackground.Name = "BarBackground"
                    barBackground.Size = UDim2.new(0.8, 0, 0, 5)
                    barBackground.Position = UDim2.new(0.1, 0, 0.85, 0)
                    barBackground.BackgroundColor3 = Color3.fromRGB(40, 40, 50)
                    barBackground.BorderSizePixel = 0
                    barBackground.Parent = mainFrame
                    
                    local barCorner = Instance.new("UICorner")
                    barCorner.CornerRadius = UDim.new(0, 3)
                    barCorner.Parent = barBackground
                    
                    local barFill = Instance.new("Frame")
                    barFill.Name = "BarFill"
                    barFill.Size = UDim2.new(0, 0, 1, 0)
                    barFill.BackgroundColor3 = Color3.fromRGB(0, 204, 255)
                    barFill.BorderSizePixel = 0
                    barFill.Parent = barBackground
                    
                    local fillCorner = Instance.new("UICorner")
                    fillCorner.CornerRadius = UDim.new(0, 3)
                    fillCorner.Parent = barFill
                    
                    local currentSpeed = 0
                    local currentMoveDir = Vector3.new(0, 0, 0) -- 실시간 미끄러짐 진행 방향을 저장할 벡터 변수
                    
                    diedConnection = humanoid.Died:Connect(function()
                        exitVehicle()
                    end)
                    
                    loopConnection = RunService.Heartbeat:Connect(function(dt)
                        if not car or not seat or not hrp or not primary then return end
                        
                        -- ★ 회전 관성 완전 제거
                        primary.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                        
                        hrp.AssemblyLinearVelocity = primary.AssemblyLinearVelocity
                        hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                        
                        hrp.CFrame = seat.CFrame * CFrame.new(0, 3, 0)
                        
                        -- A/D 누르는 동안만 회전 (누적 X)
                        local rotInput = 0
                        if UserInputService:IsKeyDown(Enum.KeyCode.A) then rotInput = rotInput + 1 end
                        if UserInputService:IsKeyDown(Enum.KeyCode.D) then rotInput = rotInput - 1 end
                        
                        local absSpeed = math.abs(currentSpeed)
                        
                        -- [드리프트 판정] 쉬프트 입력 + 회전 입력 + 속도 임계값 이상
                        local isDrifting = false
                        local shiftPressed = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
                        if shiftPressed and rotInput ~= 0 and absSpeed > 25 then
                            isDrifting = true
                        end
                        
                        -- [회전 로직] 속도에 맞춘 자연스러운 회전
                        local turnFactor = 0
                        if absSpeed > 0.1 then
                            if absSpeed < 45 then
                                turnFactor = 0.15 + (absSpeed / 45) * 0.85
                            else
                                turnFactor = math.clamp(1.0 - ((absSpeed - 45) / 155) * 0.6, 0.4, 1.0)
                            end
                        else
                            turnFactor = 0.15
                        end
                        
                        -- 후진 시 조향 방향 반전
                        local directionSign = currentSpeed >= 0 and 1 or -1
                        
                        if rotInput ~= 0 then
                            -- 드리프트 중일 때는 회전 조향력이 1.65배 향상되어 뒷꼬리가 더 급격히 흘러나갑니다.
                            local driftTurnMultiplier = isDrifting and 1.65 or 1.0
                            local finalTurnSpeed = 2.4 * turnFactor * directionSign * driftTurnMultiplier
                            primary.CFrame = primary.CFrame * CFrame.Angles(0, rotInput * finalTurnSpeed * dt, 0)
                        end
                        
                        -- 이동 방향 설정 (W/S 입력 감지)
                        local rawLook = primary.CFrame.LookVector
                        local forwardVector = Vector3.new(rawLook.X, 0, rawLook.Z).Unit
                        
                        local targetSpeed = 0
                        local hasInput = false
                        
                        if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                            targetSpeed = maxSpeed
                            hasInput = true
                        elseif UserInputService:IsKeyDown(Enum.KeyCode.S) then
                            targetSpeed = -maxSpeed * 0.5 
                            hasInput = true
                        end
                        
                        if hasInput then
                            if (targetSpeed > 0 and currentSpeed < 0) or (targetSpeed < 0 and currentSpeed > 0) then
                                local brakeDir = targetSpeed > 0 and 1 or -1
                                currentSpeed = currentSpeed + (brakeDir * decelRate * dt)
                            else
                                local speedRatio = math.clamp(math.abs(currentSpeed) / math.abs(targetSpeed), 0, 1)
                                local accelFactor = 1 - (math.pow(speedRatio, 0.7) * 0.88)
                                local finalAccel = baseAccel * accelFactor
                                
                                if targetSpeed > 0 then
                                    currentSpeed = math.min(currentSpeed + (finalAccel * dt), targetSpeed)
                                else
                                    currentSpeed = math.max(currentSpeed - (finalAccel * dt), targetSpeed)
                                end
                            end
                        else
                            if currentSpeed > 0 then
                                currentSpeed = math.max(currentSpeed - (decelRate * 0.4 * dt), 0)
                            elseif currentSpeed < 0 then
                                currentSpeed = math.min(currentSpeed + (decelRate * 0.4 * dt), 0)
                            end
                        end
                        
                        -- ==================== 🏎️ 드리프트 관성 물리 적용 ====================
                        local targetMoveDir = forwardVector * (currentSpeed >= 0 and 1 or -1)
                        
                        -- 차량이 거의 멈춰 있거나 초기 상태일 때는 정렬 상태를 즉시 맞춤
                        if absSpeed < 5 or currentMoveDir.Magnitude == 0 then
                            currentMoveDir = targetMoveDir
                        end
                        
                        if isDrifting then
                            -- 드리프트 슬립: 차체는 돌아갔으나 움직이는 관성 벡터가 늦게 따라옴
                            -- 이 수치(2.1)가 낮을수록 더 부드럽고 넓은 반경으로 미끄러집니다.
                            local driftSlipRate = 2.1
                            currentMoveDir = currentMoveDir:Lerp(targetMoveDir, driftSlipRate * dt)
                        else
                            -- 일반 그립 주행: 타이어 접지력이 복구되면서 빠르게 조향 방향으로 정렬
                            local gripRate = 12.0
                            currentMoveDir = currentMoveDir:Lerp(targetMoveDir, gripRate * dt)
                        end
                        
                        if currentMoveDir.Magnitude > 0 then
                            currentMoveDir = currentMoveDir.Unit
                        end
                        
                        if math.abs(currentSpeed) > 0.1 then
                            primary.AssemblyLinearVelocity = currentMoveDir * math.abs(currentSpeed) + Vector3.new(0, primary.AssemblyLinearVelocity.Y, 0)
                        else
                            primary.AssemblyLinearVelocity = Vector3.new(0, primary.AssemblyLinearVelocity.Y, 0)
                        end
                        
                        -- ==================== 📊 실시간 계기판 UI 업데이트 ====================
                        if speedometerGui and mainFrame then
                            local displaySpeed = math.floor(absSpeed)
                            speedLabel.Text = tostring(displaySpeed)
                            
                            local colorRatio = math.clamp(absSpeed / maxSpeed, 0, 1)
                            local baseColor = Color3.fromRGB(0, 204, 255) 
                            local highColor = Color3.fromRGB(255, 45, 90) 
                            local targetColor = baseColor:Lerp(highColor, colorRatio)
                            
                            speedLabel.TextColor3 = targetColor
                            unitLabel.TextColor3 = targetColor
                            uiStroke.Color = targetColor
                            barFill.BackgroundColor3 = targetColor
                            barFill.Size = UDim2.new(colorRatio, 0, 1, 0)
                            
                            -- 드리프트 경고등 상태 변경
                            if isDrifting then
                                driftLabel.TextTransparency = 0
                                driftStroke.Transparency = 0.2
                                -- 깜빡깜빡 비주얼 연출 추가 (초당 15회 반전)
                                local flash = math.sin(tick() * 18) > 0
                                driftLabel.TextColor3 = flash and Color3.fromRGB(255, 102, 0) or Color3.fromRGB(255, 255, 255)
                                if driftStroke then
                                    driftStroke.Color = flash and Color3.fromRGB(255, 102, 0) or Color3.fromRGB(255, 255, 255)
                                end
                            else
                                driftLabel.TextTransparency = 1
                                driftStroke.Transparency = 1
                            end
                        end
                    end)
                    
                    -- [V키 바로세우기 및 Space바 하차 입력 이벤트]
                    jumpConnection = UserInputService.InputBegan:Connect(function(input, gp)
                        if gp then return end
                        if input.KeyCode == Enum.KeyCode.Space then
                            exitVehicle()
                        elseif input.KeyCode == Enum.KeyCode.V then
                            if car and primary then
                                local currentCFrame = primary.CFrame
                                local position = currentCFrame.Position
                                
                                local look = currentCFrame.LookVector
                                local flatLook = Vector3.new(look.X, 0, look.Z)
                                
                                if flatLook.Magnitude < 0.1 then
                                    flatLook = Vector3.new(0, 0, -1)
                                else
                                    flatLook = flatLook.Unit
                                end
                                
                                local upCFrame = CFrame.lookAt(
                                    position + Vector3.new(0, 10, 0),
                                    position + Vector3.new(0, 10, 0) + flatLook
                                )
                                
                                primary.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                                primary.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                                hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                                hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                                currentSpeed = 0 
                                
                                car:SetPrimaryPartCFrame(upCFrame)
                                print("🔧 [V] 차량을 수평으로 똑바로 세우고 +10 스터드 스폰 완료!")
                            end
                        end
                    end)
                    
                    print("🚗 탑승 완료! WASD 운전 / Space 하차 / V 바로세우기 / Shift 드리프트")
                else
                    exitVehicle()
                end
            end)
        else
            warn("❌ Seat 오브젝트를 찾을 수 없습니다.")
        end
    end
})

LBox:AddButton({
    Text = "배 소환",
    Callback = function()
        print("🛥️ 요트 로드 시도 중...")
        
        -- 기존 요트 제거
        for _, child in ipairs(workspace:GetChildren()) do
            if child.Name:find("Yacht_") or child.Name == "Boat" or child.Name == "Yacht_Custom" then
                child:Destroy()
            end
        end

        local boat = nil
        local container = nil
        local assetList = { 72749250087738, 106844475991344, 128218651198278, 8989324783 }

        -- 1. 마켓플레이스 에셋 다중 로드 시도
        for _, id in ipairs(assetList) do
            local success, result = pcall(function()
                return game:GetObjects("rbxassetid://" .. id)
            end)
            if success and result and #result > 0 then
                container = result
                print("✅ 에셋 로드 성공! ID:", id)
                break
            end
        end

        local function findBoatModel(obj)
            if not obj then return nil end
            if typeof(obj) == "table" then obj = obj[1] end
            if not obj then return nil end
            if obj:IsA("Model") then return obj end
            if obj:IsA("Folder") then
                local found = obj:FindFirstChildWhichIsA("Model", true)
                if found then return found end
            end
            if obj:FindFirstChildWhichIsA("BasePart", true) then return obj end
            return nil
        end

        if container then
            boat = findBoatModel(container)
        end

        -- 2. 에셋 차단/실패 시 100% 보장되는 동적 커스텀 요트 스폰 폴백!
        if not boat then
            print("⚓ 외부 에셋 로드 제한 감지: 100% 커스텀 스피드 요트 생성!")
            boat = Instance.new("Model")
            boat.Name = "Yacht_Custom"

            local hull = Instance.new("Part")
            hull.Name = "Hull"
            hull.Size = Vector3.new(14, 4, 34)
            hull.Color = Color3.fromRGB(15, 25, 40)
            hull.Material = Enum.Material.SmoothPlastic
            hull.Parent = boat

            local bow = Instance.new("WedgePart")
            bow.Name = "Bow"
            bow.Size = Vector3.new(14, 4, 12)
            bow.Color = Color3.fromRGB(15, 25, 40)
            bow.Material = Enum.Material.SmoothPlastic
            bow.CFrame = hull.CFrame * CFrame.new(0, 0, -23) * CFrame.Angles(0, math.rad(180), 0)
            bow.Parent = boat

            local weldBow = Instance.new("WeldConstraint")
            weldBow.Part0 = hull weldBow.Part1 = bow weldBow.Parent = bow

            local seat = Instance.new("VehicleSeat")
            seat.Name = "CaptainSeat"
            seat.Size = Vector3.new(4, 2, 4)
            seat.CFrame = hull.CFrame * CFrame.new(0, 3, -4)
            seat.Color = Color3.fromRGB(0, 220, 255)
            seat.Material = Enum.Material.Neon
            seat.Parent = boat

            local weldSeat = Instance.new("WeldConstraint")
            weldSeat.Part0 = hull weldSeat.Part1 = seat weldSeat.Parent = seat

            boat.PrimaryPart = hull
        end

        if boat.Parent then boat.Parent = nil end
        boat.Parent = workspace
        if boat.Name == "Model" or boat.Name == "Folder" then
            boat.Name = "Yacht_Loaded"
        end

        -- 스크립트 활성화
        for _, obj in ipairs(boat:GetDescendants()) do
            if obj:IsA("Script") or obj:IsA("LocalScript") then
                obj.Disabled = false
            end
        end

        -- 1. 모든 파트 보존 및 PrimaryPart 설정 (위치 이동 완료 전까지 Anchored = true 유지!)
        local allParts = {}
        for _, part in ipairs(boat:GetDescendants()) do
            if part:IsA("BasePart") then
                part.Anchored = true
                table.insert(allParts, part)
            end
        end

        local primary = nil
        local maxVol = 0
        for _, p in ipairs(allParts) do
            local v = p.Size.X * p.Size.Y * p.Size.Z
            if v > maxVol then maxVol = v primary = p end
        end

        if primary then
            boat.PrimaryPart = primary
            primary.CustomPhysicalProperties = PhysicalProperties.new(0.01, 0.3, 0.5, 1, 1) -- 초경량 선체 부력 극대화 (물 밀도 1.0 대비 0.01)
            
            -- 하부 용접 킬 발라스트 (무게중심 복원력 유지 + 적정 중량 조정)
            local ballast = Instance.new("Part")
            ballast.Name = "ENI_KeelBallast"
            ballast.Size = Vector3.new(10, 6, 32)
            ballast.Transparency = 1
            ballast.CanCollide = false
            ballast.CFrame = primary.CFrame * CFrame.new(0, -14, 0)
            ballast.Parent = boat
            
            local ballastWeld = Instance.new("WeldConstraint")
            ballastWeld.Part0 = ballast
            ballastWeld.Part1 = primary
            ballastWeld.Parent = ballast
            
            ballast.CustomPhysicalProperties = PhysicalProperties.new(3.5, 0.3, 0.5, 1, 1) -- 부력을 방해하지 않는 최적 복원 중량
            
            -- X, Z축 안티-전복 복원력 BodyGyro (넘어짐 방지 & Y축 회전 자유)
            local bodyGyro = primary:FindFirstChild("ENI_SoftGyro") or Instance.new("BodyGyro", primary)
            bodyGyro.Name = "ENI_SoftGyro"
            bodyGyro.MaxTorque = Vector3.new(450000, 0, 450000)
            bodyGyro.P = 5000
            bodyGyro.D = 800
            
            -- 수중 동적 부력 장치 (현실적인 바다 수면 깊이 연동)
            local buoyancyForce = primary:FindFirstChild("ENI_BuoyancyForce") or Instance.new("BodyForce", primary)
            buoyancyForce.Name = "ENI_BuoyancyForce"
            buoyancyForce.Force = Vector3.zero
        end

        -- 2. 선체 용접 처리
        for _, part in ipairs(allParts) do
            if part ~= primary and part.Parent == boat then
                local isCritical = part:FindFirstChildWhichIsA("VehicleSeat") or part:FindFirstChildWhichIsA("Seat")
                if not isCritical then
                    local hasJoint = false
                    for _, c in ipairs(part:GetChildren()) do
                        if c:IsA("Weld") or c:IsA("WeldConstraint") or c:IsA("Motor6D") then
                            hasJoint = true break
                        end
                    end
                    if not hasJoint then
                        local wc = Instance.new("WeldConstraint")
                        wc.Part0 = primary wc.Part1 = part wc.Parent = part
                    end
                end
            end
        end

        -- 3. 플레이어 위치 감지 및 안전한 스폰 위치 설정 (고정 상태에서 정확히 위치 지정!)
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local UserInputService = game:GetService("UserInputService")

        local LocalPlayer = Players.LocalPlayer or Players:GetPlayers()[1]
        local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        local hrp = character:WaitForChild("HumanoidRootPart")
        local humanoid = character:WaitForChild("Humanoid")

        local spawnCFrame = hrp.CFrame * CFrame.new(0, 5, -25)
        boat:PivotTo(spawnCFrame)

        -- 4. 위치 고정 완료 후 앵커 해제 & 오직 조타실 유리문만 노클립(CanCollide = false) 처리!
        for _, part in ipairs(allParts) do
            if part.Name ~= "ENI_KeelBallast" then
                part.Anchored = false
                
                local nameLower = part.Name:lower()
                -- 오직 '유리문 / 도어 / 입구'만 선택적 노클립! (창문 및 기타 부분은 충돌 유지)
                local isGlassDoor = nameLower:find("door") or nameLower:find("entrance") or nameLower:find("entry") or (nameLower:find("glass") and nameLower:find("door"))
                
                if isGlassDoor then
                    part.CanCollide = false
                    part.CanQuery = false
                    part.CanTouch = false
                else
                    part.CanCollide = true
                end
                
                part.CustomPhysicalProperties = PhysicalProperties.new(0.005, 0.3, 0.5, 1, 1) -- 초경량 공기층 선체 밀도 설정
            end
        end

        local engineSound = hrp:FindFirstChild("ENI_PublicEngineSound") or Instance.new("Sound")
        engineSound.Name = "ENI_PublicEngineSound"
        engineSound.SoundId = "rbxassetid://9112793704"
        engineSound.Volume = 1.2
        engineSound.PlaybackSpeed = 0.85
        engineSound.Looped = true
        engineSound.RollOffMaxDistance = 3500
        engineSound.Parent = hrp
        local seat = boat:FindFirstChildWhichIsA("VehicleSeat", true) or boat:FindFirstChildWhichIsA("Seat", true)

        if seat then
            local prompt = seat:FindFirstChildWhichIsA("ProximityPrompt") or Instance.new("ProximityPrompt", seat)
            prompt.RequiresLineOfSight = false
            prompt.MaxActivationDistance = 35
            prompt.HoldDuration = 0
            prompt.ActionText = "요트 조종"
            
            local isSitting = false
            local loopConnection = nil
            local diedConnection = nil
            local speedometerGui = nil 
            local maxSpeed = 180 local baseAccel = 80 local decelRate = 95     
            
            local function exitVehicle()
                if not isSitting then return end
                isSitting = false
                local sternThruster = primary and primary:FindFirstChild("ENI_SternThruster")
                if sternThruster then sternThruster.Force = Vector3.zero end
                if engineSound then engineSound:Stop() end
                if loopConnection then loopConnection:Disconnect() loopConnection = nil end
                if diedConnection then diedConnection:Disconnect() diedConnection = nil end
                if speedometerGui then speedometerGui:Destroy() speedometerGui = nil end 
                if humanoid then
                    humanoid.PlatformStand = false
                    humanoid.Sit = false
                end
                task.wait(0.05)
                if hrp and seat then
                    hrp.CFrame = seat.CFrame * CFrame.new(-6, 3, 0)
                end
                print("🚶 요트 하차 완료!")
            end

            local function enterVehicle()
                if isSitting then return end
                isSitting = true
                humanoid.PlatformStand = true 
                if engineSound and not engineSound.IsPlaying then engineSound:Play() end
                
                -- ★ 사망 시 자동 조종 해제
                diedConnection = humanoid.Died:Connect(function()
                    print("💀 플레이어 사망 감지: 조종 자동 해제!")
                    exitVehicle()
                end)
                
                -- 계기판 UI 생성
                speedometerGui = Instance.new("ScreenGui", LocalPlayer:WaitForChild("PlayerGui"))
                speedometerGui.Name = "YachtSpeedometerGui"
                
                local mainFrame = Instance.new("Frame", speedometerGui)
                mainFrame.Name = "MainFrame"
                mainFrame.Size = UDim2.new(0, 240, 0, 115)
                mainFrame.Position = UDim2.new(0.5, 0, 0.85, 0)
                mainFrame.AnchorPoint = Vector2.new(0.5, 0.5)
                mainFrame.BackgroundColor3 = Color3.fromRGB(10, 20, 30)
                mainFrame.BackgroundTransparency = 0.25
                mainFrame.BorderSizePixel = 0
                
                local uiCorner = Instance.new("UICorner", mainFrame)
                uiCorner.CornerRadius = UDim.new(0, 16)
                
                local uiStroke = Instance.new("UIStroke", mainFrame)
                uiStroke.Thickness = 2
                uiStroke.Color = Color3.fromRGB(0, 220, 255)
                uiStroke.Transparency = 0.3
                
                local driftLabel = Instance.new("TextLabel", mainFrame)
                driftLabel.Name = "DriftLabel"
                driftLabel.Size = UDim2.new(1, 0, 0.2, 0)
                driftLabel.Position = UDim2.new(0, 0, -0.25, 0)
                driftLabel.BackgroundTransparency = 1
                driftLabel.Text = "WAVE SURGE"
                driftLabel.TextColor3 = Color3.fromRGB(0, 255, 200)
                driftLabel.TextSize = 18
                driftLabel.Font = Enum.Font.GothamBold
                driftLabel.TextTransparency = 1
                
                local driftStroke = Instance.new("UIStroke", driftLabel)
                driftStroke.Thickness = 1.5
                driftStroke.Color = Color3.fromRGB(0, 255, 200)
                driftStroke.Transparency = 1
                
                local speedLabel = Instance.new("TextLabel", mainFrame)
                speedLabel.Name = "SpeedLabel"
                speedLabel.Size = UDim2.new(1, 0, 0.6, 0)
                speedLabel.Position = UDim2.new(0, 0, 0.1, 0)
                speedLabel.BackgroundTransparency = 1
                speedLabel.Text = "0"
                speedLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
                speedLabel.TextSize = 46
                speedLabel.Font = Enum.Font.GothamBold
                
                local unitLabel = Instance.new("TextLabel", mainFrame)
                unitLabel.Name = "UnitLabel"
                unitLabel.Size = UDim2.new(1, 0, 0.2, 0)
                unitLabel.Position = UDim2.new(0, 0, 0.65, 0)
                unitLabel.BackgroundTransparency = 1
                unitLabel.Text = "KNOTS"
                unitLabel.TextColor3 = Color3.fromRGB(0, 220, 255)
                unitLabel.TextSize = 13
                unitLabel.Font = Enum.Font.GothamBold
                
                local barBackground = Instance.new("Frame", mainFrame)
                barBackground.Name = "BarBackground"
                barBackground.Size = UDim2.new(0.85, 0, 0, 5)
                barBackground.Position = UDim2.new(0.075, 0, 0.85, 0)
                barBackground.BackgroundColor3 = Color3.fromRGB(20, 40, 60)
                barBackground.BorderSizePixel = 0
                
                local barCorner = Instance.new("UICorner", barBackground)
                barCorner.CornerRadius = UDim.new(0, 3)
                
                local barFill = Instance.new("Frame", barBackground)
                barFill.Name = "BarFill"
                barFill.Size = UDim2.new(0, 0, 1, 0)
                barFill.BackgroundColor3 = Color3.fromRGB(0, 220, 255)
                barFill.BorderSizePixel = 0
                
                local fillCorner = Instance.new("UICorner", barFill)
                fillCorner.CornerRadius = UDim.new(0, 3)
                
                local currentSpeed = 0
                local currentTurnRate = 0
                local bodyGyro = primary:FindFirstChild("ENI_SoftGyro")
                local maxSpeed = 180
                local accelRate = 95
                local decelRate = 110
                
                loopConnection = RunService.Heartbeat:Connect(function(dt)
                    if not boat or not seat or not hrp or not primary then return end
                    hrp.CFrame = seat.CFrame * CFrame.new(0, 2.5, 0)
                    
                    local rotInput = 0
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then rotInput = rotInput + 1 end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then rotInput = rotInput - 1 end
                    
                    local isDrifting = false
                    local shiftPressed = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
                    if shiftPressed and rotInput ~= 0 and math.abs(currentSpeed) > 15 then
                        isDrifting = true
                    end
                    
                    -- A/D 키 조향 로직
                    if rotInput ~= 0 then
                        local turnAccel = 3.5
                        currentTurnRate = math.clamp(currentTurnRate + (rotInput * turnAccel * dt), -1.5, 1.5)
                        local turnMultiplier = isDrifting and 1.65 or 1.0
                        primary.CFrame = primary.CFrame * CFrame.Angles(0, currentTurnRate * turnMultiplier * dt, 0)
                    else
                        -- A/D 키를 뗐을 때 회전 관성 및 회전각을 즉시 초기화하여 직진 시 옆으로 휘어지는 현상 100% 방지!
                        currentTurnRate = 0
                        primary.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                    end
                    
                    -- 바다 수면 수중 감지 및 실시간 동적 부력 연동 (공중 솟구침 100% 방지 & 강렬한 해상 부력 연출)
                    local oceanWaterLevel = -14
                    local buoyancyForce = primary:FindFirstChild("ENI_BuoyancyForce")
                    if buoyancyForce and primary then
                        local boatMass = 0
                        for _, p in ipairs(allParts) do boatMass = boatMass + p:GetMass() end
                        
                        local currentY = primary.Position.Y
                        local targetSurfaceY = oceanWaterLevel + 4.5 -- 수면 부력 목표 높이
                        
                        if currentY < targetSurfaceY then
                            -- 수면 아래로 잠길수록 강한 부력 작용 (수면으로 솟아오름)
                            local submergedDepth = targetSurfaceY - currentY
                            local dynamicLift = math.clamp(submergedDepth * boatMass * 45, 0, boatMass * workspace.Gravity * 1.5)
                            buoyancyForce.Force = Vector3.new(0, dynamicLift, 0)
                        else
                            -- 수면 위로 올라가거나 공중으로 뜨면 부력 0 (하늘로 날아가지 않고 즉시 수면 안착)
                            buoyancyForce.Force = Vector3.zero
                        end
                    end
                    
                    -- BodyGyro를 통한 선체 복원력 & 자연스러운 턴 뱅크 기울어짐 연출 (안티 전복 보장)
                    if bodyGyro then
                        local _, yRot, _ = primary.CFrame:ToOrientation()
                        local turnBank = (rotInput ~= 0) and (-currentTurnRate * 0.14) or 0
                        local accelPitch = (currentSpeed > 20) and -0.05 or 0
                        bodyGyro.CFrame = CFrame.Angles(accelPitch, yRot, turnBank)
                    end
                    
                    -- W / S 전진/후진 추진 물리
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                        currentSpeed = math.min(currentSpeed + (accelRate * dt), maxSpeed)
                    elseif UserInputService:IsKeyDown(Enum.KeyCode.S) then
                        currentSpeed = math.max(currentSpeed - (decelRate * dt), -maxSpeed * 0.45)
                    else
                        if currentSpeed > 0 then currentSpeed = math.max(currentSpeed - (decelRate * dt), 0)
                        elseif currentSpeed < 0 then currentSpeed = math.min(currentSpeed + (decelRate * dt), 0) end
                    end
                    
                    -- 선체 주행 물리 속도 적용
                    local rawSeatLook = seat.CFrame.LookVector
                    local forwardVector = Vector3.new(rawSeatLook.X, 0, rawSeatLook.Z).Unit
                    
                    if math.abs(currentSpeed) > 0.1 then
                        local moveVel = forwardVector * currentSpeed
                        primary.AssemblyLinearVelocity = Vector3.new(moveVel.X, primary.AssemblyLinearVelocity.Y, moveVel.Z)
                    else
                        primary.AssemblyLinearVelocity = Vector3.new(0, primary.AssemblyLinearVelocity.Y, 0)
                    end
                    
                    local realSpeed = math.abs(currentSpeed)
                    
                    if engineSound then
                        local speedRatio = math.clamp(realSpeed / maxSpeed, 0, 1)
                        engineSound.Volume = math.clamp(1.2 + (speedRatio * 8.8), 1.2, 10.0) -- 주행 속도 증가 시 볼륨 1.2에서 10.0으로 확 커짐
                        engineSound.PlaybackSpeed = math.clamp(0.85 + (speedRatio * 0.95), 0.85, 1.8) -- 주행 속도 증가 시 피치/템포 상승
                    end
                    
                    if speedometerGui and mainFrame then
                        local displaySpeed = math.floor(realSpeed)
                        speedLabel.Text = tostring(displaySpeed)
                        
                        local colorRatio = math.clamp(realSpeed / maxSpeed, 0, 1)
                        local baseColor = Color3.fromRGB(0, 220, 255) 
                        local highColor = Color3.fromRGB(0, 255, 170) 
                        local targetColor = baseColor:Lerp(highColor, colorRatio)
                        
                        speedLabel.TextColor3 = targetColor
                        unitLabel.TextColor3 = targetColor
                        uiStroke.Color = targetColor
                        barFill.BackgroundColor3 = targetColor
                        barFill.Size = UDim2.new(colorRatio, 0, 1, 0)
                        
                        if isDrifting then
                            driftLabel.TextTransparency = 0
                            driftStroke.Transparency = 0.2
                            local flash = math.sin(tick() * 18) > 0
                            driftLabel.TextColor3 = flash and Color3.fromRGB(0, 255, 200) or Color3.fromRGB(255, 255, 255)
                            if driftStroke then driftStroke.Color = flash and Color3.fromRGB(0, 255, 200) or Color3.fromRGB(255, 255, 255) end
                        else
                            driftLabel.TextTransparency = 1
                            driftStroke.Transparency = 1
                        end
                    end
                end)
            end

            prompt.Triggered:Connect(function(player)
                if player ~= LocalPlayer then return end
                if not isSitting then enterVehicle() else exitVehicle() end
            end)
            
            enterVehicle()
        else
            warn("❌ Seat 오브젝트를 찾을 수 없습니다.")
        end
    end
})

-- ============================================================================
-- 해상 수면 전용 느리고 가끔씩(15~30초 무작위 간격) 들리는 갈매기 소리
-- ============================================================================
task.spawn(function()
    local Players = game:GetService("Players")
    local SoundService = game:GetService("SoundService")

    local LocalPlayer = Players.LocalPlayer or Players:GetPlayers()[1]
    
    local seagullSound = SoundService:FindFirstChild("ENI_OceanSeagullSound") or Instance.new("Sound")
    seagullSound.Name = "ENI_OceanSeagullSound"
    seagullSound.SoundId = "rbxassetid://110613799508740"
    seagullSound.Volume = 0.28 -- 은은하고 아주 작은 볼륨
    seagullSound.PlaybackSpeed = 0.58 -- 훨씬 더 느리고 잔잔한 템포 (0.58)
    seagullSound.Looped = false -- 연속 반복 끔 (가끔씩 1회성 울림)
    seagullSound.Parent = SoundService

    while true do
        -- 가끔씩(15~30초 무작위 간격) 울리도록 쿨다운 대기
        task.wait(math.random(15, 30))
        
        local character = LocalPlayer.Character
        if character and character:FindFirstChild("HumanoidRootPart") then
            local hrp = character.HumanoidRootPart
            local humanoid = character:FindFirstChildWhichIsA("Humanoid")
            
            -- 1. 발밑 파트 감지
            local raycastParams = RaycastParams.new()
            raycastParams.FilterType = Enum.RaycastFilterType.Exclude
            raycastParams.FilterDescendantsInstances = {character}
            
            local floorRay = workspace:Raycast(hrp.Position, Vector3.new(0, -6, 0), raycastParams)
            local floorPart = floorRay and floorRay.Instance
            
            -- 2. 요트/배 파트 감지 여부
            local isStandingOnBoat = false
            if floorPart then
                local model = floorPart:FindFirstAncestorWhichIsA("Model")
                if model and (model.Name:find("Yacht") or model.Name:find("Boat") or model.Name:find("Ship") or model.Name:find("Vehicle")) then
                    isStandingOnBoat = true
                elseif floorPart.Name:find("Yacht") or floorPart.Name:find("Boat") or floorPart.Name:find("ENI_") then
                    isStandingOnBoat = true
                end
            end
            
            -- 3. 일반 맵 땅/육지 밟음 여부 (요트가 아니면 true)
            local isStandingOnMapLand = false
            if floorRay and not isStandingOnBoat then
                if floorRay.Material ~= Enum.Material.Water then
                    isStandingOnMapLand = true
                end
            end
            
            -- 4. 바다 위치 및 탑승/수중 상태 조건
            local isSittingInSeat = humanoid and humanoid.Sit
            local isSwimmingInWater = humanoid and (humanoid:GetState() == Enum.HumanoidStateType.Swimming)
            local isOverOceanArea = hrp.Position.Y < 35 and math.abs(hrp.Position.X) < 6000 and math.abs(hrp.Position.Z) < 6000
            
            -- 맵 땅을 밟고 있지 않으며 요트나 바다에 있을 때만 1회성으로 느리고 은은하게 재생!
            if not isStandingOnMapLand and (isStandingOnBoat or isSittingInSeat or isSwimmingInWater or isOverOceanArea) then
                seagullSound.Volume = 0.28
                seagullSound.PlaybackSpeed = 0.58
                seagullSound:Play()
            end
        end
    end
end)


LBox:AddImage("AddImage", {Image = 0,Height = 0,})

LBox:AddToggle("루프 리셋", {
