                                task.spawn(function() rs.MenuToys.SpawnToyRemoteFunction:InvokeServer(tn, myPO.CFrame * CFrame.new(0, 3, 20), Vector3.zero) end)
                                tnf = toys:WaitForChild(tn, 0.5) or (inv and inv:WaitForChild(tn, 0.5))
                            end
                            if tnf then
                                local sPart = tnf:WaitForChild("StickyPart", 0.5)
                                local sPartPO = tnf:FindFirstChild("PartOwner") -- ?.. How
                                if sPart then
                                    if not sPartPO then rs.GrabEvents.SetNetworkOwner:FireServer(sPart, CFrame.lookAt(myPO.Position, sPart.Position)) end
                                    if sPartPO and sPartPO.Value ~= plr.Name then rs.MenuToys.DestroyToy:FireServer(tnf) end
                                    rs.PlayerEvents.StickyPartEvent:FireServer(sPart, pp.raghit, CFrame.new(0.1, -0.3, 0.3) * CFrame.Angles(math.rad(90), 0, 0))
                                    task.wait(0.3)
                                    while AntiFlyingValue and tnf.Parent and task.wait() do
                                        if not AntiFlyingS.Value["NinjaShuriken"] then break end
