                            if not tnf and ctoy.Value then
                                task.spawn(function() rs.MenuToys.SpawnToyRemoteFunction:InvokeServer(tn, myPO.CFrame * CFrame.new(0, 3, 20), Vector3.zero) end)
                                tnf = toys:WaitForChild(tn, 0.5) or (inv and inv:WaitForChild(tn, 0.5))
                            end
                            if tnf then
                                local sPart = tnf:WaitForChild("StickyPart", 0.5)
                                local sdPart = tnf:WaitForChild("SoundPart", 0.5)
                                local sPartPO = tnf:FindFirstChild("PartOwner") -- ?.. How
                                if sPart then
                                    if not sPartPO then rs.GrabEvents.SetNetworkOwner:FireServer(sdPart, CFrame.lookAt(myPO.Position, sdPart.Position)) end
                                    if sPartPO and sPartPO.Value ~= plr.Name then rs.MenuToys.DestroyToy:FireServer(tnf) end
                                    rs.PlayerEvents.StickyPartEvent:FireServer(sPart, pp.raghit, CFrame.new(0.05, -1.2, -0.3) * CFrame.Angles(math.rad(180), 0, 0))
                                    task.wait(0.3)
                                    while AntiFlyingValue and tnf.Parent and task.wait() do
                                        if not AntiFlyingS.Value["ToolPencil"] then break end
                                        local weld = sPart:FindFirstChild("StickyWeld")
                                        if not weld or weld.Part1 ~= pp.raghit then break end
                                    end
                                    rs.MenuToys.DestroyToy:FireServer(tnf)
                                end
                            end
                        end
                    end
                end)
            end
        else
            local AntiKickToy = (toys and toys:FindFirstChild("NinjaShuriken")) or (inv and inv:FindFirstChild("NinjaShuriken"))
            if AntiKickToy then rs.MenuToys.DestroyToy:FireServer(AntiKickToy) end
