local processedItems = {} 
LBox:AddToggle("AntiHoldPart", {
    Text = "안티 홀드",
    Default = false,
    Callback = function(Value)

        if AntiHoldPartS.SetDisabled then 
            AntiHoldPartS:SetDisabled(not Value) 
        end

        if AntiHoldPartC then 
            AntiHoldPartC:Disconnect() 
            AntiHoldPartC = nil
        end

        if Value then
            AntiHoldPartC = rs2.PreSimulation:Connect(function()
                if not pp.char or not pp.hrp then return end

                local myPlotNumber = nil
                local plotsFolder = workspace:FindFirstChild("Plots")
                if plotsFolder then
                    for i = 1, 5 do
                        local plot = plotsFolder:FindFirstChild("Plot" .. i)
                        local sign = plot and plot:FindFirstChild("PlotSign")
                        local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
                        local ownerVal = owners and owners:FindFirstChildOfClass("StringValue")
                        if ownerVal and ownerVal.Value == plr.Name then
                            myPlotNumber = i
                            break
                        end
                    end
                end

                local itemsToProcess = {}

                for _, otherPlayer in ipairs(game.Players:GetPlayers()) do
                    if otherPlayer == plr then continue end
                    local folder = workspace:FindFirstChild(otherPlayer.Name .. "SpawnedInToys")
                    if folder then
                        for _, item in ipairs(folder:GetChildren()) do
                            if AntiHoldPartV[item.Name] and not processedItems[item] then
                                table.insert(itemsToProcess, item)
                            end
                        end
                    end
                end

                local plotItemsFolder = workspace:FindFirstChild("PlotItems")
                if plotItemsFolder then
                    for i = 1, 5 do
                        if i == myPlotNumber then continue end
                        local plot = plotItemsFolder:FindFirstChild("Plot" .. i)
                        if plot then
                            for _, item in ipairs(plot:GetChildren()) do
                                if AntiHoldPartV[item.Name] and not processedItems[item] then
                                    table.insert(itemsToProcess, item)
                                end
                            end
                        end
                    end
                end

                for _, item in ipairs(itemsToProcess) do
                    local holdPart = item:FindFirstChild("HoldPart")
                    local holdRemote = holdPart and holdPart:FindFirstChild("HoldItemRemoteFunction")
                    local dropRemote = holdPart and holdPart:FindFirstChild("DropItemRemoteFunction")

                    if holdRemote and dropRemote then
                        processedItems[item] = true

                        task.spawn(function()
                            local success = pcall(function()
                                holdRemote:InvokeServer(item, pp.char)
                                dropRemote:InvokeServer(item, CFrame.new(0/0,0/0,0/0), Vector3.new(0/0,0/0,0/0))
                            end)
                            processedItems[item] = nil
                        end)
                    end
                end
            end)
        end
    end
})

