LBox:AddToggle("AntiExplode", {
    Text = "안티 폭발",
    Default = false,
    Callback = function(Value)
        if Value then
            AntiExplodeC = rs.BombEvents.BombExplode.OnClientEvent:Connect(function(table, pos)
                if not AntiExplodeC then return end
                local model = table["Model"]
                task.spawn(function()
                    if not (table["Radius"] + 10 > (pos - pp.torso.Position).Magnitude) then return end
                    if pp.hum.SeatPart then
                        pp.torso.Anchored = true
                        task.wait(0.03)
                        pp.torso.AssemblyLinearVelocity = Vector3.zero
                        pp.torso.AssemblyAngularVelocity = Vector3.zero
                        pp.torso.Anchored = false
                    else
                        local ragStart = tick()
                        repeat rs2.PreSimulation:Wait() until pp.rag.Value or tick() - ragStart > 0.2
                        if not pp.rag.Value then return end
                        pp.torso.Anchored = true
                        pp.hum:ChangeState(Enum.HumanoidStateType.Running)
                        pp.torso.Anchored = false
                        pp.hum.AutoRotate = true
                        repeat
                            rs2.PreSimulation:Wait()
                            if pp.head then
                                pp.head.CFrame = pp.hrp.CFrame * CFrame.new(0, 1.5, 0)
                                pp.head_c.MaxFrictionTorque = math.huge
                            end
                            if pp.la then
                                pp.la.CFrame = pp.hrp.CFrame * CFrame.new(-1.5, 0, 0)
                                pp.la_p.CanCollide = false
                                pp.la.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0, 0, 0, 0)
                            end
                            if pp.ra then
                                pp.ra.CFrame = pp.hrp.CFrame * CFrame.new(1.5, 0, 0)
                                pp.ra_p.CanCollide = false
                                pp.ra.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0, 0, 0, 0)
                            end
                            if pp.ll then
                                pp.ll.CFrame = pp.hrp.CFrame * CFrame.new(-0.5, -2, 0)
                                pp.ll_p.CanCollide = false
                                pp.ll.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0, 0, 0, 0)
                            end
                            if pp.rl then
                                pp.rl.CFrame = pp.hrp.CFrame * CFrame.new(0.5, -2, 0)
                                pp.rl_p.CanCollide = false
                                pp.rl.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0, 0, 0, 0)
                            end
                        until not pp.rag.Value
                        if pp.head then pp.head_c.MaxFrictionTorque = 20 end
                        if pp.la then pp.la.CustomPhysicalProperties = nil end
                        if pp.ra then pp.ra.CustomPhysicalProperties = nil end
                        if pp.ll then pp.ll.CustomPhysicalProperties = nil end
                        if pp.rl then pp.rl.CustomPhysicalProperties = nil end
                    end
                end)
            end)
        else
            if AntiExplodeC then
                AntiExplodeC:Disconnect()
                AntiExplodeC = nil
            end
        end
    end
})

