RBox:AddButton({
    Text = "베리어 브레이커",
    Callback = function(Value)
        if PBDrun then return end
        PBDrun = true
        if not pp.char or not pp.torso then PBDrun = false return end
        task.spawn(function() rs.MenuToys.SpawnToyRemoteFunction:InvokeServer("BallSnowball", pp.torso.CFrame * CFrame.new(0,10,20), Vector3.zero) end)
        local stick = tick()
        repeat rs2.PreSimulation:Wait() until inv:FindFirstChild("BallSnowball") or tick() - stick > 0.2
        local snowball = inv and inv:FindFirstChild("BallSnowball")
        if not snowball then PBDrun = false return end
        local stick2 = tick()
        repeat rs2.PreSimulation:Wait() until (snowball and snowball:FindFirstChild("SoundPart")) or not snowball or tick() - stick2 > 0.2
        if not snowball or not snowball.Parent then PBDrun = false return end
        local SoundPart = snowball:FindFirstChild("SoundPart")
        if not SoundPart then PBDrun = false return end
        repeat rs2.PreSimulation:Wait()
            if not snowball or not snowball.Parent or not SoundPart or not SoundPart.Parent then PBDrun = false return end
            rs.GrabEvents.SetNetworkOwner:FireServer(SoundPart, CFrame.lookAt(pp.torso.Position, SoundPart.Position))
        until SoundPart:FindFirstChild("PartOwner")
        if not snowball or not snowball.Parent or not SoundPart or not SoundPart.Parent then PBDrun = false return end
        SoundPart.CFrame = workspace.Plots.Plot1.TeslaCoil.Metal.CFrame * CFrame.new(0,10,0)
        task.wait(0.15)
        if not snowball or not snowball.Parent then PBDrun = false return end
        rs.BombEvents.BombExplode:FireServer({Radius = 0, Color = Color3.new(0,0,0), TimeLength = 0, Model = snowball, Type = "SnowPoof", ExplodesByFire = false, MaxForcePerStudSquared = 0, Hitbox = SoundPart, ImpactSpeed = 0, ExplodesByPointy = false, DestroysModel = true, PositionPart = SoundPart}, Vector3.new(0,0,0))
        Library:Notify({Title = "[ Ω.SAYS ]", Description = "DONE.", BigIcon = "circle-check", IconColor = Color3.new(1,1,1), Time = 3})
        repeat rs2.PreSimulation:Wait() until ctoy.Value
        PBDrun = false
    end
})

