local workspace = workspace
local FindFirstChild = workspace.FindFirstChild
local LookAt = CFrame.lookAt
local Heartbeat = rs2.Heartbeat
local SetNetworkOwner = rs.GrabEvents.SetNetworkOwner
local FireServer = SetNetworkOwner.FireServer

-- 핑을 안정적으로 유지하면서 도달할 수 있는 실전 최대 속도 600Hz 설정
local MAX_FIRE_RATE = 600
local RATE_LIMIT_INTERVAL = 1 / MAX_FIRE_RATE

RBox:AddToggle("LoopGrab", {
    Text = "루프 그랩",
    Default = false,
    Callback = function(Value)
        if LoopGrabC then
            LoopGrabC:Disconnect()
            LoopGrabC = nil
        end

        if Value then
            -- 메모리 할당 최소화용 로컬 캐싱
            local grabParts = FindFirstChild(workspace, "GrabParts")
            local grabPart = grabParts and FindFirstChild(grabParts, "GrabPart")
            local weld = grabPart and FindFirstChild(grabPart, "WeldConstraint")
            
            -- 타임스탬프 변수 초기화
            local lastFireTime = 0

            LoopGrabC = Heartbeat:Connect(function()
                local char = pp.char
                local torso = pp.torso
                if not char or not torso then return end

                -- 실시간 캐시 복구
                if not weld or not weld.Parent or not grabParts or not grabParts.Parent then
                    grabParts = FindFirstChild(workspace, "GrabParts")
                    grabPart = grabParts and FindFirstChild(grabParts, "GrabPart")
                    weld = grabPart and FindFirstChild(grabPart, "WeldConstraint")
                    if not weld then return end
                end

                local target = weld.Part1
                if target and target.Parent then
                    local currentTime = os.clock()
                    local targetCFrame = LookAt(torso.Position, target.Position)
                    
                    -- [600Hz 오버클럭 루프]
                    -- 프레임당 최대 10번 연속 호출하여 저프레임 환경에서도 무조건 600Hz의 일관된 난사 속도를 보장합니다.
                    -- 핑 지연을 방지하기 위해 0.0016초 간격을 정밀하게 준수하여 소유권을 독점합니다.
                    for i = 1, 10 do
                        if currentTime - lastFireTime >= RATE_LIMIT_INTERVAL then
                            lastFireTime = currentTime
                            FireServer(SetNetworkOwner, target, targetCFrame)
                        else
                            break
                        end
                    end
                end
            end)
        end
    end
})

RBox:AddToggle("KillGrab", {
    Text = "킬 그랩",
    Default = false,
    Callback = function(Value)

        if KillGrabS.SetDisabled then 
            KillGrabS:SetDisabled(not Value)
        end

        if Value then
            if KillGrabC then KillGrabC:Disconnect() end

            KillGrabC = rs2.Heartbeat:Connect(function()
                if not pp.char or not pp.torso then return end
                local GrabParts = workspace:FindFirstChild("GrabParts")
                if not GrabParts then return end

                local WeldConstraint = GrabParts.GrabPart:FindFirstChild("WeldConstraint")
                if not WeldConstraint then return end

                local Target = WeldConstraint.Part1
                local Tchar = Target.Parent
                if not Tchar then return end

                local Thum = Tchar.Humanoid
                local Thrp = Tchar:FindFirstChild("HumanoidRootPart")
                if not Thrp then return end
                local Ttorso = Tchar.Torso

                if Thrp and Tchar and KillGrabV == "None" then
                Thum.BreakJointsOnDeath = false
                Thum:ChangeState(Enum.HumanoidStateType.Dead)
                rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(pp.torso.Position, Ttorso.Position))
                rs.GrabEvents.DestroyGrabLine:FireServer(Ttorso)
                end

                if Thrp and Tchar and KillGrabV == "Void" then
				if not Thrp or Thum.Health <= 0 then GrabParts:Destroy() end
				WeldConstraint.Part0 = nil
                Thum.BreakJointsOnDeath = false
                Thum:ChangeState(Enum.HumanoidStateType.Dead)
                rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(pp.torso.Position, Ttorso.Position))
                rs.GrabEvents.DestroyGrabLine:FireServer(Ttorso)
                if isnetworkowner(Ttorso) then
				if workspace.FallenPartsDestroyHeight == -100 then
				Ttorso.CFrame = CFrame.new(0,-98,1e31)
				elseif workspace.FallenPartsDestroyHeight ~= -100 then
				Ttorso.CFrame = CFrame.new(1e31,1e31,1e31)
				end
				end
                end
            end)
        else
            if KillGrabC then
                KillGrabC:Disconnect()
                KillGrabC = nil
            end
        end
    end
})

