RBox:AddToggle("KickGrab", {
    Text = "킥 그랩",
    Default = false,
    Callback = function(Value)

        if KickGrabS.SetDisabled then 
            KickGrabS:SetDisabled(not Value)
        end

        if Value then
            if KickGrabC then KickGrabC:Disconnect() end

            local AnchorToggle = false
            local LastTarget = nil

            KickGrabC = rs2.Heartbeat:Connect(function()
                if not pp.char or not pp.torso then return end
                local GrabParts = workspace:FindFirstChild("GrabParts")
                if not GrabParts then
                    if LastTarget and LastTarget.Parent then
                        local Thrp = LastTarget.Parent:FindFirstChild("HumanoidRootPart")
                        if Thrp then
                            Thrp.Anchored = false
                        end
                    end
                    return
                end

                local WeldConstraint = GrabParts.GrabPart:FindFirstChild("WeldConstraint")
                if not WeldConstraint then return end

                local Target = WeldConstraint.Part1
                local Tchar = Target.Parent
                if not Tchar then return end

                local Thum = Tchar:FindFirstChildOfClass("Humanoid")
                local Thrp = Tchar:FindFirstChild("HumanoidRootPart")
                if not Thrp then return end
                local Ttorso = Tchar:FindFirstChild("Torso")

                LastTarget = Target

                if Thrp and Tchar and KickGrabV == "Slow" then
                if not Thum.Sit then  rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(pp.torso.Position, Ttorso.Position)) end
                if Thum.Sit then  rs.GrabEvents.DestroyGrabLine:FireServer(Ttorso) end
                if Players:GetPlayerFromCharacter(Tchar).IsHeld then rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(pp.torso.Position, Ttorso.Position)) end
                if Thum.Sit then  rs.GrabEvents.DestroyGrabLine:FireServer(Ttorso) end
                end

                if Thrp and Tchar and KickGrabV == "Fast" then
                rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(pp.torso.Position, Ttorso.Position))
                rs.GrabEvents.DestroyGrabLine:FireServer(Ttorso)
                
                AnchorToggle = not AnchorToggle
                Thrp.Anchored = AnchorToggle
                end
            end)
        else
            if KickGrabC then
                KickGrabC:Disconnect()
                KickGrabC = nil
            end
        end
    end
})

