RBox:AddToggle("HouseGrab", {
    Text = "하우스 그렙",
    Default = false,
    Callback = function(Value)
        HouseGrabT = Value
        if HouseGrabC then HouseGrabC:Disconnect() end
        if Value then
            HouseGrabC = rs2.Heartbeat:Connect(function()
                if not pp.char or not pp.torso then return end
                local GrabParts = workspace:FindFirstChild("GrabParts")
                if not GrabParts then return end
                local weld = GrabParts.GrabPart:FindFirstChild("WeldConstraint")
                if not weld or not weld.Part1 then return end
                
                local Target = weld.Part1
                local Tchar = Target.Parent
                if not Tchar then return end
                local Ttorso = Tchar:FindFirstChild("Torso")
                if not Ttorso then return end

                local minDist = 80
                local closestHouse = nil
                
                local houseList = {
                    Vector3.new(-352, 98, 353),
                    Vector3.new(-532, -7, 92),
                    Vector3.new(-484, -7, -165),
                    Vector3.new(249, -7, 461),
                    Vector3.new(513, 83, -341),
                    Vector3.new(551, 123, -73)
                }
                
                for _, housePos in pairs(houseList) do
                    if (pp.torso.Position - housePos).Magnitude < minDist then
                        closestHouse = housePos
                        break
                    end
                end
                
                if closestHouse then
                    pp.torso.CFrame = CFrame.new(closestHouse)
                    pcall(function() rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(closestHouse, Ttorso.Position)) end)
                end
            end)
        else
            if HouseGrabC then HouseGrabC:Disconnect() HouseGrabC = nil end
        end
    end
})


