            if not NCP or Processing or not ctoy.Value then return end
            Processing = true

            local tt = mouse.Target
            if not tt or not tt:IsA("BasePart") then 
                Processing = false 
                return 
            end

            if tt.Name == "PlotBarrier" then 
                local success, check = pcall(function()
                    return tt.Parent and tt.Parent.Parent and tt.Parent.Parent:FindFirstChild("PlotArea")
                end)
                if success and check and check:IsA("BasePart") then
                    tt = check
                else
                    Processing = false
                    return
                end
            end

            if tt.Name == "HumanoidRootPart" then 
                local success, check = pcall(function()
                    return tt.Parent and tt.Parent:FindFirstChild("Torso")
                end)
                if success and check and check:IsA("BasePart") then
                    tt = check
                else
                    Processing = false
                    return
                end
            end

			Library:Notify({ Title = "[ ovitar ]", Description = "Part: " .. tt.Name, Icon = "square-terminal", Time = 1,})
			NS:Play()

            task.spawn(function()
                rs.MenuToys.SpawnToyRemoteFunction:InvokeServer("NinjaKunai", pp.hrp.CFrame * CFrame.new(0, 5, 20), Vector3.zero)
            end)

            local kunai = inv:WaitForChild("NinjaKunai", 0.3)
            if not kunai then 
                Processing = false 
                return 
            end

            for _, part in ipairs(kunai:GetDescendants()) do
                if part:IsA("BasePart") then
                    hiddenParts[part] = true
                end
            end
            kunai.DescendantAdded:Connect(function(part)
                if part:IsA("BasePart") then
                    hiddenParts[part] = true
                end
            end)

            local stickyPart = kunai:WaitForChild("StickyPart", 0.05)
            local soundPart = kunai:WaitForChild("SoundPart", 0.05)

            if stickyPart and soundPart then
                local targetCF
                if NCPTypeVal == "바닥킥" then
                    targetCF = CFrame.new(216.676987, -1.00003366e+09, 12212395, -1.1920929e-07, 0, -1.00000012, -0.997803092, 0.0662516952, 1.18947383e-07, 0.0662517026, 0.997802973, -7.89781751e-09)
                else
                    targetCF = CFrame.new(1.0e+31, 0, 0)
                end

                rs.GrabEvents.SetNetworkOwner:FireServer(soundPart, CFrame.lookAt(pp.torso.Position, getRealPosition(soundPart)))
                rs.PlayerEvents.StickyPartEvent:FireServer(stickyPart, tt, targetCF)
            end

            kunai.Name = ""

            Processing = false
        end
    })

