                local Thrp = Tchar and Tchar:FindFirstChild("HumanoidRootPart")
                local Thum = Tchar and Tchar:FindFirstChildOfClass("Humanoid")

                if not Tchar or not Ttorso or not Thrp or not Thum then
                    Fake(false)
                    if isTeleported and safeCF and pp.torso then
                        pp.torso.CFrame = safeCF
                        isTeleported = false
                    end
                    currentIndex = (currentIndex % slots) + 1
                end

                if lastTarget[targetName] ~= Tchar then
                    lastTarget[targetName] = Tchar
                    kicked[targetName] = false
                end

                if Thum.Health > 0 and Ttorso.Position.Y < 999999999 then kicked[targetName] = false end
                if kicked[targetName] then 
                    if isTeleported and safeCF then
                        pp.torso.CFrame = safeCF
                        isTeleported = false
                    end
                    return 
                end

                if Thum.Health > 0 and Ttorso.Position.Y < 999999999 then
                    isTeleported = true
                    if not LoopViewC and LoopCamera and LoopKickC then cam.CameraType = Enum.CameraType.Scriptable end
                    if not isnetworkowner(Thrp) then
                        Fake(true, Ttorso)
                        ServerHrp = CFrame.new(Ttorso.Position + (Ttorso.Velocity * (plr:GetNetworkPing() + 0.22))) * CFrame.new(0, 0, 10)
                        rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(ServerHrp.Position, Ttorso.Position))
                    end
                    if isnetworkowner(Thrp) then
                        Ttorso.CFrame = CFrame.new(0, 999999999999999, 0)
                    end
                else
                    Fake(false)
                    if pp.hum and not FreeCamC then
                        cam.CameraType = Enum.CameraType.Custom
                        cam.CameraSubject = pp.hum
                    end
                    kicked[targetName] = true
                    isTeleported = false
                    task.spawn(function()
                        task.wait()
                        currentIndex = (currentIndex % slots) + 1
                        kicked[targetName] = false
                    end)
                end
            end)
        else
            Fake(false)
            if pp.hum and not FreeCamC then
                cam.CameraType = Enum.CameraType.Custom
                cam.CameraSubject = pp.hum
            end
            if LoopKickC then
                LoopKickC:Disconnect()
                LoopKickC = nil
            end
        end
    end
})

RBox:AddToggle("LoopSpamKickBlobman", {
    Text = "루프 스팸 킥",
    Default = false,
    Callback = function(Value)
        if LoopSpamKickS.SetDisabled then LoopSpamKickS:SetDisabled(not Value) end
        if Value then
            if LoopSpamKick then return end
            LoopSpamKick = true
            local savedOCF = nil
            local kicked = {}
            local lastTarget = {}
            task.spawn(function()
                if pp.torso then savedOCF = pp.torso.CFrame end
                while LoopSpamKick and task.wait() do
                    if not pp.char or not pp.torso or not pp.hrp then continue end
                    local slots = math.min(#currentTargets, maxTargets.LoopSpamKick)
                    if slots == 0 then if savedOCF then pp.torso.CFrame = savedOCF end continue end
                    local acted = false
                    for i = 1, slots do
                        if not LoopSpamKick then break end
                        local targetName = currentTargets[i]
                        local Tplr = getPlayer(targetName)
                        if not Tplr then Fake(false) lastTarget[targetName] = nil kicked[targetName] = false continue end
                        local Tchar = Tplr.Character
                        local Thead = Tchar and Tchar:FindFirstChild("Head")
                        local Ttorso = Tchar and Tchar:FindFirstChild("Torso")
                        local Thrp = Tchar and Tchar:FindFirstChild("HumanoidRootPart")
                        local Thum = Tchar and Tchar:FindFirstChildOfClass("Humanoid")
                        if not Tchar or not Ttorso or not Thrp or not Thum then Fake(false) kicked[targetName] = false lastTarget[targetName] = nil continue end
                        if lastTarget[targetName] ~= Tchar then lastTarget[targetName] = Tchar kicked[targetName] = false end
                        if not isnetworkowner(Thrp) then kicked[targetName] = false end
                        if kicked[targetName] then continue end
                        local offsetCF = targetOffsets and targetOffsets[i] or CFrame.new()
                        acted = true
                        local targetPos = pp.torso.Position + offsetCF.Position + Vector3.new(0,25,0)
                        local atTarget = Ttorso and (Ttorso.Position - targetPos).Magnitude <= 0.1
                        if Thum.Health > 0 and Thrp and not Thrp.Massless and not isnetworkowner(Thrp) and not atTarget then
                            if not LoopViewC and LoopCamera and LoopSpamKick then cam.CameraType = Enum.CameraType.Scriptable end
                            Fake(true, Ttorso)
                            ServerHrp = CFrame.new(Ttorso.Position + (Ttorso.Velocity * (plr:GetNetworkPing() + 0.22))) * CFrame.new(0,0,-5)
                            rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(ServerHrp.Position, Ttorso.Position))
                        else
                            Fake(false)
                            if pp.torso then cam.CameraType = Enum.CameraType.Custom cam.CameraSubject = pp.hum end
                            if Ttorso and savedOCF then
                                if pp.hum and pp.hum.SeatPart and pp.hum.SeatPart.Parent and pp.hum.SeatPart.Parent.Name == "CreatureBlobman" then
                                    if not BlobmanGrabLoop then
                                        BlobmanGrabLoop = true
                                        task.spawn(function()
                                            task.wait(2)
                                            while LoopSpamKick and pp.hum and pp.hum.SeatPart and pp.hum.SeatPart.Parent do
                                                local parent = pp.hum.SeatPart.Parent
                                                local we = parent:FindFirstChild("LeftDetector") and parent.LeftDetector:FindFirstChild("LeftWeld")
                                                local scripta = parent:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                if we and scripta and Thrp then
                                                    local grab = scripta:FindFirstChild("CreatureGrab")
                                                    local rlse = scripta:FindFirstChild("CreatureRelease")
                                                    if grab and rlse then grab:FireServer(we, Thrp, we) rlse:FireServer(we) end
                                                end
                                                task.wait(0.07)
                                            end
                                            BlobmanGrabLoop = false
                                        end)
                                    end
                                end
                                if LoopSpamKickV == "Fast" then
                                    rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(ServerHrp.Position, Ttorso.Position))
                                    rs.GrabEvents.DestroyGrabLine:FireServer(Ttorso)
                                elseif LoopSpamKickV == "Slow" then

                                if not Thum.Sit then rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(ServerHrp.Position, Ttorso.Position)) end
                                if Thum.Sit then rs.GrabEvents.DestroyGrabLine:FireServer(Ttorso) end
                                if Tplr.IsHeld then rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(ServerHrp.Position, Ttorso.Position)) end
                                if Thum.Sit then rs.GrabEvents.DestroyGrabLine:FireServer(Ttorso) end

                                elseif LoopSpamKickV == "Bring" then
                                    rs.GrabEvents.SetNetworkOwner:FireServer(Ttorso, CFrame.lookAt(ServerHrp.Position, Ttorso.Position))
                                end
                                local okr = Thead:FindFirstChild("OwnerKickRagdoll") or Instance.new("StringValue")
                                okr.Name = "OwnerKickRagdoll"
                                okr.Parent = Thead
                                local bp = Ttorso:FindFirstChild("_BodyPosition") or Instance.new("BodyPosition")
                                bp.Name = "_BodyPosition"
                                bp.MaxForce = Vector3.new(9e9, 9e9, 9e9)
                                bp.P = 800000
                                bp.D = 500
                                bp.Position = targetPos
                                bp.Parent = Ttorso
                                Ttorso.AssemblyLinearVelocity = Vector3.zero
                                Ttorso.AssemblyAngularVelocity = Vector3.zero
                            end
                        end
                        task.wait()
                    end
                    if not acted and savedOCF then end
                end
            end)
        else
            Fake(false)
            LoopSpamKick = false
            task.wait(0.1)
            for _, targetName in ipairs(currentTargets) do
                local Tplr = getPlayer(targetName)
                local Tchar = Tplr and Tplr.Character
                local Thead = Tchar and Tchar:FindFirstChild("Head")
                local Ttorso = Tchar and Tchar:FindFirstChild("Torso")
                local okr = Thead and Thead:FindFirstChild("OwnerKickRagdoll")
                local bp = Ttorso and Ttorso:FindFirstChild("_BodyPosition")
                if bp then bp:Destroy() end
                if okr then okr:Destroy() end
            end
            if pp.hum and not FreeCamC then cam.CameraType = Enum.CameraType.Custom cam.CameraSubject = pp.hum end
        end
    end
})

LoopSpamKickV = {"Fast"}
LoopSpamKickS = RBox:AddDropdown("LoopSpamKickBlobmanType", {
    Values = {"Fast", "Slow", "Bring"},
    Multi = false,
    Callback = function(Value)
        LoopSpamKickV = Value
    end
})
LoopSpamKickS:SetValue("Fast")
LoopSpamKickS:SetDisabled(true)

do
    local oatsKickActive = false
    local oatsKickTask = nil

    RBox:AddToggle("BestKickLoop", {
        Text = "Best kick loop",
        Default = false,
        Callback = function(Value)
            oatsKickActive = Value
            
            local function sno(part)
                pcall(function()
                    local grabEvents = game:GetService("ReplicatedStorage"):FindFirstChild("GrabEvents")
                    local setNetOwner = grabEvents and grabEvents:FindFirstChild("SetNetworkOwner")
                    if setNetOwner then
                        setNetOwner:FireServer(part, part.CFrame)
                    end
                end)
            end
            
            if Value then
                local targetName = currentTargets[1]
                if not targetName or targetName == "" then
                    oatsKickActive = false
                    Library:Notify({ Title = "Error", Description = "Select target first!", Time = 3 })
                    if Toggles and Toggles.BestKickLoop then Toggles.BestKickLoop:SetValue(false) end
                    return
                end
                
                oatsKickTask = task.spawn(function()
                    local RunService = game:GetService("RunService")
                    local ReplicatedStorage = game:GetService("ReplicatedStorage")
                    
                    local myChar = Player.Character
                    local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    if not (myChar and myHRP) then
                        oatsKickActive = false
                        return
                    end

                    local savedPos = myHRP.CFrame
                    local lastRemoteFire = tick()

                    while oatsKickActive and RunService.Heartbeat:Wait() do
                        local currentTargetName = currentTargets[1]
                        local targetPlayer = currentTargetName and getPlayer(currentTargetName)
                        
                        -- Target validation fix to prevent errors if target leaves or resets
                        if not targetPlayer or not targetPlayer.Character then
                            break
                        end

                        myChar = Player.Character
                        myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                        local myHead = myChar and myChar:FindFirstChild("Head")

                        local tChar = targetPlayer.Character
                        local tHRP = tChar and tChar:FindFirstChild("HumanoidRootPart")
                        local tHum = tChar and tChar:FindFirstChild("Humanoid")

                        if not (myChar and myHRP and myHead) or not (tHRP and tHum) or tHum.Health <= 0 then
                            continue
                        end

                        local dist = (tHRP.Position - myHRP.Position).Magnitude

                        if dist > 30 then
                            pcall(function()
                                myChar:PivotTo(tHRP.CFrame * CFrame.new(0, 2, 4))
                            end)
                            
                            sno(tHRP)

                            if not tHRP:FindFirstChild("KickAlign") then
                                local oldBp = tHRP:FindFirstChildOfClass("BodyPosition")
                                if oldBp then oldBp:Destroy() end

                                local att0 = Instance.new("Attachment", tHRP)
                                att0.Name = "KickAtt0"
                                
                                local att1 = Instance.new("Attachment", workspace.Terrain)
                                att1.Name = "KickAtt1"

                                local alignPos = Instance.new("AlignPosition")
                                alignPos.Name = "KickAlign"
                                alignPos.Attachment0 = att0
                                alignPos.Attachment1 = att1
                                alignPos.MaxForce = math.huge
                                alignPos.Responsiveness = 200
                                alignPos.Parent = tHRP

                                local alignRot = Instance.new("AlignOrientation")
                                alignRot.Name = "KickRot"
                                alignRot.Attachment0 = att0
                                alignRot.Mode = Enum.OrientationAlignmentMode.OneAttachment
                                alignRot.CFrame = CFrame.new() 
                                alignRot.MaxTorque = math.huge
                                alignRot.Responsiveness = 200
                                alignRot.Parent = tHRP
                            end

                            local grabStartTime = tick()
                            while (tick() - grabStartTime) < 0.3 and oatsKickActive do
                                task.wait(0.05)
                                sno(tHRP)
                                pcall(function()
                                    local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
                                    local destroyLine = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine")
                                    if destroyLine then
                                        destroyLine:FireServer(tHRP)
                                    end
                                end)
                                
                                local align = tHRP:FindFirstChild("KickAlign")
                                if myHead and align and align.Attachment1 then
                                    align.Attachment1.WorldPosition = myHead.Position + Vector3.new(0, 15, 0)
                                end
                            end

                            if oatsKickActive then
                                pcall(function()
                                    myChar:PivotTo(savedPos)
                                    tHRP.CFrame = savedPos * CFrame.new(0, 15, 0)
                                end)
                            end
                            
                            continue
                        end

                        if not tHRP:FindFirstChild("KickAlign") then
                            local oldBp = tHRP:FindFirstChildOfClass("BodyPosition")
                            if oldBp then oldBp:Destroy() end

                            local att0 = Instance.new("Attachment", tHRP)
                            att0.Name = "KickAtt0"
                            
                            local att1 = Instance.new("Attachment", workspace.Terrain)
                            att1.Name = "KickAtt1"

                            local alignPos = Instance.new("AlignPosition")
                            alignPos.Name = "KickAlign"
                            alignPos.Attachment0 = att0
                            alignPos.Attachment1 = att1
                            alignPos.MaxForce = math.huge
                            alignPos.Responsiveness = 200
                            alignPos.Parent = tHRP

                            local alignRot = Instance.new("AlignOrientation")
                            alignRot.Name = "KickRot"
                            alignRot.Attachment0 = att0
                            alignRot.Mode = Enum.OrientationAlignmentMode.OneAttachment
                            alignRot.CFrame = CFrame.new() 
                            alignRot.MaxTorque = math.huge
                            alignRot.Responsiveness = 200
                            alignRot.Parent = tHRP
                        end

                        sno(tHRP)

                        local align = tHRP:FindFirstChild("KickAlign")
                        if align and align.Attachment1 and oatsKickActive then
                            align.Attachment1.WorldPosition = myHead.Position + Vector3.new(0, 20, 0)
                        end

                        local rot = tHRP:FindFirstChild("KickRot")
                        if rot then 
                            rot.CFrame = CFrame.Angles(0, 0, 0) 
                        end

                        if tick() - lastRemoteFire > 0.05 and oatsKickActive then
                            pcall(function()
                                local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
                                local destroyLine = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine")
                                if destroyLine then
                                    destroyLine:FireServer(tHRP)
                                end
                            end)
                            lastRemoteFire = tick()
                        end
                    end

                    -- Cleanup logic for target when toggle is disabled internally
                    local finalTargetName = currentTargets[1]
                    local finalTarget = finalTargetName and getPlayer(finalTargetName)
                    
                    if finalTarget and finalTarget.Character then
                        local tH = finalTarget.Character:FindFirstChild("HumanoidRootPart")
                        if tH then
                            local align = tH:FindFirstChild("KickAlign")
                            local rot = tH:FindFirstChild("KickRot")
                            local att0 = tH:FindFirstChild("KickAtt0")
                            
                            if align then 
                                if align.Attachment1 then align.Attachment1:Destroy() end
                                align:Destroy() 
                            end
                            if rot then rot:Destroy() end
                            if att0 then att0:Destroy() end

                            pcall(function()
                                local grabEvents = ReplicatedStorage:FindFirstChild("GrabEvents")
                                local destroyLine = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine")
                                if destroyLine then
                                    destroyLine:FireServer(tH)
                                end
                            end)
                        end
                    end

                    oatsKickActive = false
                end)
            else
                oatsKickActive = false
                if oatsKickTask then
                    task.cancel(oatsKickTask)
                    oatsKickTask = nil
                end
                
                local currentTargetName = currentTargets[1]
                local targetPlayer = currentTargetName and getPlayer(currentTargetName)
                
                if targetPlayer and targetPlayer.Character then
                    local tH = targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if tH then
                        local align = tH:FindFirstChild("KickAlign")
                        local rot = tH:FindFirstChild("KickRot")
                        local att0 = tH:FindFirstChild("KickAtt0")
                        
                        if align then 
                            if align.Attachment1 then align.Attachment1:Destroy() end
                            align:Destroy() 
                        end
                        if rot then rot:Destroy() end
                        if att0 then att0:Destroy() end

                        pcall(function()
                            local grabEvents = game:GetService("ReplicatedStorage"):FindFirstChild("GrabEvents")
                            local destroyLine = grabEvents and grabEvents:FindFirstChild("DestroyGrabLine")
                            if destroyLine then
                                destroyLine:FireServer(tH)
                            end
                        end)
                    end
                end
            end
        end
    })
end

local RBox = Tab.Combat:AddRightGroupbox("Blobman", "bot-off")

RBox:AddToggle("LoopGrabBlobman", {
    Text = "루프 그랩(블룹맨)",
    Default = false,
    Callback = function(Value)
        if Value then
            if LoopBlobGrab then return end
            LoopBlobGrab = true

            task.spawn(function()
                while LoopBlobGrab and task.wait(0.08) do
                    if not pp.hum or not pp.hum.SeatPart or not pp.hum.SeatPart.Parent then continue end
                    if pp.hum.SeatPart.Parent.Name ~= "CreatureBlobman" then continue end

                    local parent = pp.hum.SeatPart.Parent
                    local Lwe = parent:FindFirstChild("LeftDetector") and parent.LeftDetector:FindFirstChild("LeftWeld")
                    local Rwe = parent:FindFirstChild("RightDetector") and parent.RightDetector:FindFirstChild("RightWeld")
                    local scripta = parent:FindFirstChild("BlobmanSeatAndOwnerScript")
                    if not scripta then continue end

                    local grab = scripta:FindFirstChild("CreatureGrab")
                    local rlse = scripta:FindFirstChild("CreatureRelease")
                    if not grab or not rlse then continue end

                    local slots = math.min(#currentTargets, maxTargets.LoopGrab)
                    for i = 1, slots do
                        local targetName = currentTargets[i]
                        local Tplr = getPlayer(targetName)
                        if not Tplr then continue end
                        local Tchar = Tplr.Character
                        local Thrp = Tchar and Tchar:FindFirstChild("HumanoidRootPart")
                        if not Thrp then continue end

                        local we = (i == 1) and Lwe or Rwe
                        if not we then continue end

                        grab:FireServer(we, Thrp, we)
                        rlse:FireServer(we)
                        grab:FireServer(we, Thrp, we)
                    end
                end
            end)

            task.spawn(function()
                while LoopBlobGrab and task.wait(0.3) do
                    local slots = math.min(#currentTargets, maxTargets.LoopGrab)
                    for i = 1, slots do
                        local targetName = currentTargets[i]
                        local Tplr = Players:FindFirstChild(targetName)
                        if not Tplr then continue end
                        local Tchar = Tplr.Character
                        local Thum = Tchar and Tchar:FindFirstChild("Humanoid")
                        if not Thum then continue end
                        Thum.Sit = true
                        task.wait(0.3)
                        if not LoopBlobGrab then break end
                        Thum.Sit = false
                    end
                end
            end)
        else
            LoopBlobGrab = false
        end
    end
})

RBox:AddToggle("LoopKillBlobman", {
    Text = "루프 킬(블룹맨)",
    Default = false,
    Callback = function(Value)
        if Value then
            if BlobLoopKillC then BlobLoopKillC:Disconnect() end

            local killed = {}
            local lastTarget = {}
            local currentIndex = 1
            local safeCF = pp.torso and pp.torso.CFrame
            local isTeleported = false

            BlobLoopKillC = rs2.PreSimulation:Connect(function()
                if not pp.char or not pp.torso then return end
                if not pp.hum.SeatPart then return end
                if pp.hum.SeatPart.Parent.Name ~= "CreatureBlobman" then return end
                
                local slots = math.min(#currentTargets, maxTargets.LoopKillB)
                if slots == 0 then
                    if isTeleported and safeCF then
                        pp.torso.CFrame = safeCF
                        ServerHrp = safeCF
                        isTeleported = false
                    end
                    return
                end

                local we = pp.hum.SeatPart.Parent.LeftDetector.LeftWeld
                local scripta = pp.hum.SeatPart.Parent.BlobmanSeatAndOwnerScript
                local grab = scripta.CreatureGrab
                local drop = scripta.CreatureDrop
                local rlse = scripta.CreatureRelease

                if currentIndex > slots then currentIndex = 1 end

                if not isTeleported then
                    safeCF = pp.torso.CFrame
                end

                local targetName = currentTargets[currentIndex]
                local Tplr = getPlayer(targetName)
                local Tchar = Tplr and Tplr.Character
                local Ttorso = Tchar and Tchar:FindFirstChild("Torso")
                local Thrp = Tchar and Tchar:FindFirstChild("HumanoidRootPart")
                local Thum = Tchar and Tchar:FindFirstChildOfClass("Humanoid")

                if not Tplr or not Tchar or not Ttorso or not Thum then
                    if isTeleported and safeCF then
                        pp.torso.CFrame = safeCF
                        pp.torso.AssemblyLinearVelocity = Vector3.zero
                        pp.torso.AssemblyAngularVelocity = Vector3.zero
                        isTeleported = false
                    end
                    currentIndex = (currentIndex % slots) + 1
                    return
                end

                if lastTarget[targetName] ~= Tchar then
                    lastTarget[targetName] = Tchar
                    killed[targetName] = false
                end

                if Thum.Health > 0 then
                    isTeleported = true
                    if not LoopViewC and LoopCamera and BlobLoopKillC then cam.CameraType = Enum.CameraType.Scriptable end
                    Thum.BreakJointsOnDeath = false
                    Thum:ChangeState(Enum.HumanoidStateType.Dead)
                    grab:FireServer(we, Thrp, we)
                    rlse:FireServer(we)
                    Fake(true, Ttorso)
                    ServerHrp = CFrame.new(Ttorso.Position + (Ttorso.Velocity * (plr:GetNetworkPing() + 0.22))) * CFrame.new(0, 0, 10)
                else
                    Fake(false)
                    if pp.hum and not FreeCamC then
                        cam.CameraType = Enum.CameraType.Custom
                        cam.CameraSubject = pp.hum
                    end
                    if pp.torso and safeCF then
                        pp.torso.CFrame = safeCF
                        ServerHrp = safeCF
                    end
                    killed[targetName] = true
                    isTeleported = false
                    task.spawn(function()
                        task.wait()
                        currentIndex = (currentIndex % slots) + 1
                        killed[targetName] = false
                    end)
                end
            end)
        else
            Fake(false)
            if pp.hum and not FreeCamC then
                cam.CameraType = Enum.CameraType.Custom
                cam.CameraSubject = pp.hum
            end
            if BlobLoopKillC then
                BlobLoopKillC:Disconnect()
                BlobLoopKillC = nil
            end
        end
    end
})

RBox:AddToggle("LoopKickBlobman", {
    Text = "루프 킥(블룹맨)",
    Default = false,
    Callback = function(Value)
        if Value then
            if LoopKickRunning then return end
            LoopKickRunning = true

            local kicked = {}
            local lastTarget = {}
            local currentIndex = 1
            local safeCF = nil

            task.spawn(function()
                while LoopKickRunning and task.wait() do
                    if not pp.char or not pp.torso or not pp.hrp then continue end
                    if not pp.hum.SeatPart or pp.hum.SeatPart.Parent.Name ~= "CreatureBlobman" then continue end

                    local slots = math.min(#currentTargets, maxTargets.LoopKickB)
                    if slots == 0 then
                        if safeCF then
                            pp.torso.CFrame = safeCF
                            pp.torso.AssemblyLinearVelocity = Vector3.zero
                            pp.torso.AssemblyAngularVelocity = Vector3.zero
                            safeCF = nil
                        end
                        continue
                    end

                    if not safeCF then
                        safeCF = pp.torso.CFrame
                    end

                    local we = pp.hum.SeatPart.Parent.RightDetector.RightWeld
                    local script = pp.hum.SeatPart.Parent.BlobmanSeatAndOwnerScript
                    local grab = script.CreatureGrab
                    local drop = script.CreatureDrop

                    if currentIndex > slots then currentIndex = 1 end

                    local targetName = currentTargets[currentIndex]
                    local Tplr = getPlayer(targetName)

                    if not Tplr then
                        if safeCF then
                            pp.torso.CFrame = safeCF
                            ServerHrp = safeCF
                        end
                        currentIndex = (currentIndex % slots) + 1
                        continue
                    end

                    local Tchar = Tplr.Character
                    local Thead = Tchar and Tchar:FindFirstChild("Head")
                    local Ttorso = Tchar and Tchar:FindFirstChild("Torso")
                    local Thrp = Tchar and Tchar:FindFirstChild("HumanoidRootPart")
                    local Thum = Tchar and Tchar:FindFirstChildOfClass("Humanoid")

                    if not Tchar or not Ttorso or not Thrp or not Thum then
                        if safeCF then
                            pp.torso.CFrame = safeCF
                        end
                        currentIndex = (currentIndex % slots) + 1
                        continue
                    end

                    if lastTarget[targetName] ~= Tchar then
                        lastTarget[targetName] = Tchar
                        kicked[targetName] = false
                    end

                    if Thum.Health > 0 and Thrp and not Thrp.Massless then
                        kicked[targetName] = false
                    end

                    if kicked[targetName] then
                        if safeCF then
                            pp.torso.CFrame = safeCF
                        end
                        task.wait()
                        currentIndex = (currentIndex % slots) + 1
                        kicked[targetName] = false
                        continue
                    end

                    if Thum.Health > 0 and Thrp and not Thrp.Massless then
                        if not LoopViewC and LoopKickRunning and LoopCamera then cam.CameraType = Enum.CameraType.Scriptable end

                        if not isnetworkowner(Thrp) then
                            repeat task.wait()
                                local ownerTag = Thead:FindFirstChild("PartOwner")
                                if ownerTag and ownerTag.Value == plr.Name then break end
                                Fake(true, Thead)
                                ServerHrp = CFrame.new(Ttorso.Position + (Ttorso.Velocity * (plr:GetNetworkPing() + 0.22))) * CFrame.new(0,25,0)
                                rs.GrabEvents.SetNetworkOwner:FireServer(Thead, CFrame.lookAt(ServerHrp.Position, Thead.Position))
                            until not hrp or not pp.hrp or not LoopKickRunning
                        end

                        rs.GrabEvents.DestroyGrabLine:FireServer(Thead, Thead.CFrame)
                        Ttorso.CFrame = pp.torso.CFrame * CFrame.new(0,20,0)
                        grab:FireServer(we, pp.hrp, we)
                        grab:FireServer(we, Thrp, we)
                        drop:FireServer(we)
                    else
                        Fake(false)
                        if pp.hum and not FreeCamC then
                            cam.CameraType = Enum.CameraType.Custom
                            cam.CameraSubject = pp.hum
                        end
                        if safeCF then
                            pp.torso.CFrame = safeCF
                            ServerHrp = safeCF
                            if pp.torso then pp.torso.Anchored = false end
                        end
                        kicked[targetName] = true
                        task.wait()
                        currentIndex = (currentIndex % slots) + 1
                        kicked[targetName] = false
                        safeCF = nil
                    end
                end
            end)
        else
            Fake(false)
            task.wait(0.2)
            LoopKickRunning = false
            if pp.hum and not FreeCamC then
                cam.CameraType = Enum.CameraType.Custom
                cam.CameraSubject = pp.hum
            end
        end
    end
})

local LBox = Tab.Keybind:AddLeftGroupbox("Mouse", "mouse-pointer-click")

LBox:AddToggle("TeleporTtoMouse", {
    Text = "텔레포트",
    Default = false,
    Callback = function(Value)
        TPMOUSE = Value
    end
}):AddKeyPicker("TeleporTtoMouseTrigger", {
    Default = "Z",
    Text = "",
    Mode = "Toggle",
    Callback = function()
        if not TPMOUSE or IsRunning2 then return end
        if not mouse.Target then return end
        if not mouse.Hit then return end

        local currentTime = tick()
        if currentTime - (lastTPTime or 0) < (TP_COOLDOWN or 0.1) then return end
        if not pp.hrp or not pp.hum then return end

        IsRunning2 = true
        lastTPTime = currentTime

        local vehicleModel = nil

        if pp.hum.Sit and pp.hum.SeatPart and pp.hum.SeatPart:IsA("BasePart") then
            vehicleModel = pp.hum.SeatPart.Parent
		elseif not pp.hrp then
            vehicleModel = pp.torso
        end

        local targetObject = vehicleModel or pp.hrp

        local finalPos = mouse.Hit.Position + Vector3.new(0, 3, 0)

        local lookDir = workspace.CurrentCamera.CFrame.LookVector
        local targetCFrame = CFrame.new(finalPos, finalPos + Vector3.new(lookDir.X, 0, lookDir.Z))

        local distance = (targetObject:GetPivot().Position - finalPos).Magnitude
        local duration = math.clamp(distance / 1500, 0.05, 0.2)
        local tweenInfo = TweenInfo.new(duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

        local function clearVelocity(obj)
            for _, p in ipairs(obj:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.AssemblyLinearVelocity = Vector3.zero
                    p.AssemblyAngularVelocity = Vector3.zero
                end
            end
        end

        clearVelocity(targetObject)

        if vehicleModel then
            local cfValue = Instance.new("CFrameValue")
            cfValue.Value = vehicleModel:GetPivot()

            local conn = cfValue:GetPropertyChangedSignal("Value"):Connect(function()
                vehicleModel:PivotTo(cfValue.Value)
            end)

            local t = Tween:Create(cfValue, tweenInfo, {Value = targetCFrame})
            t.Completed:Connect(function()
                conn:Disconnect()
                cfValue:Destroy()
                clearVelocity(vehicleModel)
                IsRunning2 = false
            end)
            t:Play()
        else
            local t = Tween:Create(pp.hrp, tweenInfo, {CFrame = targetCFrame})
            t.Completed:Connect(function()
                pp.hrp.AssemblyLinearVelocity = Vector3.zero
                IsRunning2 = false
            end)
            t:Play()
        end
    end
})

