rs.GrabEvents.ExtendGrabLine.OnClientEvent:Connect(function(fromPlr, message)
    if typeof(fromPlr) ~= "Instance" or not fromPlr:IsA("Player") then return end
    if fromPlr == plr then return end
    if type(message) ~= "string" then return end
    local cleanMessage = string.gsub(message, "\"", "")
    if string.find(cleanMessage, "@FN.msg.", 1, true) then return end
    if cleanMessage == "" then return end
    if string.match(cleanMessage, "^[%d%.]+$") then return end
    Library:Notify({Title = fromPlr.Name .. " [" .. fromPlr.DisplayName .. "]",Description = cleanMessage,Icon = "message-circle-more",Time = 2.5,})
    NS:Play()
end)

