    end
    if fovCircle then
        fovCircle.Radius = getgenv().Settings.Fov
        fovCircle.Thickness = 4
        fovCircle.Position = Vector2.new(currentCamera.ViewportSize.X / 2, currentCamera.ViewportSize.Y / 2 + 36)
        fovCircle.Transparency = 1
