	if protectionEnabled then
		local humanoid_ = localPlayer.Character and localPlayer.Character:FindFirstChild("Humanoid")

		if humanoid_ then
			protectHumanoidOld(humanoid_)
		end

		setAntiRagdollProtection(true)
	else
		clearConnections()
		setAntiRagdollProtection(false)
	end
end

