	removeNoksESP = function(arg)
		if tbl14[arg] then
			pcall(function()
				if arg:FindFirstChild("Noks_Highlight") then
					arg.Noks_Highlight:Destroy()
				end
			end)

			tbl14[arg].Gui:Destroy()
			tbl14[arg] = nil
		end

		tbl17[arg] = nil
		tbl18[arg] = nil
