		end
	end

	local function fn_17()
		if not v16 then
			return
		end
		local leftDetector = v16:FindFirstChild("LeftDetector", true)
		if not leftDetector then
			return
		end
		local attachPlayer = leftDetector:FindFirstChild("AttachPlayer")

