	local function fn_20(arg)
		if arg == localPlayer2 then
			return false
		end

		if not fn_14(arg) then
			return false
		end
		local flag6 = true

		if flag3 then
			flag6 = fn_12(arg)
		end

		if flag6 then
			return false
		end

		if fn_13(arg) then
			return false
		end
		local character = arg.Character
		local v17 = tbl16[arg.UserId]
		local flag7

		if v17 then
