		end

		if flag7 and v17.char == character then
			return false
		end
		local v18 = fn_19(arg)
		if not v18 then
			return false
		end
		return true, v18, character
	end

	local function fn_21()
		local v17 = fn_3()
		if not v17 then
			return {}
		end
		local tbl18 = {}

		for _, player in ipairs(tbl17.Players:GetPlayers()) do
			local v18, v19, v20 = fn_20(player)

			if v18 then
