local tbl16 = {}

lcUpsert = function(arg, name, arg2)
	local Lighting = game:GetService("Lighting")

	if tbl16[name] then
		pcall(function()
			tbl16[name]:Destroy()
		end)
	end

	local instance = Instance.new(arg)
	instance.Name = name

	for k, v19 in pairs(arg2) do
		pcall(function()
			instance[k] = v19
		end)
	end

	instance.Parent = Lighting
	tbl16[name] = instance
	return instance
end

