			end
		else
			if arg.large then
				arg.large.Image = arg.originalLargeImage
				arg.large.ImageColor3 = arg.originalLargeImageColor3 or Color3.new(1, 1, 1)
				arg.large.ImageTransparency = arg.originalLargeImageTrans or 0
			end

