				end)

				if part1 ~= v22 then
					arg:SetAttribute("broken", false)

					if connection4 then
						connection4:Disconnect()
					end
				end
			end)

			return true
		end

		arg2.Sit = true
		task.wait(0.05)
		arg2.Sit = false

		if connection3 then
			connection3:Disconnect()
		end

